fn is_canonical_sha256_hex(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}

fn consensus_instance_lock_key(parent_height: u64, parent_state_root: &str) -> String {
    format!("{CONSENSUS_INSTANCE_LOCK_PREFIX}{parent_height}:{parent_state_root}")
}

fn parse_consensus_vote_lock_key(key: &str) -> Result<(u64, String), LedgerError> {
    if let Some(current) = key.strip_prefix(CONSENSUS_INSTANCE_LOCK_PREFIX) {
        let (height, root) = current.split_once(':').ok_or_else(|| {
            LedgerError::InvalidQuorum("malformed consensus instance vote-lock key".into())
        })?;
        let height = height.parse::<u64>().map_err(|_| {
            LedgerError::InvalidQuorum("malformed consensus instance vote-lock height".into())
        })?;
        if root.is_empty() {
            return Err(LedgerError::InvalidQuorum(
                "consensus instance vote-lock root is empty".into(),
            ));
        }
        return Ok((height, root.to_owned()));
    }

    let mut fields = key.rsplitn(3, ':');
    let (Some(round), Some(root), Some(height)) = (fields.next(), fields.next(), fields.next())
    else {
        return Err(LedgerError::InvalidQuorum(
            "unrecognized legacy consensus vote-lock key".into(),
        ));
    };
    let height = height.parse::<u64>().map_err(|_| {
        LedgerError::InvalidQuorum("malformed legacy consensus vote-lock height".into())
    })?;
    round.parse::<u64>().map_err(|_| {
        LedgerError::InvalidQuorum("malformed legacy consensus vote-lock round".into())
    })?;
    if root.is_empty() {
        return Err(LedgerError::InvalidQuorum(
            "legacy consensus vote-lock root is empty".into(),
        ));
    }
    Ok((height, root.to_owned()))
}

