#[derive(Debug, Error)]
pub enum LedgerError {
    #[error("amount error: {0}")]
    Amount(#[from] AmountError),
    #[error("coin not found: {0}")]
    CoinNotFound(String),
    #[error("coin is not spendable")]
    CoinNotSpendable,
    #[error("coin owner does not match signer")]
    OwnerMismatch,
    #[error("invalid signature: {0}")]
    InvalidSignature(String),
    #[error("invalid request: {0}")]
    Invalid(String),
    #[error("duplicate identifier: {0}")]
    Duplicate(String),
    #[error("transit not found: {0}")]
    TransitNotFound(String),
    #[error("transit has already been imported")]
    TransitAlreadyImported,
    #[error("quorum certificate rejected: {0}")]
    InvalidQuorum(String),
    #[error("causal firewall quarantined the message: {0}")]
    CausalQuarantine(String),
    #[error("service order not found: {0}")]
    ServiceOrderNotFound(String),
    #[error("service lease not found: {0}")]
    ServiceLeaseNotFound(String),
    #[error("service order is not in the required state")]
    ServiceState,
    #[error("testnet-only operation")]
    TestnetOnly,
    #[error("supply conservation failure: {0}")]
    Supply(String),
    #[error("operational proof rejected: {0}")]
    InvalidOperationalProof(String),
    #[error("source Zone is quarantined: {0}")]
    SourceZoneQuarantined(String),
    #[error("voyage escrow not found: {0}")]
    VoyageNotFound(String),
    #[error("liquidity offer not found: {0}")]
    LiquidityOfferNotFound(String),
    #[error("route quote not found: {0}")]
    RouteQuoteNotFound(String),
    #[error("era transition rejected: {0}")]
    EraTransition(String),
    #[error("real-value risk policy rejected: {0}")]
    ValueRisk(String),
    #[error("economic reserve release rejected: {0}")]
    Economic(String),
    #[error("stake-state resource policy or accounting rejected: {0}")]
    StakeResource(String),
}

/// Private-field capability for finishing consensus metadata after an
/// externally assisted command transition while freezing every Ledger field
/// that the state root does not directly commit.
///
/// Some future commands need authenticated node-local evidence while they are
/// replayed. The caller may produce their state-rooted transition, but it must
/// not synthesize or edit Era-certificate history, derived checkpoints,
/// durable vote locks or the commit inventory. Only a capability created from
/// the exact prestate can install the commit-specific successor metadata.
#[derive(Clone, Debug)]
pub struct AuthenticatedConsensusCommitMetadataV1 {
    commit: ConsensusCommit,
    commit_hash: String,
    prior_unrooted_bytes: Vec<u8>,
    successor_vote_locks: BTreeMap<String, String>,
    expected_height: u64,
    expected_state_root: String,
}

/// Private-field capability for installing exactly one tag-28 vote lock after
/// the signed proposal and its node-local Admission proof have both been
/// authenticated against the current Ledger prestate.
///
/// The type has no deserializer. It freezes all existing unrooted consensus
/// bookkeeping and the only permitted successor lock map, so a persistence
/// adapter cannot use node-local evidence as a generic Ledger mutation hook.
#[derive(Clone, Debug)]
pub struct AuthenticatedAdmissionCheckpointVoteLockV1 {
    proposal_hash: String,
    parent_height: u64,
    parent_state_root: String,
    prior_unrooted_bytes: Vec<u8>,
    successor_vote_locks: BTreeMap<String, String>,
}

impl AuthenticatedAdmissionCheckpointVoteLockV1 {
    pub fn proposal_hash(&self) -> &str {
        &self.proposal_hash
    }
}

