impl Ledger {
    #[allow(dead_code)]
    fn stake_context_at(
        &self,
        finalized_height: u128,
        finalized_state_root: String,
    ) -> StakeLedgerContextV1 {
        StakeLedgerContextV1 {
            network_domain: self.descriptor.network_domain.clone(),
            zone_id: self.descriptor.zone_id.clone(),
            currency_genesis_root: self.descriptor.currency_genesis_root.clone(),
            protocol_era: self.descriptor.protocol_era,
            crypto_era: self.descriptor.crypto_era,
            consensus_protocol_version: CONSENSUS_PROTOCOL_VERSION_V1,
            finalized_height,
            finalized_state_root,
        }
    }

    fn ensure_stake_positions_registered(
        &self,
        positions: &[ConsensusStakePosition],
    ) -> Result<(), LedgerError> {
        for position in positions {
            if self.consensus_stake_escrows.get(&position.escrow_coin_id) != Some(position) {
                return Err(LedgerError::Invalid(format!(
                    "stake position {} has no exact owner-authorized escrow registration",
                    position.position_id
                )));
            }
        }
        Ok(())
    }

    fn validate_consensus_stake_escrows(&self) -> Result<(), LedgerError> {
        let mut escrow_ids = BTreeSet::new();
        let mut source_ids = BTreeSet::new();
        let mut position_ids = BTreeSet::new();
        for (escrow_id, position) in &self.consensus_stake_escrows {
            if escrow_id != &position.escrow_coin_id
                || !position_ids.insert(position.position_id.as_str())
                || !escrow_ids.insert(position.escrow_coin_id.as_str())
                || !source_ids.insert(position.source_coin_id.as_str())
            {
                return Err(LedgerError::Invalid(
                    "stake escrow registry key, source or escrow is duplicated".into(),
                ));
            }
            let source = self
                .coins
                .get(&position.source_coin_id)
                .ok_or_else(|| LedgerError::CoinNotFound(position.source_coin_id.clone()))?;
            let escrow = self
                .coins
                .get(&position.escrow_coin_id)
                .ok_or_else(|| LedgerError::CoinNotFound(position.escrow_coin_id.clone()))?;
            let expected_version = Self::checked_next_coin_version(source.version)?;
            if source.state != CoinState::Consumed
                || source.owner != position.owner
                || source.amount < position.amount
                || escrow.state != CoinState::Reserved
                || escrow.owner != position.owner
                || escrow.amount != position.amount
                || escrow.parent_ids != [position.source_coin_id.clone()]
                || escrow.lineage_root != source.lineage_root
                || escrow.version != expected_version
                || u128::from(escrow.created_height) != position.locked_height
                || escrow.transit_id.is_some()
                || escrow.zone_id != self.descriptor.zone_id
                || escrow.origin_genesis_root != self.descriptor.currency_genesis_root
            {
                return Err(LedgerError::Invalid(format!(
                    "stake escrow {} does not match its consumed source Coin and position",
                    position.position_id
                )));
            }
        }
        let mut unbonded_positions = BTreeSet::new();
        let mut completion_ids = BTreeSet::new();
        for (request_id, record) in &self.consensus_stake_unbonds {
            if request_id != &record.request_id
                || record.owner != record.position.owner
                || record.beneficiary != record.owner
                || record.request_commitment != record.compute_request_commitment()
                || !unbonded_positions.insert(record.position.position_id.as_str())
            {
                return Err(LedgerError::Invalid(
                    "stake unbond record identity, owner or commitment mismatch".into(),
                ));
            }
            let escrow = self
                .coins
                .get(&record.position.escrow_coin_id)
                .ok_or_else(|| LedgerError::CoinNotFound(record.position.escrow_coin_id.clone()))?;
            match record.status {
                ConsensusStakeUnbondStatusV1::Pending => {
                    if record.completion_id.is_some()
                        || record.completed_height.is_some()
                        || record.payout_coin_id.is_some()
                        || record.slash_id.is_some()
                        || !record.slashed_amount.is_zero()
                        || self
                            .consensus_stake_escrows
                            .get(&record.position.escrow_coin_id)
                            != Some(&record.position)
                        || escrow.state != CoinState::Reserved
                    {
                        return Err(LedgerError::Invalid(
                            "pending stake unbond does not retain its exact Reserved escrow".into(),
                        ));
                    }
                }
                ConsensusStakeUnbondStatusV1::Completed => {
                    let completion_id = record.completion_id.as_deref().ok_or_else(|| {
                        LedgerError::Invalid("completed stake unbond has no completion id".into())
                    })?;
                    if !completion_ids.insert(completion_id)
                        || record.completed_height.is_none()
                        || record.slash_id.is_some()
                        || !record.slashed_amount.is_zero()
                        || self
                            .consensus_stake_escrows
                            .contains_key(&record.position.escrow_coin_id)
                        || escrow.state != CoinState::Consumed
                    {
                        return Err(LedgerError::Invalid(
                            "completed stake unbond retained an active escrow or invalid state"
                                .into(),
                        ));
                    }
                    let payout_id = record.payout_coin_id.as_ref().ok_or_else(|| {
                        LedgerError::Invalid("completed stake unbond has no payout Coin".into())
                    })?;
                    let payout = self
                        .coins
                        .get(payout_id)
                        .ok_or_else(|| LedgerError::CoinNotFound(payout_id.clone()))?;
                    if !matches!(payout.state, CoinState::Spendable | CoinState::Consumed)
                        || payout.owner != record.beneficiary
                        || payout.amount != record.position.amount
                        || payout.parent_ids != [record.position.escrow_coin_id.clone()]
                        || payout.lineage_root != escrow.lineage_root
                        || payout.version != Self::checked_next_coin_version(escrow.version)?
                        || payout.created_height != record.completed_height.unwrap()
                        || payout.transit_id.is_some()
                    {
                        return Err(LedgerError::Invalid(
                            "completed stake unbond payout does not match its escrow".into(),
                        ));
                    }
                }
                ConsensusStakeUnbondStatusV1::FullySlashed => {
                    let slash_id = record.slash_id.as_deref().ok_or_else(|| {
                        LedgerError::Invalid("fully slashed unbond has no slash id".into())
                    })?;
                    if record.completion_id.is_some()
                        || record.completed_height.is_none()
                        || record.payout_coin_id.is_some()
                        || record.slashed_amount != record.position.amount
                        || self
                            .consensus_stake_escrows
                            .contains_key(&record.position.escrow_coin_id)
                        || escrow.state != CoinState::Consumed
                        || self
                            .consensus_stake_slashes
                            .get(slash_id)
                            .is_none_or(|slash| slash.position != record.position)
                    {
                        return Err(LedgerError::Invalid(
                            "fully slashed unbond retained value or lost its slash lineage".into(),
                        ));
                    }
                }
            }
        }
        if let Some(authority) = &self.consensus_stake_authority {
            self.ensure_stake_positions_registered(&authority.positions)?;
            if authority.positions.iter().any(|position| {
                self.consensus_stake_unbonds
                    .values()
                    .any(|record| record.position.position_id == position.position_id)
            }) {
                return Err(LedgerError::Invalid(
                    "stake authority reintroduced a position with an unbond request".into(),
                ));
            }
        }
        Ok(())
    }

    fn validate_stake_position_liability_horizons(&self) -> Result<(), LedgerError> {
        let current_empty = self.stake_position_liability_horizons.is_empty();
        let history_empty = self.stake_position_liability_horizon_history.is_empty();
        if current_empty && history_empty {
            if self.stake_liability_horizon_activation_epoch.is_some() {
                return Err(LedgerError::Invalid(
                    "empty stake liability horizon has an activation Epoch".into(),
                ));
            }
            // Historical pre-horizon ledgers remain byte-for-byte replayable.
            // Resource-bound unbond V2 will require a populated exact index.
            return Ok(());
        }
        let activation_epoch = self
            .stake_liability_horizon_activation_epoch
            .filter(|epoch| *epoch != 0 && self.derived_stake_epochs.contains_key(epoch));
        if current_empty != history_empty || activation_epoch.is_none() {
            return Err(LedgerError::Invalid(
                "stake liability horizon index, history or activation Epoch diverges".into(),
            ));
        }
        let (expected_current, expected_history) =
            rebuild_stake_position_liability_horizons_v1(self.derived_stake_epochs.values())
                .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if self.stake_position_liability_horizons != expected_current
            || self.stake_position_liability_horizon_history != expected_history
        {
            return Err(LedgerError::Invalid(
                "stake liability horizons do not exactly rebuild from retained Epochs".into(),
            ));
        }
        Ok(())
    }

    fn preview_stake_liability_horizon_update(
        &self,
        record: &LedgerDerivedStakeEpochV1,
    ) -> Result<StakePositionLiabilityHorizonStateV1, LedgerError> {
        self.validate_stake_position_liability_horizons()?;
        if self.stake_position_liability_horizons.is_empty() {
            let mut epochs = self.derived_stake_epochs.clone();
            if epochs
                .insert(record.descriptor.consensus_epoch, record.clone())
                .is_some()
            {
                return Err(LedgerError::Invalid(
                    "liability horizon preview would replace an Epoch".into(),
                ));
            }
            rebuild_stake_position_liability_horizons_v1(epochs.values())
                .map_err(|error| LedgerError::StakeResource(error.to_string()))
        } else {
            let mut horizons = self.stake_position_liability_horizons.clone();
            let mut history = self.stake_position_liability_horizon_history.clone();
            extend_stake_position_liability_horizons_v1(&mut horizons, &mut history, record)
                .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
            Ok((horizons, history))
        }
    }

    fn recorded_stake_liability_horizon_usage(
        &self,
        consensus_epoch: u64,
    ) -> Result<StakeLiabilityHorizonUsageDeltaV1, LedgerError> {
        let Some(activation_epoch) = self.stake_liability_horizon_activation_epoch else {
            return Ok(StakeLiabilityHorizonUsageDeltaV1::default());
        };
        if consensus_epoch < activation_epoch {
            return Ok(StakeLiabilityHorizonUsageDeltaV1::default());
        }
        let empty_current = BTreeMap::new();
        let empty_history = BTreeMap::new();
        let (previous_current, previous_history) = if consensus_epoch == activation_epoch {
            (empty_current, empty_history)
        } else {
            rebuild_stake_position_liability_horizons_v1(
                self.derived_stake_epochs
                    .values()
                    .filter(|record| record.descriptor.consensus_epoch < consensus_epoch),
            )
            .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?
        };
        let (next_current, next_history) = rebuild_stake_position_liability_horizons_v1(
            self.derived_stake_epochs
                .values()
                .filter(|record| record.descriptor.consensus_epoch <= consensus_epoch),
        )
        .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?;
        stake_liability_horizon_usage_delta_v1(
            &previous_current,
            &previous_history,
            &next_current,
            &next_history,
        )
        .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))
    }

    fn validate_consensus_stake_slashes(&self) -> Result<(), LedgerError> {
        if self.consensus_stake_slashes.len() != self.consensus_stake_evidence_nullifiers.len() {
            return Err(LedgerError::Invalid(
                "stake slash records and evidence nullifiers diverge".into(),
            ));
        }
        let mut evidence_nullifiers = BTreeSet::new();
        let mut positions = BTreeSet::new();
        let mut safety_coins = BTreeSet::new();
        for (slash_id, record) in &self.consensus_stake_slashes {
            let evidence_nullifier = consensus_stake_slash_nullifier_v1(
                &record.evidence_hash,
                &record.liability_commitment,
            );
            let epoch = self
                .derived_stake_epochs
                .get(&record.consensus_epoch)
                .filter(|epoch| epoch.record_hash == record.derived_epoch_record_hash);
            let liability = epoch.and_then(|epoch| {
                epoch
                    .stake_liabilities
                    .iter()
                    .find(|liability| liability.liability_commitment == record.liability_commitment)
            });
            let verified_evidence = epoch.and_then(|epoch| {
                verify_consensus_stake_slash_evidence_v1(
                    epoch,
                    &record.position.position_id,
                    &record.liability_commitment,
                    &record.evidence,
                )
                .ok()
            });
            if slash_id != &record.slash_id
                || record.record_hash != record.compute_record_hash()
                || !evidence_nullifiers.insert(evidence_nullifier.clone())
                || !positions.insert(record.position.position_id.as_str())
                || !safety_coins.insert(record.safety_pool_coin_id.as_str())
                || !self
                    .consensus_stake_evidence_nullifiers
                    .contains(&evidence_nullifier)
                || record.slash_bps != 10_000
                || record.slashed_amount != record.position.amount
                || record.source_escrow_coin_id != record.position.escrow_coin_id
                || self
                    .consensus_stake_escrows
                    .contains_key(&record.source_escrow_coin_id)
                || liability.is_none_or(|liability| {
                    liability.position != record.position
                        || u128::from(record.applied_height) < liability.activation_height
                        || u128::from(record.applied_height) >= liability.evidence_deadline_height
                })
                || verified_evidence.as_ref().is_none_or(|verified| {
                    verified.evidence_hash != record.evidence_hash
                        || verified.kind != record.evidence_kind
                        || verified.slash_bps != record.slash_bps
                        || verified.fault_height > u128::from(record.applied_height)
                })
            {
                return Err(LedgerError::Invalid(
                    "stake slash identity, evidence, liability, amount, nullifier or source mismatch"
                        .into(),
                ));
            }
            let source = self
                .coins
                .get(&record.source_escrow_coin_id)
                .ok_or_else(|| LedgerError::CoinNotFound(record.source_escrow_coin_id.clone()))?;
            let safety = self
                .coins
                .get(&record.safety_pool_coin_id)
                .ok_or_else(|| LedgerError::CoinNotFound(record.safety_pool_coin_id.clone()))?;
            if source.state != CoinState::Consumed
                || safety.state != CoinState::Reserved
                || safety.owner != CONSENSUS_SLASH_SAFETY_POOL_V2
                || safety.amount != record.slashed_amount
                || safety.parent_ids != [source.object_id.clone()]
                || safety.lineage_root != source.lineage_root
                || safety.version != Self::checked_next_coin_version(source.version)?
                || safety.created_height != record.applied_height
                || safety.transit_id.is_some()
            {
                return Err(LedgerError::Invalid(
                    "stake slash safety-pool Coin does not preserve exact escrow lineage".into(),
                ));
            }
        }
        Ok(())
    }

    /// Installs one already-authorized, canonical, predecessor-linked
    /// stake-authority view into ledger state.  Callers must validate the
    /// content-addressed governance wrapper before reaching this mutation.
    pub(crate) fn stage_ledger_stake_authority(
        &mut self,
        update: LedgerStakeAuthorityUpdateV1,
    ) -> Result<LedgerStakeAuthorityStateV1, LedgerError> {
        let source_height = u128::from(self.height);
        let source_state_root = self.state_root()?;
        let effective_height = source_height
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("stake authority height overflow".into()))?;
        let context = self.stake_context_at(source_height, source_state_root);
        self.ensure_stake_positions_registered(&update.positions)?;
        let state = build_ledger_stake_authority_state_v1(
            &context,
            effective_height,
            self.consensus_stake_authority.as_ref(),
            update,
            &self.coins,
        )
        .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        self.ensure_counter_headroom(1, 0)?;
        self.advance()?;
        self.consensus_stake_authority = Some(state.clone());
        Ok(state)
    }

    /// Derives and stores exactly the next candidate Epoch from the current
    /// ledger-owned authority state and pre-transition state root. The record
    /// remains `DERIVED_ONLY`; this method never changes runtime membership.
    pub(crate) fn derive_and_store_next_stake_epoch(
        &mut self,
    ) -> Result<LedgerDerivedStakeEpochV1, LedgerError> {
        let authority = self
            .consensus_stake_authority
            .clone()
            .ok_or_else(|| LedgerError::Invalid("ledger has no staged stake authority".into()))?;
        validate_ledger_stake_authority_state_v1(&authority)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        self.ensure_stake_positions_registered(&authority.positions)?;
        if u128::from(self.height) < authority.effective_height {
            return Err(LedgerError::Invalid(
                "stake authority is not yet effective".into(),
            ));
        }

        let snapshot_height = u128::from(self.height);
        let snapshot_state_root = self.state_root()?;
        let context = self.stake_context_at(snapshot_height, snapshot_state_root.clone());
        let previous = self.derived_stake_epochs.values().next_back();
        let (consensus_epoch, activation_height, record_chain_anchor) =
            if let Some(previous) = previous {
                (
                    previous
                        .descriptor
                        .consensus_epoch
                        .checked_add(1)
                        .ok_or_else(|| LedgerError::Invalid("stake Epoch overflow".into()))?,
                    previous.descriptor.exit_height,
                    previous.record_hash.clone(),
                )
            } else {
                (
                    1,
                    snapshot_height
                        .checked_add(authority.policy.activation_delay_blocks)
                        .ok_or_else(|| {
                            LedgerError::Invalid("stake activation height overflow".into())
                        })?,
                    ledger_stake_authority_genesis_anchor_v1(&context),
                )
            };
        let anchor = ConsensusEpochAnchor {
            consensus_epoch,
            activation_height,
            stake_snapshot_height: snapshot_height,
            stake_snapshot_state_root: snapshot_state_root,
            record_chain_anchor,
        };
        let record = derive_ledger_stake_epoch_v1(
            &context,
            &authority.policy,
            &anchor,
            previous,
            &authority.candidates,
            &authority.positions,
            &authority.ubo_control,
            &self.coins,
        )
        .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if self
            .derived_stake_epochs
            .contains_key(&record.descriptor.consensus_epoch)
        {
            return Err(LedgerError::Duplicate(format!(
                "stake-epoch-{}",
                record.descriptor.consensus_epoch
            )));
        }
        self.ensure_counter_headroom(1, 0)?;
        self.advance()?;
        self.derived_stake_epochs
            .insert(record.descriptor.consensus_epoch, record.clone());
        Ok(record)
    }

    fn reconstruct_stake_authority_command_state(
        &self,
        request: &StakeAuthorityGovernanceUpdateV1,
        source_height: u128,
        source_state_root: String,
        effective_height: u128,
    ) -> Result<LedgerStakeAuthorityStateV1, LedgerError> {
        let update = request.to_ledger_update().map_err(LedgerError::Invalid)?;
        let state = LedgerStakeAuthorityStateV1 {
            authority_version: update.authority_version,
            status: StakeAuthorityStateStatus::StagedOnly,
            network_domain: self.descriptor.network_domain.clone(),
            zone_id: request.zone_id.clone(),
            currency_genesis_root: request.currency_genesis_root.clone(),
            protocol_era: request.protocol_era,
            crypto_era: request.crypto_era,
            consensus_protocol_version: CONSENSUS_PROTOCOL_VERSION_V1,
            sequence: update.sequence,
            previous_commitment: update.expected_previous_commitment,
            source_height,
            source_state_root,
            effective_height,
            policy: update.policy,
            candidates: update.candidates,
            positions: update.positions,
            ubo_control: update.ubo_control,
            commitment: request.prospective_authority_commitment.clone(),
        };
        validate_ledger_stake_authority_state_v1(&state)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        Ok(state)
    }

    /// Stages a ledger-owned authority view through a dual-governance command.
    /// This command cannot activate runtime membership and is permitted only
    /// while the real-value gate remains closed.
    pub fn submit_stake_authority_update(
        &mut self,
        request: StakeAuthorityGovernanceUpdateV1,
    ) -> Result<LedgerStakeAuthorityStateV1, LedgerError> {
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "stake authority staging requires VALUE_CAP_0".into(),
            ));
        }
        if request.update_id.trim().is_empty() {
            return Err(LedgerError::Invalid(
                "stake authority update id is required".into(),
            ));
        }
        if request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "stake authority Zone, currency or era binding mismatch".into(),
            ));
        }
        if request.proposed_height != self.height {
            return Err(LedgerError::Invalid(
                "stake authority proposal height does not match current state".into(),
            ));
        }
        if request.expires_at_height <= self.height {
            return Err(LedgerError::Invalid(
                "stake authority governance request expired".into(),
            ));
        }
        if self
            .descriptor
            .validator_keys
            .iter()
            .any(|key| self.descriptor.notary_keys.contains(key))
        {
            return Err(LedgerError::InvalidQuorum(
                "validator and independent notary sets overlap".into(),
            ));
        }

        let update = request.to_ledger_update().map_err(LedgerError::Invalid)?;
        if self.consensus_stake_authority.is_some() {
            return Err(LedgerError::Invalid(
                "broad stake governance is bootstrap-only and cannot change candidate lifecycle, policy, positions or UBO after bootstrap".into(),
            ));
        }
        let source_height = u128::from(self.height);
        let source_state_root = self.state_root()?;
        let effective_height = source_height
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("stake authority height overflow".into()))?;
        let context = self.stake_context_at(source_height, source_state_root);
        let prospective = build_ledger_stake_authority_state_v1(
            &context,
            effective_height,
            self.consensus_stake_authority.as_ref(),
            update.clone(),
            &self.coins,
        )
        .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if request.prospective_authority_commitment != prospective.commitment {
            return Err(LedgerError::Invalid(
                "prospective stake authority commitment mismatch".into(),
            ));
        }
        let subject = request.compute_subject_hash();
        if request.subject_hash != subject {
            return Err(LedgerError::Invalid(
                "stake authority governance subject commitment mismatch".into(),
            ));
        }
        self.verify_local_dual_quorum(&subject, &request.validator_qc, &request.notary_qc)?;
        self.ensure_stake_positions_registered(&update.positions)?;

        let mut staged = self.clone();
        let stored = staged.stage_ledger_stake_authority(update)?;
        if stored != prospective {
            return Err(LedgerError::Invalid(
                "stake authority changed between validation and storage".into(),
            ));
        }
        staged.assert_conservation()?;
        *self = staged;
        Ok(stored)
    }

    /// Atomically consumes one owner-authorized spendable Coin, creates a
    /// stake-specific reserved escrow and advances the staged authority view.
    /// Runtime validator membership remains unchanged.
    pub fn lock_consensus_stake(
        &mut self,
        request: LockConsensusStakeRequestV1,
    ) -> Result<ConsensusStakePosition, LedgerError> {
        if self.stake_resource_accounting.is_some() {
            return Err(LedgerError::StakeResource(
                "legacy consensus stake locking is disabled after resource-policy activation; use V3"
                    .into(),
            ));
        }
        let mut staged = self.clone();
        let payload_hash = request.payload_hash();
        let position = staged.apply_consensus_stake_lock(ConsensusStakeLockInput {
            position_id: request.position_id,
            zone_id: request.zone_id,
            currency_genesis_root: request.currency_genesis_root,
            protocol_era: request.protocol_era,
            crypto_era: request.crypto_era,
            proposed_height: request.proposed_height,
            expires_at_height: request.expires_at_height,
            expected_authority_sequence: request.expected_authority_sequence,
            expected_authority_commitment: request.expected_authority_commitment,
            position_type: request.position_type,
            validator_id: request.validator_id,
            owner: request.owner,
            source_coin_id: request.source_coin_id,
            amount: request.amount,
            committed_through_height: request.committed_through_height,
            action: LOCK_CONSENSUS_STAKE_ACTION_V1,
            payload_hash,
            slash_terms_authorization: None,
            authorization: request.authorization,
        })?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(position)
    }

    pub fn lock_consensus_stake_v2(
        &mut self,
        request: LockConsensusStakeRequestV2,
    ) -> Result<ConsensusStakePosition, LedgerError> {
        if self.stake_resource_accounting.is_some() {
            return Err(LedgerError::StakeResource(
                "unmetered V2 consensus stake locking is disabled after resource-policy activation; use V3"
                    .into(),
            ));
        }
        let mut staged = self.clone();
        let payload_hash = request.payload_hash();
        let position = staged.apply_consensus_stake_lock(ConsensusStakeLockInput {
            position_id: request.position_id,
            zone_id: request.zone_id,
            currency_genesis_root: request.currency_genesis_root,
            protocol_era: request.protocol_era,
            crypto_era: request.crypto_era,
            proposed_height: request.proposed_height,
            expires_at_height: request.expires_at_height,
            expected_authority_sequence: request.expected_authority_sequence,
            expected_authority_commitment: request.expected_authority_commitment,
            position_type: request.position_type,
            validator_id: request.validator_id,
            owner: request.owner,
            source_coin_id: request.source_coin_id,
            amount: request.amount,
            committed_through_height: request.committed_through_height,
            action: LOCK_CONSENSUS_STAKE_ACTION_V2,
            payload_hash,
            slash_terms_authorization: Some(request.slash_terms_authorization),
            authorization: request.authorization,
        })?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(position)
    }

    fn apply_consensus_stake_lock(
        &mut self,
        request: ConsensusStakeLockInput,
    ) -> Result<ConsensusStakePosition, LedgerError> {
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "consensus stake locking requires VALUE_CAP_0".into(),
            ));
        }
        if request.position_id.trim().is_empty()
            || request.validator_id.trim().is_empty()
            || request.owner.trim().is_empty()
            || request.source_coin_id.trim().is_empty()
            || request.amount.is_zero()
        {
            return Err(LedgerError::Invalid(
                "consensus stake lock request is incomplete".into(),
            ));
        }
        if request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "consensus stake lock Zone, currency or era binding mismatch".into(),
            ));
        }
        if request.proposed_height != self.height {
            return Err(LedgerError::Invalid(
                "consensus stake lock height does not match current state".into(),
            ));
        }
        if request.expires_at_height <= self.height {
            return Err(LedgerError::Invalid(
                "consensus stake lock request expired".into(),
            ));
        }
        if self
            .consensus_stake_escrows
            .values()
            .any(|position| position.position_id == request.position_id)
        {
            return Err(LedgerError::Duplicate(request.position_id));
        }

        let authority = self
            .consensus_stake_authority
            .clone()
            .ok_or_else(|| LedgerError::Invalid("ledger has no staged stake authority".into()))?;
        validate_ledger_stake_authority_state_v1(&authority)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if authority.sequence != request.expected_authority_sequence
            || authority.commitment != request.expected_authority_commitment
        {
            return Err(LedgerError::Invalid(
                "consensus stake authority precondition mismatch".into(),
            ));
        }
        if authority
            .positions
            .iter()
            .any(|position| position.position_id == request.position_id)
        {
            return Err(LedgerError::Duplicate(request.position_id));
        }
        if authority.policy.policy_version == 2 && request.slash_terms_authorization.is_none() {
            return Err(LedgerError::Invalid(
                "derivation-policy v2 forbids legacy unslashable stake admission".into(),
            ));
        }
        let candidate = authority
            .candidates
            .iter()
            .find(|candidate| candidate.validator_id == request.validator_id)
            .ok_or_else(|| {
                LedgerError::Invalid("stake target is not a staged validator candidate".into())
            })?;
        if candidate.exit_height.is_some() {
            return Err(LedgerError::Invalid(
                "new stake cannot target a validator candidate that has requested exit".into(),
            ));
        }
        match request.position_type {
            StakePositionTypeV1::SelfBond => {
                if request.owner != candidate.owner {
                    return Err(LedgerError::OwnerMismatch);
                }
                if request.amount < authority.policy.minimum_self_bond {
                    return Err(LedgerError::Invalid(
                        "self-bond is below the staged policy minimum".into(),
                    ));
                }
            }
            StakePositionTypeV1::Delegation => {
                if request.amount < authority.policy.minimum_delegation {
                    return Err(LedgerError::Invalid(
                        "delegation is below the staged policy minimum".into(),
                    ));
                }
            }
        }

        let lock_height = u128::from(self.height)
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("stake lock height overflow".into()))?;
        let stake_mature_height = lock_height
            .checked_add(authority.policy.stake_maturity_blocks)
            .ok_or_else(|| LedgerError::Invalid("stake maturity height overflow".into()))?;
        let candidate_mature_height = candidate
            .registered_height
            .checked_add(authority.policy.candidate_maturity_blocks)
            .ok_or_else(|| LedgerError::Invalid("candidate maturity height overflow".into()))?;
        let minimum_commitment_height = stake_mature_height
            .max(candidate_mature_height)
            .checked_add(authority.policy.activation_delay_blocks)
            .and_then(|height| height.checked_add(authority.policy.epoch_length_blocks))
            .and_then(|height| height.checked_add(authority.policy.evidence_window_blocks))
            .ok_or_else(|| LedgerError::Invalid("stake commitment height overflow".into()))?;
        if u128::from(request.committed_through_height) < minimum_commitment_height {
            return Err(LedgerError::Invalid(
                "stake commitment does not cover maturity, one Epoch and its evidence window"
                    .into(),
            ));
        }

        let position_kind = match request.position_type {
            StakePositionTypeV1::SelfBond => ConsensusStakePositionKind::SelfBond {
                validator_id: request.validator_id.clone(),
            },
            StakePositionTypeV1::Delegation => ConsensusStakePositionKind::Delegation {
                validator_id: request.validator_id.clone(),
            },
        };
        self.verify_owner_authorization(
            &request.authorization,
            &request.owner,
            request.action,
            &request.payload_hash,
        )?;
        let slash_terms = if let Some(authorization) = &request.slash_terms_authorization {
            if authorization.authorization_id == request.authorization.authorization_id {
                return Err(LedgerError::Duplicate(
                    authorization.authorization_id.clone(),
                ));
            }
            let slash_policy = ConsensusStakeSlashPolicyV2::protocol_v2();
            let payload_hash = consensus_stake_slash_terms_payload_hash_v2(
                &request.position_id,
                &position_kind,
                &request.owner,
                &request.source_coin_id,
                request.amount,
                u128::from(request.committed_through_height),
                &slash_policy,
            );
            self.verify_owner_authorization(
                authorization,
                &request.owner,
                ACCEPT_CONSENSUS_STAKE_SLASH_TERMS_ACTION_V2,
                &payload_hash,
            )?;
            Some(ConsensusStakeSlashTermsV2 {
                terms_version: slash_policy.policy_version,
                slash_policy,
                owner_authorization: authorization.clone(),
            })
        } else {
            None
        };
        let input = self
            .coins
            .get(&request.source_coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(request.source_coin_id.clone()))?;
        if input.state != CoinState::Spendable || input.owner != request.owner {
            return Err(LedgerError::CoinNotSpendable);
        }
        if request.amount > input.amount {
            return Err(LedgerError::Invalid(
                "stake amount exceeds its spendable input".into(),
            ));
        }
        if self.consensus_stake_escrows.values().any(|position| {
            position.source_coin_id == request.source_coin_id
                || position.escrow_coin_id == request.source_coin_id
        }) {
            return Err(LedgerError::Duplicate(request.source_coin_id));
        }

        self.ensure_counter_headroom(1, 2)?;
        let source_height = u128::from(self.height);
        let source_state_root = self.state_root()?;
        let next_version = Self::checked_next_coin_version(input.version)?;
        self.consume_authorization(&request.authorization)?;
        if let Some(authorization) = &request.slash_terms_authorization {
            self.consume_authorization(authorization)?;
        }
        self.advance()?;
        self.consume_coin(&input.object_id)?;
        let escrow = self.make_coin(
            request.owner.clone(),
            request.amount,
            CoinState::Reserved,
            vec![input.object_id.clone()],
            Some(input.lineage_root.clone()),
            None,
            input.imported_from.clone(),
            next_version,
        )?;
        self.coins.insert(escrow.object_id.clone(), escrow.clone());
        let change = input.amount.checked_sub(request.amount)?;
        if !change.is_zero() {
            let change_coin = self.make_coin(
                request.owner.clone(),
                change,
                CoinState::Spendable,
                vec![input.object_id.clone()],
                Some(input.lineage_root.clone()),
                None,
                input.imported_from.clone(),
                next_version,
            )?;
            self.coins
                .insert(change_coin.object_id.clone(), change_coin);
        }
        let position = ConsensusStakePosition {
            position_id: request.position_id.clone(),
            kind: position_kind,
            owner: request.owner,
            source_coin_id: input.object_id,
            escrow_coin_id: escrow.object_id,
            amount: request.amount,
            locked_height: u128::from(self.height),
            committed_through_height: u128::from(request.committed_through_height),
            slash_terms,
        };
        self.consensus_stake_escrows
            .insert(position.escrow_coin_id.clone(), position.clone());

        let mut positions = authority.positions.clone();
        positions.push(position.clone());
        let mut ubo_control = authority.ubo_control.clone();
        ubo_control.predecessor_commitment = ubo_control_commitment_v1(&authority.ubo_control)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        ubo_control.sequence = ubo_control
            .sequence
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("stake UBO sequence overflow".into()))?;
        let update = LedgerStakeAuthorityUpdateV1 {
            authority_version: authority.authority_version,
            sequence: authority
                .sequence
                .checked_add(1)
                .ok_or_else(|| LedgerError::Invalid("stake authority sequence overflow".into()))?,
            expected_previous_commitment: authority.commitment.clone(),
            policy: authority.policy.clone(),
            candidates: authority.candidates.clone(),
            positions,
            ubo_control,
        };
        let context = self.stake_context_at(source_height, source_state_root);
        let next_authority = build_ledger_stake_authority_state_v1(
            &context,
            u128::from(self.height),
            Some(&authority),
            update,
            &self.coins,
        )
        .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        self.consensus_stake_authority = Some(next_authority);
        Ok(position)
    }

    fn prepare_position_resource_admission(
        &self,
        request: StakeStateResourceAdmissionRequestV1,
        admission_height: u64,
    ) -> Result<
        (
            StakeStateResourceAccountingV1,
            StakeStateResourceAdmissionOutcomeV1,
        ),
        LedgerError,
    > {
        let funding_coin = self
            .coins
            .get(&request.envelope.funding_coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(request.envelope.funding_coin_id.clone()))?;
        let mut protected_coin_ids = self
            .consensus_stake_escrows
            .keys()
            .cloned()
            .collect::<BTreeSet<_>>();
        let mut accounting = self
            .stake_resource_accounting
            .clone()
            .ok_or_else(|| LedgerError::StakeResource("no active stake resource policy".into()))?;
        protected_coin_ids.extend(
            accounting
                .bonds()
                .values()
                .map(|record| record.bond_coin_id.clone()),
        );
        let admission = accounting
            .admit(
                request,
                &funding_coin,
                &protected_coin_ids,
                admission_height,
            )
            .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
        Ok((accounting, admission))
    }

    fn commit_position_resource_admission(
        &mut self,
        accounting: StakeStateResourceAccountingV1,
        admission: &StakeStateResourceAdmissionOutcomeV1,
        sponsor_authorization: &SignedActionAuthorization,
    ) -> Result<(), LedgerError> {
        let mut output_ids = BTreeSet::new();
        for coin in std::iter::once(&admission.bond_coin).chain(admission.change_coin.iter()) {
            if !output_ids.insert(coin.object_id.as_str())
                || self.coins.contains_key(&coin.object_id)
                || coin.object_id == admission.consumed_funding_coin.object_id
            {
                return Err(LedgerError::Duplicate(coin.object_id.clone()));
            }
        }
        let funding = self
            .coins
            .get(&admission.consumed_funding_coin.object_id)
            .ok_or_else(|| {
                LedgerError::CoinNotFound(admission.consumed_funding_coin.object_id.clone())
            })?;
        if funding.state != CoinState::Spendable
            || funding.version != admission.consumed_funding_coin.version
            || funding.amount != admission.consumed_funding_coin.amount
            || funding.owner != admission.consumed_funding_coin.owner
        {
            return Err(LedgerError::StakeResource(
                "resource funding Coin changed between admission and atomic commit".into(),
            ));
        }
        self.consume_authorization(sponsor_authorization)?;
        self.coins.insert(
            admission.consumed_funding_coin.object_id.clone(),
            admission.consumed_funding_coin.clone(),
        );
        self.coins.insert(
            admission.bond_coin.object_id.clone(),
            admission.bond_coin.clone(),
        );
        if let Some(change_coin) = &admission.change_coin {
            self.coins
                .insert(change_coin.object_id.clone(), change_coin.clone());
        }
        self.stake_resource_accounting = Some(accounting);
        Ok(())
    }

    /// Atomically creates one slashable stake position and a separately funded
    /// state-responsibility bond. The caller cannot provide resource counters,
    /// and the resource funding Coin cannot alias the stake principal.
    pub fn lock_consensus_stake_v3(
        &mut self,
        request: LockConsensusStakeRequestV3,
    ) -> Result<LockConsensusStakeOutcomeV3, LedgerError> {
        let mut staged = self.clone();
        let outcome = staged.apply_consensus_stake_lock_v3(request)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(outcome)
    }

    fn apply_consensus_stake_lock_v3(
        &mut self,
        request: LockConsensusStakeRequestV3,
    ) -> Result<LockConsensusStakeOutcomeV3, LedgerError> {
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "resource-bound consensus stake locking requires VALUE_CAP_0".into(),
            ));
        }
        if request.source_coin_id == request.resource_envelope.funding_coin_id {
            return Err(LedgerError::StakeResource(
                "stake principal and resource funding must be distinct Coins".into(),
            ));
        }
        let sponsor_authorization = &request.resource_envelope.authorization;
        let authorization_ids = [
            request.authorization.authorization_id.as_str(),
            request.slash_terms_authorization.authorization_id.as_str(),
            sponsor_authorization.authorization_id.as_str(),
        ];
        if authorization_ids[0] == authorization_ids[1]
            || authorization_ids[0] == authorization_ids[2]
            || authorization_ids[1] == authorization_ids[2]
            || self
                .authorization_nullifiers
                .contains(sponsor_authorization.authorization_id.as_str())
        {
            return Err(LedgerError::Duplicate(
                sponsor_authorization.authorization_id.clone(),
            ));
        }
        let accounting = self
            .stake_resource_accounting
            .as_ref()
            .ok_or_else(|| LedgerError::StakeResource("no active stake resource policy".into()))?;
        self.validate_stake_resource_policy_covers_inventory(
            accounting.active_policy(),
            None,
            Some(&request.owner),
        )?;
        let required_lease_end = request
            .committed_through_height
            .checked_add(accounting.active_policy().terminal_retention_blocks)
            .ok_or_else(|| LedgerError::StakeResource("position resource lease overflow".into()))?;
        if request.resource_envelope.lease_end_height < required_lease_end {
            return Err(LedgerError::StakeResource(
                "position resource lease does not cover stake liability plus terminal retention"
                    .into(),
            ));
        }
        let source = self
            .coins
            .get(&request.source_coin_id)
            .ok_or_else(|| LedgerError::CoinNotFound(request.source_coin_id.clone()))?;
        if source.zone_id != self.descriptor.zone_id
            || source.origin_genesis_root != self.descriptor.currency_genesis_root
            || !is_canonical_sha256_hex(&source.lineage_root)
            || source.transit_id.is_some()
        {
            return Err(LedgerError::Invalid(
                "stake principal Coin has noncanonical Zone, currency, lineage or transit state"
                    .into(),
            ));
        }
        let wire_bytes = ConsensusCommand::LockConsensusStakeV3(Box::new(request.clone()))
            .wire_v1_command_bytes(&self.descriptor.network_domain)
            .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
        let usage = StakeStateResourceUsageV1 {
            wire_bytes: u32::try_from(wire_bytes.len()).map_err(|_| {
                LedgerError::StakeResource("stake V3 command exceeds the u32 wire meter".into())
            })?,
            persistent_bytes: lock_consensus_stake_persistent_bytes_v3(&request)
                .map_err(|error| LedgerError::StakeResource(error.to_string()))?,
            signature_checks: LOCK_CONSENSUS_STAKE_SIGNATURE_CHECKS_V3,
            state_reads: LOCK_CONSENSUS_STAKE_STATE_READS_V3,
            state_writes: LOCK_CONSENSUS_STAKE_STATE_WRITES_V3,
        };
        let resource_key = format!("POSITION/{}", request.position_id);
        let admission_request = StakeStateResourceAdmissionRequestV1 {
            resource_key: resource_key.clone(),
            resource_kind: StakeStateResourceKindV1::Position,
            resource_owner: request.owner.clone(),
            outer_operation_hash: request.resource_operation_hash(),
            expected_parent_commitment: request.expected_authority_commitment.clone(),
            usage,
            envelope: request.resource_envelope.clone(),
        };
        let admission_height = self
            .height
            .checked_add(1)
            .ok_or_else(|| LedgerError::StakeResource("stake V3 height overflow".into()))?;
        let (next_accounting, admission) =
            self.prepare_position_resource_admission(admission_request, admission_height)?;
        let payload_hash = request.payload_hash();
        let position = self.apply_consensus_stake_lock(ConsensusStakeLockInput {
            position_id: request.position_id,
            zone_id: request.zone_id,
            currency_genesis_root: request.currency_genesis_root,
            protocol_era: request.protocol_era,
            crypto_era: request.crypto_era,
            proposed_height: request.proposed_height,
            expires_at_height: request.expires_at_height,
            expected_authority_sequence: request.expected_authority_sequence,
            expected_authority_commitment: request.expected_authority_commitment,
            position_type: request.position_type,
            validator_id: request.validator_id,
            owner: request.owner,
            source_coin_id: request.source_coin_id,
            amount: request.amount,
            committed_through_height: request.committed_through_height,
            action: LOCK_CONSENSUS_STAKE_ACTION_V3,
            payload_hash,
            slash_terms_authorization: Some(request.slash_terms_authorization),
            authorization: request.authorization,
        })?;
        if self.height != admission_height {
            return Err(LedgerError::StakeResource(
                "stake and resource admission heights diverged".into(),
            ));
        }
        self.commit_position_resource_admission(
            next_accounting,
            &admission,
            sponsor_authorization,
        )?;
        Ok(LockConsensusStakeOutcomeV3 {
            position,
            resource_key,
            bond_id: admission.bond_record.bond_id.clone(),
            bond_coin_id: admission.bond_record.bond_coin_id.clone(),
            charged_fee: admission.charged_fee,
            locked_bond: admission.locked_bond,
            initial_bond_record_hash: admission.bond_record.initial_record_hash(),
        })
    }

    /// Adds resource responsibility to one exact active pre-policy position.
    /// The finite authority inventory and its exact position commitment are
    /// both bound; principal, escrow and authority membership remain unchanged.
    pub fn migrate_consensus_stake_resource(
        &mut self,
        request: MigrateConsensusStakeResourceRequestV1,
    ) -> Result<MigrateConsensusStakeResourceOutcomeV1, LedgerError> {
        let mut staged = self.clone();
        let outcome = staged.apply_consensus_stake_resource_migration(request)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(outcome)
    }

    fn apply_consensus_stake_resource_migration(
        &mut self,
        request: MigrateConsensusStakeResourceRequestV1,
    ) -> Result<MigrateConsensusStakeResourceOutcomeV1, LedgerError> {
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "consensus stake resource migration requires VALUE_CAP_0".into(),
            ));
        }
        if request.request_id.trim().is_empty()
            || request.position_id.trim().is_empty()
            || request.escrow_coin_id.trim().is_empty()
            || request.owner.trim().is_empty()
            || !is_canonical_sha256_hex(&request.expected_position_commitment)
        {
            return Err(LedgerError::Invalid(
                "stake resource migration request is incomplete or noncanonical".into(),
            ));
        }
        if request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "stake resource migration Zone, currency or era binding mismatch".into(),
            ));
        }
        if request.proposed_height != self.height || request.expires_at_height <= self.height {
            return Err(LedgerError::Invalid(
                "stake resource migration height is stale or expired".into(),
            ));
        }
        let authority = self
            .consensus_stake_authority
            .clone()
            .ok_or_else(|| LedgerError::Invalid("ledger has no staged stake authority".into()))?;
        validate_ledger_stake_authority_state_v1(&authority)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if authority.sequence != request.expected_authority_sequence
            || authority.commitment != request.expected_authority_commitment
        {
            return Err(LedgerError::Invalid(
                "stake resource migration authority precondition mismatch".into(),
            ));
        }
        let position = authority
            .positions
            .iter()
            .find(|position| {
                position.position_id == request.position_id
                    && position.escrow_coin_id == request.escrow_coin_id
            })
            .cloned()
            .ok_or_else(|| LedgerError::Invalid("active legacy position was not found".into()))?;
        if position.owner != request.owner {
            return Err(LedgerError::OwnerMismatch);
        }
        if position.slash_terms.is_none()
            || position.resource_commitment_v1() != request.expected_position_commitment
        {
            return Err(LedgerError::Invalid(
                "stake resource migration does not bind the exact slashable position".into(),
            ));
        }
        if !self
            .consensus_stake_escrows
            .get(&position.escrow_coin_id)
            .is_some_and(|retained| retained == &position)
            || self
                .consensus_stake_unbonds
                .values()
                .any(|record| record.position.position_id == position.position_id)
            || self
                .consensus_stake_slashes
                .values()
                .any(|record| record.position.position_id == position.position_id)
        {
            return Err(LedgerError::Invalid(
                "only an exact active, nonterminal position can enter resource accounting".into(),
            ));
        }
        let escrow = self
            .coins
            .get(&position.escrow_coin_id)
            .ok_or_else(|| LedgerError::CoinNotFound(position.escrow_coin_id.clone()))?;
        if escrow.state != CoinState::Reserved
            || escrow.owner != position.owner
            || escrow.amount != position.amount
            || escrow.parent_ids != [position.source_coin_id.clone()]
        {
            return Err(LedgerError::Invalid(
                "migrated position escrow is not the exact protected principal".into(),
            ));
        }
        let sponsor_authorization = &request.resource_envelope.authorization;
        if request.authorization.authorization_id == sponsor_authorization.authorization_id
            || self
                .authorization_nullifiers
                .contains(sponsor_authorization.authorization_id.as_str())
        {
            return Err(LedgerError::Duplicate(
                sponsor_authorization.authorization_id.clone(),
            ));
        }
        let accounting = self
            .stake_resource_accounting
            .as_ref()
            .ok_or_else(|| LedgerError::StakeResource("no active stake resource policy".into()))?;
        self.validate_stake_resource_policy_covers_inventory(
            accounting.active_policy(),
            None,
            None,
        )?;
        let required_lease_end = u64::try_from(position.committed_through_height)
            .ok()
            .and_then(|height| {
                height.checked_add(accounting.active_policy().terminal_retention_blocks)
            })
            .ok_or_else(|| {
                LedgerError::StakeResource("migrated position resource lease overflow".into())
            })?;
        if request.resource_envelope.lease_end_height < required_lease_end {
            return Err(LedgerError::StakeResource(
                "migrated position lease does not cover liability plus terminal retention".into(),
            ));
        }
        let payload_hash = request.payload_hash();
        self.verify_owner_authorization(
            &request.authorization,
            &request.owner,
            MIGRATE_CONSENSUS_STAKE_RESOURCE_ACTION_V1,
            &payload_hash,
        )?;
        let wire_bytes = ConsensusCommand::MigrateConsensusStakeResource(Box::new(request.clone()))
            .wire_v1_command_bytes(&self.descriptor.network_domain)
            .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
        let usage = StakeStateResourceUsageV1 {
            wire_bytes: u32::try_from(wire_bytes.len()).map_err(|_| {
                LedgerError::StakeResource(
                    "stake resource migration exceeds the u32 wire meter".into(),
                )
            })?,
            persistent_bytes: migrate_consensus_stake_resource_persistent_bytes_v1(
                &request, &position,
            )
            .map_err(|error| LedgerError::StakeResource(error.to_string()))?,
            signature_checks: MIGRATE_CONSENSUS_STAKE_RESOURCE_SIGNATURE_CHECKS_V1,
            state_reads: MIGRATE_CONSENSUS_STAKE_RESOURCE_STATE_READS_V1,
            state_writes: MIGRATE_CONSENSUS_STAKE_RESOURCE_STATE_WRITES_V1,
        };
        let resource_key = format!("POSITION/{}", position.position_id);
        let admission_request = StakeStateResourceAdmissionRequestV1 {
            resource_key: resource_key.clone(),
            resource_kind: StakeStateResourceKindV1::Position,
            resource_owner: request.owner.clone(),
            outer_operation_hash: request.resource_operation_hash(),
            expected_parent_commitment: request.expected_authority_commitment.clone(),
            usage,
            envelope: request.resource_envelope.clone(),
        };
        let admission_height = self.height.checked_add(1).ok_or_else(|| {
            LedgerError::StakeResource("resource migration height overflow".into())
        })?;
        let (next_accounting, admission) =
            self.prepare_position_resource_admission(admission_request, admission_height)?;
        self.ensure_counter_headroom(1, 0)?;
        self.consume_authorization(&request.authorization)?;
        self.advance()?;
        self.commit_position_resource_admission(
            next_accounting,
            &admission,
            sponsor_authorization,
        )?;
        Ok(MigrateConsensusStakeResourceOutcomeV1 {
            position,
            resource_key,
            bond_id: admission.bond_record.bond_id.clone(),
            bond_coin_id: admission.bond_record.bond_coin_id.clone(),
            charged_fee: admission.charged_fee,
            locked_bond: admission.locked_bond,
            initial_bond_record_hash: admission.bond_record.initial_record_hash(),
        })
    }

    /// Adds resource responsibility to one exact active pre-policy candidate.
    /// The authority and runtime validator sets are immutable across this
    /// bounded migration.
    pub fn migrate_consensus_candidate_resource(
        &mut self,
        request: MigrateConsensusCandidateResourceRequestV1,
    ) -> Result<MigrateConsensusCandidateResourceOutcomeV1, LedgerError> {
        let mut staged = self.clone();
        let outcome = staged.apply_consensus_candidate_resource_migration(request)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(outcome)
    }

    fn apply_consensus_candidate_resource_migration(
        &mut self,
        request: MigrateConsensusCandidateResourceRequestV1,
    ) -> Result<MigrateConsensusCandidateResourceOutcomeV1, LedgerError> {
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "consensus candidate resource migration requires VALUE_CAP_0".into(),
            ));
        }
        if request.request_id.trim().is_empty()
            || request.validator_id.trim().is_empty()
            || request.owner.trim().is_empty()
            || request.public_key.trim().is_empty()
            || request.proof_of_possession.trim().is_empty()
            || !is_canonical_sha256_hex(&request.expected_candidate_commitment)
        {
            return Err(LedgerError::Invalid(
                "candidate resource migration request is incomplete or noncanonical".into(),
            ));
        }
        if request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "candidate resource migration Zone, currency or era binding mismatch".into(),
            ));
        }
        if request.proposed_height != self.height || request.expires_at_height <= self.height {
            return Err(LedgerError::Invalid(
                "candidate resource migration height is stale or expired".into(),
            ));
        }
        let authority = self
            .consensus_stake_authority
            .clone()
            .ok_or_else(|| LedgerError::Invalid("ledger has no staged stake authority".into()))?;
        validate_ledger_stake_authority_state_v1(&authority)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if authority.sequence != request.expected_authority_sequence
            || authority.commitment != request.expected_authority_commitment
        {
            return Err(LedgerError::Invalid(
                "candidate resource migration authority precondition mismatch".into(),
            ));
        }
        let candidate = authority
            .candidates
            .iter()
            .find(|candidate| candidate.validator_id == request.validator_id)
            .cloned()
            .ok_or_else(|| LedgerError::Invalid("active legacy candidate was not found".into()))?;
        if candidate.owner != request.owner {
            return Err(LedgerError::OwnerMismatch);
        }
        let requested_candidate = ValidatorCandidateRecord {
            validator_id: request.validator_id.clone(),
            owner: request.owner.clone(),
            public_key: request.public_key.clone(),
            key_era: request.key_era,
            registered_height: u128::from(request.registered_height),
            exit_height: request.exit_height.map(u128::from),
            proof_of_possession: request.proof_of_possession.clone(),
        };
        if candidate != requested_candidate
            || candidate.resource_commitment_v1() != request.expected_candidate_commitment
        {
            return Err(LedgerError::Invalid(
                "candidate resource migration does not bind the exact retained candidate".into(),
            ));
        }
        if candidate
            .exit_height
            .is_some_and(|exit_height| exit_height <= u128::from(self.height))
        {
            return Err(LedgerError::Invalid(
                "terminal candidate cannot enter active resource accounting".into(),
            ));
        }
        let sponsor_authorization = &request.resource_envelope.authorization;
        if request.authorization.authorization_id == sponsor_authorization.authorization_id
            || self
                .authorization_nullifiers
                .contains(sponsor_authorization.authorization_id.as_str())
        {
            return Err(LedgerError::Duplicate(
                sponsor_authorization.authorization_id.clone(),
            ));
        }
        let accounting = self
            .stake_resource_accounting
            .as_ref()
            .ok_or_else(|| LedgerError::StakeResource("no active stake resource policy".into()))?;
        self.validate_stake_resource_policy_covers_inventory(
            accounting.active_policy(),
            None,
            None,
        )?;
        let payload_hash = request.payload_hash();
        self.verify_owner_authorization(
            &request.authorization,
            &request.owner,
            MIGRATE_CONSENSUS_CANDIDATE_RESOURCE_ACTION_V1,
            &payload_hash,
        )?;
        let wire_bytes =
            ConsensusCommand::MigrateConsensusCandidateResource(Box::new(request.clone()))
                .wire_v1_command_bytes(&self.descriptor.network_domain)
                .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
        let usage = StakeStateResourceUsageV1 {
            wire_bytes: u32::try_from(wire_bytes.len()).map_err(|_| {
                LedgerError::StakeResource("candidate migration exceeds the u32 wire meter".into())
            })?,
            persistent_bytes: migrate_consensus_candidate_resource_persistent_bytes_v1(
                &request, &candidate,
            )
            .map_err(|error| LedgerError::StakeResource(error.to_string()))?,
            signature_checks: MIGRATE_CONSENSUS_CANDIDATE_RESOURCE_SIGNATURE_CHECKS_V1,
            state_reads: MIGRATE_CONSENSUS_CANDIDATE_RESOURCE_STATE_READS_V1,
            state_writes: MIGRATE_CONSENSUS_CANDIDATE_RESOURCE_STATE_WRITES_V1,
        };
        let resource_key = format!("CANDIDATE/{}", candidate.validator_id);
        let admission_request = StakeStateResourceAdmissionRequestV1 {
            resource_key: resource_key.clone(),
            resource_kind: StakeStateResourceKindV1::Candidate,
            resource_owner: request.owner.clone(),
            outer_operation_hash: request.resource_operation_hash(),
            expected_parent_commitment: request.expected_authority_commitment.clone(),
            usage,
            envelope: request.resource_envelope.clone(),
        };
        let admission_height = self.height.checked_add(1).ok_or_else(|| {
            LedgerError::StakeResource("candidate migration height overflow".into())
        })?;
        let (next_accounting, admission) =
            self.prepare_position_resource_admission(admission_request, admission_height)?;
        let runtime_validator_keys = self.descriptor.validator_keys.clone();
        self.ensure_counter_headroom(1, 0)?;
        self.consume_authorization(&request.authorization)?;
        self.advance()?;
        self.commit_position_resource_admission(
            next_accounting,
            &admission,
            sponsor_authorization,
        )?;
        if self.descriptor.validator_keys != runtime_validator_keys
            || self.consensus_stake_authority.as_ref() != Some(&authority)
        {
            return Err(LedgerError::StakeResource(
                "candidate resource migration changed authority or runtime membership".into(),
            ));
        }
        Ok(MigrateConsensusCandidateResourceOutcomeV1 {
            candidate,
            resource_key,
            bond_id: admission.bond_record.bond_id.clone(),
            bond_coin_id: admission.bond_record.bond_coin_id.clone(),
            charged_fee: admission.charged_fee,
            locked_bond: admission.locked_bond,
            initial_bond_record_hash: admission.bond_record.initial_record_hash(),
        })
    }

    /// Attaches the protocol-fixed objective-fault slash terms to one exact
    /// active legacy position. Coin ownership and amount are unchanged.
    pub fn migrate_consensus_stake_slash_terms(
        &mut self,
        request: MigrateConsensusStakeSlashTermsV2,
    ) -> Result<ConsensusStakePosition, LedgerError> {
        let mut staged = self.clone();
        let position = staged.apply_consensus_stake_slash_terms_migration(request)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(position)
    }

    fn apply_consensus_stake_slash_terms_migration(
        &mut self,
        request: MigrateConsensusStakeSlashTermsV2,
    ) -> Result<ConsensusStakePosition, LedgerError> {
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "consensus stake slash-terms migration requires VALUE_CAP_0".into(),
            ));
        }
        if request.request_id.trim().is_empty()
            || request.position_id.trim().is_empty()
            || request.escrow_coin_id.trim().is_empty()
            || request.owner.trim().is_empty()
        {
            return Err(LedgerError::Invalid(
                "consensus stake slash-terms migration is incomplete".into(),
            ));
        }
        if request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "stake slash-terms migration Zone, currency or era binding mismatch".into(),
            ));
        }
        if request.proposed_height != self.height {
            return Err(LedgerError::Invalid(
                "stake slash-terms migration height does not match current state".into(),
            ));
        }
        if request.expires_at_height <= self.height {
            return Err(LedgerError::Invalid(
                "stake slash-terms migration request expired".into(),
            ));
        }

        let authority = self
            .consensus_stake_authority
            .clone()
            .ok_or_else(|| LedgerError::Invalid("ledger has no staged stake authority".into()))?;
        validate_ledger_stake_authority_state_v1(&authority)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if authority.sequence != request.expected_authority_sequence
            || authority.commitment != request.expected_authority_commitment
        {
            return Err(LedgerError::Invalid(
                "stake slash-terms migration authority precondition mismatch".into(),
            ));
        }
        let mut position = self
            .consensus_stake_escrows
            .get(&request.escrow_coin_id)
            .filter(|position| position.position_id == request.position_id)
            .cloned()
            .ok_or_else(|| {
                LedgerError::Invalid("registered stake position was not found".into())
            })?;
        if position.owner != request.owner {
            return Err(LedgerError::OwnerMismatch);
        }
        if position.slash_terms.is_some() {
            return Err(LedgerError::Duplicate(request.position_id));
        }
        if !authority.positions.contains(&position) {
            return Err(LedgerError::Invalid(
                "stake position is not active in the current authority".into(),
            ));
        }
        if self.consensus_stake_unbonds.values().any(|record| {
            record.position.position_id == position.position_id
                || record.position.escrow_coin_id == position.escrow_coin_id
        }) {
            return Err(LedgerError::Invalid(
                "stake position already has an unbond record".into(),
            ));
        }
        let escrow = self
            .coins
            .get(&position.escrow_coin_id)
            .ok_or_else(|| LedgerError::CoinNotFound(position.escrow_coin_id.clone()))?;
        if escrow.state != CoinState::Reserved
            || escrow.owner != position.owner
            || escrow.amount != position.amount
        {
            return Err(LedgerError::Invalid(
                "stake migration escrow is not the exact protected Reserved Coin".into(),
            ));
        }
        if request.slash_terms_authorization.authorization_id
            == request.authorization.authorization_id
        {
            return Err(LedgerError::Duplicate(
                request.authorization.authorization_id.clone(),
            ));
        }

        let slash_policy = ConsensusStakeSlashPolicyV2::protocol_v2();
        let slash_terms_payload_hash = position.slash_terms_payload_hash_v2();
        self.verify_owner_authorization(
            &request.slash_terms_authorization,
            &request.owner,
            ACCEPT_CONSENSUS_STAKE_SLASH_TERMS_ACTION_V2,
            &slash_terms_payload_hash,
        )?;
        let payload_hash = request.payload_hash(&position);
        self.verify_owner_authorization(
            &request.authorization,
            &request.owner,
            MIGRATE_CONSENSUS_STAKE_SLASH_TERMS_ACTION_V2,
            &payload_hash,
        )?;

        self.ensure_counter_headroom(1, 0)?;
        let source_height = u128::from(self.height);
        let source_state_root = self.state_root()?;
        position.slash_terms = Some(ConsensusStakeSlashTermsV2 {
            terms_version: slash_policy.policy_version,
            slash_policy,
            owner_authorization: request.slash_terms_authorization.clone(),
        });
        let mut positions = authority.positions.clone();
        let position_slot = positions
            .iter_mut()
            .find(|existing| existing.position_id == position.position_id)
            .expect("active position was checked");
        *position_slot = position.clone();

        self.consume_authorization(&request.authorization)?;
        self.consume_authorization(&request.slash_terms_authorization)?;
        self.advance()?;
        self.consensus_stake_escrows
            .insert(position.escrow_coin_id.clone(), position.clone());

        let mut ubo_control = authority.ubo_control.clone();
        ubo_control.predecessor_commitment = ubo_control_commitment_v1(&authority.ubo_control)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        ubo_control.sequence = ubo_control
            .sequence
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("stake UBO sequence overflow".into()))?;
        let update = LedgerStakeAuthorityUpdateV1 {
            authority_version: authority.authority_version,
            sequence: authority
                .sequence
                .checked_add(1)
                .ok_or_else(|| LedgerError::Invalid("stake authority sequence overflow".into()))?,
            expected_previous_commitment: authority.commitment.clone(),
            policy: authority.policy.clone(),
            candidates: authority.candidates.clone(),
            positions,
            ubo_control,
        };
        let context = self.stake_context_at(source_height, source_state_root);
        let next_authority = build_ledger_stake_authority_state_v1(
            &context,
            u128::from(self.height),
            Some(&authority),
            update,
            &self.coins,
        )
        .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if !next_authority.positions.contains(&position) {
            return Err(LedgerError::Invalid(
                "migrated position disappeared during canonicalization".into(),
            ));
        }
        self.consensus_stake_authority = Some(next_authority);
        Ok(position)
    }

    /// Atomically applies one objective-fault slash against an exact historical
    /// V2 liability. Evidence is permissionless; neither the reporter nor the
    /// current authority selects the penalty or destination.
    pub fn slash_consensus_stake(
        &mut self,
        request: SlashConsensusStakeV1,
    ) -> Result<ConsensusStakeSlashRecordV1, LedgerError> {
        let mut staged = self.clone();
        let record = staged.apply_consensus_stake_slash(request)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(record)
    }

    fn apply_consensus_stake_slash(
        &mut self,
        request: SlashConsensusStakeV1,
    ) -> Result<ConsensusStakeSlashRecordV1, LedgerError> {
        // Consensus-significant failure priority: envelope, replay, authority,
        // Epoch/liability, evidence/deadline, live escrow/unbond, accounting.
        if request.slash_id.trim().is_empty()
            || request.position_id.trim().is_empty()
            || request.escrow_coin_id.trim().is_empty()
            || request.expected_position_amount.is_zero()
            || !is_canonical_sha256_hex(&request.derived_epoch_record_hash)
            || !is_canonical_sha256_hex(&request.liability_commitment)
            || !is_canonical_sha256_hex(&request.evidence_hash)
            || request
                .expected_unbond_request_commitment
                .as_ref()
                .is_some_and(|hash| !is_canonical_sha256_hex(hash))
        {
            return Err(LedgerError::Invalid(
                "consensus stake slash envelope is incomplete or noncanonical".into(),
            ));
        }
        if request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "consensus stake slash Zone, currency or era binding mismatch".into(),
            ));
        }
        if request.proposed_height != self.height {
            return Err(LedgerError::Invalid(
                "consensus stake slash height does not match current state".into(),
            ));
        }
        if request.expires_at_height <= self.height {
            return Err(LedgerError::Invalid(
                "consensus stake slash request expired".into(),
            ));
        }
        if self.consensus_stake_slashes.contains_key(&request.slash_id) {
            return Err(LedgerError::Duplicate(request.slash_id));
        }
        let evidence_nullifier = consensus_stake_slash_nullifier_v1(
            &request.evidence_hash,
            &request.liability_commitment,
        );
        if self
            .consensus_stake_evidence_nullifiers
            .contains(&evidence_nullifier)
        {
            return Err(LedgerError::Duplicate(evidence_nullifier));
        }
        let authority = self
            .consensus_stake_authority
            .clone()
            .ok_or_else(|| LedgerError::Invalid("ledger has no staged stake authority".into()))?;
        validate_ledger_stake_authority_state_v1(&authority)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if authority.sequence != request.expected_authority_sequence
            || authority.commitment != request.expected_authority_commitment
        {
            return Err(LedgerError::Invalid(
                "consensus stake slash authority precondition mismatch".into(),
            ));
        }

        let epoch = self
            .derived_stake_epochs
            .get(&request.consensus_epoch)
            .filter(|record| record.record_hash == request.derived_epoch_record_hash)
            .cloned()
            .ok_or_else(|| {
                LedgerError::Invalid("referenced derived stake Epoch was not found".into())
            })?;
        let verified = verify_consensus_stake_slash_evidence_v1(
            &epoch,
            &request.position_id,
            &request.liability_commitment,
            &request.evidence,
        )
        .map_err(|error| LedgerError::Invalid(format!("stake slash evidence rejected: {error}")))?;
        if verified.evidence_hash != request.evidence_hash {
            return Err(LedgerError::Invalid(
                "stake slash evidence hash mismatch".into(),
            ));
        }
        if verified.fault_height > u128::from(self.height) {
            return Err(LedgerError::Invalid(
                "stake slash evidence claims a future fault height".into(),
            ));
        }
        if u128::from(self.height) >= verified.liability.evidence_deadline_height {
            return Err(LedgerError::Invalid(
                "stake slash evidence window has closed".into(),
            ));
        }
        if verified.slash_bps != 10_000 {
            return Err(LedgerError::Invalid(
                "stake slash policy is not the supported full objective-fault penalty".into(),
            ));
        }

        let position = self
            .consensus_stake_escrows
            .get(&request.escrow_coin_id)
            .filter(|position| position.position_id == request.position_id)
            .cloned()
            .ok_or_else(|| {
                LedgerError::Invalid("slashable consensus stake escrow was not found".into())
            })?;
        if position != verified.liability.position
            || position.amount != request.expected_position_amount
            || position.escrow_coin_id != request.escrow_coin_id
        {
            return Err(LedgerError::Invalid(
                "live stake position does not equal the historical liability".into(),
            ));
        }
        if self
            .consensus_stake_slashes
            .values()
            .any(|record| record.position.position_id == position.position_id)
        {
            return Err(LedgerError::Duplicate(position.position_id));
        }
        let pending_unbond_id = self
            .consensus_stake_unbonds
            .iter()
            .find(|(_, record)| record.position.position_id == position.position_id)
            .map(|(request_id, _)| request_id.clone());
        let unbond_request_commitment = match (
            request.expected_unbond_request_commitment.as_deref(),
            pending_unbond_id.as_deref(),
        ) {
            (None, None) => None,
            (Some(expected), Some(request_id)) => {
                let record = self
                    .consensus_stake_unbonds
                    .get(request_id)
                    .expect("unbond request was found");
                if record.status != ConsensusStakeUnbondStatusV1::Pending
                    || record.request_commitment != expected
                {
                    return Err(LedgerError::Invalid(
                        "stake slash pending-unbond precondition mismatch".into(),
                    ));
                }
                Some(record.request_commitment.clone())
            }
            _ => {
                return Err(LedgerError::Invalid(
                    "stake slash must bind the exact pending-unbond state".into(),
                ));
            }
        };
        let escrow = self
            .coins
            .get(&position.escrow_coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(position.escrow_coin_id.clone()))?;
        if escrow.state != CoinState::Reserved
            || escrow.owner != position.owner
            || escrow.amount != position.amount
            || escrow.parent_ids != [position.source_coin_id.clone()]
        {
            return Err(LedgerError::Invalid(
                "stake slash escrow is not the exact protected Reserved Coin".into(),
            ));
        }

        self.ensure_counter_headroom(1, 1)?;
        let source_height = u128::from(self.height);
        let source_state_root = self.state_root()?;
        let next_height = self
            .height
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("stake slash height overflow".into()))?;
        let next_authority = if authority.positions.contains(&position) {
            let mut positions = authority.positions.clone();
            positions.retain(|candidate| candidate.position_id != position.position_id);
            let mut ubo_control = authority.ubo_control.clone();
            ubo_control.predecessor_commitment = ubo_control_commitment_v1(&authority.ubo_control)
                .map_err(|error| LedgerError::Invalid(error.to_string()))?;
            ubo_control.sequence = ubo_control
                .sequence
                .checked_add(1)
                .ok_or_else(|| LedgerError::Invalid("stake UBO sequence overflow".into()))?;
            let update = LedgerStakeAuthorityUpdateV1 {
                authority_version: authority.authority_version,
                sequence: authority.sequence.checked_add(1).ok_or_else(|| {
                    LedgerError::Invalid("stake authority sequence overflow".into())
                })?,
                expected_previous_commitment: authority.commitment.clone(),
                policy: authority.policy.clone(),
                candidates: authority.candidates.clone(),
                positions,
                ubo_control,
            };
            let context = self.stake_context_at(source_height, source_state_root);
            Some(
                build_ledger_stake_authority_state_v1(
                    &context,
                    u128::from(next_height),
                    Some(&authority),
                    update,
                    &self.coins,
                )
                .map_err(|error| LedgerError::Invalid(error.to_string()))?,
            )
        } else {
            None
        };

        let next_version = Self::checked_next_coin_version(escrow.version)?;
        self.advance()?;
        self.consensus_stake_escrows.remove(&escrow.object_id);
        self.coins
            .get_mut(&escrow.object_id)
            .expect("stake slash escrow was checked")
            .state = CoinState::Consumed;
        let safety_coin = self.make_coin(
            CONSENSUS_SLASH_SAFETY_POOL_V2.into(),
            position.amount,
            CoinState::Reserved,
            vec![escrow.object_id.clone()],
            Some(escrow.lineage_root.clone()),
            None,
            escrow.imported_from.clone(),
            next_version,
        )?;
        self.coins
            .insert(safety_coin.object_id.clone(), safety_coin.clone());
        if let Some(authority) = next_authority {
            self.consensus_stake_authority = Some(authority);
        }
        if let Some(request_id) = pending_unbond_id {
            let record = self
                .consensus_stake_unbonds
                .get_mut(&request_id)
                .expect("pending unbond was checked");
            record.status = ConsensusStakeUnbondStatusV1::FullySlashed;
            record.completed_height = Some(self.height);
            record.slash_id = Some(request.slash_id.clone());
            record.slashed_amount = position.amount;
        }

        let mut record = ConsensusStakeSlashRecordV1 {
            slash_id: request.slash_id.clone(),
            evidence_kind: verified.kind,
            evidence_hash: verified.evidence_hash.clone(),
            evidence: request.evidence,
            consensus_epoch: request.consensus_epoch,
            derived_epoch_record_hash: request.derived_epoch_record_hash,
            liability_commitment: request.liability_commitment,
            position,
            unbond_request_commitment,
            slash_bps: verified.slash_bps,
            slashed_amount: request.expected_position_amount,
            source_escrow_coin_id: escrow.object_id,
            safety_pool_coin_id: safety_coin.object_id,
            applied_height: self.height,
            record_hash: String::new(),
        };
        record.record_hash = record.compute_record_hash();
        self.consensus_stake_evidence_nullifiers
            .insert(evidence_nullifier);
        self.consensus_stake_slashes
            .insert(record.slash_id.clone(), record.clone());
        Ok(record)
    }

    /// Owner-authorized first phase of delayed withdrawal. The position is
    /// removed from the authority in the same atomic transition, so no later
    /// derived Epoch can count it while the Reserved Coin remains protected.
    pub fn request_consensus_stake_unbond(
        &mut self,
        request: RequestConsensusStakeUnbondV1,
    ) -> Result<ConsensusStakeUnbondRecordV1, LedgerError> {
        let mut staged = self.clone();
        let record = staged.apply_consensus_stake_unbond_request(request)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(record)
    }

    fn apply_consensus_stake_unbond_request(
        &mut self,
        request: RequestConsensusStakeUnbondV1,
    ) -> Result<ConsensusStakeUnbondRecordV1, LedgerError> {
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "consensus stake unbond requires VALUE_CAP_0".into(),
            ));
        }
        if request.request_id.trim().is_empty()
            || request.position_id.trim().is_empty()
            || request.escrow_coin_id.trim().is_empty()
            || request.owner.trim().is_empty()
            || request.beneficiary.trim().is_empty()
        {
            return Err(LedgerError::Invalid(
                "consensus stake unbond request is incomplete".into(),
            ));
        }
        if request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "consensus stake unbond Zone, currency or era binding mismatch".into(),
            ));
        }
        if request.proposed_height != self.height {
            return Err(LedgerError::Invalid(
                "consensus stake unbond height does not match current state".into(),
            ));
        }
        if request.expires_at_height <= self.height {
            return Err(LedgerError::Invalid(
                "consensus stake unbond request expired".into(),
            ));
        }
        if request.beneficiary != request.owner {
            return Err(LedgerError::OwnerMismatch);
        }
        if self
            .consensus_stake_unbonds
            .contains_key(&request.request_id)
            || self.consensus_stake_unbonds.values().any(|record| {
                record.position.position_id == request.position_id
                    || record.position.escrow_coin_id == request.escrow_coin_id
            })
        {
            return Err(LedgerError::Duplicate(request.request_id));
        }

        let authority = self
            .consensus_stake_authority
            .clone()
            .ok_or_else(|| LedgerError::Invalid("ledger has no staged stake authority".into()))?;
        validate_ledger_stake_authority_state_v1(&authority)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if authority.sequence != request.expected_authority_sequence
            || authority.commitment != request.expected_authority_commitment
        {
            return Err(LedgerError::Invalid(
                "consensus stake unbond authority precondition mismatch".into(),
            ));
        }
        let position = self
            .consensus_stake_escrows
            .get(&request.escrow_coin_id)
            .filter(|position| position.position_id == request.position_id)
            .cloned()
            .ok_or_else(|| {
                LedgerError::Invalid("registered stake position was not found".into())
            })?;
        if position.owner != request.owner {
            return Err(LedgerError::OwnerMismatch);
        }
        if !authority.positions.contains(&position) {
            return Err(LedgerError::Invalid(
                "stake position is not active in the current authority".into(),
            ));
        }
        let escrow = self
            .coins
            .get(&position.escrow_coin_id)
            .ok_or_else(|| LedgerError::CoinNotFound(position.escrow_coin_id.clone()))?;
        if escrow.state != CoinState::Reserved
            || escrow.owner != position.owner
            || escrow.amount != position.amount
        {
            return Err(LedgerError::Invalid(
                "stake unbond escrow is not the exact protected Reserved Coin".into(),
            ));
        }

        let requested_height = self
            .height
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("stake unbond request height overflow".into()))?;
        let notice_end = u128::from(requested_height)
            .checked_add(authority.policy.activation_delay_blocks)
            .ok_or_else(|| LedgerError::Invalid("stake unbond notice height overflow".into()))?;
        let validator_id = match &position.kind {
            ConsensusStakePositionKind::SelfBond { validator_id }
            | ConsensusStakePositionKind::Delegation { validator_id } => validator_id,
        };
        let mut protected_epoch_end = 0u128;
        for record in self.derived_stake_epochs.values().filter(|record| {
            record.stake_snapshot_height >= position.locked_height
                && record
                    .descriptor
                    .validators
                    .iter()
                    .any(|validator| validator.validator_id == *validator_id)
        }) {
            let validator_unbonding = record
                .descriptor
                .validators
                .iter()
                .find(|validator| validator.validator_id == *validator_id)
                .expect("filtered validator exists")
                .unbonding_height;
            protected_epoch_end = protected_epoch_end.max(validator_unbonding);
        }
        let minimum_withdrawal = notice_end
            .max(position.committed_through_height)
            .max(protected_epoch_end);
        if u128::from(request.requested_withdraw_after_height) < minimum_withdrawal {
            return Err(LedgerError::Invalid(
                "stake unbond withdrawal truncates notice, commitment or Epoch evidence window"
                    .into(),
            ));
        }

        let payload_hash = request.payload_hash();
        self.verify_owner_authorization(
            &request.authorization,
            &request.owner,
            REQUEST_CONSENSUS_STAKE_UNBOND_ACTION_V1,
            &payload_hash,
        )?;
        self.ensure_counter_headroom(1, 0)?;
        let source_height = u128::from(self.height);
        let source_state_root = self.state_root()?;
        let mut positions = authority.positions.clone();
        positions.retain(|candidate| candidate.position_id != position.position_id);
        let mut ubo_control = authority.ubo_control.clone();
        ubo_control.predecessor_commitment = ubo_control_commitment_v1(&authority.ubo_control)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        ubo_control.sequence = ubo_control
            .sequence
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("stake UBO sequence overflow".into()))?;
        let update = LedgerStakeAuthorityUpdateV1 {
            authority_version: authority.authority_version,
            sequence: authority
                .sequence
                .checked_add(1)
                .ok_or_else(|| LedgerError::Invalid("stake authority sequence overflow".into()))?,
            expected_previous_commitment: authority.commitment.clone(),
            policy: authority.policy.clone(),
            candidates: authority.candidates.clone(),
            positions,
            ubo_control,
        };
        let context = self.stake_context_at(source_height, source_state_root);
        let next_authority = build_ledger_stake_authority_state_v1(
            &context,
            u128::from(requested_height),
            Some(&authority),
            update,
            &self.coins,
        )
        .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        let mut record = ConsensusStakeUnbondRecordV1 {
            request_id: request.request_id.clone(),
            position,
            owner: request.owner,
            beneficiary: request.beneficiary,
            requested_height,
            withdraw_after_height: request.requested_withdraw_after_height,
            request_commitment: String::new(),
            status: ConsensusStakeUnbondStatusV1::Pending,
            completion_id: None,
            completed_height: None,
            payout_coin_id: None,
            slash_id: None,
            slashed_amount: Amount::ZERO,
        };
        record.request_commitment = record.compute_request_commitment();
        self.consume_authorization(&request.authorization)?;
        self.advance()?;
        self.consensus_stake_authority = Some(next_authority);
        self.consensus_stake_unbonds
            .insert(record.request_id.clone(), record.clone());
        Ok(record)
    }

    /// Completes one matured request by atomically consuming the protected
    /// escrow and creating an equal Spendable descendant for the fixed owner.
    pub fn complete_consensus_stake_unbond(
        &mut self,
        request: CompleteConsensusStakeUnbondV1,
    ) -> Result<ConsensusStakeUnbondRecordV1, LedgerError> {
        let mut staged = self.clone();
        let record = staged.apply_consensus_stake_unbond_completion(request)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(record)
    }

    fn apply_consensus_stake_unbond_completion(
        &mut self,
        request: CompleteConsensusStakeUnbondV1,
    ) -> Result<ConsensusStakeUnbondRecordV1, LedgerError> {
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "consensus stake unbond completion requires VALUE_CAP_0".into(),
            ));
        }
        if request.completion_id.trim().is_empty()
            || request.request_id.trim().is_empty()
            || request.beneficiary.trim().is_empty()
        {
            return Err(LedgerError::Invalid(
                "consensus stake unbond completion is incomplete".into(),
            ));
        }
        if request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "stake unbond completion Zone, currency or era binding mismatch".into(),
            ));
        }
        if request.proposed_height != self.height {
            return Err(LedgerError::Invalid(
                "stake unbond completion height does not match current state".into(),
            ));
        }
        if request.expires_at_height <= self.height {
            return Err(LedgerError::Invalid(
                "stake unbond completion request expired".into(),
            ));
        }
        if self
            .consensus_stake_unbonds
            .values()
            .any(|record| record.completion_id.as_deref() == Some(request.completion_id.as_str()))
        {
            return Err(LedgerError::Duplicate(request.completion_id));
        }
        let mut record = self
            .consensus_stake_unbonds
            .get(&request.request_id)
            .cloned()
            .ok_or_else(|| LedgerError::Invalid("stake unbond request was not found".into()))?;
        if record.status != ConsensusStakeUnbondStatusV1::Pending {
            return Err(LedgerError::Duplicate(request.request_id));
        }
        if request.expected_unbond_request_commitment != record.request_commitment
            || request.beneficiary != record.beneficiary
            || record.beneficiary != record.owner
        {
            return Err(LedgerError::Invalid(
                "stake unbond completion changed the request commitment or beneficiary".into(),
            ));
        }
        if self.height < record.withdraw_after_height {
            return Err(LedgerError::Invalid(
                "stake unbond has not reached its withdrawal height".into(),
            ));
        }
        if self
            .consensus_stake_authority
            .as_ref()
            .is_some_and(|authority| {
                authority.positions.iter().any(|position| {
                    position.position_id == record.position.position_id
                        || position.escrow_coin_id == record.position.escrow_coin_id
                })
            })
        {
            return Err(LedgerError::Invalid(
                "stake unbond position is still active in the authority".into(),
            ));
        }
        if self
            .consensus_stake_escrows
            .get(&record.position.escrow_coin_id)
            != Some(&record.position)
        {
            return Err(LedgerError::Invalid(
                "stake unbond active escrow registry mismatch".into(),
            ));
        }
        let escrow = self
            .coins
            .get(&record.position.escrow_coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(record.position.escrow_coin_id.clone()))?;
        if escrow.state != CoinState::Reserved
            || escrow.owner != record.owner
            || escrow.amount != record.position.amount
        {
            return Err(LedgerError::Invalid(
                "stake unbond escrow is no longer an exact Reserved Coin".into(),
            ));
        }

        self.ensure_counter_headroom(1, 1)?;
        let next_version = Self::checked_next_coin_version(escrow.version)?;
        self.advance()?;
        self.coins
            .get_mut(&escrow.object_id)
            .expect("stake unbond escrow was checked")
            .state = CoinState::Consumed;
        let payout = self.make_coin(
            record.beneficiary.clone(),
            escrow.amount,
            CoinState::Spendable,
            vec![escrow.object_id.clone()],
            Some(escrow.lineage_root.clone()),
            None,
            escrow.imported_from.clone(),
            next_version,
        )?;
        self.coins.insert(payout.object_id.clone(), payout.clone());
        self.consensus_stake_escrows.remove(&escrow.object_id);
        record.status = ConsensusStakeUnbondStatusV1::Completed;
        record.completion_id = Some(request.completion_id);
        record.completed_height = Some(self.height);
        record.payout_coin_id = Some(payout.object_id);
        self.consensus_stake_unbonds
            .insert(record.request_id.clone(), record.clone());
        Ok(record)
    }

    /// Appends one candidate through owner authorization and a proof made by
    /// the candidate consensus key. The registration height is assigned by
    /// the ledger and cannot be backdated by the request.
    pub fn register_consensus_validator(
        &mut self,
        request: RegisterConsensusValidatorRequestV1,
    ) -> Result<ValidatorCandidateRecord, LedgerError> {
        let mut staged = self.clone();
        let candidate = staged.apply_consensus_validator_registration(request)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(candidate)
    }

    fn apply_consensus_validator_registration(
        &mut self,
        request: RegisterConsensusValidatorRequestV1,
    ) -> Result<ValidatorCandidateRecord, LedgerError> {
        if self.stake_resource_accounting.is_some() {
            return Err(LedgerError::StakeResource(
                "legacy validator registration is disabled after resource-policy activation; use V2"
                    .into(),
            ));
        }
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "consensus validator registration requires VALUE_CAP_0".into(),
            ));
        }
        if request.request_id.trim().is_empty()
            || request.validator_id.trim().is_empty()
            || request.owner.trim().is_empty()
            || request.public_key.trim().is_empty()
            || request.proof_of_possession.trim().is_empty()
        {
            return Err(LedgerError::Invalid(
                "consensus validator registration request is incomplete".into(),
            ));
        }
        if request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
            || request.key_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "consensus validator registration Zone, currency or era binding mismatch".into(),
            ));
        }
        if request.proposed_height != self.height {
            return Err(LedgerError::Invalid(
                "consensus validator registration height does not match current state".into(),
            ));
        }
        if request.expires_at_height <= self.height {
            return Err(LedgerError::Invalid(
                "consensus validator registration request expired".into(),
            ));
        }

        let authority = self
            .consensus_stake_authority
            .clone()
            .ok_or_else(|| LedgerError::Invalid("ledger has no staged stake authority".into()))?;
        validate_ledger_stake_authority_state_v1(&authority)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if authority.sequence != request.expected_authority_sequence
            || authority.commitment != request.expected_authority_commitment
        {
            return Err(LedgerError::Invalid(
                "consensus validator registration authority precondition mismatch".into(),
            ));
        }
        if authority
            .candidates
            .iter()
            .any(|candidate| candidate.validator_id == request.validator_id)
        {
            return Err(LedgerError::Duplicate(request.validator_id));
        }
        if authority
            .candidates
            .iter()
            .any(|candidate| candidate.public_key == request.public_key)
        {
            return Err(LedgerError::Duplicate(request.public_key));
        }
        if !authority
            .ubo_control
            .validators
            .contains_key(&request.validator_id)
        {
            return Err(LedgerError::Invalid(
                "candidate has no separately governed UBO control record".into(),
            ));
        }

        let payload_hash = request.payload_hash();
        self.verify_owner_authorization(
            &request.authorization,
            &request.owner,
            REGISTER_CONSENSUS_VALIDATOR_ACTION_V1,
            &payload_hash,
        )?;
        self.ensure_counter_headroom(1, 0)?;
        let source_height = u128::from(self.height);
        let source_state_root = self.state_root()?;
        let registered_height = self
            .height
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("candidate registration height overflow".into()))?;
        let candidate = ValidatorCandidateRecord {
            validator_id: request.validator_id,
            owner: request.owner,
            public_key: request.public_key,
            key_era: request.key_era,
            registered_height: u128::from(registered_height),
            exit_height: None,
            proof_of_possession: request.proof_of_possession,
        };
        self.consume_authorization(&request.authorization)?;
        self.advance()?;

        let mut candidates = authority.candidates.clone();
        candidates.push(candidate.clone());
        let mut ubo_control = authority.ubo_control.clone();
        ubo_control.predecessor_commitment = ubo_control_commitment_v1(&authority.ubo_control)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        ubo_control.sequence = ubo_control
            .sequence
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("stake UBO sequence overflow".into()))?;
        let update = LedgerStakeAuthorityUpdateV1 {
            authority_version: authority.authority_version,
            sequence: authority
                .sequence
                .checked_add(1)
                .ok_or_else(|| LedgerError::Invalid("stake authority sequence overflow".into()))?,
            expected_previous_commitment: authority.commitment.clone(),
            policy: authority.policy.clone(),
            candidates,
            positions: authority.positions.clone(),
            ubo_control,
        };
        let context = self.stake_context_at(source_height, source_state_root);
        let next_authority = build_ledger_stake_authority_state_v1(
            &context,
            u128::from(self.height),
            Some(&authority),
            update,
            &self.coins,
        )
        .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if !next_authority.candidates.contains(&candidate) {
            return Err(LedgerError::Invalid(
                "registered candidate disappeared during canonicalization".into(),
            ));
        }
        self.consensus_stake_authority = Some(next_authority);
        Ok(candidate)
    }

    /// Appends one candidate only after consensus derives and charges its
    /// exact resource responsibility. Candidate membership remains staged;
    /// this transition never changes the runtime validator key set.
    pub fn register_consensus_validator_v2(
        &mut self,
        request: RegisterConsensusValidatorRequestV2,
    ) -> Result<RegisterConsensusValidatorOutcomeV2, LedgerError> {
        let mut staged = self.clone();
        let outcome = staged.apply_consensus_validator_registration_v2(request)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(outcome)
    }

    fn apply_consensus_validator_registration_v2(
        &mut self,
        request: RegisterConsensusValidatorRequestV2,
    ) -> Result<RegisterConsensusValidatorOutcomeV2, LedgerError> {
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "resource-bound validator registration requires VALUE_CAP_0".into(),
            ));
        }
        if request.request_id.trim().is_empty()
            || request.validator_id.trim().is_empty()
            || request.owner.trim().is_empty()
            || request.public_key.trim().is_empty()
            || request.proof_of_possession.trim().is_empty()
        {
            return Err(LedgerError::Invalid(
                "resource-bound validator registration request is incomplete".into(),
            ));
        }
        if request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
            || request.key_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "resource-bound validator registration Zone, currency or era binding mismatch"
                    .into(),
            ));
        }
        if request.proposed_height != self.height {
            return Err(LedgerError::Invalid(
                "resource-bound validator registration height does not match current state".into(),
            ));
        }
        if request.expires_at_height <= self.height {
            return Err(LedgerError::Invalid(
                "resource-bound validator registration request expired".into(),
            ));
        }

        let accounting = self
            .stake_resource_accounting
            .clone()
            .ok_or_else(|| LedgerError::StakeResource("no active stake resource policy".into()))?;
        self.validate_stake_resource_policy_covers_inventory(
            accounting.active_policy(),
            Some(&request.owner),
            None,
        )?;
        let authority = self
            .consensus_stake_authority
            .clone()
            .ok_or_else(|| LedgerError::Invalid("ledger has no staged stake authority".into()))?;
        validate_ledger_stake_authority_state_v1(&authority)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if authority.sequence != request.expected_authority_sequence
            || authority.commitment != request.expected_authority_commitment
        {
            return Err(LedgerError::Invalid(
                "resource-bound validator registration authority precondition mismatch".into(),
            ));
        }
        if authority
            .candidates
            .iter()
            .any(|candidate| candidate.validator_id == request.validator_id)
        {
            return Err(LedgerError::Duplicate(request.validator_id));
        }
        if authority
            .candidates
            .iter()
            .any(|candidate| candidate.public_key == request.public_key)
        {
            return Err(LedgerError::Duplicate(request.public_key));
        }
        if !authority
            .ubo_control
            .validators
            .contains_key(&request.validator_id)
        {
            return Err(LedgerError::Invalid(
                "candidate has no separately governed UBO control record".into(),
            ));
        }

        let sponsor_authorization = &request.resource_envelope.authorization;
        if sponsor_authorization.authorization_id == request.authorization.authorization_id
            || self
                .authorization_nullifiers
                .contains(&sponsor_authorization.authorization_id)
        {
            return Err(LedgerError::Duplicate(
                sponsor_authorization.authorization_id.clone(),
            ));
        }
        let payload_hash = request.payload_hash();
        self.verify_owner_authorization(
            &request.authorization,
            &request.owner,
            REGISTER_CONSENSUS_VALIDATOR_ACTION_V2,
            &payload_hash,
        )?;

        let source_height = u128::from(self.height);
        let source_state_root = self.state_root()?;
        let registered_height = self
            .height
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("candidate registration height overflow".into()))?;
        let candidate = ValidatorCandidateRecord {
            validator_id: request.validator_id.clone(),
            owner: request.owner.clone(),
            public_key: request.public_key.clone(),
            key_era: request.key_era,
            registered_height: u128::from(registered_height),
            exit_height: None,
            proof_of_possession: request.proof_of_possession.clone(),
        };
        let mut candidates = authority.candidates.clone();
        candidates.push(candidate.clone());
        let mut ubo_control = authority.ubo_control.clone();
        ubo_control.predecessor_commitment = ubo_control_commitment_v1(&authority.ubo_control)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        ubo_control.sequence = ubo_control
            .sequence
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("stake UBO sequence overflow".into()))?;
        let update = LedgerStakeAuthorityUpdateV1 {
            authority_version: authority.authority_version,
            sequence: authority
                .sequence
                .checked_add(1)
                .ok_or_else(|| LedgerError::Invalid("stake authority sequence overflow".into()))?,
            expected_previous_commitment: authority.commitment.clone(),
            policy: authority.policy.clone(),
            candidates,
            positions: authority.positions.clone(),
            ubo_control,
        };
        let context = self.stake_context_at(source_height, source_state_root);
        let next_authority = build_ledger_stake_authority_state_v1(
            &context,
            u128::from(registered_height),
            Some(&authority),
            update,
            &self.coins,
        )
        .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if !next_authority.candidates.contains(&candidate) {
            return Err(LedgerError::Invalid(
                "registered candidate disappeared during canonicalization".into(),
            ));
        }

        let wire_bytes = ConsensusCommand::RegisterConsensusValidatorV2(Box::new(request.clone()))
            .wire_v1_command_bytes(&self.descriptor.network_domain)
            .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
        let usage = StakeStateResourceUsageV1 {
            wire_bytes: u32::try_from(wire_bytes.len()).map_err(|_| {
                LedgerError::StakeResource("candidate command exceeds the u32 wire meter".into())
            })?,
            persistent_bytes: register_consensus_validator_persistent_bytes_v2(&request)
                .map_err(|error| LedgerError::StakeResource(error.to_string()))?,
            signature_checks: REGISTER_CONSENSUS_VALIDATOR_SIGNATURE_CHECKS_V2,
            state_reads: REGISTER_CONSENSUS_VALIDATOR_STATE_READS_V2,
            state_writes: REGISTER_CONSENSUS_VALIDATOR_STATE_WRITES_V2,
        };
        let resource_key = format!("CANDIDATE/{}", request.validator_id);
        let admission_request = StakeStateResourceAdmissionRequestV1 {
            resource_key: resource_key.clone(),
            resource_kind: StakeStateResourceKindV1::Candidate,
            resource_owner: request.owner.clone(),
            outer_operation_hash: request.resource_operation_hash(),
            expected_parent_commitment: request.expected_authority_commitment.clone(),
            usage,
            envelope: request.resource_envelope.clone(),
        };
        let funding_coin = self
            .coins
            .get(&request.resource_envelope.funding_coin_id)
            .cloned()
            .ok_or_else(|| {
                LedgerError::CoinNotFound(request.resource_envelope.funding_coin_id.clone())
            })?;
        let mut protected_coin_ids = self
            .consensus_stake_escrows
            .keys()
            .cloned()
            .collect::<BTreeSet<_>>();
        protected_coin_ids.extend(
            accounting
                .bonds()
                .values()
                .map(|record| record.bond_coin_id.clone()),
        );
        let mut next_accounting = accounting;
        let admission = next_accounting
            .admit(
                admission_request,
                &funding_coin,
                &protected_coin_ids,
                registered_height,
            )
            .map_err(|error| LedgerError::StakeResource(error.to_string()))?;

        let mut output_ids = BTreeSet::new();
        for coin in std::iter::once(&admission.bond_coin).chain(admission.change_coin.iter()) {
            if !output_ids.insert(coin.object_id.as_str())
                || self.coins.contains_key(&coin.object_id)
                || coin.object_id == funding_coin.object_id
            {
                return Err(LedgerError::Duplicate(coin.object_id.clone()));
            }
        }
        self.ensure_counter_headroom(1, 0)?;
        let runtime_validator_keys = self.descriptor.validator_keys.clone();
        self.consume_authorization(&request.authorization)?;
        self.consume_authorization(sponsor_authorization)?;
        self.advance()?;
        self.coins.insert(
            admission.consumed_funding_coin.object_id.clone(),
            admission.consumed_funding_coin.clone(),
        );
        self.coins.insert(
            admission.bond_coin.object_id.clone(),
            admission.bond_coin.clone(),
        );
        if let Some(change_coin) = &admission.change_coin {
            self.coins
                .insert(change_coin.object_id.clone(), change_coin.clone());
        }
        self.stake_resource_accounting = Some(next_accounting);
        self.consensus_stake_authority = Some(next_authority);
        if self.descriptor.validator_keys != runtime_validator_keys {
            return Err(LedgerError::StakeResource(
                "candidate admission changed runtime validator membership".into(),
            ));
        }

        Ok(RegisterConsensusValidatorOutcomeV2 {
            candidate,
            resource_key,
            bond_id: admission.bond_record.bond_id.clone(),
            bond_coin_id: admission.bond_record.bond_coin_id.clone(),
            charged_fee: admission.charged_fee,
            locked_bond: admission.locked_bond,
            initial_bond_record_hash: admission.bond_record.initial_record_hash(),
        })
    }

    fn replay_consensus_validator_registration_v2(
        &self,
        request: &RegisterConsensusValidatorRequestV2,
        expected_height: u64,
    ) -> Result<RegisterConsensusValidatorOutcomeV2, LedgerError> {
        let accounting = self.stake_resource_accounting.as_ref().ok_or_else(|| {
            LedgerError::InvalidQuorum(
                "recorded resource-bound candidate has no accounting state".into(),
            )
        })?;
        let wire_bytes = ConsensusCommand::RegisterConsensusValidatorV2(Box::new(request.clone()))
            .wire_v1_command_bytes(&self.descriptor.network_domain)
            .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?;
        let usage = StakeStateResourceUsageV1 {
            wire_bytes: u32::try_from(wire_bytes.len()).map_err(|_| {
                LedgerError::InvalidQuorum("recorded candidate wire meter overflow".into())
            })?,
            persistent_bytes: register_consensus_validator_persistent_bytes_v2(request)
                .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?,
            signature_checks: REGISTER_CONSENSUS_VALIDATOR_SIGNATURE_CHECKS_V2,
            state_reads: REGISTER_CONSENSUS_VALIDATOR_STATE_READS_V2,
            state_writes: REGISTER_CONSENSUS_VALIDATOR_STATE_WRITES_V2,
        };
        let resource_key = format!("CANDIDATE/{}", request.validator_id);
        let admission_request = StakeStateResourceAdmissionRequestV1 {
            resource_key: resource_key.clone(),
            resource_kind: StakeStateResourceKindV1::Candidate,
            resource_owner: request.owner.clone(),
            outer_operation_hash: request.resource_operation_hash(),
            expected_parent_commitment: request.expected_authority_commitment.clone(),
            usage,
            envelope: request.resource_envelope.clone(),
        };
        let expected_subject =
            stake_state_resource_subject_hash_v1(accounting.context(), &admission_request);
        let record = accounting.bonds().get(&resource_key).ok_or_else(|| {
            LedgerError::InvalidQuorum(
                "recorded resource-bound candidate has no retained bond record".into(),
            )
        })?;
        if record.resource_kind != StakeStateResourceKindV1::Candidate
            || record.resource_owner != request.owner
            || record.resource_policy_sequence != request.resource_envelope.resource_policy_sequence
            || record.resource_policy_commitment
                != request.resource_envelope.resource_policy_commitment
            || record.resource_subject_hash != expected_subject
            || record.resource_subject_hash != request.resource_envelope.resource_subject_hash
            || record.sponsor != request.resource_envelope.sponsor
            || record.sponsor_authorization_id
                != request.resource_envelope.authorization.authorization_id
            || record.funding_source_coin_id != request.resource_envelope.funding_coin_id
            || record.created_height != expected_height
            || record.charged_wire_bytes != usage.wire_bytes
            || record.charged_persistent_bytes != usage.persistent_bytes
            || record.charged_signature_checks != usage.signature_checks
            || record.charged_state_reads != usage.state_reads
            || record.charged_state_writes != usage.state_writes
        {
            return Err(LedgerError::InvalidQuorum(
                "recorded resource-bound candidate does not match its immutable admission".into(),
            ));
        }
        Ok(RegisterConsensusValidatorOutcomeV2 {
            candidate: ValidatorCandidateRecord {
                validator_id: request.validator_id.clone(),
                owner: request.owner.clone(),
                public_key: request.public_key.clone(),
                key_era: request.key_era,
                registered_height: u128::from(expected_height),
                exit_height: None,
                proof_of_possession: request.proof_of_possession.clone(),
            },
            resource_key,
            bond_id: record.bond_id.clone(),
            bond_coin_id: record.bond_coin_id.clone(),
            charged_fee: record.charged_creation_fee,
            locked_bond: record.locked_amount,
            initial_bond_record_hash: record.initial_record_hash(),
        })
    }

    fn retained_consensus_stake_position(
        &self,
        position_id: &str,
        escrow_coin_id: Option<&str>,
    ) -> Option<ConsensusStakePosition> {
        let matches = |position: &&ConsensusStakePosition| {
            position.position_id == position_id
                && escrow_coin_id.is_none_or(|coin_id| position.escrow_coin_id == coin_id)
        };
        self.consensus_stake_escrows
            .values()
            .find(matches)
            .or_else(|| {
                self.consensus_stake_unbonds
                    .values()
                    .map(|record| &record.position)
                    .find(matches)
            })
            .or_else(|| {
                self.consensus_stake_slashes
                    .values()
                    .map(|record| &record.position)
                    .find(matches)
            })
            .cloned()
    }

    fn verify_recorded_position_resource_admission(
        &self,
        admission_request: &StakeStateResourceAdmissionRequestV1,
        expected_height: u64,
    ) -> Result<&crate::StakeStateBondRecordV2, LedgerError> {
        let accounting = self.stake_resource_accounting.as_ref().ok_or_else(|| {
            LedgerError::InvalidQuorum(
                "recorded resource-bound position has no accounting state".into(),
            )
        })?;
        let expected_subject =
            stake_state_resource_subject_hash_v1(accounting.context(), admission_request);
        let record = accounting
            .bonds()
            .get(&admission_request.resource_key)
            .ok_or_else(|| {
                LedgerError::InvalidQuorum(
                    "recorded resource-bound position has no retained bond record".into(),
                )
            })?;
        let envelope = &admission_request.envelope;
        let usage = admission_request.usage;
        if record.resource_kind != StakeStateResourceKindV1::Position
            || record.resource_owner != admission_request.resource_owner
            || record.resource_policy_sequence != envelope.resource_policy_sequence
            || record.resource_policy_commitment != envelope.resource_policy_commitment
            || record.resource_subject_hash != expected_subject
            || record.resource_subject_hash != envelope.resource_subject_hash
            || record.sponsor != envelope.sponsor
            || record.sponsor_authorization_id != envelope.authorization.authorization_id
            || record.funding_source_coin_id != envelope.funding_coin_id
            || record.created_height != expected_height
            || record.charged_wire_bytes != usage.wire_bytes
            || record.charged_persistent_bytes != usage.persistent_bytes
            || record.charged_signature_checks != usage.signature_checks
            || record.charged_state_reads != usage.state_reads
            || record.charged_state_writes != usage.state_writes
        {
            return Err(LedgerError::InvalidQuorum(
                "recorded position does not match its immutable resource admission".into(),
            ));
        }
        Ok(record)
    }

    fn verify_recorded_resource_admission(
        &self,
        admission_request: &StakeStateResourceAdmissionRequestV1,
        expected_height: u64,
        expected_kind: StakeStateResourceKindV1,
        label: &str,
    ) -> Result<&crate::StakeStateBondRecordV2, LedgerError> {
        let accounting = self.stake_resource_accounting.as_ref().ok_or_else(|| {
            LedgerError::InvalidQuorum(format!("recorded {label} has no resource accounting state"))
        })?;
        let expected_subject =
            stake_state_resource_subject_hash_v1(accounting.context(), admission_request);
        let record = accounting
            .bonds()
            .get(&admission_request.resource_key)
            .ok_or_else(|| {
                LedgerError::InvalidQuorum(format!(
                    "recorded {label} has no retained resource bond"
                ))
            })?;
        let envelope = &admission_request.envelope;
        let usage = admission_request.usage;
        if record.resource_kind != expected_kind
            || record.resource_owner != admission_request.resource_owner
            || record.resource_policy_sequence != envelope.resource_policy_sequence
            || record.resource_policy_commitment != envelope.resource_policy_commitment
            || record.resource_subject_hash != expected_subject
            || record.resource_subject_hash != envelope.resource_subject_hash
            || record.sponsor != envelope.sponsor
            || record.sponsor_authorization_id != envelope.authorization.authorization_id
            || record.funding_source_coin_id != envelope.funding_coin_id
            || record.created_height != expected_height
            || record.charged_wire_bytes != usage.wire_bytes
            || record.charged_persistent_bytes != usage.persistent_bytes
            || record.charged_signature_checks != usage.signature_checks
            || record.charged_state_reads != usage.state_reads
            || record.charged_state_writes != usage.state_writes
        {
            return Err(LedgerError::InvalidQuorum(format!(
                "recorded {label} does not match its immutable resource admission"
            )));
        }
        Ok(record)
    }

    fn replay_consensus_stake_lock_v3(
        &self,
        request: &LockConsensusStakeRequestV3,
        expected_height: u64,
    ) -> Result<LockConsensusStakeOutcomeV3, LedgerError> {
        let position = self
            .retained_consensus_stake_position(&request.position_id, None)
            .ok_or_else(|| {
                LedgerError::InvalidQuorum(
                    "recorded V3 lock has no retained position or permanent tombstone".into(),
                )
            })?;
        let expected_kind = match request.position_type {
            StakePositionTypeV1::SelfBond => ConsensusStakePositionKind::SelfBond {
                validator_id: request.validator_id.clone(),
            },
            StakePositionTypeV1::Delegation => ConsensusStakePositionKind::Delegation {
                validator_id: request.validator_id.clone(),
            },
        };
        let expected_terms = ConsensusStakeSlashTermsV2 {
            terms_version: ConsensusStakeSlashPolicyV2::protocol_v2().policy_version,
            slash_policy: ConsensusStakeSlashPolicyV2::protocol_v2(),
            owner_authorization: request.slash_terms_authorization.clone(),
        };
        if position.kind != expected_kind
            || position.owner != request.owner
            || position.source_coin_id != request.source_coin_id
            || position.amount != request.amount
            || position.locked_height != u128::from(expected_height)
            || position.committed_through_height != u128::from(request.committed_through_height)
            || position.slash_terms.as_ref() != Some(&expected_terms)
        {
            return Err(LedgerError::InvalidQuorum(
                "recorded V3 lock does not match its immutable position".into(),
            ));
        }
        let wire_bytes = ConsensusCommand::LockConsensusStakeV3(Box::new(request.clone()))
            .wire_v1_command_bytes(&self.descriptor.network_domain)
            .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?;
        let usage = StakeStateResourceUsageV1 {
            wire_bytes: u32::try_from(wire_bytes.len()).map_err(|_| {
                LedgerError::InvalidQuorum("recorded V3 stake wire meter overflow".into())
            })?,
            persistent_bytes: lock_consensus_stake_persistent_bytes_v3(request)
                .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?,
            signature_checks: LOCK_CONSENSUS_STAKE_SIGNATURE_CHECKS_V3,
            state_reads: LOCK_CONSENSUS_STAKE_STATE_READS_V3,
            state_writes: LOCK_CONSENSUS_STAKE_STATE_WRITES_V3,
        };
        let resource_key = format!("POSITION/{}", request.position_id);
        let admission_request = StakeStateResourceAdmissionRequestV1 {
            resource_key: resource_key.clone(),
            resource_kind: StakeStateResourceKindV1::Position,
            resource_owner: request.owner.clone(),
            outer_operation_hash: request.resource_operation_hash(),
            expected_parent_commitment: request.expected_authority_commitment.clone(),
            usage,
            envelope: request.resource_envelope.clone(),
        };
        let record =
            self.verify_recorded_position_resource_admission(&admission_request, expected_height)?;
        Ok(LockConsensusStakeOutcomeV3 {
            position,
            resource_key,
            bond_id: record.bond_id.clone(),
            bond_coin_id: record.bond_coin_id.clone(),
            charged_fee: record.charged_creation_fee,
            locked_bond: record.locked_amount,
            initial_bond_record_hash: record.initial_record_hash(),
        })
    }

    fn replay_consensus_stake_resource_migration(
        &self,
        request: &MigrateConsensusStakeResourceRequestV1,
        expected_height: u64,
    ) -> Result<MigrateConsensusStakeResourceOutcomeV1, LedgerError> {
        let position = self
            .retained_consensus_stake_position(&request.position_id, Some(&request.escrow_coin_id))
            .filter(|position| {
                position.owner == request.owner
                    && position.resource_commitment_v1() == request.expected_position_commitment
            })
            .ok_or_else(|| {
                LedgerError::InvalidQuorum(
                    "recorded resource migration has no exact retained position".into(),
                )
            })?;
        let wire_bytes = ConsensusCommand::MigrateConsensusStakeResource(Box::new(request.clone()))
            .wire_v1_command_bytes(&self.descriptor.network_domain)
            .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?;
        let usage = StakeStateResourceUsageV1 {
            wire_bytes: u32::try_from(wire_bytes.len()).map_err(|_| {
                LedgerError::InvalidQuorum("recorded resource migration wire overflow".into())
            })?,
            persistent_bytes: migrate_consensus_stake_resource_persistent_bytes_v1(
                request, &position,
            )
            .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?,
            signature_checks: MIGRATE_CONSENSUS_STAKE_RESOURCE_SIGNATURE_CHECKS_V1,
            state_reads: MIGRATE_CONSENSUS_STAKE_RESOURCE_STATE_READS_V1,
            state_writes: MIGRATE_CONSENSUS_STAKE_RESOURCE_STATE_WRITES_V1,
        };
        let resource_key = format!("POSITION/{}", request.position_id);
        let admission_request = StakeStateResourceAdmissionRequestV1 {
            resource_key: resource_key.clone(),
            resource_kind: StakeStateResourceKindV1::Position,
            resource_owner: request.owner.clone(),
            outer_operation_hash: request.resource_operation_hash(),
            expected_parent_commitment: request.expected_authority_commitment.clone(),
            usage,
            envelope: request.resource_envelope.clone(),
        };
        let record =
            self.verify_recorded_position_resource_admission(&admission_request, expected_height)?;
        Ok(MigrateConsensusStakeResourceOutcomeV1 {
            position,
            resource_key,
            bond_id: record.bond_id.clone(),
            bond_coin_id: record.bond_coin_id.clone(),
            charged_fee: record.charged_creation_fee,
            locked_bond: record.locked_amount,
            initial_bond_record_hash: record.initial_record_hash(),
        })
    }

    fn replay_consensus_candidate_resource_migration(
        &self,
        request: &MigrateConsensusCandidateResourceRequestV1,
        expected_height: u64,
    ) -> Result<MigrateConsensusCandidateResourceOutcomeV1, LedgerError> {
        let candidate = ValidatorCandidateRecord {
            validator_id: request.validator_id.clone(),
            owner: request.owner.clone(),
            public_key: request.public_key.clone(),
            key_era: request.key_era,
            registered_height: u128::from(request.registered_height),
            exit_height: request.exit_height.map(u128::from),
            proof_of_possession: request.proof_of_possession.clone(),
        };
        if candidate.resource_commitment_v1() != request.expected_candidate_commitment {
            return Err(LedgerError::InvalidQuorum(
                "recorded candidate migration commitment is not self-consistent".into(),
            ));
        }
        let retained = self
            .consensus_stake_authority
            .as_ref()
            .and_then(|authority| {
                authority
                    .candidates
                    .iter()
                    .find(|current| current.validator_id == candidate.validator_id)
            })
            .ok_or_else(|| {
                LedgerError::InvalidQuorum(
                    "recorded candidate migration has no retained candidate".into(),
                )
            })?;
        let exit_history_matches = match candidate.exit_height {
            Some(recorded_exit) => retained.exit_height == Some(recorded_exit),
            None => true,
        };
        if retained.owner != candidate.owner
            || retained.public_key != candidate.public_key
            || retained.key_era != candidate.key_era
            || retained.registered_height != candidate.registered_height
            || retained.proof_of_possession != candidate.proof_of_possession
            || !exit_history_matches
        {
            return Err(LedgerError::InvalidQuorum(
                "retained candidate diverges from recorded migration history".into(),
            ));
        }
        let wire_bytes =
            ConsensusCommand::MigrateConsensusCandidateResource(Box::new(request.clone()))
                .wire_v1_command_bytes(&self.descriptor.network_domain)
                .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?;
        let usage = StakeStateResourceUsageV1 {
            wire_bytes: u32::try_from(wire_bytes.len()).map_err(|_| {
                LedgerError::InvalidQuorum("recorded candidate migration wire overflow".into())
            })?,
            persistent_bytes: migrate_consensus_candidate_resource_persistent_bytes_v1(
                request, &candidate,
            )
            .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?,
            signature_checks: MIGRATE_CONSENSUS_CANDIDATE_RESOURCE_SIGNATURE_CHECKS_V1,
            state_reads: MIGRATE_CONSENSUS_CANDIDATE_RESOURCE_STATE_READS_V1,
            state_writes: MIGRATE_CONSENSUS_CANDIDATE_RESOURCE_STATE_WRITES_V1,
        };
        let resource_key = format!("CANDIDATE/{}", request.validator_id);
        let admission_request = StakeStateResourceAdmissionRequestV1 {
            resource_key: resource_key.clone(),
            resource_kind: StakeStateResourceKindV1::Candidate,
            resource_owner: request.owner.clone(),
            outer_operation_hash: request.resource_operation_hash(),
            expected_parent_commitment: request.expected_authority_commitment.clone(),
            usage,
            envelope: request.resource_envelope.clone(),
        };
        let record = self.verify_recorded_resource_admission(
            &admission_request,
            expected_height,
            StakeStateResourceKindV1::Candidate,
            "candidate migration",
        )?;
        Ok(MigrateConsensusCandidateResourceOutcomeV1 {
            candidate,
            resource_key,
            bond_id: record.bond_id.clone(),
            bond_coin_id: record.bond_coin_id.clone(),
            charged_fee: record.charged_creation_fee,
            locked_bond: record.locked_amount,
            initial_bond_record_hash: record.initial_record_hash(),
        })
    }

    fn replay_next_stake_epoch_v2(
        &self,
        request: &DeriveNextStakeEpochRequestV2,
        expected_height: u64,
    ) -> Result<DeriveNextStakeEpochOutcomeV2, LedgerError> {
        let epoch = self
            .derived_stake_epochs
            .get(&request.expected_consensus_epoch)
            .filter(|record| record.record_hash == request.expected_derived_record_hash)
            .cloned()
            .ok_or_else(|| {
                LedgerError::InvalidQuorum(
                    "recorded resource-bound Epoch has no exact retained record".into(),
                )
            })?;
        let wire_bytes = ConsensusCommand::DeriveNextStakeEpochV2(Box::new(request.clone()))
            .wire_v1_command_bytes(&self.descriptor.network_domain)
            .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?;
        let horizon_usage =
            self.recorded_stake_liability_horizon_usage(epoch.descriptor.consensus_epoch)?;
        let usage = StakeStateResourceUsageV1 {
            wire_bytes: u32::try_from(wire_bytes.len()).map_err(|_| {
                LedgerError::InvalidQuorum("recorded Epoch V2 wire overflow".into())
            })?,
            persistent_bytes: derive_next_stake_epoch_persistent_bytes_v2(
                request,
                &epoch,
                horizon_usage,
            )
            .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?,
            signature_checks: DERIVE_NEXT_STAKE_EPOCH_SIGNATURE_CHECKS_V2,
            state_reads: derive_next_stake_epoch_state_reads_v2(&epoch, horizon_usage)
                .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?,
            state_writes: derive_next_stake_epoch_state_writes_v2(horizon_usage)
                .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?,
        };
        let resource_key = format!("EPOCH/{}", request.expected_consensus_epoch);
        let admission_request = StakeStateResourceAdmissionRequestV1 {
            resource_key: resource_key.clone(),
            resource_kind: StakeStateResourceKindV1::Epoch,
            resource_owner: request.payer.clone(),
            outer_operation_hash: request.resource_operation_hash(),
            expected_parent_commitment: epoch.previous_record_hash.clone(),
            usage,
            envelope: request.resource_envelope.clone(),
        };
        let record = self.verify_recorded_resource_admission(
            &admission_request,
            expected_height,
            StakeStateResourceKindV1::Epoch,
            "resource-bound Epoch",
        )?;
        Ok(DeriveNextStakeEpochOutcomeV2 {
            epoch,
            resource_key,
            bond_id: record.bond_id.clone(),
            bond_coin_id: record.bond_coin_id.clone(),
            charged_fee: record.charged_creation_fee,
            locked_bond: record.locked_amount,
            initial_bond_record_hash: record.initial_record_hash(),
        })
    }

    /// Sets a candidate's immutable exit height. Both the owner wallet and the
    /// candidate consensus key authorize the exact updated record.
    pub fn exit_consensus_validator(
        &mut self,
        request: ExitConsensusValidatorRequestV1,
    ) -> Result<ValidatorCandidateRecord, LedgerError> {
        let mut staged = self.clone();
        let candidate = staged.apply_consensus_validator_exit(request)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(candidate)
    }

    fn apply_consensus_validator_exit(
        &mut self,
        request: ExitConsensusValidatorRequestV1,
    ) -> Result<ValidatorCandidateRecord, LedgerError> {
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "consensus validator exit requires VALUE_CAP_0".into(),
            ));
        }
        if request.request_id.trim().is_empty()
            || request.validator_id.trim().is_empty()
            || request.owner.trim().is_empty()
            || request.public_key.trim().is_empty()
            || request.proof_of_possession.trim().is_empty()
        {
            return Err(LedgerError::Invalid(
                "consensus validator exit request is incomplete".into(),
            ));
        }
        if request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "consensus validator exit Zone, currency or era binding mismatch".into(),
            ));
        }
        if request.proposed_height != self.height {
            return Err(LedgerError::Invalid(
                "consensus validator exit height does not match current state".into(),
            ));
        }
        if request.expires_at_height <= self.height {
            return Err(LedgerError::Invalid(
                "consensus validator exit request expired".into(),
            ));
        }

        let authority = self
            .consensus_stake_authority
            .clone()
            .ok_or_else(|| LedgerError::Invalid("ledger has no staged stake authority".into()))?;
        validate_ledger_stake_authority_state_v1(&authority)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if authority.sequence != request.expected_authority_sequence
            || authority.commitment != request.expected_authority_commitment
        {
            return Err(LedgerError::Invalid(
                "consensus validator exit authority precondition mismatch".into(),
            ));
        }
        let mut candidate = authority
            .candidates
            .iter()
            .find(|candidate| candidate.validator_id == request.validator_id)
            .cloned()
            .ok_or_else(|| LedgerError::Invalid("validator candidate was not found".into()))?;
        if candidate.owner != request.owner {
            return Err(LedgerError::OwnerMismatch);
        }
        if candidate.public_key != request.public_key
            || candidate.key_era != request.key_era
            || candidate.registered_height != u128::from(request.registered_height)
        {
            return Err(LedgerError::Invalid(
                "candidate exit does not bind the exact registered candidate".into(),
            ));
        }
        if candidate.exit_height.is_some() {
            return Err(LedgerError::Invalid(
                "validator candidate exit is already final".into(),
            ));
        }
        let effective_height = self
            .height
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("candidate exit height overflow".into()))?;
        let notice_end = u128::from(effective_height)
            .checked_add(authority.policy.activation_delay_blocks)
            .ok_or_else(|| LedgerError::Invalid("candidate exit notice overflow".into()))?;
        let protected_epoch_end = self
            .derived_stake_epochs
            .values()
            .filter(|record| {
                record
                    .descriptor
                    .validators
                    .iter()
                    .any(|validator| validator.validator_id == candidate.validator_id)
            })
            .map(|record| record.descriptor.exit_height)
            .max()
            .unwrap_or(0);
        let minimum_exit_height = notice_end.max(protected_epoch_end);
        if u128::from(request.exit_height) < minimum_exit_height
            || u128::from(request.exit_height) <= candidate.registered_height
        {
            return Err(LedgerError::Invalid(
                "candidate exit does not preserve notice and already-derived Epoch windows".into(),
            ));
        }
        candidate.exit_height = Some(u128::from(request.exit_height));
        candidate.proof_of_possession = request.proof_of_possession.clone();

        let payload_hash = request.payload_hash();
        self.verify_owner_authorization(
            &request.authorization,
            &request.owner,
            EXIT_CONSENSUS_VALIDATOR_ACTION_V1,
            &payload_hash,
        )?;
        self.ensure_counter_headroom(1, 0)?;
        let source_height = u128::from(self.height);
        let source_state_root = self.state_root()?;
        self.consume_authorization(&request.authorization)?;
        self.advance()?;

        let mut candidates = authority.candidates.clone();
        let candidate_slot = candidates
            .iter_mut()
            .find(|existing| existing.validator_id == candidate.validator_id)
            .expect("candidate was checked");
        *candidate_slot = candidate.clone();
        let mut ubo_control = authority.ubo_control.clone();
        ubo_control.predecessor_commitment = ubo_control_commitment_v1(&authority.ubo_control)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        ubo_control.sequence = ubo_control
            .sequence
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("stake UBO sequence overflow".into()))?;
        let update = LedgerStakeAuthorityUpdateV1 {
            authority_version: authority.authority_version,
            sequence: authority
                .sequence
                .checked_add(1)
                .ok_or_else(|| LedgerError::Invalid("stake authority sequence overflow".into()))?,
            expected_previous_commitment: authority.commitment.clone(),
            policy: authority.policy.clone(),
            candidates,
            positions: authority.positions.clone(),
            ubo_control,
        };
        let context = self.stake_context_at(source_height, source_state_root);
        let next_authority = build_ledger_stake_authority_state_v1(
            &context,
            u128::from(self.height),
            Some(&authority),
            update,
            &self.coins,
        )
        .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if !next_authority.candidates.contains(&candidate) {
            return Err(LedgerError::Invalid(
                "exited candidate disappeared during canonicalization".into(),
            ));
        }
        self.consensus_stake_authority = Some(next_authority);
        Ok(candidate)
    }

    /// Persists exactly the deterministic next candidate Epoch.  The request
    /// carries only preconditions; it cannot supply a validator set and it
    /// never changes the runtime descriptor's validator keys.
    pub fn derive_next_stake_epoch(
        &mut self,
        request: DeriveNextStakeEpochRequestV1,
    ) -> Result<LedgerDerivedStakeEpochV1, LedgerError> {
        if self.stake_resource_accounting.is_some() {
            return Err(LedgerError::StakeResource(
                "legacy stake Epoch derivation is disabled after resource-policy activation; use V2"
                    .into(),
            ));
        }
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "stake Epoch derivation requires VALUE_CAP_0".into(),
            ));
        }
        if request.request_id.trim().is_empty() {
            return Err(LedgerError::Invalid(
                "stake Epoch derivation request id is required".into(),
            ));
        }
        if request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "stake Epoch request Zone, currency or era binding mismatch".into(),
            ));
        }
        if request.proposed_height != self.height || request.expected_snapshot_height != self.height
        {
            return Err(LedgerError::Invalid(
                "stake Epoch request height does not match current state".into(),
            ));
        }
        if request.expires_at_height <= self.height {
            return Err(LedgerError::Invalid(
                "stake Epoch derivation request expired".into(),
            ));
        }
        let authority = self
            .consensus_stake_authority
            .as_ref()
            .ok_or_else(|| LedgerError::Invalid("ledger has no staged stake authority".into()))?;
        if authority.sequence != request.expected_authority_sequence
            || authority.commitment != request.expected_authority_commitment
        {
            return Err(LedgerError::Invalid(
                "stake Epoch request authority precondition mismatch".into(),
            ));
        }
        let expected_epoch = self
            .derived_stake_epochs
            .keys()
            .next_back()
            .copied()
            .unwrap_or(0)
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("stake Epoch overflow".into()))?;
        if request.expected_consensus_epoch != expected_epoch {
            return Err(LedgerError::Invalid(
                "stake Epoch request sequence precondition mismatch".into(),
            ));
        }
        let root = self.state_root()?;
        if request.expected_snapshot_state_root != root {
            return Err(LedgerError::Invalid(
                "stake Epoch request state-root precondition mismatch".into(),
            ));
        }
        let runtime_validator_keys = self.descriptor.validator_keys.clone();
        let mut staged = self.clone();
        let record = staged.derive_and_store_next_stake_epoch()?;
        if record.descriptor.consensus_epoch != expected_epoch
            || staged.descriptor.validator_keys != runtime_validator_keys
        {
            return Err(LedgerError::Invalid(
                "stake Epoch derivation changed an immutable precondition".into(),
            ));
        }
        *self = staged;
        Ok(record)
    }

    /// Persists one deterministic Epoch only when every selected candidate,
    /// every retained liability and the new Epoch record itself have funded
    /// resource responsibility through the evidence/retention boundary.
    pub fn derive_next_stake_epoch_v2(
        &mut self,
        request: DeriveNextStakeEpochRequestV2,
    ) -> Result<DeriveNextStakeEpochOutcomeV2, LedgerError> {
        let mut staged = self.clone();
        let outcome = staged.apply_next_stake_epoch_v2(request)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(outcome)
    }

    fn apply_next_stake_epoch_v2(
        &mut self,
        request: DeriveNextStakeEpochRequestV2,
    ) -> Result<DeriveNextStakeEpochOutcomeV2, LedgerError> {
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "resource-bound stake Epoch derivation requires VALUE_CAP_0".into(),
            ));
        }
        if request.request_id.trim().is_empty()
            || request.payer.trim().is_empty()
            || !is_canonical_sha256_hex(&request.expected_derived_record_hash)
        {
            return Err(LedgerError::Invalid(
                "resource-bound stake Epoch request is incomplete or noncanonical".into(),
            ));
        }
        if request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "resource-bound stake Epoch Zone, currency or era binding mismatch".into(),
            ));
        }
        if request.proposed_height != self.height
            || request.expected_snapshot_height != self.height
            || request.expires_at_height <= self.height
        {
            return Err(LedgerError::Invalid(
                "resource-bound stake Epoch height is stale or expired".into(),
            ));
        }
        let authority = self
            .consensus_stake_authority
            .clone()
            .ok_or_else(|| LedgerError::Invalid("ledger has no staged stake authority".into()))?;
        validate_ledger_stake_authority_state_v1(&authority)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if authority.sequence != request.expected_authority_sequence
            || authority.commitment != request.expected_authority_commitment
        {
            return Err(LedgerError::Invalid(
                "resource-bound stake Epoch authority precondition mismatch".into(),
            ));
        }
        let expected_epoch = self
            .derived_stake_epochs
            .keys()
            .next_back()
            .copied()
            .unwrap_or(0)
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("stake Epoch overflow".into()))?;
        if request.expected_consensus_epoch != expected_epoch {
            return Err(LedgerError::Invalid(
                "resource-bound stake Epoch sequence precondition mismatch".into(),
            ));
        }
        let snapshot_root = self.state_root()?;
        if request.expected_snapshot_state_root != snapshot_root {
            return Err(LedgerError::Invalid(
                "resource-bound stake Epoch state-root precondition mismatch".into(),
            ));
        }

        // Preview on an isolated copy. The output hash is signed by the payer
        // and sponsor before any Coin, nullifier or Epoch record is mutated.
        let mut preview_ledger = self.clone();
        let preview = preview_ledger.derive_and_store_next_stake_epoch()?;
        if preview.derivation_version != crate::STAKE_EPOCH_DERIVATION_VERSION_V2
            || preview.descriptor.consensus_epoch != expected_epoch
            || preview.record_hash != request.expected_derived_record_hash
        {
            return Err(LedgerError::Invalid(
                "resource-bound stake Epoch requires derivation v2 and an exact output commitment"
                    .into(),
            ));
        }
        let (preview_horizons, preview_horizon_history) =
            self.preview_stake_liability_horizon_update(&preview)?;
        let horizon_usage = stake_liability_horizon_usage_delta_v1(
            &self.stake_position_liability_horizons,
            &self.stake_position_liability_horizon_history,
            &preview_horizons,
            &preview_horizon_history,
        )
        .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
        let accounting = self
            .stake_resource_accounting
            .as_ref()
            .ok_or_else(|| LedgerError::StakeResource("no active stake resource policy".into()))?;
        self.validate_stake_resource_policy_covers_inventory(
            accounting.active_policy(),
            None,
            None,
        )?;
        let evidence_deadline = preview
            .descriptor
            .exit_height
            .checked_add(authority.policy.evidence_window_blocks)
            .ok_or_else(|| LedgerError::StakeResource("Epoch evidence deadline overflow".into()))?;
        let required_lease_end_u128 = evidence_deadline
            .checked_add(u128::from(
                accounting.active_policy().terminal_retention_blocks,
            ))
            .ok_or_else(|| {
                LedgerError::StakeResource("Epoch retention deadline overflow".into())
            })?;
        let required_lease_end = u64::try_from(required_lease_end_u128).map_err(|_| {
            LedgerError::StakeResource("Epoch retention deadline exceeds runtime height".into())
        })?;
        if request.resource_envelope.lease_end_height < required_lease_end {
            return Err(LedgerError::StakeResource(
                "Epoch resource lease does not cover exit, evidence and terminal retention".into(),
            ));
        }
        for validator in &preview.descriptor.validators {
            let candidate = authority
                .candidates
                .iter()
                .find(|candidate| candidate.validator_id == validator.validator_id)
                .ok_or_else(|| {
                    LedgerError::StakeResource(
                        "derived validator has no exact retained candidate".into(),
                    )
                })?;
            let resource_key = format!("CANDIDATE/{}", validator.validator_id);
            let bond = accounting.bonds().get(&resource_key).ok_or_else(|| {
                LedgerError::StakeResource(format!(
                    "selected candidate lacks resource responsibility: {}",
                    validator.validator_id
                ))
            })?;
            if bond.resource_kind != StakeStateResourceKindV1::Candidate
                || bond.resource_owner != candidate.owner
                || bond.status != StakeStateBondStatusV1::Locked
                || accounting.effective_lease_end_height(&resource_key) < Some(required_lease_end)
            {
                return Err(LedgerError::StakeResource(format!(
                    "selected candidate resource bond is ineligible or too short: {}",
                    validator.validator_id
                )));
            }
        }
        for liability in &preview.stake_liabilities {
            let resource_key = format!("POSITION/{}", liability.position.position_id);
            let bond = accounting.bonds().get(&resource_key).ok_or_else(|| {
                LedgerError::StakeResource(format!(
                    "Epoch liability lacks resource responsibility: {}",
                    liability.position.position_id
                ))
            })?;
            if bond.resource_kind != StakeStateResourceKindV1::Position
                || bond.resource_owner != liability.position.owner
                || bond.status != StakeStateBondStatusV1::Locked
                || accounting.effective_lease_end_height(&resource_key) < Some(required_lease_end)
            {
                return Err(LedgerError::StakeResource(format!(
                    "Epoch liability resource bond is ineligible or too short: {}",
                    liability.position.position_id
                )));
            }
        }

        let sponsor_authorization = &request.resource_envelope.authorization;
        if request.authorization.authorization_id == sponsor_authorization.authorization_id
            || self
                .authorization_nullifiers
                .contains(sponsor_authorization.authorization_id.as_str())
        {
            return Err(LedgerError::Duplicate(
                sponsor_authorization.authorization_id.clone(),
            ));
        }
        let payload_hash = request.payload_hash();
        self.verify_owner_authorization(
            &request.authorization,
            &request.payer,
            DERIVE_NEXT_STAKE_EPOCH_ACTION_V2,
            &payload_hash,
        )?;
        let wire_bytes = ConsensusCommand::DeriveNextStakeEpochV2(Box::new(request.clone()))
            .wire_v1_command_bytes(&self.descriptor.network_domain)
            .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
        let usage = StakeStateResourceUsageV1 {
            wire_bytes: u32::try_from(wire_bytes.len()).map_err(|_| {
                LedgerError::StakeResource("Epoch V2 command exceeds the u32 wire meter".into())
            })?,
            persistent_bytes: derive_next_stake_epoch_persistent_bytes_v2(
                &request,
                &preview,
                horizon_usage,
            )
            .map_err(|error| LedgerError::StakeResource(error.to_string()))?,
            signature_checks: DERIVE_NEXT_STAKE_EPOCH_SIGNATURE_CHECKS_V2,
            state_reads: derive_next_stake_epoch_state_reads_v2(&preview, horizon_usage)
                .map_err(|error| LedgerError::StakeResource(error.to_string()))?,
            state_writes: derive_next_stake_epoch_state_writes_v2(horizon_usage)
                .map_err(|error| LedgerError::StakeResource(error.to_string()))?,
        };
        let resource_key = format!("EPOCH/{expected_epoch}");
        let admission_request = StakeStateResourceAdmissionRequestV1 {
            resource_key: resource_key.clone(),
            resource_kind: StakeStateResourceKindV1::Epoch,
            resource_owner: request.payer.clone(),
            outer_operation_hash: request.resource_operation_hash(),
            expected_parent_commitment: preview.previous_record_hash.clone(),
            usage,
            envelope: request.resource_envelope.clone(),
        };
        let admission_height = self
            .height
            .checked_add(1)
            .ok_or_else(|| LedgerError::StakeResource("Epoch V2 height overflow".into()))?;
        let (next_accounting, admission) =
            self.prepare_position_resource_admission(admission_request, admission_height)?;
        let runtime_validator_keys = self.descriptor.validator_keys.clone();
        let actual = self.derive_and_store_next_stake_epoch()?;
        if actual != preview || self.height != admission_height {
            return Err(LedgerError::StakeResource(
                "Epoch derivation diverged from the funded preview".into(),
            ));
        }
        self.stake_position_liability_horizons = preview_horizons;
        self.stake_position_liability_horizon_history = preview_horizon_history;
        self.stake_liability_horizon_activation_epoch
            .get_or_insert(expected_epoch);
        self.consume_authorization(&request.authorization)?;
        self.commit_position_resource_admission(
            next_accounting,
            &admission,
            sponsor_authorization,
        )?;
        if self.descriptor.validator_keys != runtime_validator_keys {
            return Err(LedgerError::StakeResource(
                "resource-bound Epoch changed runtime validator membership".into(),
            ));
        }
        Ok(DeriveNextStakeEpochOutcomeV2 {
            epoch: actual,
            resource_key,
            bond_id: admission.bond_record.bond_id.clone(),
            bond_coin_id: admission.bond_record.bond_coin_id.clone(),
            charged_fee: admission.charged_fee,
            locked_bond: admission.locked_bond,
            initial_bond_record_hash: admission.bond_record.initial_record_hash(),
        })
    }

    fn stake_resource_context(&self) -> StakeStateResourceContextV1 {
        StakeStateResourceContextV1 {
            network_domain: self.descriptor.network_domain.clone(),
            zone_id: self.descriptor.zone_id.clone(),
            currency_genesis_root: self.descriptor.currency_genesis_root.clone(),
            protocol_era: self.descriptor.protocol_era,
            crypto_era: self.descriptor.crypto_era,
        }
    }

    /// Extends only the lease of one already-accounted resource. The covered
    /// candidate/position/Epoch and its original bond record remain untouched.
    pub fn renew_stake_state_resource_bond(
        &mut self,
        request: RenewStakeStateResourceBondRequestV1,
    ) -> Result<RenewStakeStateResourceBondOutcomeV1, LedgerError> {
        let mut staged = self.clone();
        let outcome = staged.apply_stake_state_resource_bond_renewal(request)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(outcome)
    }

    fn apply_stake_state_resource_bond_renewal(
        &mut self,
        request: RenewStakeStateResourceBondRequestV1,
    ) -> Result<RenewStakeStateResourceBondOutcomeV1, LedgerError> {
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "resource-bond renewal requires VALUE_CAP_0".into(),
            ));
        }
        if request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
            || request.proposed_height != self.height
            || request.expires_at_height < self.height
            || request.expires_at_height <= request.proposed_height
        {
            return Err(LedgerError::StakeResource(
                "renewal context, era or height mismatch".into(),
            ));
        }
        let accounting = self
            .stake_resource_accounting
            .as_ref()
            .ok_or_else(|| LedgerError::StakeResource("no active stake resource policy".into()))?;
        let original = accounting
            .bonds()
            .get(&request.resource_key)
            .ok_or_else(|| {
                LedgerError::StakeResource("renewal refers to an unknown resource".into())
            })?;
        let subject_exists = match request.resource_kind {
            StakeStateResourceKindV1::Candidate => self
                .consensus_stake_authority
                .as_ref()
                .is_some_and(|authority| {
                    authority.candidates.iter().any(|candidate| {
                        request.resource_key == format!("CANDIDATE/{}", candidate.validator_id)
                            && candidate.owner == request.resource_owner
                    })
                }),
            StakeStateResourceKindV1::Position => {
                let exact = |position: &ConsensusStakePosition| {
                    request.resource_key == format!("POSITION/{}", position.position_id)
                        && position.owner == request.resource_owner
                        && position.slash_terms.is_some()
                };
                self.consensus_stake_escrows.values().any(exact)
                    || self
                        .consensus_stake_unbonds
                        .values()
                        .any(|record| exact(&record.position))
                    || self
                        .consensus_stake_slashes
                        .values()
                        .any(|record| exact(&record.position))
            }
            StakeStateResourceKindV1::Epoch => self.derived_stake_epochs.values().any(|record| {
                request.resource_key == format!("EPOCH/{}", record.descriptor.consensus_epoch)
            }),
            StakeStateResourceKindV1::Unbond | StakeStateResourceKindV1::SlashEvidence => false,
        };
        if !subject_exists
            || original.resource_kind != request.resource_kind
            || original.resource_owner != request.resource_owner
        {
            return Err(LedgerError::StakeResource(
                "renewal resource subject is missing or does not match retained state".into(),
            ));
        }
        let wire_bytes = ConsensusCommand::RenewStakeStateResourceBond(Box::new(request.clone()))
            .wire_v1_command_bytes(&self.descriptor.network_domain)
            .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
        let usage = StakeStateResourceUsageV1 {
            wire_bytes: u32::try_from(wire_bytes.len())
                .map_err(|_| LedgerError::StakeResource("renewal wire length overflow".into()))?,
            persistent_bytes: renew_stake_state_resource_bond_persistent_bytes_v1(&request)
                .map_err(|error| LedgerError::StakeResource(error.to_string()))?,
            signature_checks: RENEW_STAKE_STATE_RESOURCE_BOND_SIGNATURE_CHECKS_V1,
            state_reads: RENEW_STAKE_STATE_RESOURCE_BOND_STATE_READS_V1,
            state_writes: RENEW_STAKE_STATE_RESOURCE_BOND_STATE_WRITES_V1,
        };
        let funding_coin = self
            .coins
            .get(&request.funding_coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(request.funding_coin_id.clone()))?;
        let mut protected_coin_ids = self
            .consensus_stake_escrows
            .keys()
            .cloned()
            .collect::<BTreeSet<_>>();
        protected_coin_ids.extend(
            accounting
                .bonds()
                .values()
                .map(|record| record.bond_coin_id.clone()),
        );
        protected_coin_ids.extend(
            accounting
                .renewals()
                .values()
                .map(|record| record.bond_coin_id.clone()),
        );
        let renewal_height = self
            .height
            .checked_add(1)
            .ok_or_else(|| LedgerError::StakeResource("renewal height overflow".into()))?;
        let mut next_accounting = accounting.clone();
        let renewal = next_accounting
            .renew(
                &request,
                usage,
                &funding_coin,
                &protected_coin_ids,
                renewal_height,
            )
            .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
        let mut output_ids = BTreeSet::new();
        for coin in std::iter::once(&renewal.bond_coin).chain(renewal.change_coin.iter()) {
            if !output_ids.insert(coin.object_id.as_str())
                || self.coins.contains_key(&coin.object_id)
                || coin.object_id == renewal.consumed_funding_coin.object_id
            {
                return Err(LedgerError::Duplicate(coin.object_id.clone()));
            }
        }
        let current_funding = self
            .coins
            .get(&renewal.consumed_funding_coin.object_id)
            .ok_or_else(|| {
                LedgerError::CoinNotFound(renewal.consumed_funding_coin.object_id.clone())
            })?;
        if current_funding.state != CoinState::Spendable
            || current_funding.version != renewal.consumed_funding_coin.version
            || current_funding.amount != renewal.consumed_funding_coin.amount
            || current_funding.owner != renewal.consumed_funding_coin.owner
        {
            return Err(LedgerError::StakeResource(
                "renewal funding Coin changed before atomic commit".into(),
            ));
        }
        self.ensure_counter_headroom(1, 0)?;
        self.consume_authorization(&request.authorization)?;
        self.advance()?;
        self.coins.insert(
            renewal.consumed_funding_coin.object_id.clone(),
            renewal.consumed_funding_coin.clone(),
        );
        self.coins.insert(
            renewal.bond_coin.object_id.clone(),
            renewal.bond_coin.clone(),
        );
        if let Some(change) = &renewal.change_coin {
            self.coins.insert(change.object_id.clone(), change.clone());
        }
        self.stake_resource_accounting = Some(next_accounting);
        Ok(RenewStakeStateResourceBondOutcomeV1 {
            renewal_id: request.renewal_id,
            resource_key: request.resource_key,
            previous_renewal_hash: renewal.renewal_record.previous_renewal_hash,
            renewal_record_hash: renewal.renewal_record.record_hash,
            bond_coin_id: renewal.renewal_record.bond_coin_id,
            charged_fee: renewal.charged_fee,
            additional_bond: renewal.additional_bond,
            previous_lease_end_height: renewal.renewal_record.previous_lease_end_height,
            new_lease_end_height: renewal.renewal_record.new_lease_end_height,
        })
    }

    fn replay_stake_state_resource_bond_renewal(
        &self,
        request: &RenewStakeStateResourceBondRequestV1,
    ) -> Result<RenewStakeStateResourceBondOutcomeV1, LedgerError> {
        let accounting = self
            .stake_resource_accounting
            .as_ref()
            .ok_or_else(|| LedgerError::StakeResource("no resource accounting state".into()))?;
        let record = accounting
            .renewals()
            .get(&request.renewal_id)
            .filter(|record| {
                record.resource_key == request.resource_key
                    && record.resource_kind == request.resource_kind
                    && record.resource_owner == request.resource_owner
                    && record.original_bond_id == request.expected_bond_id
                    && record.initial_bond_record_hash == request.expected_initial_bond_record_hash
                    && record.previous_renewal_hash == request.expected_previous_renewal_hash
                    && record.previous_lease_end_height == request.expected_current_lease_end_height
                    && record.new_lease_end_height == request.new_lease_end_height
                    && record.resource_policy_sequence == request.resource_policy_sequence
                    && record.resource_policy_commitment == request.resource_policy_commitment
                    && record.sponsor == request.sponsor
                    && record.sponsor_authorization_id == request.authorization.authorization_id
                    && record.funding_source_coin_id == request.funding_coin_id
            })
            .ok_or_else(|| {
                LedgerError::InvalidQuorum(
                    "recorded commit has no exact resource-bond renewal".into(),
                )
            })?;
        Ok(RenewStakeStateResourceBondOutcomeV1 {
            renewal_id: record.renewal_id.clone(),
            resource_key: record.resource_key.clone(),
            previous_renewal_hash: record.previous_renewal_hash.clone(),
            renewal_record_hash: record.record_hash.clone(),
            bond_coin_id: record.bond_coin_id.clone(),
            charged_fee: record.charged_renewal_fee,
            additional_bond: record.additional_locked_amount,
            previous_lease_end_height: record.previous_lease_end_height,
            new_lease_end_height: record.new_lease_end_height,
        })
    }

    fn current_stake_resource_policy_identity(&self) -> (u64, String) {
        self.stake_resource_accounting.as_ref().map_or_else(
            || (0, crate::stake_resource_accounting::ZERO_SHA256.into()),
            |accounting| {
                (
                    accounting.active_policy().sequence,
                    accounting.active_policy_commitment().to_owned(),
                )
            },
        )
    }

    /// A resource policy may never start below already retained stake state.
    /// Candidate registration also calls this with one prospective owner so
    /// legacy and resource-accounted records share the same global limits.
    fn validate_stake_resource_policy_covers_inventory(
        &self,
        policy: &StakeStateResourcePolicyV1,
        additional_candidate_owner: Option<&str>,
        additional_position_owner: Option<&str>,
    ) -> Result<(), LedgerError> {
        fn check_owner_limit<'a>(
            owners: impl Iterator<Item = &'a str>,
            limit: u32,
            label: &str,
        ) -> Result<(), LedgerError> {
            let mut counts = BTreeMap::<&str, u64>::new();
            for owner in owners {
                let count = counts.entry(owner).or_default();
                *count = count.checked_add(1).ok_or_else(|| {
                    LedgerError::StakeResource(format!("{label} owner count overflow"))
                })?;
            }
            if counts.values().any(|count| *count > u64::from(limit)) {
                return Err(LedgerError::StakeResource(format!(
                    "resource policy {label} owner limit is below retained state"
                )));
            }
            Ok(())
        }

        let candidates = self
            .consensus_stake_authority
            .as_ref()
            .map_or(&[][..], |authority| authority.candidates.as_slice());
        let candidate_total = u64::try_from(candidates.len())
            .ok()
            .and_then(|count| count.checked_add(u64::from(additional_candidate_owner.is_some())))
            .ok_or_else(|| LedgerError::StakeResource("candidate count overflow".into()))?;
        if candidate_total > u64::from(policy.maximum_active_candidates) {
            return Err(LedgerError::StakeResource(
                "resource policy candidate limit is below retained state".into(),
            ));
        }
        check_owner_limit(
            candidates
                .iter()
                .map(|candidate| candidate.owner.as_str())
                .chain(additional_candidate_owner),
            policy.maximum_candidates_per_owner,
            "candidate",
        )?;

        let positions = self
            .consensus_stake_authority
            .as_ref()
            .map_or(&[][..], |authority| authority.positions.as_slice());
        let position_total = positions
            .len()
            .checked_add(usize::from(additional_position_owner.is_some()))
            .ok_or_else(|| LedgerError::StakeResource("position count overflow".into()))?;
        if position_total > policy.maximum_active_positions as usize {
            return Err(LedgerError::StakeResource(
                "resource policy position limit is below retained state".into(),
            ));
        }
        check_owner_limit(
            positions
                .iter()
                .map(|position| position.owner.as_str())
                .chain(additional_position_owner),
            policy.maximum_positions_per_owner,
            "position",
        )?;

        let pending_unbonds = self
            .consensus_stake_unbonds
            .values()
            .filter(|record| record.status == ConsensusStakeUnbondStatusV1::Pending)
            .collect::<Vec<_>>();
        if pending_unbonds.len() > policy.maximum_pending_unbonds as usize {
            return Err(LedgerError::StakeResource(
                "resource policy pending-unbond limit is below retained state".into(),
            ));
        }
        check_owner_limit(
            pending_unbonds.iter().map(|record| record.owner.as_str()),
            policy.maximum_pending_unbonds_per_owner,
            "pending-unbond",
        )
    }

    fn stake_resource_signer_sets_for_era(
        &self,
        protocol_era: u64,
        crypto_era: u64,
    ) -> Option<(&[String], &[String])> {
        if protocol_era == self.descriptor.protocol_era && crypto_era == self.descriptor.crypto_era
        {
            return Some((
                self.descriptor.validator_keys.as_slice(),
                self.descriptor.notary_keys.as_slice(),
            ));
        }
        self.era_certificates.iter().find_map(|certificate| {
            if protocol_era == certificate.previous_protocol_era
                && crypto_era == certificate.previous_crypto_era
            {
                Some((
                    certificate.previous_validator_keys.as_slice(),
                    certificate.previous_notary_keys.as_slice(),
                ))
            } else if protocol_era == certificate.new_protocol_era
                && crypto_era == certificate.new_crypto_era
            {
                Some((
                    certificate.new_validator_keys.as_slice(),
                    certificate.new_notary_keys.as_slice(),
                ))
            } else {
                None
            }
        })
    }

    fn verify_stake_resource_dual_quorum_for_era(
        &self,
        protocol_era: u64,
        crypto_era: u64,
        subject: &str,
        validator_qc: &QuorumCertificate,
        notary_qc: &QuorumCertificate,
    ) -> Result<(), LedgerError> {
        if validator_qc.subject_hash != subject || notary_qc.subject_hash != subject {
            return Err(LedgerError::StakeResource(
                "resource-policy quorum subject mismatch".into(),
            ));
        }
        let (validator_keys, notary_keys) = self
            .stake_resource_signer_sets_for_era(protocol_era, crypto_era)
            .ok_or_else(|| {
                LedgerError::StakeResource(
                    "resource-policy governance record refers to an unknown era".into(),
                )
            })?;
        let simulated = validator_qc.testnet_simulated && notary_qc.testnet_simulated;
        if simulated {
            if self.descriptor.testnet && validator_keys.is_empty() && notary_keys.is_empty() {
                return Ok(());
            }
            return Err(LedgerError::StakeResource(
                "simulated resource-policy quorum is forbidden for this signer set".into(),
            ));
        }
        if validator_qc.testnet_simulated || notary_qc.testnet_simulated {
            return Err(LedgerError::StakeResource(
                "resource-policy validator and notary quorum modes differ".into(),
            ));
        }
        validator_qc
            .verify(validator_keys)
            .map_err(LedgerError::StakeResource)?;
        notary_qc
            .verify(notary_keys)
            .map_err(LedgerError::StakeResource)
    }

    fn validate_stored_stake_resource_policy_proposal(
        &self,
        request: &ProposeStakeStateResourcePolicyV1,
    ) -> Result<(), LedgerError> {
        if request.proposal_id.trim().is_empty()
            || request.proposed_height >= request.expires_at_height
            || request.activate_after_height > request.expires_at_height
            || request.network_domain != self.descriptor.network_domain
            || request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
        {
            return Err(LedgerError::StakeResource(
                "stored resource-policy proposal identity, context or height is invalid".into(),
            ));
        }
        validate_stake_state_resource_policy_v1(&request.proposed_policy)
            .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
        let proposed_commitment =
            stake_state_resource_policy_commitment_v1(&request.proposed_policy)
                .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
        if request.proposed_policy_commitment != proposed_commitment
            || request.proposed_policy.sequence
                != request
                    .expected_current_policy_sequence
                    .checked_add(1)
                    .ok_or_else(|| {
                        LedgerError::StakeResource(
                            "stored resource-policy proposal sequence overflow".into(),
                        )
                    })?
            || request.proposed_policy.previous_policy_commitment
                != request.expected_current_policy_commitment
        {
            return Err(LedgerError::StakeResource(
                "stored resource-policy proposal predecessor or commitment mismatch".into(),
            ));
        }
        let subject = request.compute_subject_hash();
        if request.subject_hash != subject {
            return Err(LedgerError::StakeResource(
                "stored resource-policy proposal subject mismatch".into(),
            ));
        }
        self.verify_stake_resource_dual_quorum_for_era(
            request.protocol_era,
            request.crypto_era,
            &subject,
            &request.validator_qc,
            &request.notary_qc,
        )
    }

    fn validate_stake_resource_policy_proposal(
        &self,
        request: &ProposeStakeStateResourcePolicyV1,
    ) -> Result<(), LedgerError> {
        if request.proposal_id.trim().is_empty()
            || request.proposed_height >= request.expires_at_height
            || request.activate_after_height > request.expires_at_height
        {
            return Err(LedgerError::StakeResource(
                "resource-policy proposal identity or height window is invalid".into(),
            ));
        }
        if request.network_domain != self.descriptor.network_domain
            || request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::StakeResource(
                "resource-policy proposal network, Zone, currency or era mismatch".into(),
            ));
        }
        validate_stake_state_resource_policy_v1(&request.proposed_policy)
            .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
        self.validate_stake_resource_policy_covers_inventory(&request.proposed_policy, None, None)?;
        let (current_sequence, current_commitment) = self.current_stake_resource_policy_identity();
        let expected_next_sequence = current_sequence.checked_add(1).ok_or_else(|| {
            LedgerError::StakeResource("resource-policy sequence overflow".into())
        })?;
        let proposed_commitment =
            stake_state_resource_policy_commitment_v1(&request.proposed_policy)
                .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
        if request.expected_current_policy_sequence != current_sequence
            || request.expected_current_policy_commitment != current_commitment
            || request.proposed_policy.sequence != expected_next_sequence
            || request.proposed_policy.previous_policy_commitment != current_commitment
            || request.proposed_policy_commitment != proposed_commitment
        {
            return Err(LedgerError::StakeResource(
                "resource-policy proposal predecessor or commitment mismatch".into(),
            ));
        }
        let subject = request.compute_subject_hash();
        if request.subject_hash != subject {
            return Err(LedgerError::StakeResource(
                "resource-policy proposal subject mismatch".into(),
            ));
        }
        self.verify_local_dual_quorum(&subject, &request.validator_qc, &request.notary_qc)
    }

    /// Stores one bounded, delayed resource-policy proposal. This transition
    /// charges no user funds, installs no fee market and cannot change runtime
    /// validator membership.
    pub fn propose_stake_state_resource_policy(
        &mut self,
        request: ProposeStakeStateResourcePolicyV1,
    ) -> Result<ProposeStakeStateResourcePolicyV1, LedgerError> {
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "stake resource-policy proposal requires VALUE_CAP_0".into(),
            ));
        }
        self.validate_stake_resource_policy_proposal(&request)?;
        if request.proposed_height != self.height {
            return Err(LedgerError::StakeResource(
                "resource-policy proposal height does not match current state".into(),
            ));
        }
        if self
            .pending_stake_resource_policy
            .as_ref()
            .is_some_and(|pending| self.height <= pending.expires_at_height)
        {
            return Err(LedgerError::StakeResource(
                "an unexpired resource-policy proposal is already pending".into(),
            ));
        }
        if self
            .stake_resource_policy_proposals
            .contains_key(&request.proposal_id)
        {
            return Err(LedgerError::StakeResource(
                "resource-policy proposal id was already used".into(),
            ));
        }
        if self.stake_resource_policy_proposals.len() >= MAX_STAKE_RESOURCE_GOVERNANCE_RECORDS_V1 {
            return Err(LedgerError::StakeResource(
                "resource-policy proposal history reached its fail-closed bound".into(),
            ));
        }
        let controlling_delay = self.stake_resource_accounting.as_ref().map_or(
            request.proposed_policy.activation_delay_blocks,
            |accounting| accounting.active_policy().activation_delay_blocks,
        );
        let minimum_activation = self.height.checked_add(controlling_delay).ok_or_else(|| {
            LedgerError::StakeResource("resource-policy activation height overflow".into())
        })?;
        if request.activate_after_height < minimum_activation
            || request.expires_at_height < request.activate_after_height
        {
            return Err(LedgerError::StakeResource(
                "resource-policy proposal does not preserve the controlling activation delay"
                    .into(),
            ));
        }
        self.ensure_counter_headroom(1, 0)?;
        let mut staged = self.clone();
        staged.pending_stake_resource_policy = Some(request.clone());
        staged
            .stake_resource_policy_proposals
            .insert(request.proposal_id.clone(), request.clone());
        staged.advance()?;
        staged.validate_stake_resource_policy_state()?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(request)
    }

    /// Activates exactly the pending policy after its delay and a fresh dual
    /// quorum. Resource-bearing lifecycle commands remain unavailable, so
    /// activation alone cannot charge a Coin or create a bond.
    pub fn activate_stake_state_resource_policy(
        &mut self,
        request: ActivateStakeStateResourcePolicyV1,
    ) -> Result<StakeStateResourcePolicyV1, LedgerError> {
        if self.value_risk_policy.current_cap != ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "stake resource-policy activation requires VALUE_CAP_0".into(),
            ));
        }
        if request.activation_id.trim().is_empty()
            || request.network_domain != self.descriptor.network_domain
            || request.zone_id != self.descriptor.zone_id
            || request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
            || request.proposed_height != self.height
            || request.expires_at_height < self.height
        {
            return Err(LedgerError::StakeResource(
                "resource-policy activation identity, context or height is invalid".into(),
            ));
        }
        let pending = self
            .pending_stake_resource_policy
            .clone()
            .ok_or_else(|| LedgerError::StakeResource("no resource policy is pending".into()))?;
        if self
            .stake_resource_policy_activations
            .contains_key(&request.activation_id)
        {
            return Err(LedgerError::StakeResource(
                "resource-policy activation id was already used".into(),
            ));
        }
        if self.stake_resource_policy_activations.len() >= MAX_STAKE_RESOURCE_GOVERNANCE_RECORDS_V1
        {
            return Err(LedgerError::StakeResource(
                "resource-policy activation history reached its fail-closed bound".into(),
            ));
        }
        self.validate_stake_resource_policy_proposal(&pending)?;
        let (current_sequence, current_commitment) = self.current_stake_resource_policy_identity();
        if request.proposal_id != pending.proposal_id
            || request.expected_pending_policy_commitment != pending.proposed_policy_commitment
            || request.expected_current_policy_sequence != current_sequence
            || request.expected_current_policy_commitment != current_commitment
            || request.expires_at_height != pending.expires_at_height
            || self.height < pending.activate_after_height
            || self.height > pending.expires_at_height
        {
            return Err(LedgerError::StakeResource(
                "resource-policy activation does not match the delayed pending proposal".into(),
            ));
        }
        let subject = request.compute_subject_hash();
        if request.subject_hash != subject {
            return Err(LedgerError::StakeResource(
                "resource-policy activation subject mismatch".into(),
            ));
        }
        self.verify_local_dual_quorum(&subject, &request.validator_qc, &request.notary_qc)?;
        self.ensure_counter_headroom(1, 0)?;
        let mut staged = self.clone();
        staged.advance()?;
        let activation_height = staged.height;
        if let Some(accounting) = staged.stake_resource_accounting.as_mut() {
            accounting
                .activate_policy(pending.proposed_policy.clone(), activation_height)
                .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
        } else {
            staged.stake_resource_accounting = Some(
                StakeStateResourceAccountingV1::new(
                    staged.stake_resource_context(),
                    pending.proposed_policy.clone(),
                    staged.height,
                )
                .map_err(|error| LedgerError::StakeResource(error.to_string()))?,
            );
        }
        staged
            .stake_resource_policy_activations
            .insert(request.activation_id.clone(), request);
        staged.pending_stake_resource_policy = None;
        staged.validate_stake_resource_policy_state()?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(pending.proposed_policy)
    }

    fn validate_stake_resource_policy_state(&self) -> Result<(), LedgerError> {
        if self.stake_resource_policy_proposals.len() > MAX_STAKE_RESOURCE_GOVERNANCE_RECORDS_V1
            || self.stake_resource_policy_activations.len()
                > MAX_STAKE_RESOURCE_GOVERNANCE_RECORDS_V1
        {
            return Err(LedgerError::StakeResource(
                "resource-policy governance history exceeds its fail-closed bound".into(),
            ));
        }
        for (proposal_id, proposal) in &self.stake_resource_policy_proposals {
            if proposal_id != &proposal.proposal_id {
                return Err(LedgerError::StakeResource(
                    "resource-policy proposal history key mismatch".into(),
                ));
            }
            self.validate_stored_stake_resource_policy_proposal(proposal)?;
        }

        let mut activation_order = self
            .stake_resource_policy_activations
            .iter()
            .collect::<Vec<_>>();
        activation_order.sort_by(|(left_id, left), (right_id, right)| {
            (left.proposed_height, left_id).cmp(&(right.proposed_height, right_id))
        });
        let mut activated_proposals = BTreeSet::new();
        let mut active_by_era = BTreeMap::<(u64, u64), (u64, String)>::new();
        for (activation_id, activation) in activation_order {
            if activation_id != &activation.activation_id
                || activation.activation_id.trim().is_empty()
                || activation.network_domain != self.descriptor.network_domain
                || activation.zone_id != self.descriptor.zone_id
                || activation.currency_genesis_root != self.descriptor.currency_genesis_root
                || activation.proposed_height > activation.expires_at_height
            {
                return Err(LedgerError::StakeResource(
                    "resource-policy activation history identity or context mismatch".into(),
                ));
            }
            let proposal = self
                .stake_resource_policy_proposals
                .get(&activation.proposal_id)
                .ok_or_else(|| {
                    LedgerError::StakeResource(
                        "resource-policy activation has no immutable proposal".into(),
                    )
                })?;
            if !activated_proposals.insert(activation.proposal_id.as_str())
                || activation.network_domain != proposal.network_domain
                || activation.zone_id != proposal.zone_id
                || activation.currency_genesis_root != proposal.currency_genesis_root
                || activation.protocol_era != proposal.protocol_era
                || activation.crypto_era != proposal.crypto_era
                || activation.expires_at_height != proposal.expires_at_height
                || activation.proposed_height < proposal.activate_after_height
                || activation.proposed_height > proposal.expires_at_height
                || activation.expected_pending_policy_commitment
                    != proposal.proposed_policy_commitment
                || activation.expected_current_policy_sequence
                    != proposal.expected_current_policy_sequence
                || activation.expected_current_policy_commitment
                    != proposal.expected_current_policy_commitment
            {
                return Err(LedgerError::StakeResource(
                    "resource-policy activation does not match its immutable proposal".into(),
                ));
            }
            let subject = activation.compute_subject_hash();
            if activation.subject_hash != subject {
                return Err(LedgerError::StakeResource(
                    "resource-policy activation history subject mismatch".into(),
                ));
            }
            self.verify_stake_resource_dual_quorum_for_era(
                activation.protocol_era,
                activation.crypto_era,
                &subject,
                &activation.validator_qc,
                &activation.notary_qc,
            )?;
            let era_key = (activation.protocol_era, activation.crypto_era);
            let expected = active_by_era
                .get(&era_key)
                .cloned()
                .unwrap_or_else(|| (0, crate::stake_resource_accounting::ZERO_SHA256.to_owned()));
            if activation.expected_current_policy_sequence != expected.0
                || activation.expected_current_policy_commitment != expected.1
            {
                return Err(LedgerError::StakeResource(
                    "resource-policy activation history is not a contiguous era-local chain".into(),
                ));
            }
            active_by_era.insert(
                era_key,
                (
                    proposal.proposed_policy.sequence,
                    proposal.proposed_policy_commitment.clone(),
                ),
            );
        }

        let (current_sequence, current_commitment) = self.current_stake_resource_policy_identity();
        if let Some(pending) = &self.pending_stake_resource_policy {
            self.validate_stake_resource_policy_proposal(pending)?;
            if self
                .stake_resource_policy_proposals
                .get(&pending.proposal_id)
                != Some(pending)
                || pending.expected_current_policy_sequence != current_sequence
                || pending.expected_current_policy_commitment != current_commitment
            {
                return Err(LedgerError::StakeResource(
                    "pending resource policy is not immutable or no longer binds the active policy"
                        .into(),
                ));
            }
        }
        let current_era = (self.descriptor.protocol_era, self.descriptor.crypto_era);
        let activated_current = active_by_era.get(&current_era);
        let Some(accounting) = &self.stake_resource_accounting else {
            if activated_current.is_some() {
                return Err(LedgerError::StakeResource(
                    "current-era resource-policy history exists without accounting state".into(),
                ));
            }
            return Ok(());
        };
        accounting
            .validate()
            .map_err(|error| LedgerError::StakeResource(error.to_string()))?;
        if accounting.context() != &self.stake_resource_context() {
            return Err(LedgerError::StakeResource(
                "resource accounting context is not the current ledger context".into(),
            ));
        }
        if activated_current.is_none_or(|(sequence, commitment)| {
            accounting.active_policy().sequence != *sequence
                || accounting.active_policy_commitment() != commitment
                || accounting.policy_generations() != *sequence as usize
                || (1..=*sequence)
                    .any(|generation| accounting.policy_commitment(generation).is_none())
        }) {
            return Err(LedgerError::StakeResource(
                "resource accounting policy registry does not match activation history".into(),
            ));
        }
        if !accounting
            .consumed_authorization_ids()
            .is_subset(&self.authorization_nullifiers)
        {
            return Err(LedgerError::StakeResource(
                "resource authorization nullifiers are missing from the ledger".into(),
            ));
        }
        for record in accounting.bonds().values() {
            let source = self
                .coins
                .get(&record.funding_source_coin_id)
                .ok_or_else(|| {
                    LedgerError::StakeResource("resource funding Coin is missing".into())
                })?;
            let bond = self.coins.get(&record.bond_coin_id).ok_or_else(|| {
                LedgerError::StakeResource("resource bond Coin is missing".into())
            })?;
            let required = record
                .charged_creation_fee
                .checked_add(record.locked_amount)
                .map_err(LedgerError::Amount)?;
            let change = source
                .amount
                .checked_sub(required)
                .map_err(LedgerError::Amount)?;
            let expected_change_id = if change.is_zero() {
                None
            } else {
                Some(format!(
                    "stake-state-change:{}",
                    hash_parts(&[
                        b"RLD-STAKE-STATE-RESOURCE-CHANGE-COIN-V1",
                        source.object_id.as_bytes(),
                        record.bond_id.as_bytes(),
                        &change.0.to_be_bytes(),
                    ])
                ))
            };
            let direct_change = self
                .coins
                .values()
                .filter(|coin| {
                    coin.parent_ids == [source.object_id.clone()]
                        && coin.object_id != record.bond_coin_id
                })
                .collect::<Vec<_>>();
            if source.state != CoinState::Consumed
                || source.owner != record.sponsor
                || source.amount < required
                || bond.owner != record.sponsor
                || bond.amount != record.locked_amount
                || bond.parent_ids != [source.object_id.clone()]
                || bond.lineage_root != source.lineage_root
                || source.version.checked_add(1) != Some(bond.version)
                || bond.created_height != record.created_height
                || bond.zone_id != self.descriptor.zone_id
                || bond.origin_genesis_root != self.descriptor.currency_genesis_root
                || bond.transit_id.is_some()
                || direct_change.len() != usize::from(expected_change_id.is_some())
                || direct_change.first().is_some_and(|coin| {
                    Some(coin.object_id.as_str()) != expected_change_id.as_deref()
                        || coin.owner != record.sponsor
                        || coin.amount != change
                        || coin.lineage_root != source.lineage_root
                        || source.version.checked_add(1) != Some(coin.version)
                        || coin.created_height != record.created_height
                        || coin.zone_id != self.descriptor.zone_id
                        || coin.origin_genesis_root != self.descriptor.currency_genesis_root
                        || coin.transit_id.is_some()
                })
            {
                return Err(LedgerError::StakeResource(
                    "resource bond or change is not an exact descendant of its funding Coin".into(),
                ));
            }
            let refund_children = self
                .coins
                .values()
                .filter(|coin| coin.parent_ids == [bond.object_id.clone()])
                .collect::<Vec<_>>();
            match record.status {
                StakeStateBondStatusV1::Locked | StakeStateBondStatusV1::Releaseable => {
                    if bond.state != CoinState::Reserved || !refund_children.is_empty() {
                        return Err(LedgerError::StakeResource(
                            "live resource bond Coin or descendants are inconsistent".into(),
                        ));
                    }
                }
                StakeStateBondStatusV1::Refunded => {
                    if bond.state != CoinState::Consumed
                        || refund_children.len() != 1
                        || refund_children[0].owner != record.sponsor
                        || refund_children[0].amount != record.locked_amount
                        || refund_children[0].lineage_root != bond.lineage_root
                        || bond.version.checked_add(1) != Some(refund_children[0].version)
                    {
                        return Err(LedgerError::StakeResource(
                            "refunded resource bond lineage is inconsistent".into(),
                        ));
                    }
                }
                StakeStateBondStatusV1::Forfeited => {
                    if bond.state != CoinState::Consumed || !refund_children.is_empty() {
                        return Err(LedgerError::StakeResource(
                            "forfeited resource bond has an invalid refund descendant".into(),
                        ));
                    }
                }
            }
        }
        Ok(())
    }

    pub fn ensure_current_checkpoint(&mut self) -> Result<bool, LedgerError> {
        let current_root = self.state_root()?;
        if self
            .latest_checkpoint()
            .is_some_and(|checkpoint| checkpoint.state_root == current_root)
        {
            return Ok(false);
        }
        self.ensure_counter_headroom(1, 0)?;
        self.advance()?;
        self.create_checkpoint()?;
        Ok(true)
    }

    pub fn ensure_reserve_pools(&mut self) -> Result<(), LedgerError> {
        let recorded_total = self.reserve_pools.total().map_err(LedgerError::Supply)?;
        if recorded_total == self.reserve {
            return Ok(());
        }
        if !recorded_total.is_zero() {
            return Err(LedgerError::Supply(
                "persisted protocol reserve pools do not equal the reserve".into(),
            ));
        }

        let mut migrated = protocol_reserve_pools(self.anchor_supply)?;
        let bootstrap_spent = self
            .service_receipts
            .values()
            .filter(|receipt| receipt.bootstrap)
            .try_fold(Amount::ZERO, |total, receipt| {
                total.checked_add(receipt.amount)
            })?;
        migrated.startup_services = migrated
            .startup_services
            .checked_sub(bootstrap_spent)
            .map_err(|_| {
                LedgerError::Supply(
                    "historical bootstrap rewards exceed the startup service pool".into(),
                )
            })?;
        if migrated.total().map_err(LedgerError::Supply)? != self.reserve {
            return Err(LedgerError::Supply(
                "migrated protocol reserve pools do not equal the persisted reserve".into(),
            ));
        }

        self.ensure_counter_headroom(1, 0)?;

        for receipt in self
            .service_receipts
            .values()
            .filter(|receipt| receipt.bootstrap)
        {
            self.service_orders
                .entry(receipt.order_id.clone())
                .or_insert_with(|| ServiceOrder {
                    order_id: receipt.order_id.clone(),
                    buyer: "rld:protocol:startup-services".into(),
                    role: receipt.role.clone(),
                    budget: receipt.amount,
                    escrow_coin_id: format!(
                        "protocol-reserve:startup-services:{}",
                        receipt.order_id
                    ),
                    description: "migrated testnet bootstrap verified network service".into(),
                    status: ServiceStatus::Completed,
                    created_height: receipt.completed_height,
                });
            self.service_leases
                .entry(receipt.lease_id.clone())
                .or_insert_with(|| ServiceLease {
                    lease_id: receipt.lease_id.clone(),
                    order_id: receipt.order_id.clone(),
                    node_id: receipt.node_id.clone(),
                    accepted_quote: receipt.amount,
                    accepted_height: receipt.completed_height,
                });
        }

        self.reserve_pools = migrated;
        self.advance()?;
        self.create_checkpoint()?;
        Ok(())
    }

    pub fn new(
        display_name: impl Into<String>,
        anchor_supply: Amount,
        validator_keys: Vec<String>,
        notary_keys: Vec<String>,
        testnet: bool,
    ) -> Result<Self, LedgerError> {
        let display_name = display_name.into();
        let identity_version = CURRENT_ZONE_IDENTITY_VERSION;
        let identity_hash_suite = ZONE_IDENTITY_HASH_SUITE.to_owned();
        let network_domain = if testnet {
            RLDCOIN_TESTNET_DOMAIN
        } else {
            RLDCOIN_MAINNET_DOMAIN
        }
        .to_owned();
        let currency_genesis_root = currency_genesis_root();
        let genesis_root = ZoneDescriptor::genesis_root_for_v2(
            &display_name,
            anchor_supply,
            &validator_keys,
            &notary_keys,
            &currency_genesis_root,
            &identity_hash_suite,
            &network_domain,
        );
        let zone_id =
            ZoneDescriptor::self_certifying_id(identity_version, &display_name, &genesis_root);
        let descriptor = ZoneDescriptor {
            zone_id,
            display_name,
            genesis_root,
            identity_version,
            identity_hash_suite,
            network_domain,
            anchor_supply,
            genesis_validator_keys: validator_keys.clone(),
            genesis_notary_keys: notary_keys.clone(),
            currency_genesis_root,
            validator_keys,
            notary_keys,
            protocol_era: 1,
            crypto_era: 1,
            testnet,
        };
        let era_continuity_accumulator = hash_parts(&[
            b"RLD-GENESIS-ERA",
            descriptor.zone_id.as_bytes(),
            &descriptor.protocol_era.to_be_bytes(),
            &descriptor.crypto_era.to_be_bytes(),
        ]);
        let reserve_pools = protocol_reserve_pools(anchor_supply)?;
        let mut ledger = Self {
            descriptor,
            height: 0,
            anchor_supply,
            reserve: anchor_supply,
            reserve_pools,
            imported_total: Amount::ZERO,
            finalized_export_total: Amount::ZERO,
            value_risk_policy: ValueRiskPolicy::default(),
            m0_network_birth: None,
            m0_network_birth_v3: None,
            m0_active_protocol: None,
            m0_pending_upgrade: None,
            admission_state: None,
            consensus_stake_authority: None,
            consensus_stake_escrows: BTreeMap::new(),
            consensus_stake_unbonds: BTreeMap::new(),
            consensus_stake_slashes: BTreeMap::new(),
            consensus_stake_evidence_nullifiers: BTreeSet::new(),
            derived_stake_epochs: BTreeMap::new(),
            stake_position_liability_horizons: BTreeMap::new(),
            stake_position_liability_horizon_history: BTreeMap::new(),
            stake_liability_horizon_activation_epoch: None,
            stake_resource_policy_proposals: BTreeMap::new(),
            stake_resource_policy_activations: BTreeMap::new(),
            pending_stake_resource_policy: None,
            stake_resource_accounting: None,
            coins: BTreeMap::new(),
            payments: BTreeMap::new(),
            epoch_fee_pools: BTreeMap::new(),
            payment_requests: BTreeMap::new(),
            consumed_payment_requests: BTreeSet::new(),
            recipient_receipts: BTreeMap::new(),
            transits: BTreeMap::new(),
            transit_coin_ids: BTreeMap::new(),
            import_receipts: BTreeMap::new(),
            rejection_proofs: BTreeMap::new(),
            rejected_transit_nullifiers: BTreeSet::new(),
            spendability_certificates: BTreeMap::new(),
            liquidity_offers: BTreeMap::new(),
            route_quotes: BTreeMap::new(),
            transit_nullifiers: BTreeSet::new(),
            source_object_nullifiers: BTreeSet::new(),
            authorization_nullifiers: BTreeSet::new(),
            zone_trust_policies: BTreeMap::new(),
            trusted_zone_checkpoints: BTreeMap::new(),
            gateway_bonds: BTreeMap::new(),
            quarantined_zones: BTreeSet::new(),
            zone_advertisements: BTreeMap::new(),
            traveler_capsules: BTreeMap::new(),
            voyage_escrows: BTreeMap::new(),
            voyage_receipts: BTreeMap::new(),
            era_certificates: Vec::new(),
            era_continuity_accumulator,
            service_orders: BTreeMap::new(),
            service_leases: BTreeMap::new(),
            protocol_reserve_commitments: BTreeMap::new(),
            economic_control_attestations: BTreeMap::new(),
            economic_price_attestations: BTreeMap::new(),
            economic_release_policies: BTreeMap::new(),
            protocol_service_bonds: BTreeMap::new(),
            protocol_reserve_releases: BTreeMap::new(),
            economic_consumed_work_ids: BTreeSet::new(),
            economic_consumed_fee_receipts: BTreeSet::new(),
            economic_consumed_completion_qcs: BTreeSet::new(),
            economic_bond_slash_ids: BTreeSet::new(),
            matched_service_receipts: BTreeSet::new(),
            service_receipts: BTreeMap::new(),
            node_earnings: BTreeMap::new(),
            checkpoints: Vec::new(),
            causal_firewall: CausalFirewall::default(),
            bootstrap_claims: BTreeSet::new(),
            consensus_vote_locks: BTreeMap::new(),
            consensus_commits: BTreeMap::new(),
            sequence: 0,
        };
        ledger.create_checkpoint()?;
        Ok(ledger)
    }

    pub fn genesis_zone(
        display_name: impl Into<String>,
        validator_keys: Vec<String>,
        notary_keys: Vec<String>,
        testnet: bool,
    ) -> Result<Self, LedgerError> {
        Self::new(
            display_name,
            Amount::TOTAL_SUPPLY,
            validator_keys,
            notary_keys,
            testnet,
        )
    }

    pub fn bind_m0_network_birth(
        &mut self,
        binding: M0NetworkBirthStateV2,
    ) -> Result<(), LedgerError> {
        if self.m0_network_birth_v3.is_some() || self.m0_active_protocol.is_some() {
            return Err(LedgerError::Invalid(
                "V3 birth cannot be rebound as V2".into(),
            ));
        }
        binding
            .validate_for_descriptor(&self.descriptor)
            .map_err(LedgerError::Invalid)?;
        if let Some(existing) = &self.m0_network_birth {
            if existing == &binding {
                let admission = self.admission_state.as_ref().ok_or_else(|| {
                    LedgerError::Invalid(
                        "M0 network birth exists without its admission trust state".into(),
                    )
                })?;
                admission
                    .validate_for_descriptor(&self.descriptor)
                    .map_err(|error| LedgerError::Invalid(error.to_string()))?;
                if admission.genesis != binding.admission_genesis {
                    return Err(LedgerError::Invalid(
                        "M0 network birth and admission genesis differ".into(),
                    ));
                }
                return Ok(());
            }
            return Err(LedgerError::Invalid(
                "M0 network-birth binding is immutable".into(),
            ));
        }
        let pristine = Self::genesis_zone(
            &self.descriptor.display_name,
            self.descriptor.genesis_validator_keys.clone(),
            self.descriptor.genesis_notary_keys.clone(),
            false,
        )?;
        if self.descriptor != pristine.descriptor || self.state_root()? != pristine.state_root()? {
            return Err(LedgerError::Invalid(
                "M0 network-birth binding can only be installed on exact pristine genesis state"
                    .into(),
            ));
        }
        let mut candidate = self.clone();
        candidate.m0_network_birth = Some(binding.clone());
        candidate.admission_state = None;
        let initial_asset_root =
            AdmissionHash32::from_hex(&candidate.state_root_before_admission()?)
                .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        candidate.admission_state = Some(
            LedgerAdmissionStateV1::new(binding.admission_genesis, initial_asset_root)
                .map_err(|error| LedgerError::Invalid(error.to_string()))?,
        );
        candidate.checkpoints.clear();
        candidate.create_checkpoint()?;
        *self = candidate;
        Ok(())
    }

    pub fn m0_profile_active(&self) -> bool {
        self.m0_network_birth.is_some()
            || self.m0_network_birth_v3.is_some()
            || self.m0_active_protocol.is_some()
    }

    pub fn m0_admission_genesis(&self) -> Result<Option<&crate::AdmissionGenesisV1>, LedgerError> {
        if let Some(pending) = &self.m0_pending_upgrade {
            let birth = self
                .m0_network_birth_v3
                .as_ref()
                .ok_or_else(|| LedgerError::Invalid("pending upgrade requires V3 birth".into()))?;
            let active = self.m0_active_protocol.as_ref().ok_or_else(|| {
                LedgerError::Invalid("pending upgrade requires active state".into())
            })?;
            pending
                .validate(&self.descriptor, birth, active, u128::from(self.height))
                .map_err(LedgerError::Invalid)?;
        }
        match (
            &self.m0_network_birth,
            &self.m0_network_birth_v3,
            &self.m0_active_protocol,
        ) {
            (None, None, None) => Ok(None),
            (Some(birth), None, None) => {
                birth
                    .validate_for_descriptor(&self.descriptor)
                    .map_err(LedgerError::Invalid)?;
                Ok(Some(&birth.admission_genesis))
            }
            (None, Some(birth), Some(active)) => {
                birth
                    .validate_for_descriptor(&self.descriptor)
                    .map_err(LedgerError::Invalid)?;
                active
                    .validate_for_birth(birth)
                    .map_err(LedgerError::Invalid)?;
                Ok(Some(&birth.admission_genesis))
            }
            _ => Err(LedgerError::Invalid(
                "mixed, missing or downgraded M0 birth/active state".into(),
            )),
        }
    }

    pub fn bind_m0_network_birth_v3(
        &mut self,
        birth: crate::M0NetworkBirthStateV3,
    ) -> Result<(), LedgerError> {
        birth
            .validate_for_descriptor(&self.descriptor)
            .map_err(LedgerError::Invalid)?;
        if self.m0_network_birth_v3.as_ref() == Some(&birth) {
            self.validated_admission_state()?;
            return Ok(());
        }
        if self.m0_profile_active() {
            return Err(LedgerError::Invalid(
                "M0 birth cannot be replaced or upgraded in place".into(),
            ));
        }
        let pristine = Self::genesis_zone(
            &self.descriptor.display_name,
            self.descriptor.genesis_validator_keys.clone(),
            self.descriptor.genesis_notary_keys.clone(),
            false,
        )?;
        if serde_json::to_vec(self).map_err(|e| LedgerError::Invalid(e.to_string()))?
            != serde_json::to_vec(&pristine).map_err(|e| LedgerError::Invalid(e.to_string()))?
        {
            return Err(LedgerError::Invalid(
                "V3 birth requires exact pristine genesis including unrooted bookkeeping".into(),
            ));
        }
        let mut candidate = self.clone();
        candidate.m0_active_protocol =
            Some(crate::M0ActiveProtocolStateV1::at_birth(&birth).map_err(LedgerError::Invalid)?);
        candidate.m0_network_birth_v3 = Some(birth.clone());
        let initial_asset_root =
            AdmissionHash32::from_hex(&candidate.state_root_before_admission()?)
                .map_err(|e| LedgerError::Invalid(e.to_string()))?;
        candidate.admission_state = Some(
            LedgerAdmissionStateV1::new(birth.admission_genesis, initial_asset_root)
                .map_err(|e| LedgerError::Invalid(e.to_string()))?,
        );
        candidate.checkpoints.clear();
        candidate.create_checkpoint()?;
        *self = candidate;
        Ok(())
    }

    /// Applies one already-verified admission-control fact to the bounded
    /// Ledger extension. This is deliberately not a command route: the future
    /// tag-28 transition must call it only after proof verification, and the
    /// containing authenticated main-WAL commit supplies the finality anchor.
    /// Keeping that anchor outside the fact avoids a commit-hash/state-root
    /// self-reference.
    #[cfg_attr(not(test), allow(dead_code))]
    pub(crate) fn apply_admission_ledger_control_fact(
        &mut self,
        fact: &crate::AdmissionLedgerControlFactV1,
    ) -> Result<(), LedgerError> {
        let admission_genesis = self.m0_admission_genesis()?.ok_or_else(|| {
            LedgerError::Invalid(
                "admission Ledger-control facts require the signed M0 trust root".into(),
            )
        })?;
        let prestate_root = AdmissionHash32::from_hex(&self.state_root()?)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if let crate::AdmissionLedgerControlFactV1::RolloverAuthorization(authorization) = fact {
            if authorization.finalized_ledger_state_root != prestate_root {
                return Err(LedgerError::Invalid(
                    "rollover authorization must bind the exact finalized Ledger prestate root"
                        .into(),
                ));
            }
        }
        let admission = self.admission_state.as_ref().ok_or_else(|| {
            LedgerError::Invalid("signed M0 trust root has no admission Ledger state".into())
        })?;
        if &admission.genesis != admission_genesis {
            return Err(LedgerError::Invalid(
                "admission Ledger state differs from the signed M0 trust root".into(),
            ));
        }
        let mut candidate = admission.control.clone();
        candidate
            .apply_exact_fact(fact, &admission.genesis.config)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        candidate
            .validate_recovered(&admission.genesis.config)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        self.admission_state
            .as_mut()
            .expect("admission state was checked above")
            .control = candidate;
        Ok(())
    }

    /// Executes one already-verified tag-28 checkpoint result against the exact
    /// authenticated proposal prestate and successor commitment. The live
    /// Ledger changes only after admission mutation, height advancement and the
    /// signed expected state root all agree.
    ///
    /// Pure `ConsensusCommand` dispatch remains deliberately fail-closed: the
    /// node route must supply exact retained history and authenticated main-WAL
    /// anchors before this external-evidence transition can execute.
    #[cfg_attr(not(test), allow(dead_code))]
    pub fn execute_authenticated_admission_checkpoint_transition(
        &mut self,
        proposal_context: &AuthenticatedAdmissionCheckpointProposalV1,
        transition: &VerifiedAdmissionCheckpointTransitionV1,
    ) -> Result<(), LedgerError> {
        let parent_state_root = self.state_root()?;
        if proposal_context.parent_height() != self.height
            || proposal_context.parent_state_root() != parent_state_root
            || proposal_context.committing_ledger_height()
                != u128::from(self.height.checked_add(1).ok_or_else(|| {
                    LedgerError::Invalid("tag-28 proposal successor height overflows U64".into())
                })?)
            || proposal_context.proof_id() != transition.proof_id
            || proposal_context.committing_ledger_height() != transition.committing_ledger_height
        {
            return Err(LedgerError::Invalid(
                "verified admission transition does not match the authenticated tag-28 proposal context"
                    .into(),
            ));
        }

        let mut staged = self.clone();
        staged.apply_verified_admission_checkpoint_transition_inner(transition)?;
        staged.advance()?;
        if u128::from(staged.height) != proposal_context.committing_ledger_height()
            || staged.state_root()? != proposal_context.expected_state_root()
        {
            return Err(LedgerError::Invalid(
                "tag-28 execution result does not match the authenticated proposal successor"
                    .into(),
            ));
        }
        *self = staged;
        Ok(())
    }

    /// Computes the exact tag-28 successor commitment after a proof has been
    /// verified against local Admission history. This does not mutate the
    /// Ledger or authenticate a proposal; it lets a proposer commit the same
    /// height/root that replay will later enforce.
    pub fn admission_checkpoint_successor_commitment(
        &self,
        transition: &VerifiedAdmissionCheckpointTransitionV1,
    ) -> Result<(u64, String), LedgerError> {
        let mut expected = self.clone();
        expected.apply_verified_admission_checkpoint_transition_inner(transition)?;
        expected.advance()?;
        Ok((expected.height, expected.state_root()?))
    }

    /// Computes a tag-28 successor only when the Ledger-minted pre-signing plan
    /// still names this exact current prestate and the locally verified proof.
    /// A plan cannot survive an intervening Ledger commit or be reused for a
    /// substituted checkpoint proof.
    pub fn admission_checkpoint_successor_commitment_from_plan(
        &self,
        plan: &AdmissionCheckpointProposalPlanV1,
        transition: &VerifiedAdmissionCheckpointTransitionV1,
    ) -> Result<(u64, String), LedgerError> {
        let current_root = self.state_root()?;
        let expected_height = self.height.checked_add(1).ok_or_else(|| {
            LedgerError::Invalid("tag-28 proposal-plan successor height overflows U64".into())
        })?;
        if plan.parent_height() != self.height
            || plan.parent_state_root() != current_root
            || plan.expected_height() != expected_height
            || plan.proof_id() != transition.proof_id
            || plan.committing_ledger_height() != transition.committing_ledger_height
        {
            return Err(LedgerError::Invalid(
                "tag-28 proposal plan is stale or differs from the locally verified transition"
                    .into(),
            ));
        }
        let successor = self.admission_checkpoint_successor_commitment(transition)?;
        if successor.0 != plan.expected_height() {
            return Err(LedgerError::Invalid(
                "tag-28 successor differs from the Ledger-minted proposal plan".into(),
            ));
        }
        Ok(successor)
    }

    fn apply_verified_admission_checkpoint_transition_inner(
        &mut self,
        transition: &VerifiedAdmissionCheckpointTransitionV1,
    ) -> Result<(), LedgerError> {
        let admission_genesis = self.m0_admission_genesis()?.ok_or_else(|| {
            LedgerError::Invalid(
                "verified admission checkpoint requires the signed M0 trust root".into(),
            )
        })?;
        let current_asset_root = AdmissionHash32::from_hex(&self.state_root_before_admission()?)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        let admission = self.admission_state.as_ref().ok_or_else(|| {
            LedgerError::Invalid("signed M0 trust root has no admission Ledger state".into())
        })?;
        if &admission.genesis != admission_genesis {
            return Err(LedgerError::Invalid(
                "admission Ledger state differs from the signed M0 trust root".into(),
            ));
        }
        let mut candidate = admission.clone();
        candidate
            .apply_verified_checkpoint_transition(transition, current_asset_root)
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        self.admission_state = Some(candidate);
        Ok(())
    }

    #[cfg(test)]
    pub(crate) fn test_authenticated_admission_checkpoint_proposal(
        &self,
        transition: &VerifiedAdmissionCheckpointTransitionV1,
    ) -> Result<AuthenticatedAdmissionCheckpointProposalV1, LedgerError> {
        let (expected_height, expected_state_root) =
            self.admission_checkpoint_successor_commitment(transition)?;
        AuthenticatedAdmissionCheckpointProposalV1::from_authenticated_proposal(
            hash_bytes(b"RLD-TEST-AUTHENTICATED-ADMISSION-PROPOSAL"),
            hash_bytes(b"RLD-TEST-AUTHENTICATED-ADMISSION-COMMAND"),
            transition.proof_id,
            self.height,
            self.state_root()?,
            expected_height,
            expected_state_root,
        )
        .map_err(|error| LedgerError::Invalid(error.to_string()))
    }

    fn ensure_m0_consensus_command_allowed(
        &self,
        command: &ConsensusCommand,
    ) -> Result<(), LedgerError> {
        self.ensure_consensus_upgrade_boundary(command)?;
        self.ensure_m0_consensus_command_profile_allowed(command)
    }

    fn ensure_consensus_upgrade_boundary(
        &self,
        command: &ConsensusCommand,
    ) -> Result<(), LedgerError> {
        if let ConsensusCommand::ActivateUpgrade(activation) = command {
            self.validate_supported_upgrade_activation(activation)
                .map_err(LedgerError::Invalid)
        } else {
            self.ensure_upgrade_height_boundary(1)
        }
    }

    fn ensure_m0_consensus_command_profile_allowed(
        &self,
        command: &ConsensusCommand,
    ) -> Result<(), LedgerError> {
        self.validated_admission_state()?;
        if self.m0_profile_active()
            && !matches!(
                command,
                ConsensusCommand::NetworkHeartbeat(_)
                    | ConsensusCommand::CommitAdmissionCheckpoint(_)
                    | ConsensusCommand::ScheduleUpgrade(_)
                    | ConsensusCommand::ActivateUpgrade(_)
            )
        {
            return Err(LedgerError::ValueRisk(
                "consensus-rooted M0 profile permits only value-free NETWORK_HEARTBEAT; all value, governance, membership and production commands fail closed".into(),
            ));
        }
        Ok(())
    }

    fn validated_admission_state(&self) -> Result<Option<&LedgerAdmissionStateV1>, LedgerError> {
        match (self.m0_admission_genesis()?, &self.admission_state) {
            (None, None) => Ok(None),
            (Some(admission_genesis), Some(admission)) => {
                admission
                    .validate_for_descriptor(&self.descriptor)
                    .map_err(|error| {
                        LedgerError::ValueRisk(format!(
                            "consensus-rooted M0 admission trust state is invalid; all commands fail closed: {error}"
                        ))
                    })?;
                if &admission.genesis != admission_genesis {
                    return Err(LedgerError::ValueRisk(
                        "consensus-rooted M0 binding and admission genesis differ; all commands fail closed"
                            .into(),
                    ));
                }
                Ok(Some(admission))
            }
            (Some(_), None) => Err(LedgerError::ValueRisk(
                "consensus-rooted M0 binding has no admission trust state; all commands fail closed"
                    .into(),
            )),
            (None, Some(_)) => Err(LedgerError::ValueRisk(
                "admission trust state exists without its M0 network-birth binding; all commands fail closed"
                    .into(),
            )),
        }
    }

    pub fn admission_may_sign_consensus(&self) -> Result<bool, LedgerError> {
        Ok(self
            .validated_admission_state()?
            .is_none_or(|admission| admission.censorship_guard.may_sign_consensus()))
    }

    pub fn admission_may_accept_value_eligible_finality(&self) -> Result<bool, LedgerError> {
        Ok(self.validated_admission_state()?.is_none_or(|admission| {
            admission
                .censorship_guard
                .may_accept_value_eligible_finality()
        }))
    }

    pub fn admission_may_raise_value_cap(&self) -> Result<bool, LedgerError> {
        Ok(self
            .validated_admission_state()?
            .is_none_or(|admission| admission.censorship_guard.may_raise_value_cap()))
    }

    fn ensure_admission_may_raise_value_cap(&self) -> Result<(), LedgerError> {
        if !self.admission_may_raise_value_cap()? {
            return Err(LedgerError::ValueRisk(
                "CENSORSHIP_STALLED blocks every value-cap or value-limit risk increase".into(),
            ));
        }
        Ok(())
    }

    pub fn empty_zone(
        display_name: impl Into<String>,
        validator_keys: Vec<String>,
        notary_keys: Vec<String>,
        testnet: bool,
    ) -> Result<Self, LedgerError> {
        Self::new(
            display_name,
            Amount::ZERO,
            validator_keys,
            notary_keys,
            testnet,
        )
    }

    pub fn balance(&self, owner: &str) -> Result<Amount, LedgerError> {
        self.coins
            .values()
            .filter(|coin| coin.owner == owner && coin.state == CoinState::Spendable)
            .try_fold(Amount::ZERO, |sum, coin| sum.checked_add(coin.amount))
            .map_err(LedgerError::from)
    }

    /// Finalizes one explicitly value-free liveness block. Consensus itself is
    /// the authorization; the command cannot mint, transfer, reserve, unlock,
    /// govern, or alter membership.
    pub fn network_heartbeat(
        &mut self,
        heartbeat: NetworkHeartbeatV1,
    ) -> Result<NetworkHeartbeatV1, LedgerError> {
        if heartbeat.heartbeat_id.is_empty()
            || heartbeat.heartbeat_id.len() > 128
            || !heartbeat
                .heartbeat_id
                .bytes()
                .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b':'))
        {
            return Err(LedgerError::Invalid(
                "network heartbeat id is not a bounded canonical identifier".into(),
            ));
        }
        if heartbeat.zone_id != self.descriptor.zone_id
            || heartbeat.currency_genesis_root != self.descriptor.currency_genesis_root
            || heartbeat.protocol_era != self.descriptor.protocol_era
            || heartbeat.crypto_era != self.descriptor.crypto_era
            || heartbeat.parent_height != self.height
        {
            return Err(LedgerError::Invalid(
                "network heartbeat does not extend the exact local ledger context".into(),
            ));
        }
        if !is_canonical_sha256_hex(&heartbeat.note_hash) {
            return Err(LedgerError::Invalid(
                "network heartbeat note hash must be lowercase SHA-256 hex".into(),
            ));
        }
        self.ensure_counter_headroom(1, 0)?;
        self.advance()?;
        Ok(heartbeat)
    }

    pub fn coins_for_owner(&self, owner: &str) -> Vec<CoinObject> {
        self.coins
            .values()
            .filter(|coin| coin.owner == owner && coin.state.carries_supply())
            .cloned()
            .collect()
    }

    pub fn register_zone_advertisement(
        &mut self,
        advertisement: ZoneAdvertisement,
    ) -> Result<ZoneAdvertisement, LedgerError> {
        advertisement.verify().map_err(LedgerError::InvalidQuorum)?;
        let zone_id = advertisement.descriptor.zone_id.clone();
        if let Some(existing) = self.zone_advertisements.get(&zone_id) {
            if advertisement.sequence <= existing.sequence {
                return Err(LedgerError::Duplicate(format!(
                    "stale Zone advertisement for {zone_id}"
                )));
            }
            if advertisement.descriptor.genesis_root != existing.descriptor.genesis_root {
                return Err(LedgerError::Invalid(
                    "Zone advertisement attempts to replace the genesis root".into(),
                ));
            }
        }
        self.zone_advertisements
            .insert(zone_id, advertisement.clone());
        Ok(advertisement)
    }

    pub fn register_payment_request(
        &mut self,
        request: PaymentRequest,
    ) -> Result<PaymentRequest, LedgerError> {
        request.verify().map_err(LedgerError::InvalidSignature)?;
        if request.destination_zone != self.descriptor.zone_id {
            return Err(LedgerError::Invalid(
                "payment request destination Zone mismatch".into(),
            ));
        }
        self.validate_payment_request_context(&request)?;
        if request.expires_at_height <= self.height {
            return Err(LedgerError::Invalid("payment request has expired".into()));
        }
        if self.payment_requests.contains_key(&request.request_id)
            || self.consumed_payment_requests.contains(&request.request_id)
        {
            return Err(LedgerError::Duplicate(request.request_id));
        }
        self.ensure_counter_headroom(1, 0)?;
        self.advance()?;
        self.payment_requests
            .insert(request.request_id.clone(), request.clone());
        Ok(request)
    }

    pub fn create_route_quote(
        &mut self,
        request: CreateRouteQuoteRequest,
    ) -> Result<RouteQuote, LedgerError> {
        let CreateRouteQuoteRequest {
            provider,
            destination_zone,
            route,
            transport,
            base_fee,
            authorized_reroute_budget,
            expires_at_height,
            authorization,
        } = request;
        if destination_zone == self.descriptor.zone_id
            || route.len() < 2
            || route.len() > 64
            || route.first() != Some(&self.descriptor.zone_id)
            || route.last() != Some(&destination_zone)
            || route.iter().any(|zone| zone.trim().is_empty())
            || route.iter().collect::<BTreeSet<_>>().len() != route.len()
            || expires_at_height <= self.height
            || transport == TransportClass::ChronologyUnsafe
        {
            return Err(LedgerError::Invalid(
                "invalid route quote path, expiry, or transport".into(),
            ));
        }
        let route_path = route.join("|");
        let payload_hash = action_payload_hash(
            "CREATE_ROUTE_QUOTE",
            &[
                provider.as_bytes(),
                destination_zone.as_bytes(),
                route_path.as_bytes(),
                transport_code(&transport).as_bytes(),
                &base_fee.0.to_be_bytes(),
                &authorized_reroute_budget.0.to_be_bytes(),
                &expires_at_height.to_be_bytes(),
            ],
        );
        self.verify_owner_authorization(
            &authorization,
            &provider,
            "CREATE_ROUTE_QUOTE",
            &payload_hash,
        )?;
        self.ensure_counter_headroom(1, 1)?;
        self.consume_authorization(&authorization)?;
        self.advance()?;
        let quote = RouteQuote {
            quote_id: self.next_id("route-quote")?,
            provider,
            source_zone: self.descriptor.zone_id.clone(),
            destination_zone,
            route,
            transport,
            base_fee,
            authorized_reroute_budget,
            consumed_reroute_fee: Amount::ZERO,
            expires_at_height,
            status: RouteQuoteStatus::Open,
            locked_payment_id: None,
            created_height: self.height,
        };
        self.route_quotes
            .insert(quote.quote_id.clone(), quote.clone());
        Ok(quote)
    }

    pub fn reroute_route_quote(
        &mut self,
        quote_id: &str,
        request: RerouteRouteQuoteRequest,
    ) -> Result<RouteQuote, LedgerError> {
        let quote = self
            .route_quotes
            .get(quote_id)
            .cloned()
            .ok_or_else(|| LedgerError::RouteQuoteNotFound(quote_id.into()))?;
        if quote.status != RouteQuoteStatus::Open || quote.expires_at_height <= self.height {
            return Err(LedgerError::Invalid(
                "only a live open route quote can fail over".into(),
            ));
        }
        if !quote.route.contains(&request.failed_hop)
            || request.failed_hop == quote.source_zone
            || request.failed_hop == quote.destination_zone
            || request.replacement_route.len() < 2
            || request.replacement_route.len() > 64
            || request.replacement_route.first() != Some(&quote.source_zone)
            || request.replacement_route.last() != Some(&quote.destination_zone)
            || request
                .replacement_route
                .iter()
                .any(|zone| zone.trim().is_empty() || zone == &request.failed_hop)
            || request
                .replacement_route
                .iter()
                .collect::<BTreeSet<_>>()
                .len()
                != request.replacement_route.len()
        {
            return Err(LedgerError::Invalid(
                "replacement route must bypass one failed intermediate hop".into(),
            ));
        }
        let new_consumed = quote
            .consumed_reroute_fee
            .checked_add(request.incremental_fee)?;
        if new_consumed > quote.authorized_reroute_budget {
            return Err(LedgerError::Invalid(
                "reroute fee exceeds the payer-authorized budget".into(),
            ));
        }
        let route_path = request.replacement_route.join("|");
        let payload_hash = action_payload_hash(
            "REROUTE_ROUTE_QUOTE",
            &[
                quote_id.as_bytes(),
                request.failed_hop.as_bytes(),
                route_path.as_bytes(),
                &request.incremental_fee.0.to_be_bytes(),
            ],
        );
        self.verify_owner_authorization(
            &request.authorization,
            &quote.provider,
            "REROUTE_ROUTE_QUOTE",
            &payload_hash,
        )?;
        self.ensure_counter_headroom(1, 0)?;
        self.consume_authorization(&request.authorization)?;
        self.advance()?;
        let stored = self
            .route_quotes
            .get_mut(quote_id)
            .expect("route quote was checked");
        stored.route = request.replacement_route;
        stored.consumed_reroute_fee = new_consumed;
        Ok(stored.clone())
    }

    pub fn accept_recipient_receipt(
        &mut self,
        receipt: RecipientReceipt,
    ) -> Result<RecipientReceipt, LedgerError> {
        receipt.verify().map_err(LedgerError::InvalidSignature)?;
        if receipt.destination_zone != self.descriptor.zone_id {
            return Err(LedgerError::Invalid(
                "recipient receipt destination Zone mismatch".into(),
            ));
        }
        if receipt.currency_genesis_root != self.descriptor.currency_genesis_root
            || receipt.protocol_era != self.descriptor.protocol_era
            || receipt.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "recipient receipt network or era context mismatch".into(),
            ));
        }
        if receipt.observed_destination_height > self.height {
            return Err(LedgerError::Invalid(
                "recipient receipt references a future height".into(),
            ));
        }
        if self.recipient_receipts.contains_key(&receipt.payment_id)
            || self
                .recipient_receipts
                .values()
                .any(|existing| existing.receipt_id == receipt.receipt_id)
        {
            return Err(LedgerError::Duplicate(receipt.receipt_id));
        }

        let local_match = self
            .payments
            .get(&receipt.payment_id)
            .is_some_and(|payment| {
                matches!(
                    payment.status,
                    PaymentStatus::LocalSpendable | PaymentStatus::UniversallySettled
                ) && payment.intent.recipient == receipt.recipient
                    && payment.intent.amount == receipt.amount
                    && receipt.settlement_reference == payment.intent.payment_id
            });
        let import_match = self.import_receipts.values().any(|import| {
            import.payment_id == receipt.payment_id
                && import.transit_id == receipt.settlement_reference
                && import.recipient == receipt.recipient
                && import.amount == receipt.amount
        });
        let spendability_match = self
            .spendability_certificates
            .get(&receipt.payment_id)
            .is_some_and(|certificate| {
                certificate.local_coin_id == receipt.settlement_reference
                    && certificate.recipient == receipt.recipient
                    && certificate.amount == receipt.amount
            });
        if !(local_match || import_match || spendability_match) {
            return Err(LedgerError::Invalid(
                "recipient receipt does not match a locally spendable settlement".into(),
            ));
        }

        self.ensure_counter_headroom(1, 0)?;
        self.advance()?;
        self.recipient_receipts
            .insert(receipt.payment_id.clone(), receipt.clone());
        Ok(receipt)
    }

    pub fn bootstrap_service_reward(
        &mut self,
        node_id: String,
        owner: String,
        role: ServiceRole,
        proof_hash: String,
        amount: Amount,
    ) -> Result<(CoinObject, ServiceReceipt), LedgerError> {
        if !self.descriptor.testnet {
            return Err(LedgerError::TestnetOnly);
        }
        if self.bootstrap_claims.contains(&owner) {
            return Err(LedgerError::Duplicate("bootstrap owner".into()));
        }
        let max = Amount::from_rld_whole(100)?;
        if amount.is_zero() || amount > max {
            return Err(LedgerError::Invalid(
                "bootstrap reward must be between 1 runlai and 100 RLD".into(),
            ));
        }
        if proof_hash.trim().is_empty() {
            return Err(LedgerError::Invalid("work proof is required".into()));
        }
        self.ensure_counter_headroom(1, 4)?;
        self.reserve_pools.startup_services = self
            .reserve_pools
            .startup_services
            .checked_sub(amount)
            .map_err(|_| LedgerError::Supply("startup service pool is exhausted".into()))?;
        self.reserve = self.reserve.checked_sub(amount)?;
        self.advance()?;
        let coin = self.make_coin(
            owner.clone(),
            amount,
            CoinState::Spendable,
            Vec::new(),
            None,
            None,
            None,
            1,
        )?;
        self.coins.insert(coin.object_id.clone(), coin.clone());

        let order_id = self.next_id("bootstrap-order")?;
        let lease_id = self.next_id("bootstrap-lease")?;
        let order = ServiceOrder {
            order_id: order_id.clone(),
            buyer: "rld:protocol:startup-services".into(),
            role: role.clone(),
            budget: amount,
            escrow_coin_id: format!("protocol-reserve:startup-services:{order_id}"),
            description: "testnet bootstrap verified network service".into(),
            status: ServiceStatus::Completed,
            created_height: self.height,
        };
        let lease = ServiceLease {
            lease_id: lease_id.clone(),
            order_id: order_id.clone(),
            node_id: node_id.clone(),
            accepted_quote: amount,
            accepted_height: self.height,
        };
        let receipt = ServiceReceipt {
            receipt_id: self.next_id("service-receipt")?,
            order_id: order_id.clone(),
            lease_id: lease_id.clone(),
            node_id: node_id.clone(),
            role: role.clone(),
            amount,
            proof_hash,
            completed_height: self.height,
            bootstrap: true,
            protocol_reserve_pool: Some(ProtocolReservePoolKind::StartupServices),
        };
        self.service_orders.insert(order_id, order);
        self.service_leases.insert(lease_id, lease);
        self.service_receipts
            .insert(receipt.receipt_id.clone(), receipt.clone());
        self.record_earnings(&node_id, &role, amount, &receipt.receipt_id)?;
        self.bootstrap_claims.insert(owner);
        self.assert_conservation()?;
        Ok((coin, receipt))
    }

    pub fn local_payment(
        &mut self,
        intent: UniversalPaymentIntent,
    ) -> Result<PaymentRecord, LedgerError> {
        self.validate_intent(&intent, true)?;
        if self.payments.contains_key(&intent.payment_id) {
            return Err(LedgerError::Duplicate(intent.payment_id));
        }
        let input = self.spendable_owned_coin(&intent.coin_id, &intent.sender_public_key)?;
        let (fee_resources, charged_fee) = self.local_payment_fee_quote(&intent)?;
        if intent.max_fee < charged_fee {
            return Err(LedgerError::Invalid(format!(
                "payment max_fee {} is below deterministic resource fee {}",
                intent.max_fee, charged_fee
            )));
        }
        let required_input = intent.amount.checked_add(charged_fee)?;
        if intent.amount.is_zero() || required_input > input.amount {
            return Err(LedgerError::Invalid("invalid payment amount".into()));
        }
        let next_value_total =
            self.next_value_risk_total(ValueRiskPath::LocalPayment, intent.amount)?;
        let change = input.amount.checked_sub(required_input)?;
        let next_version = Self::checked_next_coin_version(input.version)?;
        let sequence_steps = 1 + u64::from(!change.is_zero());
        let current_fee_pool = self
            .epoch_fee_pools
            .get(&LOCAL_PAYMENT_PRICING_EPOCH)
            .cloned()
            .unwrap_or_else(|| EpochFeePool {
                pricing_epoch: LOCAL_PAYMENT_PRICING_EPOCH,
                ..EpochFeePool::default()
            });
        let next_fee_collected = current_fee_pool.collected.checked_add(charged_fee)?;
        let next_charged_payments = current_fee_pool
            .charged_payments
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("epoch fee payment counter overflow".into()))?;
        self.ensure_counter_headroom(1, sequence_steps)?;

        self.advance()?;
        self.consume_coin(&input.object_id)?;
        let recipient_coin = self.make_coin(
            intent.recipient.clone(),
            intent.amount,
            CoinState::Spendable,
            vec![input.object_id.clone()],
            Some(input.lineage_root.clone()),
            None,
            None,
            next_version,
        )?;
        let mut outputs = vec![recipient_coin.object_id.clone()];
        self.coins
            .insert(recipient_coin.object_id.clone(), recipient_coin);
        if !change.is_zero() {
            let change_coin = self.make_coin(
                input.owner,
                change,
                CoinState::Spendable,
                vec![input.object_id],
                Some(input.lineage_root),
                None,
                None,
                next_version,
            )?;
            outputs.push(change_coin.object_id.clone());
            self.coins
                .insert(change_coin.object_id.clone(), change_coin);
        }
        let fee_pool = self
            .epoch_fee_pools
            .entry(LOCAL_PAYMENT_PRICING_EPOCH)
            .or_insert(current_fee_pool);
        fee_pool.collected = next_fee_collected;
        fee_pool.charged_payments = next_charged_payments;
        let record = PaymentRecord {
            intent: intent.clone(),
            status: PaymentStatus::UniversallySettled,
            output_coin_ids: outputs,
            transit_id: None,
            updated_height: self.height,
            charged_fee,
            fee_resources,
            pricing_epoch: LOCAL_PAYMENT_PRICING_EPOCH,
        };
        self.consume_payment_request(&intent)?;
        self.payments.insert(intent.payment_id, record.clone());
        self.record_value_risk_total(ValueRiskPath::LocalPayment, next_value_total);
        self.assert_conservation()?;
        Ok(record)
    }

    pub fn local_payment_fee_quote(
        &self,
        intent: &UniversalPaymentIntent,
    ) -> Result<(ResourceVector, Amount), LedgerError> {
        let ingress_bytes = u64::try_from(
            serde_json::to_vec(intent)
                .map_err(|error| LedgerError::Invalid(error.to_string()))?
                .len(),
        )
        .map_err(|_| LedgerError::Invalid("local payment envelope is too large".into()))?;
        let resources = ResourceVector {
            ingress_bytes,
            signature_checks_classic: 1 + u64::from(intent.payment_request.is_some()),
            signature_checks_pq: 0,
            state_reads: 3 + u64::from(intent.payment_request_id.is_some()),
            state_writes: 6 + u64::from(intent.payment_request_id.is_some()),
            new_state_bytes: ingress_bytes.checked_add(1_024).ok_or_else(|| {
                LedgerError::Invalid("local payment state-byte accounting overflow".into())
            })?,
            proof_bytes: 0,
            proof_verification_units: 0,
            consensus_units: 1,
            archive_byte_epochs: 0,
        };
        let fee = local_payment_price_schedule()
            .quote(&resources)
            .map_err(LedgerError::Invalid)?;
        Ok((resources, fee))
    }

    pub fn validate_consensus_proposal(
        &self,
        proposal: &ConsensusProposal,
    ) -> Result<ConsensusOutcome, LedgerError> {
        self.validate_consensus_proposal_envelope(proposal)?;

        let mut staged = self.clone();
        let record = staged.execute_consensus_command(proposal.command.clone())?;
        if staged.height != proposal.expected_height
            || staged.state_root()? != proposal.expected_state_root
        {
            return Err(LedgerError::InvalidQuorum(
                "proposal execution result does not match its state commitment".into(),
            ));
        }
        Ok(record)
    }

    /// Verifies the signed proposal, deterministic authority and exact
    /// prestate without attempting command execution. Only the external
    /// evidence path uses this for commands whose deterministic dependencies
    /// live outside the bounded Ledger state.
    fn validate_consensus_proposal_envelope(
        &self,
        proposal: &ConsensusProposal,
    ) -> Result<(), LedgerError> {
        if self.descriptor.testnet {
            proposal.verify().map_err(LedgerError::InvalidQuorum)?;
        } else {
            proposal
                .verify_wire_v1(&self.descriptor.network_domain)
                .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?;
        }
        self.validate_consensus_proposal_authority_and_prestate(proposal)?;
        Ok(())
    }

    /// Mints the only pre-signing context accepted by bounded tag-28 proof
    /// verification. It binds the canonical proof command to the exact current
    /// Ledger prestate without accepting caller-supplied heights or roots.
    pub fn plan_admission_checkpoint_proposal(
        &self,
        proof: &AdmissionCheckpointProofV1,
    ) -> Result<AdmissionCheckpointProposalPlanV1, LedgerError> {
        self.ensure_upgrade_height_boundary(1)?;
        if self.descriptor.testnet {
            return Err(LedgerError::InvalidQuorum(
                "tag-28 proposal planning is mainnet-wire only".into(),
            ));
        }
        if self.validated_admission_state()?.is_none() {
            return Err(LedgerError::Invalid(
                "tag-28 proposal planning requires signed M0 admission state".into(),
            ));
        }
        let expected_height = self.height.checked_add(1).ok_or_else(|| {
            LedgerError::Invalid("tag-28 proposal-plan successor height overflows U64".into())
        })?;
        let proof_id = proof
            .proof_id()
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        let command_hash = crate::command_wire::admission_checkpoint_candidate_command_hash_v1(
            &self.descriptor.network_domain,
            proof,
        )
        .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        AdmissionCheckpointProposalPlanV1::from_ledger_prestate(
            command_hash,
            proof_id,
            self.height,
            self.state_root()?,
            expected_height,
        )
        .map_err(|error| LedgerError::Invalid(error.to_string()))
    }

    /// Authenticates the signed proposal context needed by bounded tag-28 proof
    /// verification. The formal command is decodable, but pure Ledger dispatch
    /// remains fail-closed because retained Admission history is node-local.
    pub fn authenticate_admission_checkpoint_proposal(
        &self,
        proposal: &ConsensusProposal,
        proof: &AdmissionCheckpointProofV1,
    ) -> Result<AuthenticatedAdmissionCheckpointProposalV1, LedgerError> {
        if self.descriptor.testnet {
            return Err(LedgerError::InvalidQuorum(
                "tag-28 proposal authentication is mainnet-wire only".into(),
            ));
        }
        if self.validated_admission_state()?.is_none() {
            return Err(LedgerError::Invalid(
                "tag-28 proposal authentication requires signed M0 admission state".into(),
            ));
        }
        let ConsensusCommand::CommitAdmissionCheckpoint(committed_proof) = &proposal.command else {
            return Err(LedgerError::InvalidQuorum(
                "tag-28 authentication requires the formal admission-checkpoint command".into(),
            ));
        };
        if committed_proof.as_ref() != proof {
            return Err(LedgerError::InvalidQuorum(
                "tag-28 proof differs from the decoded proposal command".into(),
            ));
        }
        self.validate_consensus_proposal_envelope(proposal)?;
        let expected_command_hash =
            crate::command_wire::admission_checkpoint_candidate_command_hash_v1(
                &self.descriptor.network_domain,
                proof,
            )
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if proposal.command_hash != expected_command_hash {
            return Err(LedgerError::InvalidQuorum(
                "proposal does not commit the exact reserved tag-28 checkpoint proof".into(),
            ));
        }
        let proposal_hash = proposal
            .wire_v1_proposal_hash(&self.descriptor.network_domain)
            .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?;
        AuthenticatedAdmissionCheckpointProposalV1::from_authenticated_proposal(
            proposal_hash,
            expected_command_hash,
            proof
                .proof_id()
                .map_err(|error| LedgerError::Invalid(error.to_string()))?,
            proposal.parent_height,
            proposal.parent_state_root.clone(),
            proposal.expected_height,
            proposal.expected_state_root.clone(),
        )
        .map_err(|error| LedgerError::Invalid(error.to_string()))
    }

    pub(crate) fn validate_consensus_proposal_authority_and_prestate(
        &self,
        proposal: &ConsensusProposal,
    ) -> Result<(), LedgerError> {
        self.ensure_consensus_upgrade_boundary(&proposal.command)?;
        if self.descriptor.validator_keys.is_empty() {
            return Err(LedgerError::InvalidQuorum(
                "consensus requires a configured validator set".into(),
            ));
        }
        let expected_leader = deterministic_round_zero_leader(
            &self.descriptor.validator_keys,
            proposal.parent_height,
        )
        .map_err(LedgerError::InvalidQuorum)?;
        if proposal.zone_id != self.descriptor.zone_id
            || proposal.currency_genesis_root != self.descriptor.currency_genesis_root
            || proposal.protocol_era != self.descriptor.protocol_era
            || proposal.crypto_era != self.descriptor.crypto_era
            || proposal.proposer_public_key != expected_leader
        {
            return Err(LedgerError::InvalidQuorum(
                "proposal Zone is not authorized or proposer is not the deterministic round-zero leader"
                    .into(),
            ));
        }
        if proposal.parent_height != self.height
            || proposal.parent_state_root != self.state_root()?
        {
            return Err(LedgerError::InvalidQuorum(
                "proposal does not extend the current finalized state".into(),
            ));
        }
        Ok(())
    }

    pub fn lock_consensus_vote(&mut self, proposal: &ConsensusProposal) -> Result<(), LedgerError> {
        let mut locks = self.normalized_consensus_vote_locks()?;
        self.validate_consensus_proposal(proposal)?;
        let lock_key =
            consensus_instance_lock_key(proposal.parent_height, &proposal.parent_state_root);
        let proposal_hash = self.consensus_proposal_hash(proposal)?;
        if let Some(existing) = locks.get(&lock_key) {
            if existing != &proposal_hash {
                return Err(LedgerError::InvalidQuorum(
                    "validator already voted for a conflicting proposal in this consensus instance"
                        .into(),
                ));
            }
            self.consensus_vote_locks = locks;
            return Ok(());
        }
        locks.insert(lock_key, proposal_hash);
        self.consensus_vote_locks = locks;
        Ok(())
    }

    /// Freezes the only vote-lock mutation permitted for an externally
    /// verified tag-28 proposal. The authenticated proposal capability proves
    /// signature/leader/prestate binding; executing the verified transition on
    /// a throwaway clone proves the proposal's exact successor root before a
    /// lock can be minted.
    pub fn authenticate_admission_checkpoint_vote_lock(
        &self,
        proposal_context: &AuthenticatedAdmissionCheckpointProposalV1,
        transition: &VerifiedAdmissionCheckpointTransitionV1,
    ) -> Result<AuthenticatedAdmissionCheckpointVoteLockV1, LedgerError> {
        let mut successor = self.clone();
        successor
            .execute_authenticated_admission_checkpoint_transition(proposal_context, transition)?;
        let prior_unrooted_bytes = serde_json::to_vec(&(
            &self.era_certificates,
            &self.checkpoints,
            &self.consensus_vote_locks,
            &self.consensus_commits,
        ))
        .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        let mut successor_vote_locks = self.normalized_consensus_vote_locks()?;
        let lock_key = consensus_instance_lock_key(
            proposal_context.parent_height(),
            proposal_context.parent_state_root(),
        );
        let proposal_hash = proposal_context.proposal_hash().to_owned();
        if successor_vote_locks
            .get(&lock_key)
            .is_some_and(|existing| existing != &proposal_hash)
        {
            return Err(LedgerError::InvalidQuorum(
                "validator already voted for a conflicting proposal in this consensus instance"
                    .into(),
            ));
        }
        successor_vote_locks.insert(lock_key, proposal_hash.clone());
        Ok(AuthenticatedAdmissionCheckpointVoteLockV1 {
            proposal_hash,
            parent_height: proposal_context.parent_height(),
            parent_state_root: proposal_context.parent_state_root().into(),
            prior_unrooted_bytes,
            successor_vote_locks,
        })
    }

    /// Applies only the lock map frozen by
    /// `authenticate_admission_checkpoint_vote_lock`. Any intervening Ledger
    /// change or edit to other unrooted consensus metadata invalidates the
    /// capability before mutation.
    pub fn apply_authenticated_admission_checkpoint_vote_lock(
        &mut self,
        authenticated: AuthenticatedAdmissionCheckpointVoteLockV1,
    ) -> Result<(), LedgerError> {
        if self.height != authenticated.parent_height
            || self.state_root()? != authenticated.parent_state_root
        {
            return Err(LedgerError::InvalidQuorum(
                "authenticated tag-28 vote lock no longer names the current Ledger prestate".into(),
            ));
        }
        let current_unrooted_bytes = serde_json::to_vec(&(
            &self.era_certificates,
            &self.checkpoints,
            &self.consensus_vote_locks,
            &self.consensus_commits,
        ))
        .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if current_unrooted_bytes != authenticated.prior_unrooted_bytes {
            return Err(LedgerError::InvalidQuorum(
                "authenticated tag-28 vote lock does not match current consensus bookkeeping"
                    .into(),
            ));
        }
        self.consensus_vote_locks = authenticated.successor_vote_locks;
        Ok(())
    }

    /// Re-authenticates a formal tag-28 proposal and proves that this exact
    /// proposal hash is already present in the recovered durable vote-lock
    /// state. This is the only external-evidence substitute for pure proposal
    /// execution when constructing an unsigned vote.
    pub fn authenticate_locked_admission_checkpoint_proposal(
        &self,
        proposal: &ConsensusProposal,
        proof: &AdmissionCheckpointProofV1,
    ) -> Result<AuthenticatedAdmissionCheckpointProposalV1, LedgerError> {
        let proposal_context = self.authenticate_admission_checkpoint_proposal(proposal, proof)?;
        let locks = self.normalized_consensus_vote_locks()?;
        let lock_key = consensus_instance_lock_key(
            proposal_context.parent_height(),
            proposal_context.parent_state_root(),
        );
        if locks.get(&lock_key).map(String::as_str) != Some(proposal_context.proposal_hash()) {
            return Err(LedgerError::InvalidQuorum(
                "tag-28 vote construction requires this exact authenticated durable vote lock"
                    .into(),
            ));
        }
        Ok(proposal_context)
    }

    /// Converts legacy `height:root:round` vote locks to one lock per
    /// consensus instance. Conflicting legacy history is not repairable and
    /// therefore prevents startup.
    pub fn migrate_consensus_vote_locks(&mut self) -> Result<bool, LedgerError> {
        let normalized = self.normalized_consensus_vote_locks()?;
        if normalized == self.consensus_vote_locks {
            return Ok(false);
        }
        self.consensus_vote_locks = normalized;
        Ok(true)
    }

    fn normalized_consensus_vote_locks(&self) -> Result<BTreeMap<String, String>, LedgerError> {
        let mut normalized = BTreeMap::new();
        for (stored_key, proposal_hash) in &self.consensus_vote_locks {
            if proposal_hash.trim().is_empty() {
                return Err(LedgerError::InvalidQuorum(
                    "consensus vote lock contains an empty proposal commitment".into(),
                ));
            }
            let (parent_height, parent_state_root) = parse_consensus_vote_lock_key(stored_key)?;
            let instance_key = consensus_instance_lock_key(parent_height, &parent_state_root);
            if let Some(existing) = normalized.get(&instance_key) {
                if existing != proposal_hash {
                    return Err(LedgerError::InvalidQuorum(format!(
                        "conflicting durable vote locks exist for consensus instance {parent_height}:{parent_state_root}"
                    )));
                }
            } else {
                normalized.insert(instance_key, proposal_hash.clone());
            }
        }
        Ok(normalized)
    }

    fn consensus_proposal_hash(&self, proposal: &ConsensusProposal) -> Result<String, LedgerError> {
        if self.descriptor.testnet {
            Ok(proposal.proposal_hash())
        } else {
            proposal
                .wire_v1_proposal_hash(&self.descriptor.network_domain)
                .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))
        }
    }

    /// Authenticates a new consensus commit against the exact current prestate
    /// and freezes every field omitted from the state root plus the only
    /// permitted successor for vote-lock and commit metadata. This capability
    /// has private fields and no deserializer.
    ///
    /// It does not execute the command. It exists for bounded recovery adapters
    /// whose state-rooted transition needs node-local evidence unavailable to
    /// the pure Ledger command dispatcher.
    pub fn authenticate_consensus_commit_for_external_execution(
        &self,
        commit: &ConsensusCommit,
    ) -> Result<AuthenticatedConsensusCommitMetadataV1, LedgerError> {
        self.ensure_m0_consensus_command_allowed(&commit.proposal.command)?;
        let legacy_commit_hash = commit.commit_hash();
        let commit_hash = if self.descriptor.testnet {
            legacy_commit_hash.clone()
        } else {
            commit
                .wire_v1_commit_hash(&self.descriptor.network_domain)
                .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?
        };
        if self.consensus_commits.contains_key(&commit_hash)
            || (!self.descriptor.testnet
                && self
                    .consensus_commits
                    .get(&legacy_commit_hash)
                    .is_some_and(|existing| existing == commit))
        {
            return Err(LedgerError::InvalidQuorum(
                "external consensus execution requires a new commit at the exact prestate".into(),
            ));
        }
        if self.descriptor.testnet {
            commit
                .verify(&self.descriptor.validator_keys)
                .map_err(LedgerError::InvalidQuorum)?;
        } else {
            commit
                .verify_wire_v1(
                    &self.descriptor.validator_keys,
                    &self.descriptor.network_domain,
                )
                .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?;
        }
        if matches!(
            commit.proposal.command,
            ConsensusCommand::CommitAdmissionCheckpoint(_)
        ) {
            self.validate_consensus_proposal_envelope(&commit.proposal)?;
        } else {
            self.validate_consensus_proposal(&commit.proposal)?;
        }
        let prior_unrooted_bytes = serde_json::to_vec(&(
            &self.era_certificates,
            &self.checkpoints,
            &self.consensus_vote_locks,
            &self.consensus_commits,
        ))
        .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        let mut successor_vote_locks = self.normalized_consensus_vote_locks()?;
        let lock_key = consensus_instance_lock_key(
            commit.proposal.parent_height,
            &commit.proposal.parent_state_root,
        );
        let proposal_hash = self.consensus_proposal_hash(&commit.proposal)?;
        if successor_vote_locks
            .get(&lock_key)
            .is_some_and(|existing| existing != &proposal_hash)
        {
            return Err(LedgerError::InvalidQuorum(
                "certified commit conflicts with this validator's durable vote lock".into(),
            ));
        }
        successor_vote_locks.remove(&lock_key);
        Ok(AuthenticatedConsensusCommitMetadataV1 {
            commit: commit.clone(),
            commit_hash,
            prior_unrooted_bytes,
            successor_vote_locks,
            expected_height: commit.proposal.expected_height,
            expected_state_root: commit.proposal.expected_state_root.clone(),
        })
    }

    /// Installs only the consensus metadata frozen by
    /// `authenticate_consensus_commit_for_external_execution` after the caller
    /// has produced the exact state-rooted successor. Any callback edit to the
    /// pre-existing unrooted bookkeeping is rejected atomically.
    pub fn finalize_externally_executed_consensus_commit(
        &mut self,
        authenticated: AuthenticatedConsensusCommitMetadataV1,
    ) -> Result<(), LedgerError> {
        if self.height != authenticated.expected_height
            || self.state_root()? != authenticated.expected_state_root
        {
            return Err(LedgerError::InvalidQuorum(
                "externally executed commit does not match its certified state successor".into(),
            ));
        }
        let current_unrooted_bytes = serde_json::to_vec(&(
            &self.era_certificates,
            &self.checkpoints,
            &self.consensus_vote_locks,
            &self.consensus_commits,
        ))
        .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        if current_unrooted_bytes != authenticated.prior_unrooted_bytes {
            return Err(LedgerError::InvalidQuorum(
                "external consensus execution changed protected unrooted Ledger bookkeeping".into(),
            ));
        }
        let mut staged = self.clone();
        staged.consensus_vote_locks = authenticated.successor_vote_locks;
        if staged
            .consensus_commits
            .insert(authenticated.commit_hash, authenticated.commit)
            .is_some()
        {
            return Err(LedgerError::InvalidQuorum(
                "external consensus execution conflicts with an existing commit".into(),
            ));
        }
        *self = staged;
        Ok(())
    }

    pub fn apply_consensus_commit(
        &mut self,
        commit: ConsensusCommit,
    ) -> Result<ConsensusOutcome, LedgerError> {
        // An authenticated exact retry reads a durable outcome; it does not
        // cross the next-height boundary of a pending upgrade.
        self.ensure_m0_consensus_command_profile_allowed(&commit.proposal.command)?;
        let legacy_commit_hash = commit.commit_hash();
        let commit_hash = if self.descriptor.testnet {
            legacy_commit_hash.clone()
        } else {
            commit
                .wire_v1_commit_hash(&self.descriptor.network_domain)
                .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?
        };
        // Mainnet may read an exact pre-migration record under its legacy key,
        // but new records and non-identical replays never fall back to legacy.
        let current_record_exists = self.consensus_commits.contains_key(&commit_hash);
        let existing = self.consensus_commits.get(&commit_hash).or_else(|| {
            (!self.descriptor.testnet)
                .then(|| self.consensus_commits.get(&legacy_commit_hash))
                .flatten()
                .filter(|existing| *existing == &commit)
        });
        if let Some(existing) = existing {
            if !self.descriptor.testnet && current_record_exists {
                commit
                    .verify_wire_v1(
                        &self.descriptor.validator_keys,
                        &self.descriptor.network_domain,
                    )
                    .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?;
            }
            return match &existing.proposal.command {
                ConsensusCommand::LocalPayment(intent) => self
                    .payments
                    .get(&intent.payment_id)
                    .cloned()
                    .map(ConsensusOutcome::LocalPayment)
                    .ok_or_else(|| {
                        LedgerError::InvalidQuorum(
                            "recorded commit has no finalized payment".into(),
                        )
                    }),
                ConsensusCommand::ExportPayment { intent, .. } => self
                    .payments
                    .get(&intent.payment_id)
                    .and_then(|record| record.transit_id.as_ref())
                    .and_then(|transit_id| self.transits.get(transit_id))
                    .cloned()
                    .map(Box::new)
                    .map(ConsensusOutcome::ExportPayment)
                    .ok_or_else(|| {
                        LedgerError::InvalidQuorum(
                            "recorded commit has no finalized export capsule".into(),
                        )
                    }),
                ConsensusCommand::ImportCapsule(capsule) => self
                    .import_receipts
                    .get(&capsule.transit_id)
                    .cloned()
                    .map(ConsensusOutcome::ImportCapsule)
                    .ok_or_else(|| {
                        LedgerError::InvalidQuorum(
                            "recorded commit has no finalized import receipt".into(),
                        )
                    }),
                ConsensusCommand::FinalizeExport(receipt) => self
                    .payments
                    .get(&receipt.payment_id)
                    .cloned()
                    .map(ConsensusOutcome::FinalizeExport)
                    .ok_or_else(|| {
                        LedgerError::InvalidQuorum(
                            "recorded commit has no finalized source payment".into(),
                        )
                    }),
                ConsensusCommand::SubmitValueRiskPolicyUpdate(_)
                | ConsensusCommand::ActivatePendingValueRiskPolicy => Ok(
                    ConsensusOutcome::ValueRiskPolicy(self.value_risk_policy.clone()),
                ),
                ConsensusCommand::SubmitStakeAuthorityUpdate(request) => self
                    .reconstruct_stake_authority_command_state(
                        request,
                        u128::from(existing.proposal.parent_height),
                        existing.proposal.parent_state_root.clone(),
                        u128::from(existing.proposal.expected_height),
                    )
                    .map(ConsensusOutcome::StakeAuthority),
                ConsensusCommand::DeriveNextStakeEpoch(request) => self
                    .derived_stake_epochs
                    .get(&request.expected_consensus_epoch)
                    .cloned()
                    .map(ConsensusOutcome::DerivedStakeEpoch)
                    .ok_or_else(|| {
                        LedgerError::InvalidQuorum(
                            "recorded commit has no derived stake Epoch".into(),
                        )
                    }),
                ConsensusCommand::LockConsensusStake(request) => {
                    let exact_position = |position: &&ConsensusStakePosition| {
                        let expected_kind = match request.position_type {
                            StakePositionTypeV1::SelfBond => ConsensusStakePositionKind::SelfBond {
                                validator_id: request.validator_id.clone(),
                            },
                            StakePositionTypeV1::Delegation => {
                                ConsensusStakePositionKind::Delegation {
                                    validator_id: request.validator_id.clone(),
                                }
                            }
                        };
                        position.position_id == request.position_id
                            && position.owner == request.owner
                            && position.kind == expected_kind
                            && position.source_coin_id == request.source_coin_id
                            && position.amount == request.amount
                            && position.committed_through_height
                                == u128::from(request.committed_through_height)
                            && position.slash_terms.is_none()
                    };
                    self.consensus_stake_escrows
                        .values()
                        .find(|position| exact_position(position))
                        .or_else(|| {
                            self.consensus_stake_unbonds
                                .values()
                                .map(|record| &record.position)
                                .find(|position| exact_position(position))
                        })
                        .cloned()
                        .map(ConsensusOutcome::ConsensusStake)
                        .ok_or_else(|| {
                            LedgerError::InvalidQuorum(
                                "recorded commit has no exact consensus stake position or permanent unbond tombstone".into(),
                            )
                        })
                }
                ConsensusCommand::LockConsensusStakeV2(request) => {
                    let exact_position = |position: &&ConsensusStakePosition| {
                        let expected_kind = match request.position_type {
                            StakePositionTypeV1::SelfBond => ConsensusStakePositionKind::SelfBond {
                                validator_id: request.validator_id.clone(),
                            },
                            StakePositionTypeV1::Delegation => {
                                ConsensusStakePositionKind::Delegation {
                                    validator_id: request.validator_id.clone(),
                                }
                            }
                        };
                        let slash_policy = ConsensusStakeSlashPolicyV2::protocol_v2();
                        let expected_terms = ConsensusStakeSlashTermsV2 {
                            terms_version: slash_policy.policy_version,
                            slash_policy,
                            owner_authorization: request.slash_terms_authorization.clone(),
                        };
                        position.position_id == request.position_id
                            && position.owner == request.owner
                            && position.kind == expected_kind
                            && position.source_coin_id == request.source_coin_id
                            && position.amount == request.amount
                            && position.committed_through_height
                                == u128::from(request.committed_through_height)
                            && position.slash_terms.as_ref() == Some(&expected_terms)
                    };
                    self.consensus_stake_escrows
                        .values()
                        .find(|position| exact_position(position))
                        .or_else(|| {
                            self.consensus_stake_unbonds
                                .values()
                                .map(|record| &record.position)
                                .find(|position| exact_position(position))
                        })
                        .cloned()
                        .map(ConsensusOutcome::ConsensusStake)
                        .ok_or_else(|| {
                            LedgerError::InvalidQuorum(
                                "recorded commit has no exact slashable consensus stake position or permanent unbond tombstone".into(),
                            )
                        })
                }
                ConsensusCommand::MigrateConsensusStakeSlashTerms(request) => {
                    let slash_policy = ConsensusStakeSlashPolicyV2::protocol_v2();
                    let expected_terms = ConsensusStakeSlashTermsV2 {
                        terms_version: slash_policy.policy_version,
                        slash_policy,
                        owner_authorization: request.slash_terms_authorization.clone(),
                    };
                    let exact_position = |position: &&ConsensusStakePosition| {
                        position.position_id == request.position_id
                            && position.escrow_coin_id == request.escrow_coin_id
                            && position.owner == request.owner
                            && position.slash_terms.as_ref() == Some(&expected_terms)
                    };
                    self.consensus_stake_escrows
                        .values()
                        .find(|position| exact_position(position))
                        .or_else(|| {
                            self.consensus_stake_unbonds
                                .values()
                                .map(|record| &record.position)
                                .find(|position| exact_position(position))
                        })
                        .cloned()
                        .map(ConsensusOutcome::ConsensusStake)
                        .ok_or_else(|| {
                            LedgerError::InvalidQuorum(
                                "recorded commit has no exact migrated slash-terms position or permanent unbond tombstone".into(),
                            )
                        })
                }
                ConsensusCommand::SlashConsensusStake(request) => self
                    .consensus_stake_slashes
                    .get(&request.slash_id)
                    .filter(|record| {
                        record.evidence_hash == request.evidence_hash
                            && record.consensus_epoch == request.consensus_epoch
                            && record.derived_epoch_record_hash == request.derived_epoch_record_hash
                            && record.liability_commitment == request.liability_commitment
                            && record.position.position_id == request.position_id
                            && record.position.escrow_coin_id == request.escrow_coin_id
                            && record.position.amount == request.expected_position_amount
                            && record.unbond_request_commitment
                                == request.expected_unbond_request_commitment
                    })
                    .cloned()
                    .map(Box::new)
                    .map(ConsensusOutcome::ConsensusStakeSlash)
                    .ok_or_else(|| {
                        LedgerError::InvalidQuorum(
                            "recorded commit has no exact consensus stake slash record".into(),
                        )
                    }),
                ConsensusCommand::RegisterConsensusValidator(request) => {
                    Ok(ConsensusOutcome::StakeCandidate(ValidatorCandidateRecord {
                        validator_id: request.validator_id.clone(),
                        owner: request.owner.clone(),
                        public_key: request.public_key.clone(),
                        key_era: request.key_era,
                        registered_height: u128::from(existing.proposal.expected_height),
                        exit_height: None,
                        proof_of_possession: request.proof_of_possession.clone(),
                    }))
                }
                ConsensusCommand::RegisterConsensusValidatorV2(request) => self
                    .replay_consensus_validator_registration_v2(
                        request,
                        existing.proposal.expected_height,
                    )
                    .map(Box::new)
                    .map(ConsensusOutcome::StakeCandidateResourceRegistration),
                ConsensusCommand::LockConsensusStakeV3(request) => self
                    .replay_consensus_stake_lock_v3(request, existing.proposal.expected_height)
                    .map(Box::new)
                    .map(ConsensusOutcome::ConsensusStakeResourceLock),
                ConsensusCommand::MigrateConsensusStakeResource(request) => self
                    .replay_consensus_stake_resource_migration(
                        request,
                        existing.proposal.expected_height,
                    )
                    .map(Box::new)
                    .map(ConsensusOutcome::ConsensusStakeResourceMigration),
                ConsensusCommand::MigrateConsensusCandidateResource(request) => self
                    .replay_consensus_candidate_resource_migration(
                        request,
                        existing.proposal.expected_height,
                    )
                    .map(Box::new)
                    .map(ConsensusOutcome::ConsensusCandidateResourceMigration),
                ConsensusCommand::DeriveNextStakeEpochV2(request) => self
                    .replay_next_stake_epoch_v2(request, existing.proposal.expected_height)
                    .map(Box::new)
                    .map(ConsensusOutcome::DerivedStakeEpochResource),
                ConsensusCommand::RenewStakeStateResourceBond(request) => self
                    .replay_stake_state_resource_bond_renewal(request)
                    .map(Box::new)
                    .map(ConsensusOutcome::StakeStateResourceBondRenewal),
                ConsensusCommand::ExitConsensusValidator(request) => {
                    Ok(ConsensusOutcome::StakeCandidate(ValidatorCandidateRecord {
                        validator_id: request.validator_id.clone(),
                        owner: request.owner.clone(),
                        public_key: request.public_key.clone(),
                        key_era: request.key_era,
                        registered_height: u128::from(request.registered_height),
                        exit_height: Some(u128::from(request.exit_height)),
                        proof_of_possession: request.proof_of_possession.clone(),
                    }))
                }
                ConsensusCommand::RequestConsensusStakeUnbond(request) => {
                    let current = self
                        .consensus_stake_unbonds
                        .get(&request.request_id)
                        .filter(|record| {
                            record.position.position_id == request.position_id
                                && record.position.escrow_coin_id == request.escrow_coin_id
                                && record.owner == request.owner
                                && record.beneficiary == request.beneficiary
                                && record.withdraw_after_height
                                    == request.requested_withdraw_after_height
                        })
                        .ok_or_else(|| {
                            LedgerError::InvalidQuorum(
                                "recorded commit has no exact stake unbond request".into(),
                            )
                        })?;
                    let mut historical = current.clone();
                    historical.requested_height = existing.proposal.expected_height;
                    historical.status = ConsensusStakeUnbondStatusV1::Pending;
                    historical.completion_id = None;
                    historical.completed_height = None;
                    historical.payout_coin_id = None;
                    historical.slash_id = None;
                    historical.slashed_amount = Amount::ZERO;
                    historical.request_commitment = historical.compute_request_commitment();
                    Ok(ConsensusOutcome::ConsensusStakeUnbond(historical))
                }
                ConsensusCommand::CompleteConsensusStakeUnbond(request) => self
                    .consensus_stake_unbonds
                    .get(&request.request_id)
                    .filter(|record| {
                        record.status == ConsensusStakeUnbondStatusV1::Completed
                            && record.completion_id.as_deref()
                                == Some(request.completion_id.as_str())
                            && record.request_commitment
                                == request.expected_unbond_request_commitment
                            && record.beneficiary == request.beneficiary
                    })
                    .cloned()
                    .map(ConsensusOutcome::ConsensusStakeUnbond)
                    .ok_or_else(|| {
                        LedgerError::InvalidQuorum(
                            "recorded commit has no exact completed stake unbond".into(),
                        )
                    }),
                ConsensusCommand::ProposeStakeStateResourcePolicy(request) => self
                    .stake_resource_policy_proposals
                    .get(&request.proposal_id)
                    .filter(|record| *record == request.as_ref())
                    .cloned()
                    .map(Box::new)
                    .map(ConsensusOutcome::StakeStateResourcePolicyProposal)
                    .ok_or_else(|| {
                        LedgerError::InvalidQuorum(
                            "recorded commit has no exact resource-policy proposal".into(),
                        )
                    }),
                ConsensusCommand::ActivateStakeStateResourcePolicy(request) => self
                    .stake_resource_policy_activations
                    .get(&request.activation_id)
                    .filter(|record| *record == request.as_ref())
                    .and_then(|record| {
                        self.stake_resource_policy_proposals
                            .get(&record.proposal_id)
                    })
                    .map(|proposal| proposal.proposed_policy.clone())
                    .map(ConsensusOutcome::StakeStateResourcePolicy)
                    .ok_or_else(|| {
                        LedgerError::InvalidQuorum(
                            "recorded commit has no exact resource-policy activation".into(),
                        )
                    }),
                ConsensusCommand::ScheduleUpgrade(schedule) => {
                    Ok(ConsensusOutcome::UpgradeScheduled(
                        crate::genesis::upgrade_pending::PendingUpgradeV1 {
                            format_version: "RLD-PENDING-UPGRADE-V1".into(),
                            scheduled_height: u128::from(existing.proposal.expected_height),
                            scheduled_parent_root: AdmissionHash32::from_hex(
                                &existing.proposal.parent_state_root,
                            )
                            .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?,
                            schedule: schedule.as_ref().clone(),
                        },
                    ))
                }
                ConsensusCommand::ActivateUpgrade(activation) => self
                    .m0_active_protocol
                    .as_ref()
                    .filter(|active| {
                        active.upgrade_sequence == activation.sequence
                            && active.last_activated_upgrade.as_deref()
                                == Some(activation.intent_id.to_hex().as_str())
                    })
                    .cloned()
                    .map(ConsensusOutcome::UpgradeActivated)
                    .ok_or_else(|| {
                        LedgerError::InvalidQuorum(
                            "recorded activation has no exact active successor".into(),
                        )
                    }),
                ConsensusCommand::NetworkHeartbeat(heartbeat) => {
                    Ok(ConsensusOutcome::NetworkHeartbeat(heartbeat.clone()))
                }
                ConsensusCommand::CommitAdmissionCheckpoint(proof) => proof
                    .proof_id()
                    .map(ConsensusOutcome::AdmissionCheckpoint)
                    .map_err(|error| LedgerError::InvalidQuorum(error.to_string())),
                ConsensusCommand::Production(command) => self
                    .replay_production_command(command)
                    .map(ConsensusOutcome::Production),
            };
        }
        self.ensure_consensus_upgrade_boundary(&commit.proposal.command)?;
        if self.descriptor.testnet {
            commit
                .verify(&self.descriptor.validator_keys)
                .map_err(LedgerError::InvalidQuorum)?;
        } else {
            commit
                .verify_wire_v1(
                    &self.descriptor.validator_keys,
                    &self.descriptor.network_domain,
                )
                .map_err(|error| LedgerError::InvalidQuorum(error.to_string()))?;
        }
        self.validate_consensus_proposal(&commit.proposal)?;
        let mut locks = self.normalized_consensus_vote_locks()?;
        let lock_key = consensus_instance_lock_key(
            commit.proposal.parent_height,
            &commit.proposal.parent_state_root,
        );
        let proposal_hash = self.consensus_proposal_hash(&commit.proposal)?;
        if locks
            .get(&lock_key)
            .is_some_and(|existing| existing != &proposal_hash)
        {
            return Err(LedgerError::InvalidQuorum(
                "certified commit conflicts with this validator's durable vote lock".into(),
            ));
        }
        // Execute and compare the certified post-state on a clone so any
        // command failure or expected-root mismatch is failure-atomic for the
        // live ledger, including across future command variants.
        let mut staged = self.clone();
        let record = staged.execute_consensus_command(commit.proposal.command.clone())?;
        if staged.height != commit.proposal.expected_height
            || staged.state_root()? != commit.proposal.expected_state_root
        {
            return Err(LedgerError::InvalidQuorum(
                "committed execution diverged from the certified state root".into(),
            ));
        }
        locks.remove(&lock_key);
        staged.consensus_vote_locks = locks;
        staged.consensus_commits.insert(commit_hash, commit);
        *self = staged;
        Ok(record)
    }

    pub fn execute_consensus_command(
        &mut self,
        command: ConsensusCommand,
    ) -> Result<ConsensusOutcome, LedgerError> {
        self.ensure_m0_consensus_command_allowed(&command)?;
        match command {
            ConsensusCommand::LocalPayment(intent) => self
                .local_payment(intent)
                .map(ConsensusOutcome::LocalPayment),
            ConsensusCommand::ExportPayment { intent, transport } => self
                .export_payment(intent, transport)
                .map(Box::new)
                .map(ConsensusOutcome::ExportPayment),
            ConsensusCommand::ImportCapsule(capsule) => self
                .import_capsule(*capsule)
                .map(ConsensusOutcome::ImportCapsule),
            ConsensusCommand::FinalizeExport(receipt) => self
                .finalize_export(&receipt)
                .map(ConsensusOutcome::FinalizeExport),
            ConsensusCommand::SubmitValueRiskPolicyUpdate(update) => self
                .submit_value_risk_policy_update(*update)
                .map(ConsensusOutcome::ValueRiskPolicy),
            ConsensusCommand::ActivatePendingValueRiskPolicy => self
                .activate_pending_value_risk_policy()
                .map(ConsensusOutcome::ValueRiskPolicy),
            ConsensusCommand::SubmitStakeAuthorityUpdate(update) => self
                .submit_stake_authority_update(*update)
                .map(ConsensusOutcome::StakeAuthority),
            ConsensusCommand::DeriveNextStakeEpoch(request) => self
                .derive_next_stake_epoch(*request)
                .map(ConsensusOutcome::DerivedStakeEpoch),
            ConsensusCommand::LockConsensusStake(request) => self
                .lock_consensus_stake(*request)
                .map(ConsensusOutcome::ConsensusStake),
            ConsensusCommand::RegisterConsensusValidator(request) => self
                .register_consensus_validator(*request)
                .map(ConsensusOutcome::StakeCandidate),
            ConsensusCommand::RegisterConsensusValidatorV2(request) => self
                .register_consensus_validator_v2(*request)
                .map(Box::new)
                .map(ConsensusOutcome::StakeCandidateResourceRegistration),
            ConsensusCommand::ExitConsensusValidator(request) => self
                .exit_consensus_validator(*request)
                .map(ConsensusOutcome::StakeCandidate),
            ConsensusCommand::RequestConsensusStakeUnbond(request) => self
                .request_consensus_stake_unbond(*request)
                .map(ConsensusOutcome::ConsensusStakeUnbond),
            ConsensusCommand::CompleteConsensusStakeUnbond(request) => self
                .complete_consensus_stake_unbond(*request)
                .map(ConsensusOutcome::ConsensusStakeUnbond),
            ConsensusCommand::LockConsensusStakeV2(request) => self
                .lock_consensus_stake_v2(*request)
                .map(ConsensusOutcome::ConsensusStake),
            ConsensusCommand::MigrateConsensusStakeSlashTerms(request) => self
                .migrate_consensus_stake_slash_terms(*request)
                .map(ConsensusOutcome::ConsensusStake),
            ConsensusCommand::SlashConsensusStake(request) => self
                .slash_consensus_stake(*request)
                .map(Box::new)
                .map(ConsensusOutcome::ConsensusStakeSlash),
            ConsensusCommand::ProposeStakeStateResourcePolicy(request) => self
                .propose_stake_state_resource_policy(*request)
                .map(Box::new)
                .map(ConsensusOutcome::StakeStateResourcePolicyProposal),
            ConsensusCommand::ActivateStakeStateResourcePolicy(request) => self
                .activate_stake_state_resource_policy(*request)
                .map(ConsensusOutcome::StakeStateResourcePolicy),
            ConsensusCommand::LockConsensusStakeV3(request) => self
                .lock_consensus_stake_v3(*request)
                .map(Box::new)
                .map(ConsensusOutcome::ConsensusStakeResourceLock),
            ConsensusCommand::MigrateConsensusStakeResource(request) => self
                .migrate_consensus_stake_resource(*request)
                .map(Box::new)
                .map(ConsensusOutcome::ConsensusStakeResourceMigration),
            ConsensusCommand::MigrateConsensusCandidateResource(request) => self
                .migrate_consensus_candidate_resource(*request)
                .map(Box::new)
                .map(ConsensusOutcome::ConsensusCandidateResourceMigration),
            ConsensusCommand::DeriveNextStakeEpochV2(request) => self
                .derive_next_stake_epoch_v2(*request)
                .map(Box::new)
                .map(ConsensusOutcome::DerivedStakeEpochResource),
            ConsensusCommand::RenewStakeStateResourceBond(request) => self
                .renew_stake_state_resource_bond(*request)
                .map(Box::new)
                .map(ConsensusOutcome::StakeStateResourceBondRenewal),
            ConsensusCommand::ScheduleUpgrade(schedule) => {
                crate::genesis::upgrade_migration::validate_first_schedule_artifacts(&schedule).map_err(LedgerError::Invalid)?;
                let next = self.preview_upgrade_schedule(&schedule)?;
                let outcome = next.m0_pending_upgrade.clone().ok_or_else(|| LedgerError::Invalid("missing schedule successor".into()))?;
                *self = next;
                Ok(ConsensusOutcome::UpgradeScheduled(outcome))
            }
            ConsensusCommand::ActivateUpgrade(activation) => {
                let next = self.preview_supported_upgrade_activation(&activation).map_err(LedgerError::Invalid)?;
                let outcome = next.m0_active_protocol.clone().ok_or_else(|| LedgerError::Invalid("missing activation successor".into()))?;
                *self = next;
                Ok(ConsensusOutcome::UpgradeActivated(outcome))
            }
            ConsensusCommand::NetworkHeartbeat(heartbeat) => self
                .network_heartbeat(heartbeat)
                .map(ConsensusOutcome::NetworkHeartbeat),
            ConsensusCommand::CommitAdmissionCheckpoint(_) => Err(LedgerError::Invalid(
                "tag-28 admission checkpoint requires authenticated node-local history; pure Ledger dispatch is fail-closed"
                    .into(),
            )),
            ConsensusCommand::Production(command) => self
                .execute_production_command(*command)
                .map(ConsensusOutcome::Production),
        }
    }

    pub fn execute_production_command(
        &mut self,
        command: ProductionCommand,
    ) -> Result<serde_json::Value, LedgerError> {
        fn output<T: Serialize>(value: T) -> Result<serde_json::Value, LedgerError> {
            serde_json::to_value(value).map_err(|error| LedgerError::Invalid(error.to_string()))
        }

        match command {
            ProductionCommand::ZoneAdvertisement(advertisement) => {
                output(self.register_zone_advertisement(advertisement)?)
            }
            ProductionCommand::RouteQuoteCreate(request) => {
                output(self.create_route_quote(request)?)
            }
            ProductionCommand::RouteQuoteReroute { quote_id, request } => {
                output(self.reroute_route_quote(&quote_id, request)?)
            }
            ProductionCommand::PaymentRequest(request) => {
                output(self.register_payment_request(request)?)
            }
            ProductionCommand::RecipientReceipt(receipt) => {
                output(self.accept_recipient_receipt(receipt)?)
            }
            ProductionCommand::GatewayBond(request) => output(self.create_gateway_bond(request)?),
            ProductionCommand::RejectionCreate { capsule, reason } => {
                output(self.create_destination_rejection(*capsule, reason)?)
            }
            ProductionCommand::RejectionCertify {
                transit_id,
                validator_qc,
                notary_qc,
            } => {
                output(self.certify_destination_rejection(&transit_id, validator_qc, notary_qc)?)
            }
            ProductionCommand::ReturnBegin(proof) => {
                output(self.begin_return_from_rejection(proof)?)
            }
            ProductionCommand::ReturnFinalize(transit_id) => {
                output(self.finalize_return(&transit_id)?)
            }
            ProductionCommand::TransitCertify {
                transit_id,
                validator_qc,
                notary_qc,
            } => output(self.certify_transit(&transit_id, validator_qc, notary_qc)?),
            ProductionCommand::TravelerCreate { intent, transport } => {
                output(self.create_traveler_capsule(intent, transport)?)
            }
            ProductionCommand::TravelerImport(capsule) => {
                output(self.import_traveler_capsule(*capsule)?)
            }
            ProductionCommand::DscIssue(request) => {
                output(self.issue_spendability_certificate(request)?)
            }
            ProductionCommand::LiquidityOfferCreate(request) => {
                output(self.create_liquidity_offer(request)?)
            }
            ProductionCommand::LiquidityOfferTake(request) => {
                output(self.take_liquidity_offer(*request)?)
            }
            ProductionCommand::ProtocolServiceOrder(request) => {
                output(self.create_protocol_service_order(request)?)
            }
            ProductionCommand::ServiceOrder {
                buyer,
                coin_id,
                role,
                budget,
                description,
                authorization,
            } => output(self.create_service_order(
                buyer,
                coin_id,
                role,
                budget,
                description,
                authorization,
            )?),
            ProductionCommand::ServiceLease {
                order_id,
                node_id,
                accepted_quote,
                authorization,
            } => output(self.lease_service(&order_id, node_id, accepted_quote, authorization)?),
            ProductionCommand::ServiceComplete {
                lease_id,
                proof_hash,
                authorization,
                validator_qc,
                notary_qc,
            } => match (validator_qc, notary_qc) {
                (Some(validator_qc), Some(notary_qc)) => output(self.complete_protocol_service(
                    &lease_id,
                    proof_hash,
                    authorization,
                    validator_qc,
                    notary_qc,
                )?),
                (None, None) => {
                    output(self.complete_service(&lease_id, proof_hash, authorization)?)
                }
                _ => Err(LedgerError::Invalid(
                    "protocol completion requires both validator and notary QCs".into(),
                )),
            },
            ProductionCommand::EconomicControlAttestation(attestation) => {
                output(self.register_economic_control_attestation(attestation)?)
            }
            ProductionCommand::EconomicPriceAttestation(attestation) => {
                output(self.register_economic_price_attestation(attestation)?)
            }
            ProductionCommand::EconomicReleasePolicy(policy) => {
                output(self.set_economic_release_policy(policy)?)
            }
            ProductionCommand::ProtocolServiceBondLock(request) => {
                output(self.lock_protocol_service_bond(request)?)
            }
            ProductionCommand::ProtocolServiceBondSlash(slash) => {
                output(self.slash_protocol_service_bond(slash)?)
            }
            ProductionCommand::ProtocolServiceBondUnbond {
                bond_id,
                authorization,
            } => output(self.unbond_protocol_service_bond(&bond_id, authorization)?),
            ProductionCommand::ProtocolReserveRelease(request) => {
                output(self.release_protocol_reserve(*request)?)
            }
            ProductionCommand::VoyageOpen {
                payer,
                coin_id,
                transit_id,
                budget,
                max_reward_per_hop,
                authorization,
            } => output(self.open_voyage_escrow(
                payer,
                coin_id,
                transit_id,
                budget,
                max_reward_per_hop,
                authorization,
            )?),
            ProductionCommand::VoyageSettle {
                escrow_id,
                node_id,
                amount,
                downstream_receipt_hash,
                authorization,
            } => output(self.settle_voyage_hop(
                &escrow_id,
                node_id,
                amount,
                downstream_receipt_hash,
                authorization,
            )?),
            ProductionCommand::EraTransition(certificate) => {
                output(self.apply_era_transition(*certificate)?)
            }
        }
    }

    fn replay_production_command(
        &self,
        command: &ProductionCommand,
    ) -> Result<serde_json::Value, LedgerError> {
        fn output<T: Serialize>(value: T) -> Result<serde_json::Value, LedgerError> {
            serde_json::to_value(value).map_err(|error| LedgerError::Invalid(error.to_string()))
        }

        match command {
            ProductionCommand::EconomicControlAttestation(attestation) => self
                .economic_control_attestations
                .get(&attestation.attestation_id)
                .cloned()
                .ok_or_else(|| {
                    LedgerError::InvalidQuorum(
                        "recorded commit has no economic control attestation".into(),
                    )
                })
                .and_then(output),
            ProductionCommand::EconomicPriceAttestation(attestation) => self
                .economic_price_attestations
                .get(&attestation.attestation_id)
                .cloned()
                .ok_or_else(|| {
                    LedgerError::InvalidQuorum(
                        "recorded commit has no economic price attestation".into(),
                    )
                })
                .and_then(output),
            ProductionCommand::EconomicReleasePolicy(policy) => self
                .economic_release_policies
                .get(&policy.policy_id)
                .cloned()
                .ok_or_else(|| {
                    LedgerError::InvalidQuorum(
                        "recorded commit has no economic release policy".into(),
                    )
                })
                .and_then(output),
            ProductionCommand::ProtocolServiceBondLock(request) => self
                .protocol_service_bonds
                .get(&request.bond_id)
                .cloned()
                .ok_or_else(|| {
                    LedgerError::InvalidQuorum(
                        "recorded commit has no protocol service bond".into(),
                    )
                })
                .and_then(output),
            ProductionCommand::ProtocolServiceBondSlash(slash) => self
                .protocol_service_bonds
                .get(&slash.bond_id)
                .cloned()
                .ok_or_else(|| {
                    LedgerError::InvalidQuorum(
                        "recorded commit has no slashed protocol service bond".into(),
                    )
                })
                .and_then(output),
            ProductionCommand::ProtocolServiceBondUnbond { bond_id, .. } => self
                .protocol_service_bonds
                .get(bond_id)
                .cloned()
                .ok_or_else(|| {
                    LedgerError::InvalidQuorum(
                        "recorded commit has no unbonded protocol service bond".into(),
                    )
                })
                .and_then(output),
            ProductionCommand::ProtocolReserveRelease(request) => self
                .protocol_reserve_releases
                .get(&request.release_id)
                .cloned()
                .ok_or_else(|| {
                    LedgerError::InvalidQuorum(
                        "recorded commit has no protocol reserve release".into(),
                    )
                })
                .and_then(output),
            _ => Ok(serde_json::Value::Null),
        }
    }

    pub fn export_payment(
        &mut self,
        intent: UniversalPaymentIntent,
        transport: TransportClass,
    ) -> Result<TransitCapsule, LedgerError> {
        self.validate_intent(&intent, false)?;
        if transport == TransportClass::ChronologyUnsafe {
            return Err(LedgerError::CausalQuarantine(
                "chronology-unsafe route".into(),
            ));
        }
        let next_cross_zone_exposure =
            self.next_value_risk_total(ValueRiskPath::CrossZone, intent.amount)?;
        if !self.descriptor.testnet {
            return Err(LedgerError::InvalidQuorum(
                "reference node requires external BFT QC integration outside testnet".into(),
            ));
        }
        if self.payments.contains_key(&intent.payment_id) {
            return Err(LedgerError::Duplicate(intent.payment_id));
        }
        let route_quote = if let Some(quote_id) = &intent.route_quote_id {
            let quote = self
                .route_quotes
                .get(quote_id)
                .cloned()
                .ok_or_else(|| LedgerError::RouteQuoteNotFound(quote_id.clone()))?;
            if quote.status != RouteQuoteStatus::Open
                || quote.source_zone != self.descriptor.zone_id
                || quote.destination_zone != intent.destination_zone
                || quote.transport != transport
                || quote.expires_at_height <= self.height
            {
                return Err(LedgerError::Invalid(
                    "route quote is not valid for this payment".into(),
                ));
            }
            let authorized_total = quote
                .base_fee
                .checked_add(quote.authorized_reroute_budget)?;
            if authorized_total > intent.max_fee {
                return Err(LedgerError::Invalid(
                    "payment max fee is below the locked route quote".into(),
                ));
            }
            Some(quote)
        } else {
            None
        };
        let validator_qc = outbound_qc(&self.descriptor.validator_keys)?;
        let notary_qc = outbound_qc(&self.descriptor.notary_keys)?;
        let input = self.spendable_owned_coin(&intent.coin_id, &intent.sender_public_key)?;
        let route_fee = route_quote
            .as_ref()
            .map(|quote| quote.base_fee.checked_add(quote.consumed_reroute_fee))
            .transpose()?
            .unwrap_or(Amount::ZERO);
        let required_input = intent.amount.checked_add(route_fee)?;
        if intent.amount.is_zero() || required_input > input.amount {
            return Err(LedgerError::Invalid("invalid export amount".into()));
        }
        let change = input.amount.checked_sub(required_input)?;
        let next_version = Self::checked_next_coin_version(input.version)?;
        let sequence_steps = 2 + u64::from(!route_fee.is_zero()) + u64::from(!change.is_zero());
        self.ensure_counter_headroom(1, sequence_steps)?;

        self.advance()?;
        self.consume_coin(&input.object_id)?;
        let transit_id = self.next_id("transit")?;
        let transit_coin = self.make_coin(
            intent.recipient.clone(),
            intent.amount,
            CoinState::InTransit,
            vec![input.object_id.clone()],
            Some(input.lineage_root.clone()),
            Some(transit_id.clone()),
            None,
            next_version,
        )?;
        let transit_coin_id = transit_coin.object_id.clone();
        self.coins
            .insert(transit_coin.object_id.clone(), transit_coin.clone());
        self.transit_coin_ids
            .insert(transit_id.clone(), transit_coin_id.clone());

        let mut outputs = vec![transit_coin_id.clone()];
        if let Some(quote) = &route_quote {
            if !route_fee.is_zero() {
                let fee_coin = self.make_coin(
                    quote.provider.clone(),
                    route_fee,
                    CoinState::Spendable,
                    vec![input.object_id.clone()],
                    Some(input.lineage_root.clone()),
                    None,
                    input.imported_from.clone(),
                    next_version,
                )?;
                outputs.push(fee_coin.object_id.clone());
                self.coins.insert(fee_coin.object_id.clone(), fee_coin);
            }
        }
        if !change.is_zero() {
            let change_coin = self.make_coin(
                input.owner,
                change,
                CoinState::Spendable,
                vec![input.object_id],
                Some(input.lineage_root),
                None,
                None,
                next_version,
            )?;
            outputs.push(change_coin.object_id.clone());
            self.coins
                .insert(change_coin.object_id.clone(), change_coin);
        }

        let checkpoint = self.create_checkpoint()?;
        let object_hash = hash_bytes(
            &serde_json::to_vec(&transit_coin)
                .map_err(|error| LedgerError::Invalid(error.to_string()))?,
        );
        let supply_certificate_hash = hash_bytes(
            &serde_json::to_vec(&checkpoint.supply)
                .map_err(|error| LedgerError::Invalid(error.to_string()))?,
        );
        let era_certificate = self.era_certificates.last().cloned();
        let era_certificate_hash = era_certificate
            .as_ref()
            .map(|certificate| certificate.certificate_hash.clone())
            .unwrap_or_else(|| {
                hash_parts(&[
                    b"RLD-GENESIS-ERA",
                    self.descriptor.zone_id.as_bytes(),
                    &self.descriptor.protocol_era.to_be_bytes(),
                    &self.descriptor.crypto_era.to_be_bytes(),
                ])
            });
        let continuity_accumulator = hash_parts(&[
            b"RLD-CONTINUITY-V1",
            transit_coin.origin_genesis_root.as_bytes(),
            self.era_continuity_accumulator.as_bytes(),
        ]);
        let transit_nullifier_commitment = hash_parts(&[
            b"RLD-TRANSIT-NULLIFIER-V1",
            self.descriptor.zone_id.as_bytes(),
            transit_id.as_bytes(),
        ]);
        let operational_proof = OperationalProof {
            checkpoint_hash: checkpoint.checkpoint_hash.clone(),
            object_hash,
            continuity_accumulator,
            lineage_merkle_path: transit_coin
                .parent_ids
                .iter()
                .map(|parent| hash_bytes(parent.as_bytes()))
                .collect(),
            transition_hashes: vec![hash_bytes(&intent.signing_bytes())],
            protocol_era: self.descriptor.protocol_era,
            crypto_era: self.descriptor.crypto_era,
            era_certificate_hash,
            supply_certificate_hash,
            transit_nullifier_commitment,
        };
        operational_proof
            .validate_bounds()
            .map_err(LedgerError::InvalidOperationalProof)?;
        let mut capsule = TransitCapsule {
            transit_id: transit_id.clone(),
            payment_id: intent.payment_id.clone(),
            payment_request_id: intent.payment_request_id.clone(),
            payment_request: intent.payment_request.clone(),
            route_quote_id: intent.route_quote_id.clone(),
            source_zone: self.descriptor.zone_id.clone(),
            destination_zone: intent.destination_zone.clone(),
            source_descriptor: self.descriptor.clone(),
            recipient: intent.recipient.clone(),
            amount: intent.amount,
            lineage_root: transit_coin.lineage_root.clone(),
            source_object_id: transit_coin_id,
            source_object_version: transit_coin.version,
            source_object: transit_coin.clone(),
            source_supply: checkpoint.supply.clone(),
            origin_genesis_root: transit_coin.origin_genesis_root.clone(),
            source_checkpoint: checkpoint.checkpoint_hash.clone(),
            validator_qc,
            notary_qc,
            operational_proof,
            era_certificate,
            gateway_endorsement: None,
            transport,
        };
        let subject_hash = capsule.subject_hash();
        capsule.validator_qc.subject_hash.clone_from(&subject_hash);
        capsule.notary_qc.subject_hash = subject_hash;
        self.consume_payment_request(&intent)?;
        if let Some(quote) = route_quote {
            let stored = self
                .route_quotes
                .get_mut(&quote.quote_id)
                .expect("route quote was checked");
            stored.status = RouteQuoteStatus::Locked;
            stored.locked_payment_id = Some(intent.payment_id.clone());
        }
        self.transits.insert(transit_id.clone(), capsule.clone());
        self.payments.insert(
            intent.payment_id.clone(),
            PaymentRecord {
                intent,
                status: PaymentStatus::InTransit,
                output_coin_ids: outputs,
                transit_id: Some(transit_id),
                updated_height: self.height,
                charged_fee: route_fee,
                fee_resources: ResourceVector::default(),
                pricing_epoch: 0,
            },
        );
        self.record_value_risk_total(ValueRiskPath::CrossZone, next_cross_zone_exposure);
        self.assert_conservation()?;
        Ok(capsule)
    }

    pub fn certify_transit(
        &mut self,
        transit_id: &str,
        validator_qc: QuorumCertificate,
        notary_qc: QuorumCertificate,
    ) -> Result<TransitCapsule, LedgerError> {
        let mut capsule = self
            .transits
            .get(transit_id)
            .cloned()
            .ok_or_else(|| LedgerError::TransitNotFound(transit_id.into()))?;
        let subject = capsule.subject_hash();
        if validator_qc.subject_hash != subject || notary_qc.subject_hash != subject {
            return Err(LedgerError::InvalidQuorum("subject hash mismatch".into()));
        }
        validator_qc
            .verify(&self.descriptor.validator_keys)
            .map_err(LedgerError::InvalidQuorum)?;
        notary_qc
            .verify(&self.descriptor.notary_keys)
            .map_err(LedgerError::InvalidQuorum)?;

        capsule.validator_qc = validator_qc;
        capsule.notary_qc = notary_qc;
        self.ensure_counter_headroom(1, 0)?;
        self.advance()?;
        if let Some(record) = self
            .payments
            .values_mut()
            .find(|record| record.transit_id.as_deref() == Some(transit_id))
        {
            record.updated_height = self.height;
        }
        self.transits.insert(transit_id.into(), capsule.clone());
        Ok(capsule)
    }

    pub fn create_destination_rejection(
        &mut self,
        capsule: TransitCapsule,
        reason: DestinationRejectionReason,
    ) -> Result<DestinationRejectionProof, LedgerError> {
        if capsule.destination_zone != self.descriptor.zone_id {
            return Err(LedgerError::Invalid("capsule destination mismatch".into()));
        }
        if self.transit_nullifiers.contains(&capsule.transit_id)
            || self
                .rejected_transit_nullifiers
                .contains(&capsule.transit_id)
            || self
                .spendability_certificates
                .contains_key(&capsule.payment_id)
        {
            return Err(LedgerError::Invalid(
                "an imported, rejected or liquidity-settled transit cannot be rejected".into(),
            ));
        }

        // Validate exactly the same capsule acceptance path on an isolated state copy.
        // The real destination commits only the rejection nullifier, never an imported coin.
        let mut verifier = self.clone();
        verifier.import_capsule(capsule.clone())?;

        self.ensure_counter_headroom(1, 1)?;
        self.advance()?;
        let checkpoint = self.create_checkpoint()?;
        let validator_qc = outbound_qc(&self.descriptor.validator_keys)?;
        let notary_qc = outbound_qc(&self.descriptor.notary_keys)?;
        let mut proof = DestinationRejectionProof {
            rejection_id: self.next_id("destination-rejection")?,
            transit_id: capsule.transit_id,
            payment_id: capsule.payment_id,
            source_zone: capsule.source_zone,
            destination_zone: self.descriptor.zone_id.clone(),
            source_object_id: capsule.source_object_id,
            source_object_version: capsule.source_object_version,
            recipient: capsule.recipient,
            amount: capsule.amount,
            reason,
            destination_descriptor: self.descriptor.clone(),
            destination_height: self.height,
            destination_checkpoint: checkpoint.checkpoint_hash,
            validator_qc,
            notary_qc,
        };
        let subject = proof.subject_hash();
        proof.validator_qc.subject_hash.clone_from(&subject);
        proof.notary_qc.subject_hash = subject;
        if proof.validator_qc.testnet_simulated && proof.notary_qc.testnet_simulated {
            self.rejected_transit_nullifiers
                .insert(proof.transit_id.clone());
        }
        self.rejection_proofs
            .insert(proof.rejection_id.clone(), proof.clone());
        self.assert_conservation()?;
        Ok(proof)
    }

    pub fn certify_destination_rejection(
        &mut self,
        rejection_id: &str,
        validator_qc: QuorumCertificate,
        notary_qc: QuorumCertificate,
    ) -> Result<DestinationRejectionProof, LedgerError> {
        let mut proof = self
            .rejection_proofs
            .get(rejection_id)
            .cloned()
            .ok_or_else(|| LedgerError::Invalid("destination rejection not found".into()))?;
        if self.transit_nullifiers.contains(&proof.transit_id)
            || self.rejected_transit_nullifiers.contains(&proof.transit_id)
        {
            return Err(LedgerError::Invalid(
                "an imported or already rejected transit cannot be certified for rejection".into(),
            ));
        }
        let subject = proof.subject_hash();
        if validator_qc.subject_hash != subject || notary_qc.subject_hash != subject {
            return Err(LedgerError::InvalidQuorum("subject hash mismatch".into()));
        }
        validator_qc
            .verify(&self.descriptor.validator_keys)
            .map_err(LedgerError::InvalidQuorum)?;
        notary_qc
            .verify(&self.descriptor.notary_keys)
            .map_err(LedgerError::InvalidQuorum)?;
        proof.validator_qc = validator_qc;
        proof.notary_qc = notary_qc;
        self.ensure_counter_headroom(1, 0)?;
        self.advance()?;
        self.rejected_transit_nullifiers
            .insert(proof.transit_id.clone());
        self.rejection_proofs
            .insert(rejection_id.into(), proof.clone());
        Ok(proof)
    }

    pub fn begin_return_from_rejection(
        &mut self,
        proof: DestinationRejectionProof,
    ) -> Result<PaymentRecord, LedgerError> {
        if self.rejection_proofs.contains_key(&proof.rejection_id) {
            return Err(LedgerError::Duplicate(proof.rejection_id));
        }
        proof
            .destination_descriptor
            .validate_identity()
            .map_err(LedgerError::InvalidOperationalProof)?;
        let capsule = self
            .transits
            .get(&proof.transit_id)
            .cloned()
            .ok_or_else(|| LedgerError::TransitNotFound(proof.transit_id.clone()))?;
        if proof.transit_id != capsule.transit_id
            || proof.payment_id != capsule.payment_id
            || proof.source_zone != self.descriptor.zone_id
            || proof.destination_zone != capsule.destination_zone
            || proof.destination_descriptor.zone_id != capsule.destination_zone
            || proof.source_object_id != capsule.source_object_id
            || proof.source_object_version != capsule.source_object_version
            || proof.recipient != capsule.recipient
            || proof.amount != capsule.amount
            || proof.destination_checkpoint.trim().is_empty()
            || proof.destination_height == 0
        {
            return Err(LedgerError::Invalid(
                "destination rejection does not bind the open transit".into(),
            ));
        }
        let subject = proof.subject_hash();
        if proof.validator_qc.subject_hash != subject || proof.notary_qc.subject_hash != subject {
            return Err(LedgerError::InvalidQuorum("subject hash mismatch".into()));
        }
        let simulated = proof.validator_qc.testnet_simulated && proof.notary_qc.testnet_simulated;
        let simulation_allowed = self.descriptor.testnet
            && proof.destination_descriptor.testnet
            && proof.destination_descriptor.validator_keys.is_empty()
            && proof.destination_descriptor.notary_keys.is_empty();
        if simulated && !simulation_allowed {
            return Err(LedgerError::InvalidQuorum(
                "simulated rejection quorum is forbidden for a configured signer set".into(),
            ));
        }
        if !simulated {
            proof
                .validator_qc
                .verify(&proof.destination_descriptor.validator_keys)
                .map_err(LedgerError::InvalidQuorum)?;
            proof
                .notary_qc
                .verify(&proof.destination_descriptor.notary_keys)
                .map_err(LedgerError::InvalidQuorum)?;
        }
        let coin_id = self
            .transit_coin_ids
            .get(&proof.transit_id)
            .cloned()
            .ok_or_else(|| LedgerError::TransitNotFound(proof.transit_id.clone()))?;
        let coin = self
            .coins
            .get(&coin_id)
            .ok_or_else(|| LedgerError::CoinNotFound(coin_id.clone()))?;
        if coin.state != CoinState::InTransit {
            return Err(LedgerError::Invalid("transit is not returnable".into()));
        }
        let next_version = Self::checked_next_coin_version(coin.version)?;
        if !self.payments.contains_key(&proof.payment_id) {
            return Err(LedgerError::Invalid("payment record missing".into()));
        }
        self.ensure_counter_headroom(1, 0)?;

        self.advance()?;
        let coin = self.coins.get_mut(&coin_id).expect("coin was checked");
        coin.state = CoinState::Returning;
        coin.version = next_version;
        let record = self
            .payments
            .get_mut(&proof.payment_id)
            .expect("payment record was checked");
        record.status = PaymentStatus::Returning;
        record.updated_height = self.height;
        let result = record.clone();
        self.rejection_proofs
            .insert(proof.rejection_id.clone(), proof);
        self.assert_conservation()?;
        Ok(result)
    }

    pub fn finalize_return(&mut self, transit_id: &str) -> Result<PaymentRecord, LedgerError> {
        let capsule = self
            .transits
            .get(transit_id)
            .cloned()
            .ok_or_else(|| LedgerError::TransitNotFound(transit_id.into()))?;
        if !self
            .rejection_proofs
            .values()
            .any(|proof| proof.transit_id == transit_id)
        {
            return Err(LedgerError::Invalid(
                "return requires a verified destination rejection proof".into(),
            ));
        }
        let coin_id = self
            .transit_coin_ids
            .get(transit_id)
            .cloned()
            .ok_or_else(|| LedgerError::TransitNotFound(transit_id.into()))?;
        let coin = self
            .coins
            .get(&coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(coin_id.clone()))?;
        if coin.state != CoinState::Returning {
            return Err(LedgerError::Invalid(
                "transit has not entered RETURNING".into(),
            ));
        }
        let payment = self
            .payments
            .get(&capsule.payment_id)
            .cloned()
            .ok_or_else(|| LedgerError::Invalid("payment record missing".into()))?;
        let sender = format!(
            "rld:{}:{}",
            self.descriptor.zone_id, payment.intent.sender_public_key
        );
        let next_version = Self::checked_next_coin_version(coin.version)?;
        self.ensure_counter_headroom(1, 1)?;

        self.advance()?;
        self.consume_coin(&coin_id)?;
        let returned_coin = self.make_coin(
            sender,
            coin.amount,
            CoinState::Spendable,
            vec![coin.object_id],
            Some(coin.lineage_root),
            None,
            coin.imported_from,
            next_version,
        )?;
        self.coins
            .insert(returned_coin.object_id.clone(), returned_coin.clone());
        let record = self
            .payments
            .get_mut(&capsule.payment_id)
            .expect("payment was checked");
        record.status = PaymentStatus::Returned;
        record.output_coin_ids.push(returned_coin.object_id);
        record.updated_height = self.height;
        let result = record.clone();
        self.assert_conservation()?;
        Ok(result)
    }

    pub fn import_capsule(
        &mut self,
        capsule: TransitCapsule,
    ) -> Result<DestinationImportReceipt, LedgerError> {
        if capsule.destination_zone != self.descriptor.zone_id {
            return Err(LedgerError::Invalid("capsule destination mismatch".into()));
        }
        let settlement_certificate = self
            .spendability_certificates
            .get(&capsule.payment_id)
            .filter(|certificate| {
                certificate.settlement_claim_transit_id == capsule.transit_id
                    && certificate.recipient == capsule.recipient
                    && certificate.amount == capsule.amount
            })
            .cloned();
        let (next_cross_zone_exposure, next_dsc_exposure) =
            if !self.descriptor.testnet && settlement_certificate.is_some() {
                let cross = self
                    .value_risk_policy
                    .exposure
                    .cross_zone_exposure
                    .checked_add(capsule.amount)
                    .map_err(|error| LedgerError::ValueRisk(error.to_string()))?;
                let dsc = self
                    .value_risk_policy
                    .exposure
                    .dsc_exposure
                    .checked_sub(capsule.amount)
                    .map_err(|_| {
                        LedgerError::ValueRisk(
                            "settlement exceeds recorded destination-spendability exposure".into(),
                        )
                    })?;
                (Some(cross), Some(dsc))
            } else {
                (
                    self.next_value_risk_total(ValueRiskPath::CrossZone, capsule.amount)?,
                    None,
                )
            };
        if capsule.source_zone != capsule.source_descriptor.zone_id {
            return Err(LedgerError::Invalid("source descriptor mismatch".into()));
        }
        capsule
            .source_descriptor
            .validate_identity()
            .map_err(LedgerError::InvalidOperationalProof)?;
        if capsule.source_descriptor.network_domain != self.descriptor.network_domain
            || capsule.source_descriptor.testnet != self.descriptor.testnet
        {
            return Err(LedgerError::InvalidOperationalProof(
                "cross-network Zone identity is forbidden".into(),
            ));
        }
        if self.quarantined_zones.contains(&capsule.source_zone) {
            return Err(LedgerError::SourceZoneQuarantined(capsule.source_zone));
        }
        let trust_policy = self
            .zone_trust_policies
            .get(&capsule.source_zone)
            .cloned()
            .unwrap_or(ZoneTrustPolicy::DualQc);
        if matches!(
            trust_policy,
            ZoneTrustPolicy::ObserveOnly | ZoneTrustPolicy::Quarantined
        ) {
            return Err(LedgerError::SourceZoneQuarantined(capsule.source_zone));
        }
        if self.transit_nullifiers.contains(&capsule.transit_id) {
            return Err(LedgerError::TransitAlreadyImported);
        }
        if self
            .rejected_transit_nullifiers
            .contains(&capsule.transit_id)
        {
            return Err(LedgerError::Invalid(
                "transit was permanently rejected by this destination".into(),
            ));
        }
        if capsule.transport == TransportClass::ChronologyUnsafe {
            return Err(LedgerError::CausalQuarantine(
                "chronology-unsafe route".into(),
            ));
        }
        capsule
            .operational_proof
            .validate_bounds()
            .map_err(LedgerError::InvalidOperationalProof)?;
        if capsule.operational_proof.checkpoint_hash != capsule.source_checkpoint
            || capsule.operational_proof.protocol_era != capsule.source_descriptor.protocol_era
            || capsule.operational_proof.crypto_era != capsule.source_descriptor.crypto_era
        {
            return Err(LedgerError::InvalidOperationalProof(
                "checkpoint or era binding mismatch".into(),
            ));
        }
        if capsule.origin_genesis_root != self.descriptor.currency_genesis_root
            || capsule.source_descriptor.currency_genesis_root
                != self.descriptor.currency_genesis_root
            || capsule.source_object.origin_genesis_root != self.descriptor.currency_genesis_root
        {
            return Err(LedgerError::InvalidOperationalProof(
                "currency genesis root mismatch".into(),
            ));
        }
        match (&capsule.payment_request_id, &capsule.payment_request) {
            (None, None) => {}
            (Some(request_id), Some(request)) => {
                if request_id != &request.request_id
                    || request.destination_zone != self.descriptor.zone_id
                    || request.recipient != capsule.recipient
                    || request.amount != capsule.amount
                {
                    return Err(LedgerError::Invalid(
                        "capsule payment request binding mismatch".into(),
                    ));
                }
                request.verify().map_err(LedgerError::InvalidSignature)?;
                self.validate_payment_request_context(request)?;
                if request.expires_at_height <= self.height {
                    return Err(LedgerError::Invalid("payment request has expired".into()));
                }
                if self.consumed_payment_requests.contains(request_id) {
                    return Err(LedgerError::Duplicate(request_id.clone()));
                }
            }
            _ => {
                return Err(LedgerError::Invalid(
                    "capsule payment request id and signed request must be supplied together"
                        .into(),
                ));
            }
        }
        if capsule.source_object.object_id != capsule.source_object_id
            || capsule.source_object.version != capsule.source_object_version
            || capsule.source_object.zone_id != capsule.source_zone
            || capsule.source_object.amount != capsule.amount
            || capsule.source_object.owner != capsule.recipient
            || capsule.source_object.state != CoinState::InTransit
            || capsule.source_object.transit_id.as_deref() != Some(&capsule.transit_id)
            || capsule.source_object.lineage_root != capsule.lineage_root
        {
            return Err(LedgerError::InvalidOperationalProof(
                "source object binding mismatch".into(),
            ));
        }
        let source_object_hash = hash_bytes(
            &serde_json::to_vec(&capsule.source_object)
                .map_err(|error| LedgerError::Invalid(error.to_string()))?,
        );
        if source_object_hash != capsule.operational_proof.object_hash {
            return Err(LedgerError::InvalidOperationalProof(
                "source object hash mismatch".into(),
            ));
        }
        let supply_certificate_hash = hash_bytes(
            &serde_json::to_vec(&capsule.source_supply)
                .map_err(|error| LedgerError::Invalid(error.to_string()))?,
        );
        let recomputed_position = capsule
            .source_supply
            .buckets
            .conservation_position()
            .map_err(LedgerError::Supply)?;
        let recomputed_reserve_pool_total = capsule
            .source_supply
            .reserve_pools
            .total()
            .map_err(LedgerError::Supply)?;
        if !capsule.source_supply.valid
            || capsule.source_supply.zone_id != capsule.source_zone
            || recomputed_position != capsule.source_supply.conservation_position
            || recomputed_position != capsule.source_supply.anchor_supply
            || recomputed_reserve_pool_total != capsule.source_supply.buckets.reserve
            || supply_certificate_hash != capsule.operational_proof.supply_certificate_hash
        {
            return Err(LedgerError::InvalidOperationalProof(
                "source supply certificate mismatch".into(),
            ));
        }
        self.verify_era_certificate(&capsule)?;
        let source_spend_nullifier = capsule.source_spend_nullifier();
        if self
            .source_object_nullifiers
            .contains(&source_spend_nullifier)
        {
            self.quarantined_zones.insert(capsule.source_zone.clone());
            self.zone_trust_policies
                .insert(capsule.source_zone.clone(), ZoneTrustPolicy::Quarantined);
            return Err(LedgerError::SourceZoneQuarantined(capsule.source_zone));
        }
        let subject = capsule.subject_hash();
        self.verify_source_acceptance(&capsule, &subject, &trust_policy)?;
        let next_version = Self::checked_next_coin_version(capsule.source_object_version)?;
        self.ensure_counter_headroom(1, 1)?;

        let envelope = CausalEnvelope {
            envelope_id: capsule.transit_id.clone(),
            parent_ids: Vec::new(),
            object_id: capsule.source_object_id.clone(),
            object_version: capsule.source_object_version,
            source_checkpoint: capsule.source_checkpoint.clone(),
            transport: capsule.transport.clone(),
            payload_hash: subject,
        };
        match self.causal_firewall.submit(envelope) {
            CausalDecision::Accepted => {}
            CausalDecision::Quarantined(reason) => {
                return Err(LedgerError::CausalQuarantine(reason));
            }
            CausalDecision::PendingMissingParents(parents) => {
                return Err(LedgerError::Invalid(format!(
                    "missing causal parents: {}",
                    parents.join(",")
                )));
            }
            CausalDecision::Duplicate => return Err(LedgerError::TransitAlreadyImported),
        }

        let settlement_owner = settlement_certificate
            .as_ref()
            .map(|certificate| certificate.liquidity_provider.clone())
            .unwrap_or_else(|| capsule.recipient.clone());
        self.advance()?;
        let mut coin = self.make_coin(
            settlement_owner,
            capsule.amount,
            CoinState::Spendable,
            vec![capsule.source_object_id.clone()],
            Some(capsule.lineage_root.clone()),
            None,
            Some(capsule.source_zone.clone()),
            next_version,
        )?;
        coin.origin_zone
            .clone_from(&capsule.source_object.origin_zone);
        coin.origin_genesis_root
            .clone_from(&capsule.origin_genesis_root);
        self.imported_total = self.imported_total.checked_add(capsule.amount)?;
        self.transit_nullifiers.insert(capsule.transit_id.clone());
        self.source_object_nullifiers.insert(source_spend_nullifier);
        if let Some(request_id) = &capsule.payment_request_id {
            self.consumed_payment_requests.insert(request_id.clone());
        }
        self.coins.insert(coin.object_id.clone(), coin.clone());
        self.record_value_risk_total(ValueRiskPath::CrossZone, next_cross_zone_exposure);
        if let Some(next_dsc_exposure) = next_dsc_exposure {
            self.value_risk_policy.exposure.dsc_exposure = next_dsc_exposure;
        }
        let checkpoint = self.create_checkpoint()?;
        let receipt = DestinationImportReceipt {
            transit_id: capsule.transit_id.clone(),
            payment_id: capsule.payment_id.clone(),
            destination_zone: self.descriptor.zone_id.clone(),
            destination_coin_id: coin.object_id,
            recipient: capsule.recipient,
            amount: capsule.amount,
            destination_height: self.height,
            checkpoint_hash: checkpoint.checkpoint_hash,
        };
        self.import_receipts
            .insert(capsule.transit_id, receipt.clone());
        self.assert_conservation()?;
        Ok(receipt)
    }

    pub fn finalize_export(
        &mut self,
        receipt: &DestinationImportReceipt,
    ) -> Result<PaymentRecord, LedgerError> {
        let capsule = self
            .transits
            .get(&receipt.transit_id)
            .cloned()
            .ok_or_else(|| LedgerError::TransitNotFound(receipt.transit_id.clone()))?;
        if receipt.destination_zone != capsule.destination_zone
            || receipt.payment_id != capsule.payment_id
            || receipt.amount != capsule.amount
            || receipt.recipient != capsule.recipient
        {
            return Err(LedgerError::Invalid("destination receipt mismatch".into()));
        }
        let coin_id = self
            .transit_coin_ids
            .get(&receipt.transit_id)
            .cloned()
            .ok_or_else(|| LedgerError::TransitNotFound(receipt.transit_id.clone()))?;
        let coin = self
            .coins
            .get(&coin_id)
            .ok_or_else(|| LedgerError::CoinNotFound(coin_id.clone()))?;
        if coin.state != CoinState::InTransit {
            return Err(LedgerError::Invalid("transit is not open".into()));
        }
        let next_cross_zone_exposure = if self.descriptor.testnet {
            None
        } else {
            Some(
                self.value_risk_policy
                    .exposure
                    .cross_zone_exposure
                    .checked_sub(receipt.amount)
                    .map_err(|_| {
                        LedgerError::ValueRisk(
                            "finalization exceeds recorded cross-Zone exposure".into(),
                        )
                    })?,
            )
        };
        let payment_id = self
            .payments
            .iter()
            .find_map(|(id, record)| {
                (record.transit_id.as_deref() == Some(&receipt.transit_id)).then(|| id.clone())
            })
            .ok_or_else(|| LedgerError::Invalid("payment record missing".into()))?;
        self.ensure_counter_headroom(1, 0)?;

        self.advance()?;
        self.consume_coin(&coin_id)?;
        self.finalized_export_total = self.finalized_export_total.checked_add(receipt.amount)?;
        self.record_value_risk_total(ValueRiskPath::CrossZone, next_cross_zone_exposure);
        let record = self
            .payments
            .get_mut(&payment_id)
            .ok_or_else(|| LedgerError::Invalid("payment record missing".into()))?;
        record.status = PaymentStatus::UniversallySettled;
        record.updated_height = self.height;
        let result = record.clone();
        self.assert_conservation()?;
        Ok(result)
    }

    pub fn issue_spendability_certificate(
        &mut self,
        request: SpendabilityCertificateRequest,
    ) -> Result<DestinationSpendabilityCertificate, LedgerError> {
        let SpendabilityCertificateRequest {
            payment_id,
            provider_coin_id,
            liquidity_provider,
            recipient,
            amount,
            settlement_claim_transit_id,
            authorization,
        } = request;
        let payload_hash = action_payload_hash(
            "ISSUE_DSC",
            &[
                payment_id.as_bytes(),
                provider_coin_id.as_bytes(),
                liquidity_provider.as_bytes(),
                recipient.as_bytes(),
                &amount.0.to_be_bytes(),
                settlement_claim_transit_id.as_bytes(),
            ],
        );
        self.verify_owner_authorization(
            &authorization,
            &liquidity_provider,
            "ISSUE_DSC",
            &payload_hash,
        )?;
        let input = self
            .coins
            .get(&provider_coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(provider_coin_id.clone()))?;
        if input.state != CoinState::Spendable || input.owner != liquidity_provider {
            return Err(LedgerError::OwnerMismatch);
        }
        if amount.is_zero() || amount > input.amount {
            return Err(LedgerError::Invalid("invalid liquidity amount".into()));
        }
        if self.spendability_certificates.contains_key(&payment_id) {
            return Err(LedgerError::Duplicate(payment_id));
        }
        let next_dsc_exposure =
            self.next_value_risk_total(ValueRiskPath::DestinationSpendability, amount)?;
        let change = input.amount.checked_sub(amount)?;
        let next_version = Self::checked_next_coin_version(input.version)?;
        let sequence_steps = 1 + u64::from(!change.is_zero());
        self.ensure_counter_headroom(1, sequence_steps)?;
        self.consume_authorization(&authorization)?;
        self.advance()?;
        self.consume_coin(&input.object_id)?;
        let local_coin = self.make_coin(
            recipient.clone(),
            amount,
            CoinState::Spendable,
            vec![input.object_id.clone()],
            Some(input.lineage_root.clone()),
            None,
            input.imported_from.clone(),
            next_version,
        )?;
        self.coins
            .insert(local_coin.object_id.clone(), local_coin.clone());
        if !change.is_zero() {
            let change_coin = self.make_coin(
                liquidity_provider.clone(),
                change,
                CoinState::Spendable,
                vec![input.object_id],
                Some(input.lineage_root),
                None,
                input.imported_from,
                next_version,
            )?;
            self.coins
                .insert(change_coin.object_id.clone(), change_coin);
        }
        let certificate = DestinationSpendabilityCertificate {
            payment_id: payment_id.clone(),
            destination_zone: self.descriptor.zone_id.clone(),
            recipient,
            local_coin_id: local_coin.object_id,
            liquidity_provider,
            amount,
            settlement_claim_transit_id,
            destination_height: self.height,
        };
        self.spendability_certificates
            .insert(payment_id, certificate.clone());
        self.record_value_risk_total(ValueRiskPath::DestinationSpendability, next_dsc_exposure);
        self.assert_conservation()?;
        Ok(certificate)
    }

    pub fn create_liquidity_offer(
        &mut self,
        request: CreateLiquidityOfferRequest,
    ) -> Result<LiquidityOffer, LedgerError> {
        let CreateLiquidityOfferRequest {
            provider,
            coin_id,
            amount,
            minimum,
            maximum,
            expires_at_height,
            authorization,
        } = request;
        if amount.is_zero()
            || minimum.is_zero()
            || minimum > maximum
            || maximum > amount
            || expires_at_height <= self.height
        {
            return Err(LedgerError::Invalid(
                "invalid liquidity offer bounds or expiry".into(),
            ));
        }
        let payload_hash = action_payload_hash(
            "CREATE_LIQUIDITY_OFFER",
            &[
                provider.as_bytes(),
                coin_id.as_bytes(),
                &amount.0.to_be_bytes(),
                &minimum.0.to_be_bytes(),
                &maximum.0.to_be_bytes(),
                &expires_at_height.to_be_bytes(),
            ],
        );
        self.verify_owner_authorization(
            &authorization,
            &provider,
            "CREATE_LIQUIDITY_OFFER",
            &payload_hash,
        )?;
        let input = self
            .coins
            .get(&coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(coin_id.clone()))?;
        if input.state != CoinState::Spendable || input.owner != provider {
            return Err(LedgerError::OwnerMismatch);
        }
        if amount > input.amount {
            return Err(LedgerError::Invalid(
                "liquidity offer exceeds the selected coin".into(),
            ));
        }
        let next_dsc_exposure =
            self.next_value_risk_total(ValueRiskPath::DestinationSpendability, amount)?;
        let change = input.amount.checked_sub(amount)?;
        let next_version = Self::checked_next_coin_version(input.version)?;
        let sequence_steps = 2 + u64::from(!change.is_zero());
        self.ensure_counter_headroom(1, sequence_steps)?;

        self.consume_authorization(&authorization)?;
        self.advance()?;
        self.consume_coin(&input.object_id)?;
        let reserved = self.make_coin(
            provider.clone(),
            amount,
            CoinState::Reserved,
            vec![input.object_id.clone()],
            Some(input.lineage_root.clone()),
            None,
            input.imported_from.clone(),
            next_version,
        )?;
        self.coins
            .insert(reserved.object_id.clone(), reserved.clone());
        if !change.is_zero() {
            let change_coin = self.make_coin(
                provider.clone(),
                change,
                CoinState::Spendable,
                vec![input.object_id],
                Some(input.lineage_root),
                None,
                input.imported_from,
                next_version,
            )?;
            self.coins
                .insert(change_coin.object_id.clone(), change_coin);
        }
        let offer = LiquidityOffer {
            offer_id: self.next_id("liquidity-offer")?,
            provider,
            destination_zone: self.descriptor.zone_id.clone(),
            reserved_coin_id: Some(reserved.object_id),
            available: amount,
            minimum,
            maximum,
            expires_at_height,
            status: LiquidityOfferStatus::Open,
            created_height: self.height,
        };
        self.liquidity_offers
            .insert(offer.offer_id.clone(), offer.clone());
        self.record_value_risk_commitment(
            ValueRiskPath::DestinationSpendability,
            offer.offer_id.clone(),
            amount,
            next_dsc_exposure,
        );
        self.assert_conservation()?;
        Ok(offer)
    }

    pub fn take_liquidity_offer(
        &mut self,
        request: TakeLiquidityOfferRequest,
    ) -> Result<DestinationSpendabilityCertificate, LedgerError> {
        let offer = self
            .liquidity_offers
            .get(&request.offer_id)
            .cloned()
            .ok_or_else(|| LedgerError::LiquidityOfferNotFound(request.offer_id.clone()))?;
        if offer.status != LiquidityOfferStatus::Open
            || offer.expires_at_height <= self.height
            || request.settlement_claim.destination_zone != self.descriptor.zone_id
            || request.settlement_claim.amount < offer.minimum
            || request.settlement_claim.amount > offer.maximum
            || request.settlement_claim.amount > offer.available
        {
            return Err(LedgerError::Invalid(
                "liquidity offer is unavailable for this settlement claim".into(),
            ));
        }
        if self
            .spendability_certificates
            .contains_key(&request.settlement_claim.payment_id)
        {
            return Err(LedgerError::Duplicate(request.settlement_claim.payment_id));
        }
        self.require_dsc_value_commitment(&request.offer_id, request.settlement_claim.amount)?;
        let mut verifier = self.clone();
        verifier.spendability_certificates.insert(
            request.settlement_claim.payment_id.clone(),
            DestinationSpendabilityCertificate {
                payment_id: request.settlement_claim.payment_id.clone(),
                destination_zone: self.descriptor.zone_id.clone(),
                recipient: request.settlement_claim.recipient.clone(),
                local_coin_id: "precommitted-liquidity-validation".into(),
                liquidity_provider: offer.provider.clone(),
                amount: request.settlement_claim.amount,
                settlement_claim_transit_id: request.settlement_claim.transit_id.clone(),
                destination_height: self.height,
            },
        );
        verifier.import_capsule(request.settlement_claim.clone())?;

        let reserved_coin_id = offer
            .reserved_coin_id
            .clone()
            .ok_or_else(|| LedgerError::Invalid("liquidity reserve is empty".into()))?;
        let input = self
            .coins
            .get(&reserved_coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(reserved_coin_id.clone()))?;
        if input.state != CoinState::Reserved
            || input.owner != offer.provider
            || input.amount != offer.available
        {
            return Err(LedgerError::Invalid(
                "liquidity reserve does not match its offer".into(),
            ));
        }

        let amount = request.settlement_claim.amount;
        let remaining = input.amount.checked_sub(amount)?;
        let next_version = Self::checked_next_coin_version(input.version)?;
        let sequence_steps = 1 + u64::from(!remaining.is_zero());
        self.ensure_counter_headroom(1, sequence_steps)?;
        self.advance()?;
        self.consume_coin(&input.object_id)?;
        let local_coin = self.make_coin(
            request.settlement_claim.recipient.clone(),
            amount,
            CoinState::Spendable,
            vec![input.object_id.clone()],
            Some(input.lineage_root.clone()),
            None,
            input.imported_from.clone(),
            next_version,
        )?;
        self.coins
            .insert(local_coin.object_id.clone(), local_coin.clone());
        let next_reserved_coin_id = if remaining.is_zero() {
            None
        } else {
            let next = self.make_coin(
                offer.provider.clone(),
                remaining,
                CoinState::Reserved,
                vec![input.object_id],
                Some(input.lineage_root),
                None,
                input.imported_from,
                next_version,
            )?;
            let next_id = next.object_id.clone();
            self.coins.insert(next_id.clone(), next);
            Some(next_id)
        };
        let certificate = DestinationSpendabilityCertificate {
            payment_id: request.settlement_claim.payment_id.clone(),
            destination_zone: self.descriptor.zone_id.clone(),
            recipient: request.settlement_claim.recipient.clone(),
            local_coin_id: local_coin.object_id,
            liquidity_provider: offer.provider.clone(),
            amount,
            settlement_claim_transit_id: request.settlement_claim.transit_id.clone(),
            destination_height: self.height,
        };
        self.spendability_certificates
            .insert(request.settlement_claim.payment_id, certificate.clone());
        let offer = self
            .liquidity_offers
            .get_mut(&request.offer_id)
            .expect("offer was checked");
        offer.available = remaining;
        offer.reserved_coin_id = next_reserved_coin_id;
        if remaining.is_zero() || remaining < offer.minimum {
            offer.status = LiquidityOfferStatus::Depleted;
        }
        self.assert_conservation()?;
        Ok(certificate)
    }

    pub fn available_protocol_reserve(
        &self,
        pool: &ProtocolReservePoolKind,
    ) -> Result<Amount, LedgerError> {
        let balance = match pool {
            ProtocolReservePoolKind::StartupServices => self.reserve_pools.startup_services,
            ProtocolReservePoolKind::ContinuityServices => self.reserve_pools.continuity_services,
            ProtocolReservePoolKind::DemandMatching => self.reserve_pools.demand_matching,
        };
        let committed = self
            .protocol_reserve_commitments
            .values()
            .filter(|commitment| {
                commitment.reserve_pool == *pool && commitment.settled_amount.is_none()
            })
            .try_fold(Amount::ZERO, |total, commitment| {
                total.checked_add(commitment.committed_amount)
            })?;
        balance.checked_sub(committed).map_err(|_| {
            LedgerError::Supply(format!(
                "active {} commitments exceed their reserve pool",
                pool.wire_name()
            ))
        })
    }

    /// Submits a consensus-domain real-value policy update.
    ///
    /// Risk increases are only staged and must survive a signed challenge
    /// delay. Risk reductions apply immediately, preserve all existing assets
    /// and exposure counters, and only stop subsequent risk creation.
    pub fn submit_value_risk_policy_update(
        &mut self,
        update: ValueRiskPolicyUpdate,
    ) -> Result<ValueRiskPolicy, LedgerError> {
        self.verify_value_risk_policy_update(&update, true)?;
        if update.from_cap != self.value_risk_policy.current_cap
            || update.previous_policy_sequence != self.value_risk_policy.policy_sequence
        {
            return Err(LedgerError::ValueRisk(
                "policy update does not extend the active policy".into(),
            ));
        }
        update
            .limits
            .validate_for_cap(update.to_cap)
            .map_err(LedgerError::ValueRisk)?;
        let next_policy_sequence = self
            .value_risk_policy
            .policy_sequence
            .checked_add(1)
            .ok_or_else(|| LedgerError::ValueRisk("policy sequence overflow".into()))?;

        let increases_risk = self.value_risk_update_increases_risk(&update);
        if increases_risk {
            self.ensure_admission_may_raise_value_cap()?;
            let earliest = self
                .height
                .checked_add(MIN_VALUE_CAP_UPGRADE_DELAY_BLOCKS)
                .ok_or_else(|| LedgerError::ValueRisk("activation height overflow".into()))?;
            if update.activate_after_height < earliest {
                return Err(LedgerError::ValueRisk(format!(
                    "risk increase requires at least {MIN_VALUE_CAP_UPGRADE_DELAY_BLOCKS} blocks of notice"
                )));
            }
            if self
                .value_risk_policy
                .pending_update
                .as_ref()
                .is_some_and(|pending| pending.expires_at_height > self.height)
            {
                return Err(LedgerError::ValueRisk(
                    "an unexpired risk increase is already pending".into(),
                ));
            }
            self.ensure_counter_headroom(1, 0)?;
            self.advance()?;
            self.value_risk_policy.pending_update = Some(update);
            return Ok(self.value_risk_policy.clone());
        }

        self.ensure_counter_headroom(1, 0)?;
        self.advance()?;
        self.apply_value_risk_policy(update, next_policy_sequence);
        Ok(self.value_risk_policy.clone())
    }

    pub fn activate_pending_value_risk_policy(&mut self) -> Result<ValueRiskPolicy, LedgerError> {
        let update = self
            .value_risk_policy
            .pending_update
            .clone()
            .ok_or_else(|| LedgerError::ValueRisk("no policy update is pending".into()))?;
        if self.height < update.activate_after_height {
            return Err(LedgerError::ValueRisk(
                "policy challenge delay has not elapsed".into(),
            ));
        }
        if self.height >= update.expires_at_height {
            return Err(LedgerError::ValueRisk(
                "pending policy update expired".into(),
            ));
        }
        if update.from_cap != self.value_risk_policy.current_cap
            || update.previous_policy_sequence != self.value_risk_policy.policy_sequence
        {
            return Err(LedgerError::ValueRisk(
                "pending policy no longer extends the active policy".into(),
            ));
        }
        self.verify_value_risk_policy_update(&update, false)?;
        update
            .limits
            .validate_for_cap(update.to_cap)
            .map_err(LedgerError::ValueRisk)?;
        let next_policy_sequence = self
            .value_risk_policy
            .policy_sequence
            .checked_add(1)
            .ok_or_else(|| LedgerError::ValueRisk("policy sequence overflow".into()))?;

        if self.value_risk_update_increases_risk(&update) {
            self.ensure_admission_may_raise_value_cap()?;
        }

        self.ensure_counter_headroom(1, 0)?;
        self.advance()?;
        self.apply_value_risk_policy(update, next_policy_sequence);
        Ok(self.value_risk_policy.clone())
    }

    fn value_risk_update_increases_risk(&self, update: &ValueRiskPolicyUpdate) -> bool {
        update.to_cap > self.value_risk_policy.current_cap
            || update
                .limits
                .increases_any_limit_over(&self.value_risk_policy.limits)
            || (update.to_cap != ValueCap::ValueCap0
                && update.safety_case_valid_until_height
                    > self.value_risk_policy.safety_case_valid_until_height)
            || (update.to_cap != ValueCap::ValueCap0
                && update.safety_case_hash != self.value_risk_policy.safety_case_hash)
    }

    fn verify_value_risk_policy_update(
        &self,
        update: &ValueRiskPolicyUpdate,
        require_current_proposal_height: bool,
    ) -> Result<(), LedgerError> {
        if update.update_id.trim().is_empty() {
            return Err(LedgerError::ValueRisk(
                "policy update id is required".into(),
            ));
        }
        if update.zone_id != self.descriptor.zone_id
            || update.currency_genesis_root != self.descriptor.currency_genesis_root
            || update.protocol_era != self.descriptor.protocol_era
            || update.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::ValueRisk(
                "policy update Zone, currency or era binding mismatch".into(),
            ));
        }
        if update.policy_version != CURRENT_VALUE_RISK_POLICY_VERSION
            || self.value_risk_policy.version != CURRENT_VALUE_RISK_POLICY_VERSION
        {
            return Err(LedgerError::ValueRisk(
                "unsupported real-value policy version".into(),
            ));
        }
        if require_current_proposal_height && update.proposed_height != self.height {
            return Err(LedgerError::ValueRisk(
                "policy proposal height does not match current state".into(),
            ));
        }
        if update.expires_at_height <= update.activate_after_height
            || update.expires_at_height <= self.height
        {
            return Err(LedgerError::ValueRisk(
                "policy activation window is empty or expired".into(),
            ));
        }
        if update.to_cap == ValueCap::ValueCap0 {
            if !update.safety_case_hash.is_empty() || update.safety_case_valid_until_height != 0 {
                return Err(LedgerError::ValueRisk(
                    "VALUE_CAP_0 must use an empty safety-case commitment and zero validity".into(),
                ));
            }
        } else {
            if !is_canonical_sha256_hex(&update.safety_case_hash) {
                return Err(LedgerError::ValueRisk(
                    "safety-case commitment must be a 64-character lowercase SHA-256 hex digest"
                        .into(),
                ));
            }
            let activation_height = update
                .activate_after_height
                .checked_add(1)
                .ok_or_else(|| LedgerError::ValueRisk("activation height overflow".into()))?;
            let resulting_height = self
                .height
                .checked_add(1)
                .ok_or_else(|| LedgerError::ValueRisk("activation height overflow".into()))?;
            if update.safety_case_valid_until_height <= activation_height
                || update.safety_case_valid_until_height <= resulting_height
            {
                return Err(LedgerError::ValueRisk(
                    "safety-case evidence expires before policy activation".into(),
                ));
            }
        }
        let subject = update.compute_subject_hash();
        if update.subject_hash != subject {
            return Err(LedgerError::ValueRisk(
                "policy update subject commitment mismatch".into(),
            ));
        }
        self.verify_local_dual_quorum(&subject, &update.validator_qc, &update.notary_qc)
    }

    fn apply_value_risk_policy(&mut self, update: ValueRiskPolicyUpdate, next_sequence: u64) {
        self.value_risk_policy.policy_sequence = next_sequence;
        self.value_risk_policy.current_cap = update.to_cap;
        self.value_risk_policy.ever_enabled |= update.to_cap != ValueCap::ValueCap0;
        self.value_risk_policy.limits = update.limits;
        self.value_risk_policy.safety_case_hash = update.safety_case_hash;
        self.value_risk_policy.safety_case_valid_until_height =
            update.safety_case_valid_until_height;
        self.value_risk_policy.activated_height = self.height;
        self.value_risk_policy.pending_update = None;
    }

    fn next_value_risk_total(
        &self,
        path: ValueRiskPath,
        amount: Amount,
    ) -> Result<Option<Amount>, LedgerError> {
        if self.descriptor.testnet {
            return Ok(None);
        }
        let policy = &self.value_risk_policy;
        if policy.version != CURRENT_VALUE_RISK_POLICY_VERSION {
            return Err(LedgerError::ValueRisk(
                "unknown policy version fails closed outside testnet".into(),
            ));
        }
        policy
            .limits
            .validate_for_cap(policy.current_cap)
            .map_err(LedgerError::ValueRisk)?;
        if policy.current_cap == ValueCap::ValueCap0 {
            return Err(LedgerError::ValueRisk(
                "VALUE_CAP_0 blocks all spendable real-value transitions".into(),
            ));
        }
        let resulting_height = self
            .height
            .checked_add(1)
            .ok_or_else(|| LedgerError::ValueRisk("transition height overflow".into()))?;
        if !is_canonical_sha256_hex(&policy.safety_case_hash)
            || resulting_height >= policy.safety_case_valid_until_height
        {
            return Err(LedgerError::ValueRisk(
                "active safety-case evidence is missing, malformed or expired".into(),
            ));
        }
        let (current, limit, label) = match path {
            ValueRiskPath::LocalPayment => (
                policy.exposure.local_value_total,
                policy.limits.max_local_value_total,
                "same-Zone value total",
            ),
            ValueRiskPath::CrossZone => (
                policy.exposure.cross_zone_exposure,
                policy.limits.max_cross_zone_exposure,
                "cross-Zone exposure",
            ),
            ValueRiskPath::DestinationSpendability => (
                policy.exposure.dsc_exposure,
                policy.limits.max_dsc_exposure,
                "destination-spendability exposure",
            ),
        };
        if limit.is_zero() {
            return Err(LedgerError::ValueRisk(format!(
                "the active policy disables the {label} path"
            )));
        }
        if amount.is_zero() || amount > policy.limits.max_single_transfer {
            return Err(LedgerError::ValueRisk(
                "transfer exceeds the active per-transaction value limit".into(),
            ));
        }
        let next = current
            .checked_add(amount)
            .map_err(|error| LedgerError::ValueRisk(error.to_string()))?;
        if next > limit {
            return Err(LedgerError::ValueRisk(format!(
                "transfer would exceed the active {label} limit"
            )));
        }
        Ok(Some(next))
    }

    fn record_value_risk_total(&mut self, path: ValueRiskPath, next: Option<Amount>) {
        let Some(next) = next else {
            return;
        };
        match path {
            ValueRiskPath::LocalPayment => {
                self.value_risk_policy.exposure.local_value_total = next;
            }
            ValueRiskPath::CrossZone => {
                self.value_risk_policy.exposure.cross_zone_exposure = next;
            }
            ValueRiskPath::DestinationSpendability => {
                self.value_risk_policy.exposure.dsc_exposure = next;
            }
        }
    }

    fn record_value_risk_commitment(
        &mut self,
        path: ValueRiskPath,
        commitment_id: String,
        amount: Amount,
        next: Option<Amount>,
    ) {
        if next.is_none() {
            return;
        }
        self.record_value_risk_total(path, next);
        match path {
            ValueRiskPath::LocalPayment => {
                self.value_risk_policy
                    .exposure
                    .local_commitment_amounts
                    .insert(commitment_id, amount);
            }
            ValueRiskPath::DestinationSpendability => {
                self.value_risk_policy
                    .exposure
                    .dsc_commitment_amounts
                    .insert(commitment_id, amount);
            }
            ValueRiskPath::CrossZone => {}
        }
    }

    fn require_local_value_commitment(
        &self,
        commitment_id: &str,
        amount: Amount,
    ) -> Result<(), LedgerError> {
        if self.descriptor.testnet {
            return Ok(());
        }
        if self
            .value_risk_policy
            .exposure
            .local_commitment_amounts
            .get(commitment_id)
            != Some(&amount)
        {
            return Err(LedgerError::ValueRisk(
                "closeout has no matching prepaid local-value commitment".into(),
            ));
        }
        Ok(())
    }

    fn require_dsc_value_commitment(
        &self,
        commitment_id: &str,
        amount: Amount,
    ) -> Result<(), LedgerError> {
        if self.descriptor.testnet {
            return Ok(());
        }
        if self
            .value_risk_policy
            .exposure
            .dsc_commitment_amounts
            .get(commitment_id)
            .is_none_or(|reserved| *reserved < amount)
        {
            return Err(LedgerError::ValueRisk(
                "closeout has no matching prepaid DSC commitment".into(),
            ));
        }
        Ok(())
    }

    fn validate_protocol_service_match(
        &self,
        request: &ProtocolServiceOrderRequest,
    ) -> Result<(), LedgerError> {
        let receipt_id = request.matched_service_receipt_id.as_ref().ok_or_else(|| {
            LedgerError::Invalid(
                "non-startup reserve work requires a real user-funded service receipt".into(),
            )
        })?;
        if self.matched_service_receipts.contains(receipt_id) {
            return Err(LedgerError::Duplicate(receipt_id.clone()));
        }
        let receipt = self
            .service_receipts
            .get(receipt_id)
            .ok_or_else(|| LedgerError::Invalid("matched service receipt was not found".into()))?;
        if receipt.bootstrap
            || receipt.protocol_reserve_pool.is_some()
            || receipt.role != request.role
            || request.budget > receipt.amount
        {
            return Err(LedgerError::Invalid(
                "reserve match must not exceed one genuine user-funded service receipt".into(),
            ));
        }
        let source_order = self
            .service_orders
            .get(&receipt.order_id)
            .ok_or_else(|| LedgerError::ServiceOrderNotFound(receipt.order_id.clone()))?;
        if source_order.buyer.rsplit(':').next() == Some(receipt.node_id.as_str()) {
            return Err(LedgerError::Invalid(
                "self-funded service traffic cannot receive a reserve match".into(),
            ));
        }
        Ok(())
    }

    pub fn create_protocol_service_order(
        &mut self,
        request: ProtocolServiceOrderRequest,
    ) -> Result<ServiceOrder, LedgerError> {
        if request.request_id.trim().is_empty()
            || request.description.trim().is_empty()
            || request.budget.is_zero()
        {
            return Err(LedgerError::Invalid(
                "protocol service order request is incomplete".into(),
            ));
        }
        if self.service_orders.contains_key(&request.request_id) {
            return Err(LedgerError::Duplicate(request.request_id));
        }
        if request.zone_id != self.descriptor.zone_id
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "protocol service order Zone or era mismatch".into(),
            ));
        }
        let subject = request.compute_subject_hash();
        if request.subject_hash != subject
            || request.validator_qc.subject_hash != subject
            || request.notary_qc.subject_hash != subject
        {
            return Err(LedgerError::InvalidQuorum(
                "protocol service order subject mismatch".into(),
            ));
        }
        self.verify_local_dual_quorum(&subject, &request.validator_qc, &request.notary_qc)?;

        match &request.reserve_pool {
            ProtocolReservePoolKind::StartupServices => {
                if request.matched_service_receipt_id.is_some() {
                    return Err(LedgerError::Invalid(
                        "startup service orders cannot claim a demand match".into(),
                    ));
                }
            }
            ProtocolReservePoolKind::ContinuityServices => {
                if !matches!(
                    &request.role,
                    ServiceRole::Storage | ServiceRole::Archive | ServiceRole::ContinuityCustodian
                ) {
                    return Err(LedgerError::Invalid(
                        "continuity pool is restricted to storage, archive and continuity custody"
                            .into(),
                    ));
                }
                self.validate_protocol_service_match(&request)?;
            }
            ProtocolReservePoolKind::DemandMatching => {
                self.validate_protocol_service_match(&request)?;
            }
        }

        if request.budget > self.available_protocol_reserve(&request.reserve_pool)? {
            return Err(LedgerError::Supply(format!(
                "{} reserve pool has insufficient uncommitted funds",
                request.reserve_pool.wire_name()
            )));
        }
        let next_value_total =
            self.next_value_risk_total(ValueRiskPath::LocalPayment, request.budget)?;

        self.ensure_counter_headroom(1, 0)?;
        self.advance()?;
        let order_id = request.request_id.clone();
        let order = ServiceOrder {
            order_id: order_id.clone(),
            buyer: format!("rld:protocol:{}", request.reserve_pool.wire_name()),
            role: request.role,
            budget: request.budget,
            escrow_coin_id: format!(
                "protocol-reserve:{}:{}",
                request.reserve_pool.wire_name(),
                order_id
            ),
            description: request.description,
            status: ServiceStatus::Open,
            created_height: self.height,
        };
        let commitment = ProtocolReserveCommitment {
            order_id: order_id.clone(),
            reserve_pool: request.reserve_pool,
            committed_amount: request.budget,
            matched_service_receipt_id: request.matched_service_receipt_id.clone(),
            authorization_subject_hash: subject,
            validator_qc: request.validator_qc,
            notary_qc: request.notary_qc,
            settled_amount: None,
        };
        if let Some(receipt_id) = request.matched_service_receipt_id {
            self.matched_service_receipts.insert(receipt_id);
        }
        self.service_orders.insert(order_id.clone(), order.clone());
        self.protocol_reserve_commitments
            .insert(order_id, commitment);
        self.record_value_risk_commitment(
            ValueRiskPath::LocalPayment,
            order.order_id.clone(),
            order.budget,
            next_value_total,
        );
        self.assert_conservation()?;
        Ok(order)
    }

    pub fn create_service_order(
        &mut self,
        buyer: String,
        coin_id: String,
        role: ServiceRole,
        budget: Amount,
        description: String,
        authorization: SignedActionAuthorization,
    ) -> Result<ServiceOrder, LedgerError> {
        let role_name = format!("{role:?}").to_uppercase();
        let payload_hash = action_payload_hash(
            "CREATE_SERVICE_ORDER",
            &[
                buyer.as_bytes(),
                coin_id.as_bytes(),
                role_name.as_bytes(),
                &budget.0.to_be_bytes(),
                description.as_bytes(),
            ],
        );
        self.verify_owner_authorization(
            &authorization,
            &buyer,
            "CREATE_SERVICE_ORDER",
            &payload_hash,
        )?;
        let input = self
            .coins
            .get(&coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(coin_id.clone()))?;
        if input.state != CoinState::Spendable || input.owner != buyer {
            return Err(LedgerError::OwnerMismatch);
        }
        if budget.is_zero() || budget > input.amount {
            return Err(LedgerError::Invalid("invalid service budget".into()));
        }
        let next_value_total = self.next_value_risk_total(ValueRiskPath::LocalPayment, budget)?;
        let change = input.amount.checked_sub(budget)?;
        let next_version = Self::checked_next_coin_version(input.version)?;
        let sequence_steps = 2 + u64::from(!change.is_zero());
        self.ensure_counter_headroom(1, sequence_steps)?;
        self.consume_authorization(&authorization)?;
        self.advance()?;
        self.consume_coin(&coin_id)?;
        let escrow = self.make_coin(
            buyer.clone(),
            budget,
            CoinState::Reserved,
            vec![input.object_id.clone()],
            Some(input.lineage_root.clone()),
            None,
            input.imported_from.clone(),
            next_version,
        )?;
        self.coins.insert(escrow.object_id.clone(), escrow.clone());
        if !change.is_zero() {
            let change_coin = self.make_coin(
                buyer.clone(),
                change,
                CoinState::Spendable,
                vec![input.object_id],
                Some(input.lineage_root),
                None,
                input.imported_from,
                next_version,
            )?;
            self.coins
                .insert(change_coin.object_id.clone(), change_coin);
        }
        let order = ServiceOrder {
            order_id: self.next_id("service-order")?,
            buyer,
            role,
            budget,
            escrow_coin_id: escrow.object_id,
            description,
            status: ServiceStatus::Open,
            created_height: self.height,
        };
        self.service_orders
            .insert(order.order_id.clone(), order.clone());
        self.record_value_risk_commitment(
            ValueRiskPath::LocalPayment,
            order.order_id.clone(),
            order.budget,
            next_value_total,
        );
        self.assert_conservation()?;
        Ok(order)
    }

    pub fn lease_service(
        &mut self,
        order_id: &str,
        node_id: String,
        accepted_quote: Amount,
        authorization: SignedActionAuthorization,
    ) -> Result<ServiceLease, LedgerError> {
        let payload_hash = action_payload_hash(
            "LEASE_SERVICE",
            &[
                order_id.as_bytes(),
                node_id.as_bytes(),
                &accepted_quote.0.to_be_bytes(),
            ],
        );
        self.verify_node_authorization(&authorization, &node_id, "LEASE_SERVICE", &payload_hash)?;
        let order = self
            .service_orders
            .get(order_id)
            .cloned()
            .ok_or_else(|| LedgerError::ServiceOrderNotFound(order_id.into()))?;
        if order.status != ServiceStatus::Open
            || accepted_quote.is_zero()
            || accepted_quote > order.budget
        {
            return Err(LedgerError::ServiceState);
        }
        if let Some(receipt_id) = self
            .protocol_reserve_commitments
            .get(order_id)
            .and_then(|commitment| commitment.matched_service_receipt_id.as_ref())
        {
            let matched = self.service_receipts.get(receipt_id).ok_or_else(|| {
                LedgerError::Invalid("matched service receipt was not found".into())
            })?;
            if matched.node_id != node_id {
                return Err(LedgerError::Invalid(
                    "demand-matched work must be leased to the original service node".into(),
                ));
            }
        }
        self.ensure_counter_headroom(1, 1)?;
        self.consume_authorization(&authorization)?;
        self.advance()?;
        let lease = ServiceLease {
            lease_id: self.next_id("service-lease")?,
            order_id: order_id.into(),
            node_id,
            accepted_quote,
            accepted_height: self.height,
        };
        self.service_leases
            .insert(lease.lease_id.clone(), lease.clone());
        self.service_orders
            .get_mut(order_id)
            .expect("order was checked")
            .status = ServiceStatus::Leased;
        Ok(lease)
    }

    pub fn complete_service(
        &mut self,
        lease_id: &str,
        proof_hash: String,
        authorization: SignedActionAuthorization,
    ) -> Result<ServiceReceipt, LedgerError> {
        if proof_hash.trim().is_empty() {
            return Err(LedgerError::Invalid("work proof is required".into()));
        }
        let lease = self
            .service_leases
            .get(lease_id)
            .cloned()
            .ok_or_else(|| LedgerError::ServiceLeaseNotFound(lease_id.into()))?;
        let payload_hash = action_payload_hash(
            "COMPLETE_SERVICE",
            &[
                lease_id.as_bytes(),
                lease.node_id.as_bytes(),
                proof_hash.as_bytes(),
            ],
        );
        self.verify_node_authorization(
            &authorization,
            &lease.node_id,
            "COMPLETE_SERVICE",
            &payload_hash,
        )?;
        let order = self
            .service_orders
            .get(&lease.order_id)
            .cloned()
            .ok_or_else(|| LedgerError::ServiceOrderNotFound(lease.order_id.clone()))?;
        if self
            .protocol_reserve_commitments
            .get(&order.order_id)
            .is_some_and(|commitment| commitment.settled_amount.is_none())
        {
            return Err(LedgerError::Invalid(
                "protocol-funded work requires dual-QC completion".into(),
            ));
        }
        if order.status != ServiceStatus::Leased {
            return Err(LedgerError::ServiceState);
        }
        let escrow = self
            .coins
            .get(&order.escrow_coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(order.escrow_coin_id.clone()))?;
        if escrow.state != CoinState::Reserved {
            return Err(LedgerError::ServiceState);
        }
        self.require_local_value_commitment(&order.order_id, order.budget)?;
        let refund = order.budget.checked_sub(lease.accepted_quote)?;
        let next_version = Self::checked_next_coin_version(escrow.version)?;
        let sequence_steps = 2 + u64::from(!refund.is_zero());
        self.ensure_counter_headroom(1, sequence_steps)?;

        self.consume_authorization(&authorization)?;
        self.advance()?;
        self.consume_coin(&escrow.object_id)?;
        let reward = self.make_coin(
            lease.node_id.clone(),
            lease.accepted_quote,
            CoinState::Spendable,
            vec![escrow.object_id.clone()],
            Some(escrow.lineage_root.clone()),
            None,
            escrow.imported_from.clone(),
            next_version,
        )?;
        self.coins.insert(reward.object_id.clone(), reward);
        if !refund.is_zero() {
            let refund_coin = self.make_coin(
                order.buyer.clone(),
                refund,
                CoinState::Spendable,
                vec![escrow.object_id],
                Some(escrow.lineage_root),
                None,
                escrow.imported_from,
                next_version,
            )?;
            self.coins
                .insert(refund_coin.object_id.clone(), refund_coin);
        }
        let receipt = ServiceReceipt {
            receipt_id: self.next_id("service-receipt")?,
            order_id: order.order_id.clone(),
            lease_id: lease.lease_id,
            node_id: lease.node_id.clone(),
            role: order.role.clone(),
            amount: lease.accepted_quote,
            proof_hash,
            completed_height: self.height,
            bootstrap: false,
            protocol_reserve_pool: None,
        };
        self.service_receipts
            .insert(receipt.receipt_id.clone(), receipt.clone());
        self.service_orders
            .get_mut(&order.order_id)
            .expect("order was checked")
            .status = ServiceStatus::Completed;
        self.record_earnings(
            &lease.node_id,
            &order.role,
            lease.accepted_quote,
            &receipt.receipt_id,
        )?;
        self.assert_conservation()?;
        Ok(receipt)
    }

    pub fn complete_protocol_service(
        &mut self,
        lease_id: &str,
        proof_hash: String,
        authorization: SignedActionAuthorization,
        validator_qc: QuorumCertificate,
        notary_qc: QuorumCertificate,
    ) -> Result<ServiceReceipt, LedgerError> {
        if !self.descriptor.testnet {
            return Err(LedgerError::Invalid(
                "mainnet protocol reserve release requires EconomicReleaseEvidence".into(),
            ));
        }
        if proof_hash.trim().is_empty() {
            return Err(LedgerError::Invalid("work proof is required".into()));
        }
        let lease = self
            .service_leases
            .get(lease_id)
            .cloned()
            .ok_or_else(|| LedgerError::ServiceLeaseNotFound(lease_id.into()))?;
        let order = self
            .service_orders
            .get(&lease.order_id)
            .cloned()
            .ok_or_else(|| LedgerError::ServiceOrderNotFound(lease.order_id.clone()))?;
        if order.status != ServiceStatus::Leased {
            return Err(LedgerError::ServiceState);
        }
        let commitment = self
            .protocol_reserve_commitments
            .get(&order.order_id)
            .cloned()
            .filter(|commitment| commitment.settled_amount.is_none())
            .ok_or_else(|| {
                LedgerError::Invalid(
                    "service order has no active protocol reserve commitment".into(),
                )
            })?;
        if lease.accepted_quote > commitment.committed_amount {
            return Err(LedgerError::Supply(
                "lease quote exceeds its protocol reserve commitment".into(),
            ));
        }
        if let Some(receipt_id) = &commitment.matched_service_receipt_id {
            let matched = self.service_receipts.get(receipt_id).ok_or_else(|| {
                LedgerError::Invalid("matched service receipt was not found".into())
            })?;
            if matched.node_id != lease.node_id || matched.proof_hash != proof_hash {
                return Err(LedgerError::Invalid(
                    "demand-matched completion must reuse the certified node and work proof".into(),
                ));
            }
        }
        self.require_local_value_commitment(&order.order_id, commitment.committed_amount)?;

        let completion_claim = ProtocolServiceCompletionClaim {
            zone_id: self.descriptor.zone_id.clone(),
            order_id: order.order_id.clone(),
            lease_id: lease.lease_id.clone(),
            node_id: lease.node_id.clone(),
            role: order.role.clone(),
            amount: lease.accepted_quote,
            proof_hash: proof_hash.clone(),
            protocol_era: self.descriptor.protocol_era,
            crypto_era: self.descriptor.crypto_era,
        };
        let completion_subject = completion_claim.subject_hash();
        self.verify_local_dual_quorum(&completion_subject, &validator_qc, &notary_qc)?;

        let payload_hash = action_payload_hash(
            "COMPLETE_SERVICE",
            &[
                lease_id.as_bytes(),
                lease.node_id.as_bytes(),
                proof_hash.as_bytes(),
            ],
        );
        self.verify_node_authorization(
            &authorization,
            &lease.node_id,
            "COMPLETE_SERVICE",
            &payload_hash,
        )?;
        self.ensure_counter_headroom(1, 2)?;
        self.consume_authorization(&authorization)?;
        self.advance()?;

        let pool = commitment.reserve_pool;
        let pool_balance = match &pool {
            ProtocolReservePoolKind::StartupServices => &mut self.reserve_pools.startup_services,
            ProtocolReservePoolKind::ContinuityServices => {
                &mut self.reserve_pools.continuity_services
            }
            ProtocolReservePoolKind::DemandMatching => &mut self.reserve_pools.demand_matching,
        };
        *pool_balance = pool_balance.checked_sub(lease.accepted_quote)?;
        self.reserve = self.reserve.checked_sub(lease.accepted_quote)?;
        let lineage_root = hash_parts(&[
            self.descriptor.currency_genesis_root.as_bytes(),
            pool.wire_name().as_bytes(),
            order.order_id.as_bytes(),
        ]);
        let reward = self.make_coin(
            lease.node_id.clone(),
            lease.accepted_quote,
            CoinState::Spendable,
            Vec::new(),
            Some(lineage_root),
            None,
            None,
            1,
        )?;
        self.coins.insert(reward.object_id.clone(), reward);

        let receipt = ServiceReceipt {
            receipt_id: self.next_id("service-receipt")?,
            order_id: order.order_id.clone(),
            lease_id: lease.lease_id,
            node_id: lease.node_id.clone(),
            role: order.role.clone(),
            amount: lease.accepted_quote,
            proof_hash,
            completed_height: self.height,
            bootstrap: false,
            protocol_reserve_pool: Some(pool),
        };
        self.service_receipts
            .insert(receipt.receipt_id.clone(), receipt.clone());
        self.service_orders
            .get_mut(&order.order_id)
            .expect("order was checked")
            .status = ServiceStatus::Completed;
        self.protocol_reserve_commitments
            .get_mut(&order.order_id)
            .expect("commitment was checked")
            .settled_amount = Some(lease.accepted_quote);
        self.record_earnings(
            &lease.node_id,
            &order.role,
            lease.accepted_quote,
            &receipt.receipt_id,
        )?;
        self.assert_conservation()?;
        Ok(receipt)
    }

    pub fn register_economic_control_attestation(
        &mut self,
        attestation: EconomicControlAttestation,
    ) -> Result<EconomicControlAttestation, LedgerError> {
        let mut staged = self.clone();
        let registered = staged.apply_economic_control_attestation(attestation)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(registered)
    }

    fn apply_economic_control_attestation(
        &mut self,
        attestation: EconomicControlAttestation,
    ) -> Result<EconomicControlAttestation, LedgerError> {
        self.ensure_economic_counter_headroom(1, 0)?;
        if attestation.attestation_id.trim().is_empty()
            || !is_canonical_sha256_hex(&attestation.evidence_hash)
            || attestation.auditor_public_key.trim().is_empty()
            || attestation.auditor_control_group_id.trim().is_empty()
            || attestation.members.is_empty()
        {
            return Err(LedgerError::Economic(
                "control attestation is incomplete".into(),
            ));
        }
        if self
            .economic_control_attestations
            .contains_key(&attestation.attestation_id)
        {
            return Err(LedgerError::Duplicate(attestation.attestation_id));
        }
        if attestation.zone_id != self.descriptor.zone_id
            || attestation.protocol_era != self.descriptor.protocol_era
            || attestation.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Economic(
                "control attestation Zone or era mismatch".into(),
            ));
        }
        if attestation.issued_height > self.height || attestation.valid_until_height <= self.height
        {
            return Err(LedgerError::Economic(
                "control attestation is not currently valid".into(),
            ));
        }
        if attestation.members.windows(2).any(|members| {
            members[0].subject_id.is_empty() || members[0].subject_id >= members[1].subject_id
        }) || attestation
            .members
            .last()
            .is_some_and(|member| member.subject_id.is_empty())
        {
            return Err(LedgerError::Economic(
                "control members must be nonempty, unique and sorted by subject id".into(),
            ));
        }

        let mut roles = BTreeSet::new();
        let mut validator_keys = BTreeSet::new();
        let mut notary_keys = BTreeSet::new();
        let mut validator_group_bps = BTreeMap::<String, u32>::new();
        let mut total_validator_bps = 0u32;
        for member in &attestation.members {
            if member.control_group_id.trim().is_empty()
                || member.control_group_id == attestation.auditor_control_group_id
            {
                return Err(LedgerError::Economic(
                    "control group is empty or affiliated with the auditor".into(),
                ));
            }
            roles.insert(member.role);
            if member.role == EconomicControlRole::Validator {
                validator_keys.insert(member.subject_id.clone());
                total_validator_bps = total_validator_bps
                    .checked_add(member.validator_vote_bps)
                    .ok_or_else(|| LedgerError::Economic("validator vote share overflow".into()))?;
                let group_bps = validator_group_bps
                    .entry(member.control_group_id.clone())
                    .or_default();
                *group_bps = group_bps
                    .checked_add(member.validator_vote_bps)
                    .ok_or_else(|| {
                        LedgerError::Economic("validator control-group share overflow".into())
                    })?;
                if *group_bps > MAX_ECONOMIC_CONTROL_GROUP_VALIDATOR_BPS {
                    return Err(LedgerError::Economic(
                        "one UBO control group exceeds the validator share cap".into(),
                    ));
                }
            } else if member.validator_vote_bps != 0 {
                return Err(LedgerError::Economic(
                    "only validator members may carry validator vote share".into(),
                ));
            }
            if member.role == EconomicControlRole::Notary {
                notary_keys.insert(member.subject_id.clone());
            }
        }
        let required_roles = [
            EconomicControlRole::Requester,
            EconomicControlRole::ServiceProvider,
            EconomicControlRole::Relay,
            EconomicControlRole::LiquidityProvider,
            EconomicControlRole::Validator,
            EconomicControlRole::Notary,
            EconomicControlRole::PriceSource,
        ];
        if required_roles.iter().any(|role| !roles.contains(role)) {
            return Err(LedgerError::Economic(
                "control attestation does not cover every economic role".into(),
            ));
        }
        if total_validator_bps != 10_000
            || validator_keys
                != self
                    .descriptor
                    .validator_keys
                    .iter()
                    .cloned()
                    .collect::<BTreeSet<_>>()
            || notary_keys
                != self
                    .descriptor
                    .notary_keys
                    .iter()
                    .cloned()
                    .collect::<BTreeSet<_>>()
        {
            return Err(LedgerError::Economic(
                "control attestation does not exactly map the configured validator/notary sets"
                    .into(),
            ));
        }

        let subject = attestation.subject_hash();
        crate::crypto::verify_bytes(
            &attestation.auditor_public_key,
            subject.as_bytes(),
            &attestation.auditor_signature,
        )
        .map_err(LedgerError::InvalidSignature)?;
        self.verify_local_dual_quorum(&subject, &attestation.validator_qc, &attestation.notary_qc)?;
        self.advance()?;
        self.economic_control_attestations
            .insert(attestation.attestation_id.clone(), attestation.clone());
        Ok(attestation)
    }

    pub fn register_economic_price_attestation(
        &mut self,
        attestation: EconomicPriceAttestation,
    ) -> Result<EconomicPriceAttestation, LedgerError> {
        let mut staged = self.clone();
        let registered = staged.apply_economic_price_attestation(attestation)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(registered)
    }

    fn apply_economic_price_attestation(
        &mut self,
        attestation: EconomicPriceAttestation,
    ) -> Result<EconomicPriceAttestation, LedgerError> {
        self.ensure_economic_counter_headroom(1, 0)?;
        if attestation.attestation_id.trim().is_empty()
            || attestation.work_id.trim().is_empty()
            || attestation.amount.is_zero()
            || !is_canonical_sha256_hex(&attestation.evidence_hash)
        {
            return Err(LedgerError::Economic(
                "price attestation is incomplete".into(),
            ));
        }
        if self
            .economic_price_attestations
            .contains_key(&attestation.attestation_id)
        {
            return Err(LedgerError::Duplicate(attestation.attestation_id));
        }
        if attestation.zone_id != self.descriptor.zone_id
            || attestation.issued_height > self.height
            || attestation.valid_until_height <= self.height
        {
            return Err(LedgerError::Economic(
                "price attestation is not currently valid for this Zone".into(),
            ));
        }
        let control = self
            .economic_control_attestations
            .get(&attestation.control_attestation_id)
            .ok_or_else(|| {
                LedgerError::Economic("price attestation has no persisted control record".into())
            })?;
        if control.valid_until_height < attestation.valid_until_height {
            return Err(LedgerError::Economic(
                "price validity exceeds its control attestation".into(),
            ));
        }
        let member = Self::economic_member(control, &attestation.source_public_key)?;
        if member.role != EconomicControlRole::PriceSource
            || member.control_group_id != attestation.source_control_group_id
        {
            return Err(LedgerError::Economic(
                "price signer is not bound to the declared independent control group".into(),
            ));
        }
        crate::crypto::verify_bytes(
            &attestation.source_public_key,
            attestation.subject_hash().as_bytes(),
            &attestation.signature,
        )
        .map_err(LedgerError::InvalidSignature)?;
        self.advance()?;
        self.economic_price_attestations
            .insert(attestation.attestation_id.clone(), attestation.clone());
        Ok(attestation)
    }

    pub fn set_economic_release_policy(
        &mut self,
        policy: EconomicReleasePolicy,
    ) -> Result<EconomicReleasePolicy, LedgerError> {
        let mut staged = self.clone();
        let registered = staged.apply_economic_release_policy(policy)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(registered)
    }

    fn apply_economic_release_policy(
        &mut self,
        policy: EconomicReleasePolicy,
    ) -> Result<EconomicReleasePolicy, LedgerError> {
        self.ensure_economic_counter_headroom(1, 0)?;
        if policy.policy_id.trim().is_empty()
            || policy.era_id.trim().is_empty()
            || policy.era_release_cap.is_zero()
            || !policy.released.is_zero()
            || policy.starts_at_height > policy.ends_after_height
            || policy.ends_after_height <= self.height
            || policy.minimum_bond_coverage_bps < MIN_PROTOCOL_SERVICE_BOND_COVERAGE_BPS
        {
            return Err(LedgerError::Economic(
                "release policy is incomplete or unsafe".into(),
            ));
        }
        if policy.zone_id != self.descriptor.zone_id
            || policy.protocol_era != self.descriptor.protocol_era
            || policy.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Economic(
                "release policy Zone or protocol era mismatch".into(),
            ));
        }
        if self
            .economic_release_policies
            .contains_key(&policy.policy_id)
            || self.economic_release_policies.values().any(|existing| {
                existing.era_id == policy.era_id && existing.reserve_pool == policy.reserve_pool
            })
        {
            return Err(LedgerError::Duplicate(policy.policy_id));
        }
        let pool_balance = self.protocol_reserve_pool_balance(policy.reserve_pool);
        if policy.era_release_cap > pool_balance {
            return Err(LedgerError::Economic(
                "Era release cap exceeds the selected reserve pool".into(),
            ));
        }
        let subject = policy.subject_hash();
        self.verify_local_dual_quorum(&subject, &policy.validator_qc, &policy.notary_qc)?;
        self.advance()?;
        self.economic_release_policies
            .insert(policy.policy_id.clone(), policy.clone());
        Ok(policy)
    }

    pub fn lock_protocol_service_bond(
        &mut self,
        request: ProtocolServiceBondLockRequest,
    ) -> Result<ProtocolServiceBond, LedgerError> {
        let mut staged = self.clone();
        let bond = staged.apply_protocol_service_bond_lock(request)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(bond)
    }

    fn apply_protocol_service_bond_lock(
        &mut self,
        request: ProtocolServiceBondLockRequest,
    ) -> Result<ProtocolServiceBond, LedgerError> {
        self.ensure_economic_counter_headroom(1, 2)?;
        if request.bond_id.trim().is_empty()
            || request.amount.is_zero()
            || !is_canonical_sha256_hex(&request.slash_conditions_hash)
            || request.challenge_end_height <= self.height
            || request.unbond_after_height <= request.challenge_end_height
        {
            return Err(LedgerError::Economic(
                "service bond request is incomplete or has no delayed unbond window".into(),
            ));
        }
        if self.protocol_service_bonds.contains_key(&request.bond_id)
            || self.protocol_service_bonds.values().any(|bond| {
                bond.order_id == request.order_id
                    && bond.lease_id == request.lease_id
                    && bond.status != ProtocolServiceBondStatus::Unbonded
            })
        {
            return Err(LedgerError::Duplicate(request.bond_id));
        }
        let lease = self
            .service_leases
            .get(&request.lease_id)
            .cloned()
            .ok_or_else(|| LedgerError::ServiceLeaseNotFound(request.lease_id.clone()))?;
        let order = self
            .service_orders
            .get(&request.order_id)
            .cloned()
            .ok_or_else(|| LedgerError::ServiceOrderNotFound(request.order_id.clone()))?;
        if lease.order_id != order.order_id
            || order.status != ServiceStatus::Leased
            || self
                .protocol_reserve_commitments
                .get(&order.order_id)
                .is_none_or(|commitment| commitment.settled_amount.is_some())
        {
            return Err(LedgerError::Economic(
                "service bond is not bound to an active protocol lease".into(),
            ));
        }
        let payload_hash = action_payload_hash(
            "LOCK_PROTOCOL_SERVICE_BOND",
            &[
                request.bond_id.as_bytes(),
                request.order_id.as_bytes(),
                request.lease_id.as_bytes(),
                request.coin_id.as_bytes(),
                &request.amount.0.to_be_bytes(),
                &request.challenge_end_height.to_be_bytes(),
                &request.unbond_after_height.to_be_bytes(),
                request.slash_conditions_hash.as_bytes(),
            ],
        );
        self.verify_owner_authorization(
            &request.authorization,
            &request.owner,
            "LOCK_PROTOCOL_SERVICE_BOND",
            &payload_hash,
        )?;
        self.verify_node_authorization(
            &request.authorization,
            &lease.node_id,
            "LOCK_PROTOCOL_SERVICE_BOND",
            &payload_hash,
        )?;
        let input = self
            .coins
            .get(&request.coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(request.coin_id.clone()))?;
        if input.state != CoinState::Spendable || input.owner != request.owner {
            return Err(LedgerError::CoinNotSpendable);
        }
        if request.amount > input.amount {
            return Err(LedgerError::Economic(
                "service bond exceeds its spendable input".into(),
            ));
        }
        let next_version = Self::checked_next_coin_version(input.version)?;

        self.consume_authorization(&request.authorization)?;
        self.advance()?;
        self.consume_coin(&input.object_id)?;
        let escrow = self.make_coin(
            request.owner.clone(),
            request.amount,
            CoinState::Reserved,
            vec![input.object_id.clone()],
            Some(input.lineage_root.clone()),
            None,
            input.imported_from.clone(),
            next_version,
        )?;
        self.coins.insert(escrow.object_id.clone(), escrow.clone());
        let change = input.amount.checked_sub(request.amount)?;
        if !change.is_zero() {
            let change_coin = self.make_coin(
                request.owner.clone(),
                change,
                CoinState::Spendable,
                vec![input.object_id],
                Some(input.lineage_root),
                None,
                input.imported_from,
                next_version,
            )?;
            self.coins
                .insert(change_coin.object_id.clone(), change_coin);
        }
        let bond = ProtocolServiceBond {
            bond_id: request.bond_id.clone(),
            order_id: order.order_id,
            lease_id: lease.lease_id,
            owner: request.owner,
            provider_node_id: lease.node_id,
            escrow_coin_id: Some(escrow.object_id),
            locked_amount: request.amount,
            slashable_remaining: request.amount,
            slashed_amount: Amount::ZERO,
            slashed_coin_ids: Vec::new(),
            challenge_end_height: request.challenge_end_height,
            unbond_after_height: request.unbond_after_height,
            slash_conditions_hash: request.slash_conditions_hash,
            created_height: self.height,
            status: ProtocolServiceBondStatus::Locked,
        };
        self.protocol_service_bonds
            .insert(bond.bond_id.clone(), bond.clone());
        Ok(bond)
    }

    pub fn slash_protocol_service_bond(
        &mut self,
        slash: ProtocolServiceBondSlash,
    ) -> Result<ProtocolServiceBond, LedgerError> {
        let mut staged = self.clone();
        let bond = staged.apply_protocol_service_bond_slash(slash)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(bond)
    }

    fn apply_protocol_service_bond_slash(
        &mut self,
        slash: ProtocolServiceBondSlash,
    ) -> Result<ProtocolServiceBond, LedgerError> {
        self.ensure_economic_counter_headroom(1, 2)?;
        if slash.slash_id.trim().is_empty()
            || slash.amount.is_zero()
            || !is_canonical_sha256_hex(&slash.evidence_hash)
        {
            return Err(LedgerError::Economic("bond slash is incomplete".into()));
        }
        if self.economic_bond_slash_ids.contains(&slash.slash_id) {
            return Err(LedgerError::Duplicate(slash.slash_id));
        }
        let bond = self
            .protocol_service_bonds
            .get(&slash.bond_id)
            .cloned()
            .ok_or_else(|| LedgerError::Economic("service bond was not found".into()))?;
        if !matches!(
            bond.status,
            ProtocolServiceBondStatus::Locked | ProtocolServiceBondStatus::PartiallySlashed
        ) || self.height >= bond.challenge_end_height
            || slash.amount > bond.slashable_remaining
        {
            return Err(LedgerError::Economic(
                "service bond is not slashable for this amount".into(),
            ));
        }
        let escrow_id = bond
            .escrow_coin_id
            .clone()
            .ok_or_else(|| LedgerError::Economic("bond has no slashable escrow".into()))?;
        let escrow = self
            .coins
            .get(&escrow_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(escrow_id.clone()))?;
        if escrow.state != CoinState::Reserved
            || escrow.owner != bond.owner
            || escrow.amount != bond.slashable_remaining
        {
            return Err(LedgerError::Economic(
                "persisted service bond escrow does not match the coin ledger".into(),
            ));
        }
        let subject = slash.subject_hash();
        self.verify_local_dual_quorum(&subject, &slash.validator_qc, &slash.notary_qc)?;
        let remaining = bond.slashable_remaining.checked_sub(slash.amount)?;
        let slashed_total = bond.slashed_amount.checked_add(slash.amount)?;
        let next_version = Self::checked_next_coin_version(escrow.version)?;

        self.advance()?;
        self.consume_coin(&escrow_id)?;
        let slashed_coin = self.make_coin(
            "rld:protocol:slashed-funds".into(),
            slash.amount,
            CoinState::Reserved,
            vec![escrow.object_id.clone()],
            Some(escrow.lineage_root.clone()),
            None,
            escrow.imported_from.clone(),
            next_version,
        )?;
        self.coins
            .insert(slashed_coin.object_id.clone(), slashed_coin.clone());
        let remaining_coin_id = if remaining.is_zero() {
            None
        } else {
            let remaining_coin = self.make_coin(
                bond.owner.clone(),
                remaining,
                CoinState::Reserved,
                vec![escrow.object_id],
                Some(escrow.lineage_root),
                None,
                escrow.imported_from,
                next_version,
            )?;
            let id = remaining_coin.object_id.clone();
            self.coins.insert(id.clone(), remaining_coin);
            Some(id)
        };
        self.economic_bond_slash_ids.insert(slash.slash_id);
        let stored = self
            .protocol_service_bonds
            .get_mut(&bond.bond_id)
            .expect("bond was checked");
        stored.escrow_coin_id = remaining_coin_id;
        stored.slashable_remaining = remaining;
        stored.slashed_amount = slashed_total;
        stored.slashed_coin_ids.push(slashed_coin.object_id);
        stored.status = if remaining.is_zero() {
            ProtocolServiceBondStatus::FullySlashed
        } else {
            ProtocolServiceBondStatus::PartiallySlashed
        };
        Ok(stored.clone())
    }

    pub fn unbond_protocol_service_bond(
        &mut self,
        bond_id: &str,
        authorization: SignedActionAuthorization,
    ) -> Result<ProtocolServiceBond, LedgerError> {
        let mut staged = self.clone();
        let bond = staged.apply_protocol_service_bond_unbond(bond_id, authorization)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(bond)
    }

    fn apply_protocol_service_bond_unbond(
        &mut self,
        bond_id: &str,
        authorization: SignedActionAuthorization,
    ) -> Result<ProtocolServiceBond, LedgerError> {
        self.ensure_economic_counter_headroom(1, 1)?;
        let bond = self
            .protocol_service_bonds
            .get(bond_id)
            .cloned()
            .ok_or_else(|| LedgerError::Economic("service bond was not found".into()))?;
        if !matches!(
            bond.status,
            ProtocolServiceBondStatus::Locked | ProtocolServiceBondStatus::PartiallySlashed
        ) || self.height < bond.unbond_after_height
            || bond.slashable_remaining.is_zero()
        {
            return Err(LedgerError::Economic(
                "service bond has not reached its delayed unbond height".into(),
            ));
        }
        let payload_hash = action_payload_hash(
            "UNBOND_PROTOCOL_SERVICE_BOND",
            &[
                bond_id.as_bytes(),
                &bond.slashable_remaining.0.to_be_bytes(),
            ],
        );
        self.verify_owner_authorization(
            &authorization,
            &bond.owner,
            "UNBOND_PROTOCOL_SERVICE_BOND",
            &payload_hash,
        )?;
        self.verify_node_authorization(
            &authorization,
            &bond.provider_node_id,
            "UNBOND_PROTOCOL_SERVICE_BOND",
            &payload_hash,
        )?;
        let escrow_id = bond
            .escrow_coin_id
            .clone()
            .ok_or_else(|| LedgerError::Economic("bond has no unbondable escrow".into()))?;
        let escrow = self
            .coins
            .get(&escrow_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(escrow_id.clone()))?;
        if escrow.state != CoinState::Reserved
            || escrow.owner != bond.owner
            || escrow.amount != bond.slashable_remaining
        {
            return Err(LedgerError::Economic(
                "persisted service bond escrow does not match the coin ledger".into(),
            ));
        }
        let next_version = Self::checked_next_coin_version(escrow.version)?;

        self.consume_authorization(&authorization)?;
        self.advance()?;
        self.consume_coin(&escrow_id)?;
        let returned = self.make_coin(
            bond.owner.clone(),
            bond.slashable_remaining,
            CoinState::Spendable,
            vec![escrow.object_id],
            Some(escrow.lineage_root),
            None,
            escrow.imported_from,
            next_version,
        )?;
        self.coins.insert(returned.object_id.clone(), returned);
        let stored = self
            .protocol_service_bonds
            .get_mut(bond_id)
            .expect("bond was checked");
        stored.escrow_coin_id = None;
        stored.slashable_remaining = Amount::ZERO;
        stored.status = ProtocolServiceBondStatus::Unbonded;
        Ok(stored.clone())
    }

    pub fn release_protocol_reserve(
        &mut self,
        request: ProtocolReserveReleaseRequest,
    ) -> Result<ProtocolReserveReleaseRecord, LedgerError> {
        let mut staged = self.clone();
        let release = staged.apply_protocol_reserve_release(request)?;
        staged.assert_conservation()?;
        *self = staged;
        Ok(release)
    }

    fn apply_protocol_reserve_release(
        &mut self,
        request: ProtocolReserveReleaseRequest,
    ) -> Result<ProtocolReserveReleaseRecord, LedgerError> {
        self.ensure_economic_counter_headroom(1, 2)?;
        if request.release_id.trim().is_empty()
            || request.work_id.trim().is_empty()
            || request.work_id
                != ProtocolReserveReleaseRequest::derive_work_id(
                    &request.requester_subject_id,
                    &request.work_proof_hash,
                )
            || !is_canonical_sha256_hex(&request.work_proof_hash)
            || request.reward.is_zero()
            || !Self::is_sorted_unique_nonempty(&request.fee_receipt_ids)
            || request.price_attestation_ids.len() < 2
            || !Self::is_sorted_unique_nonempty(&request.price_attestation_ids)
        {
            return Err(LedgerError::Economic(
                "reserve release request is incomplete or non-canonical".into(),
            ));
        }
        let completion_subject = request.completion_subject_hash();
        if self
            .protocol_reserve_releases
            .contains_key(&request.release_id)
            || self.economic_consumed_work_ids.contains(&request.work_id)
            || self
                .economic_consumed_completion_qcs
                .contains(&completion_subject)
            || request
                .fee_receipt_ids
                .iter()
                .any(|id| self.economic_consumed_fee_receipts.contains(id))
        {
            return Err(LedgerError::Duplicate(request.release_id));
        }
        let lease = self
            .service_leases
            .get(&request.lease_id)
            .cloned()
            .ok_or_else(|| LedgerError::ServiceLeaseNotFound(request.lease_id.clone()))?;
        let order = self
            .service_orders
            .get(&request.order_id)
            .cloned()
            .ok_or_else(|| LedgerError::ServiceOrderNotFound(request.order_id.clone()))?;
        let commitment = self
            .protocol_reserve_commitments
            .get(&request.order_id)
            .cloned()
            .filter(|commitment| commitment.settled_amount.is_none())
            .ok_or_else(|| LedgerError::Economic("protocol commitment is not active".into()))?;
        if lease.order_id != order.order_id
            || order.status != ServiceStatus::Leased
            || request.reward != lease.accepted_quote
            || request.reward > order.budget
            || request.reward > commitment.committed_amount
        {
            return Err(LedgerError::Economic(
                "release amount is not bound to the active order and lease".into(),
            ));
        }
        if commitment
            .matched_service_receipt_id
            .as_ref()
            .is_some_and(|id| request.fee_receipt_ids.binary_search(id).is_err())
        {
            return Err(LedgerError::Economic(
                "release omits the receipt that justified its reserve commitment".into(),
            ));
        }
        self.require_local_value_commitment(&order.order_id, commitment.committed_amount)?;

        let control = self
            .economic_control_attestations
            .get(&request.control_attestation_id)
            .cloned()
            .ok_or_else(|| LedgerError::Economic("control attestation was not found".into()))?;
        if control.zone_id != self.descriptor.zone_id
            || control.protocol_era != self.descriptor.protocol_era
            || control.crypto_era != self.descriptor.crypto_era
            || control.issued_height > self.height
            || control.valid_until_height <= self.height
        {
            return Err(LedgerError::Economic(
                "control attestation is stale or has the wrong era".into(),
            ));
        }
        let persisted_control_subject = control.subject_hash();
        crate::crypto::verify_bytes(
            &control.auditor_public_key,
            persisted_control_subject.as_bytes(),
            &control.auditor_signature,
        )
        .map_err(LedgerError::InvalidSignature)?;
        self.verify_local_dual_quorum(
            &persisted_control_subject,
            &control.validator_qc,
            &control.notary_qc,
        )?;
        let requester = Self::economic_member(&control, &request.requester_subject_id)?;
        let provider = Self::economic_member(&control, &lease.node_id)?;
        if requester.role != EconomicControlRole::Requester
            || provider.role != EconomicControlRole::ServiceProvider
            || requester.control_group_id == provider.control_group_id
        {
            return Err(LedgerError::Economic(
                "requester/provider ownership is missing or affiliated".into(),
            ));
        }
        let provider_payload =
            action_payload_hash("RELEASE_PROTOCOL_RESERVE", &[completion_subject.as_bytes()]);
        self.verify_node_authorization(
            &request.provider_authorization,
            &lease.node_id,
            "RELEASE_PROTOCOL_RESERVE",
            &provider_payload,
        )?;
        self.verify_local_dual_quorum(
            &completion_subject,
            &request.completion_validator_qc,
            &request.completion_notary_qc,
        )?;
        for signer in request
            .completion_validator_qc
            .attestations
            .iter()
            .map(|attestation| (&attestation.public_key, EconomicControlRole::Validator))
            .chain(
                request
                    .completion_notary_qc
                    .attestations
                    .iter()
                    .map(|attestation| (&attestation.public_key, EconomicControlRole::Notary)),
            )
        {
            if Self::economic_member(&control, signer.0)?.role != signer.1 {
                return Err(LedgerError::Economic(
                    "completion quorum signer has no matching persisted control role".into(),
                ));
            }
        }

        let mut attributable_fee = Amount::ZERO;
        let mut affiliated_recovery = Amount::ZERO;
        for receipt_id in &request.fee_receipt_ids {
            let receipt = self
                .service_receipts
                .get(receipt_id)
                .ok_or_else(|| LedgerError::Economic("fee receipt was not found".into()))?;
            let fee_order = self
                .service_orders
                .get(&receipt.order_id)
                .ok_or_else(|| LedgerError::ServiceOrderNotFound(receipt.order_id.clone()))?;
            let fee_lease = self
                .service_leases
                .get(&receipt.lease_id)
                .ok_or_else(|| LedgerError::ServiceLeaseNotFound(receipt.lease_id.clone()))?;
            if receipt.bootstrap
                || receipt.protocol_reserve_pool.is_some()
                || receipt.proof_hash != request.work_proof_hash
                || receipt.amount.is_zero()
                || fee_order.status != ServiceStatus::Completed
                || fee_order.buyer != request.requester_subject_id
                || fee_lease.order_id != fee_order.order_id
                || fee_lease.node_id != receipt.node_id
                || fee_lease.accepted_quote != receipt.amount
            {
                return Err(LedgerError::Economic(
                    "fee attribution is not a finalized user-funded part of this work".into(),
                ));
            }
            let earnings = self.node_earnings.get(&receipt.node_id).ok_or_else(|| {
                LedgerError::Economic("fee receipt has no persisted earnings record".into())
            })?;
            let role_key = format!("{:?}", receipt.role).to_uppercase();
            if !earnings.receipt_ids.contains(receipt_id)
                || earnings.total < receipt.amount
                || earnings
                    .by_role
                    .get(&role_key)
                    .is_none_or(|amount| *amount < receipt.amount)
            {
                return Err(LedgerError::Economic(
                    "fee receipt is not backed by actual node earnings".into(),
                ));
            }
            let recipient = Self::economic_member(&control, &receipt.node_id)?;
            let expected_role = Self::economic_role_for_service(&receipt.role);
            if recipient.role != expected_role {
                return Err(LedgerError::Economic(
                    "fee recipient has no matching persisted control role".into(),
                ));
            }
            attributable_fee = attributable_fee.checked_add(receipt.amount)?;
            if recipient.control_group_id == requester.control_group_id {
                affiliated_recovery = affiliated_recovery.checked_add(receipt.amount)?;
            }
        }
        let nonrecoverable_fee = attributable_fee.checked_sub(affiliated_recovery)?;
        if request.reward > nonrecoverable_fee {
            return Err(LedgerError::Economic(
                "reward exceeds same-work nonrecoverable user fees".into(),
            ));
        }

        let actor_groups = control
            .members
            .iter()
            .filter(|member| member.role != EconomicControlRole::PriceSource)
            .map(|member| member.control_group_id.clone())
            .chain(std::iter::once(control.auditor_control_group_id.clone()))
            .collect::<BTreeSet<_>>();
        let mut price_groups = BTreeSet::new();
        let mut independent_price_cap: Option<Amount> = None;
        for price_id in &request.price_attestation_ids {
            let price = self
                .economic_price_attestations
                .get(price_id)
                .ok_or_else(|| LedgerError::Economic("price attestation was not found".into()))?;
            if price.zone_id != self.descriptor.zone_id
                || price.work_id != request.work_id
                || price.control_attestation_id != request.control_attestation_id
                || price.issued_height > self.height
                || price.valid_until_height <= self.height
                || actor_groups.contains(&price.source_control_group_id)
            {
                return Err(LedgerError::Economic(
                    "price evidence is stale, unrelated or controlled by an economic actor".into(),
                ));
            }
            let source = Self::economic_member(&control, &price.source_public_key)?;
            if source.role != EconomicControlRole::PriceSource
                || source.control_group_id != price.source_control_group_id
            {
                return Err(LedgerError::Economic(
                    "price source ownership does not match persisted control evidence".into(),
                ));
            }
            crate::crypto::verify_bytes(
                &price.source_public_key,
                price.subject_hash().as_bytes(),
                &price.signature,
            )
            .map_err(LedgerError::InvalidSignature)?;
            price_groups.insert(price.source_control_group_id.clone());
            independent_price_cap = Some(match independent_price_cap {
                Some(cap) if cap <= price.amount => cap,
                _ => price.amount,
            });
        }
        if price_groups.len() < 2 {
            return Err(LedgerError::Economic(
                "at least two independent price-source UBO groups are required".into(),
            ));
        }
        let independent_price_cap = independent_price_cap.expect("two prices were checked");
        if request.reward > independent_price_cap {
            return Err(LedgerError::Economic(
                "reward exceeds the conservative independent price cap".into(),
            ));
        }

        let bond = self
            .protocol_service_bonds
            .get(&request.bond_id)
            .cloned()
            .ok_or_else(|| LedgerError::Economic("service bond was not found".into()))?;
        let bond_owner = Self::economic_member(&control, &bond.owner)?;
        let bond_escrow_id = bond
            .escrow_coin_id
            .as_ref()
            .ok_or_else(|| LedgerError::Economic("service bond has no escrow".into()))?;
        let bond_escrow = self
            .coins
            .get(bond_escrow_id)
            .ok_or_else(|| LedgerError::CoinNotFound(bond_escrow_id.clone()))?;
        if bond.order_id != order.order_id
            || bond.lease_id != lease.lease_id
            || bond.provider_node_id != lease.node_id
            || bond_owner.role != EconomicControlRole::ServiceProvider
            || bond_owner.control_group_id != provider.control_group_id
            || !matches!(
                bond.status,
                ProtocolServiceBondStatus::Locked | ProtocolServiceBondStatus::PartiallySlashed
            )
            || self.height >= bond.challenge_end_height
            || bond.unbond_after_height <= self.height
            || bond_escrow.state != CoinState::Reserved
            || bond_escrow.owner != bond.owner
            || bond_escrow.amount != bond.slashable_remaining
        {
            return Err(LedgerError::Economic(
                "release is not backed by the provider's live slashable bond".into(),
            ));
        }

        let policy = self
            .economic_release_policies
            .get(&request.release_policy_id)
            .cloned()
            .ok_or_else(|| LedgerError::Economic("release policy was not found".into()))?;
        if policy.zone_id != self.descriptor.zone_id
            || policy.protocol_era != self.descriptor.protocol_era
            || policy.crypto_era != self.descriptor.crypto_era
            || policy.reserve_pool != commitment.reserve_pool
            || self.height < policy.starts_at_height
            || self.height >= policy.ends_after_height
        {
            return Err(LedgerError::Economic(
                "release policy is inactive or targets another reserve pool".into(),
            ));
        }
        self.verify_local_dual_quorum(
            &policy.subject_hash(),
            &policy.validator_qc,
            &policy.notary_qc,
        )?;
        let required_bond =
            Self::checked_bps_ceil(request.reward, policy.minimum_bond_coverage_bps)?;
        if bond.locked_amount < required_bond || bond.slashable_remaining < required_bond {
            return Err(LedgerError::Economic(
                "provider bond is below the release policy coverage floor".into(),
            ));
        }
        let next_released = policy.released.checked_add(request.reward)?;
        if next_released > policy.era_release_cap {
            return Err(LedgerError::Economic(
                "release exceeds the checked per-Era reserve-pool cap".into(),
            ));
        }
        let pool_balance = self.protocol_reserve_pool_balance(commitment.reserve_pool);
        if request.reward > pool_balance || request.reward > self.reserve {
            return Err(LedgerError::Supply(
                "protocol reserve pool cannot fund this release".into(),
            ));
        }

        self.consume_authorization(&request.provider_authorization)?;
        self.advance()?;
        *self.protocol_reserve_pool_balance_mut(commitment.reserve_pool) =
            pool_balance.checked_sub(request.reward)?;
        self.reserve = self.reserve.checked_sub(request.reward)?;
        let lineage_root = hash_parts(&[
            self.descriptor.currency_genesis_root.as_bytes(),
            commitment.reserve_pool.wire_name().as_bytes(),
            order.order_id.as_bytes(),
            request.work_id.as_bytes(),
        ]);
        let reward_coin = self.make_coin(
            lease.node_id.clone(),
            request.reward,
            CoinState::Spendable,
            Vec::new(),
            Some(lineage_root),
            None,
            None,
            1,
        )?;
        self.coins
            .insert(reward_coin.object_id.clone(), reward_coin);
        let receipt = ServiceReceipt {
            receipt_id: self.next_id("service-receipt")?,
            order_id: order.order_id.clone(),
            lease_id: lease.lease_id.clone(),
            node_id: lease.node_id.clone(),
            role: order.role.clone(),
            amount: request.reward,
            proof_hash: request.work_proof_hash.clone(),
            completed_height: self.height,
            bootstrap: false,
            protocol_reserve_pool: Some(commitment.reserve_pool),
        };
        self.record_earnings(
            &lease.node_id,
            &order.role,
            request.reward,
            &receipt.receipt_id,
        )?;
        self.service_receipts
            .insert(receipt.receipt_id.clone(), receipt.clone());
        self.service_orders
            .get_mut(&order.order_id)
            .expect("order was checked")
            .status = ServiceStatus::Completed;
        self.protocol_reserve_commitments
            .get_mut(&order.order_id)
            .expect("commitment was checked")
            .settled_amount = Some(request.reward);
        self.economic_release_policies
            .get_mut(&policy.policy_id)
            .expect("policy was checked")
            .released = next_released;
        self.economic_consumed_work_ids
            .insert(request.work_id.clone());
        self.economic_consumed_completion_qcs
            .insert(completion_subject.clone());
        self.economic_consumed_fee_receipts
            .extend(request.fee_receipt_ids.iter().cloned());
        let record = ProtocolReserveReleaseRecord {
            release_id: request.release_id.clone(),
            order_id: order.order_id,
            lease_id: lease.lease_id,
            receipt_id: receipt.receipt_id,
            requester_subject_id: request.requester_subject_id,
            work_id: request.work_id,
            work_proof_hash: request.work_proof_hash,
            completion_subject_hash: completion_subject,
            completion_validator_qc: request.completion_validator_qc,
            completion_notary_qc: request.completion_notary_qc,
            fee_receipt_ids: request.fee_receipt_ids,
            control_attestation_id: request.control_attestation_id,
            price_attestation_ids: request.price_attestation_ids,
            bond_id: request.bond_id,
            bond_locked_amount: bond.locked_amount,
            bond_slashable_amount: bond.slashable_remaining,
            bond_slashed_amount: bond.slashed_amount,
            bond_challenge_end_height: bond.challenge_end_height,
            bond_unbond_after_height: bond.unbond_after_height,
            bond_slash_conditions_hash: bond.slash_conditions_hash,
            release_policy_id: request.release_policy_id,
            era_id: policy.era_id,
            era_release_cap: policy.era_release_cap,
            era_released_before: policy.released,
            pool_balance_before: pool_balance,
            minimum_bond_coverage_bps: policy.minimum_bond_coverage_bps,
            reserve_pool: commitment.reserve_pool,
            attributable_fee,
            affiliated_recovery,
            nonrecoverable_fee,
            independent_price_cap,
            reward: request.reward,
            released_height: self.height,
        };
        self.protocol_reserve_releases
            .insert(record.release_id.clone(), record.clone());
        Ok(record)
    }

    pub fn set_zone_trust_policy(
        &mut self,
        zone_id: String,
        policy: ZoneTrustPolicy,
    ) -> Result<(), LedgerError> {
        self.ensure_counter_headroom(1, 0)?;
        if policy == ZoneTrustPolicy::Quarantined {
            self.quarantined_zones.insert(zone_id.clone());
        } else {
            self.quarantined_zones.remove(&zone_id);
        }
        self.zone_trust_policies.insert(zone_id, policy);
        self.advance()?;
        self.create_checkpoint()?;
        Ok(())
    }

    pub fn trust_zone_checkpoint(
        &mut self,
        zone_id: String,
        checkpoint_hash: String,
    ) -> Result<(), LedgerError> {
        if zone_id.trim().is_empty() || checkpoint_hash.trim().is_empty() {
            return Err(LedgerError::Invalid(
                "Zone id and checkpoint hash are required".into(),
            ));
        }
        self.ensure_counter_headroom(1, 0)?;
        self.trusted_zone_checkpoints
            .entry(zone_id)
            .or_default()
            .insert(checkpoint_hash);
        self.advance()?;
        self.create_checkpoint()?;
        Ok(())
    }

    pub fn create_gateway_bond(
        &mut self,
        request: CreateGatewayBondRequest,
    ) -> Result<GatewayBond, LedgerError> {
        if request.source_zone.trim().is_empty() || request.gateway_public_key.trim().is_empty() {
            return Err(LedgerError::Invalid(
                "source Zone and gateway public key are required".into(),
            ));
        }
        let payload_hash = action_payload_hash(
            "CREATE_GATEWAY_BOND",
            &[
                request.source_zone.as_bytes(),
                request.owner.as_bytes(),
                request.gateway_public_key.as_bytes(),
                request.coin_id.as_bytes(),
                &request.amount.0.to_be_bytes(),
            ],
        );
        self.verify_owner_authorization(
            &request.authorization,
            &request.owner,
            "CREATE_GATEWAY_BOND",
            &payload_hash,
        )?;
        let input = self
            .coins
            .get(&request.coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(request.coin_id.clone()))?;
        if input.state != CoinState::Spendable || input.owner != request.owner {
            return Err(LedgerError::OwnerMismatch);
        }
        if request.amount.is_zero() || request.amount > input.amount {
            return Err(LedgerError::Invalid("invalid gateway bond amount".into()));
        }
        let change = input.amount.checked_sub(request.amount)?;
        let next_version = Self::checked_next_coin_version(input.version)?;
        let sequence_steps = 2 + u64::from(!change.is_zero());
        self.ensure_counter_headroom(1, sequence_steps)?;

        self.consume_authorization(&request.authorization)?;
        self.advance()?;
        self.consume_coin(&input.object_id)?;
        let escrow = self.make_coin(
            request.owner.clone(),
            request.amount,
            CoinState::Reserved,
            vec![input.object_id.clone()],
            Some(input.lineage_root.clone()),
            None,
            input.imported_from.clone(),
            next_version,
        )?;
        self.coins.insert(escrow.object_id.clone(), escrow.clone());
        if !change.is_zero() {
            let change_coin = self.make_coin(
                request.owner.clone(),
                change,
                CoinState::Spendable,
                vec![input.object_id],
                Some(input.lineage_root),
                None,
                input.imported_from,
                next_version,
            )?;
            self.coins
                .insert(change_coin.object_id.clone(), change_coin);
        }
        let bond = GatewayBond {
            bond_id: self.next_id("gateway-bond")?,
            source_zone: request.source_zone,
            owner: request.owner,
            gateway_public_key: request.gateway_public_key,
            amount: request.amount,
            escrow_coin_id: escrow.object_id,
            status: GatewayBondStatus::Active,
            created_height: self.height,
        };
        self.gateway_bonds
            .insert(bond.bond_id.clone(), bond.clone());
        self.assert_conservation()?;
        Ok(bond)
    }

    pub fn create_traveler_capsule(
        &mut self,
        intent: UniversalPaymentIntent,
        transport: TransportClass,
    ) -> Result<TravelerCarryCapsule, LedgerError> {
        let mut staged = self.clone();
        let capsule = staged.apply_create_traveler_capsule(intent, transport)?;
        *self = staged;
        Ok(capsule)
    }

    fn apply_create_traveler_capsule(
        &mut self,
        intent: UniversalPaymentIntent,
        transport: TransportClass,
    ) -> Result<TravelerCarryCapsule, LedgerError> {
        let owner = intent.recipient.clone();
        let transit = self.export_payment(intent, transport)?;
        let capsule_id = self.next_id("traveler-capsule")?;
        let capsule = TravelerCarryCapsule {
            capsule_id,
            owner,
            issued_height: self.height,
            transit,
        };
        self.traveler_capsules
            .insert(capsule.capsule_id.clone(), capsule.clone());
        Ok(capsule)
    }

    pub fn import_traveler_capsule(
        &mut self,
        capsule: TravelerCarryCapsule,
    ) -> Result<DestinationImportReceipt, LedgerError> {
        if capsule.owner != capsule.transit.recipient {
            return Err(LedgerError::Invalid(
                "traveler capsule owner does not match recipient".into(),
            ));
        }
        self.import_capsule(capsule.transit)
    }

    pub fn open_voyage_escrow(
        &mut self,
        payer: String,
        coin_id: String,
        transit_id: String,
        budget: Amount,
        max_reward_per_hop: Amount,
        authorization: SignedActionAuthorization,
    ) -> Result<AdaptiveVoyageEscrow, LedgerError> {
        let payload_hash = action_payload_hash(
            "OPEN_VOYAGE_ESCROW",
            &[
                payer.as_bytes(),
                coin_id.as_bytes(),
                transit_id.as_bytes(),
                &budget.0.to_be_bytes(),
                &max_reward_per_hop.0.to_be_bytes(),
            ],
        );
        self.verify_owner_authorization(
            &authorization,
            &payer,
            "OPEN_VOYAGE_ESCROW",
            &payload_hash,
        )?;
        let transit = self
            .transits
            .get(&transit_id)
            .ok_or_else(|| LedgerError::TransitNotFound(transit_id.clone()))?;
        let destination_zone = transit.destination_zone.clone();
        let input = self
            .coins
            .get(&coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(coin_id.clone()))?;
        if input.state != CoinState::Spendable || input.owner != payer {
            return Err(LedgerError::OwnerMismatch);
        }
        if budget.is_zero()
            || max_reward_per_hop.is_zero()
            || budget > input.amount
            || max_reward_per_hop > budget
        {
            return Err(LedgerError::Invalid("invalid voyage escrow budget".into()));
        }
        let next_value_total = self.next_value_risk_total(ValueRiskPath::LocalPayment, budget)?;
        let change = input.amount.checked_sub(budget)?;
        let next_version = Self::checked_next_coin_version(input.version)?;
        let sequence_steps = 2 + u64::from(!change.is_zero());
        self.ensure_counter_headroom(1, sequence_steps)?;

        self.consume_authorization(&authorization)?;
        self.advance()?;
        self.consume_coin(&input.object_id)?;
        let escrow_coin = self.make_coin(
            payer.clone(),
            budget,
            CoinState::Reserved,
            vec![input.object_id.clone()],
            Some(input.lineage_root.clone()),
            None,
            input.imported_from.clone(),
            next_version,
        )?;
        self.coins
            .insert(escrow_coin.object_id.clone(), escrow_coin.clone());
        if !change.is_zero() {
            let change_coin = self.make_coin(
                payer.clone(),
                change,
                CoinState::Spendable,
                vec![input.object_id],
                Some(input.lineage_root),
                None,
                input.imported_from,
                next_version,
            )?;
            self.coins
                .insert(change_coin.object_id.clone(), change_coin);
        }
        let voyage = AdaptiveVoyageEscrow {
            voyage_id: self.next_id("voyage")?,
            transit_id,
            payer,
            destination_zone,
            original_budget: budget,
            remaining_budget: budget,
            max_reward_per_hop,
            escrow_coin_id: Some(escrow_coin.object_id),
            settled_proof_hashes: Vec::new(),
            status: VoyageStatus::Open,
            created_height: self.height,
        };
        self.voyage_escrows
            .insert(voyage.voyage_id.clone(), voyage.clone());
        self.record_value_risk_commitment(
            ValueRiskPath::LocalPayment,
            voyage.voyage_id.clone(),
            voyage.original_budget,
            next_value_total,
        );
        self.assert_conservation()?;
        Ok(voyage)
    }

    pub fn settle_voyage_hop(
        &mut self,
        voyage_id: &str,
        node_id: String,
        amount: Amount,
        downstream_receipt_hash: String,
        authorization: SignedActionAuthorization,
    ) -> Result<VoyageServiceReceipt, LedgerError> {
        let payload_hash = action_payload_hash(
            "SETTLE_VOYAGE_HOP",
            &[
                voyage_id.as_bytes(),
                node_id.as_bytes(),
                &amount.0.to_be_bytes(),
                downstream_receipt_hash.as_bytes(),
            ],
        );
        self.verify_node_authorization(
            &authorization,
            &node_id,
            "SETTLE_VOYAGE_HOP",
            &payload_hash,
        )?;
        let voyage = self
            .voyage_escrows
            .get(voyage_id)
            .cloned()
            .ok_or_else(|| LedgerError::VoyageNotFound(voyage_id.into()))?;
        if voyage.status != VoyageStatus::Open
            || node_id == voyage.payer
            || amount.is_zero()
            || amount > voyage.max_reward_per_hop
            || amount > voyage.remaining_budget
            || downstream_receipt_hash.trim().is_empty()
            || voyage
                .settled_proof_hashes
                .contains(&downstream_receipt_hash)
        {
            return Err(LedgerError::ServiceState);
        }
        let escrow_coin_id = voyage.escrow_coin_id.ok_or(LedgerError::ServiceState)?;
        let escrow_coin = self
            .coins
            .get(&escrow_coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(escrow_coin_id.clone()))?;
        if escrow_coin.state != CoinState::Reserved || escrow_coin.amount != voyage.remaining_budget
        {
            return Err(LedgerError::ServiceState);
        }
        self.require_local_value_commitment(&voyage.voyage_id, voyage.original_budget)?;
        let remaining = voyage.remaining_budget.checked_sub(amount)?;
        let next_version = Self::checked_next_coin_version(escrow_coin.version)?;
        let sequence_steps = 2 + u64::from(!remaining.is_zero());
        self.ensure_counter_headroom(1, sequence_steps)?;

        self.consume_authorization(&authorization)?;
        self.advance()?;
        self.consume_coin(&escrow_coin_id)?;
        let reward = self.make_coin(
            node_id.clone(),
            amount,
            CoinState::Spendable,
            vec![escrow_coin.object_id.clone()],
            Some(escrow_coin.lineage_root.clone()),
            None,
            escrow_coin.imported_from.clone(),
            next_version,
        )?;
        self.coins.insert(reward.object_id.clone(), reward);
        let next_escrow_coin_id = if remaining.is_zero() {
            None
        } else {
            let next = self.make_coin(
                voyage.payer.clone(),
                remaining,
                CoinState::Reserved,
                vec![escrow_coin.object_id],
                Some(escrow_coin.lineage_root),
                None,
                escrow_coin.imported_from,
                next_version,
            )?;
            let id = next.object_id.clone();
            self.coins.insert(id.clone(), next);
            Some(id)
        };
        let receipt = VoyageServiceReceipt {
            receipt_id: self.next_id("voyage-receipt")?,
            voyage_id: voyage_id.into(),
            transit_id: voyage.transit_id,
            node_id: node_id.clone(),
            amount,
            downstream_receipt_hash: downstream_receipt_hash.clone(),
            completed_height: self.height,
        };
        self.voyage_receipts
            .insert(receipt.receipt_id.clone(), receipt.clone());
        let record = self
            .voyage_escrows
            .get_mut(voyage_id)
            .expect("voyage was checked");
        record.remaining_budget = remaining;
        record.escrow_coin_id = next_escrow_coin_id;
        record.settled_proof_hashes.push(downstream_receipt_hash);
        if remaining.is_zero() {
            record.status = VoyageStatus::Completed;
        }
        self.record_earnings(&node_id, &ServiceRole::Relay, amount, &receipt.receipt_id)?;
        self.assert_conservation()?;
        Ok(receipt)
    }

    pub fn activate_testnet_era(
        &mut self,
        new_suite: CryptoSuiteDescriptor,
    ) -> Result<EraContinuityCertificate, LedgerError> {
        if !self.descriptor.testnet {
            return Err(LedgerError::TestnetOnly);
        }
        if !self.descriptor.validator_keys.is_empty() || !self.descriptor.notary_keys.is_empty() {
            return Err(LedgerError::EraTransition(
                "simulated era activation is disabled for configured signer sets; submit a signed certificate"
                    .into(),
            ));
        }
        let previous_certificate_hash = self
            .era_certificates
            .last()
            .map(|certificate| certificate.certificate_hash.clone())
            .unwrap_or_else(|| self.era_continuity_accumulator.clone());
        let activation_checkpoint = self
            .latest_checkpoint()
            .map(|checkpoint| checkpoint.checkpoint_hash.clone())
            .ok_or_else(|| LedgerError::EraTransition("activation checkpoint missing".into()))?;
        let new_protocol_era =
            self.descriptor.protocol_era.checked_add(1).ok_or_else(|| {
                LedgerError::EraTransition("protocol era counter overflow".into())
            })?;
        let new_crypto_era = self
            .descriptor
            .crypto_era
            .checked_add(1)
            .ok_or_else(|| LedgerError::EraTransition("crypto era counter overflow".into()))?;
        let irreversible_height = self
            .height
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("ledger height counter overflow".into()))?;
        let mut certificate = EraContinuityCertificate {
            zone_id: self.descriptor.zone_id.clone(),
            previous_protocol_era: self.descriptor.protocol_era,
            new_protocol_era,
            previous_crypto_era: self.descriptor.crypto_era,
            new_crypto_era,
            previous_certificate_hash,
            activation_checkpoint,
            irreversible_height,
            new_suite,
            previous_validator_keys: self.descriptor.validator_keys.clone(),
            previous_notary_keys: self.descriptor.notary_keys.clone(),
            new_validator_keys: self.descriptor.validator_keys.clone(),
            new_notary_keys: self.descriptor.notary_keys.clone(),
            old_crypto_qc: simulated_qc(),
            new_crypto_qc: simulated_qc(),
            notary_qc: simulated_qc(),
            certificate_hash: String::new(),
        };
        let subject = certificate.subject_hash();
        certificate.certificate_hash.clone_from(&subject);
        certificate.old_crypto_qc.subject_hash.clone_from(&subject);
        certificate.new_crypto_qc.subject_hash.clone_from(&subject);
        certificate.notary_qc.subject_hash = subject;
        self.apply_era_transition(certificate.clone())?;
        Ok(certificate)
    }

    pub fn apply_era_transition(
        &mut self,
        certificate: EraContinuityCertificate,
    ) -> Result<ContinuityCheckpoint, LedgerError> {
        certificate
            .new_suite
            .validate_reference_implementation(self.descriptor.testnet)
            .map_err(LedgerError::EraTransition)?;
        let subject = certificate.subject_hash();
        let expected_protocol_era =
            self.descriptor.protocol_era.checked_add(1).ok_or_else(|| {
                LedgerError::EraTransition("protocol era counter overflow".into())
            })?;
        let expected_crypto_era = self
            .descriptor
            .crypto_era
            .checked_add(1)
            .ok_or_else(|| LedgerError::EraTransition("crypto era counter overflow".into()))?;
        let expected_height = self
            .height
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("ledger height counter overflow".into()))?;
        let expected_previous_certificate_hash = self
            .era_certificates
            .last()
            .map(|previous| previous.certificate_hash.as_str())
            .unwrap_or(self.era_continuity_accumulator.as_str());
        if certificate.zone_id != self.descriptor.zone_id
            || certificate.previous_certificate_hash != expected_previous_certificate_hash
            || certificate.previous_protocol_era != self.descriptor.protocol_era
            || certificate.previous_crypto_era != self.descriptor.crypto_era
            || certificate.new_protocol_era != expected_protocol_era
            || certificate.new_crypto_era != expected_crypto_era
            || certificate.previous_validator_keys != self.descriptor.validator_keys
            || certificate.previous_notary_keys != self.descriptor.notary_keys
            || certificate.certificate_hash != subject
            || certificate.old_crypto_qc.subject_hash != subject
            || certificate.new_crypto_qc.subject_hash != subject
            || certificate.notary_qc.subject_hash != subject
            || certificate.irreversible_height != expected_height
            || certificate.new_suite.suite_id.trim().is_empty()
        {
            return Err(LedgerError::EraTransition(
                "era certificate binding mismatch".into(),
            ));
        }
        let latest = self
            .latest_checkpoint()
            .map(|checkpoint| checkpoint.checkpoint_hash.as_str())
            .unwrap_or_default();
        if certificate.activation_checkpoint != latest {
            return Err(LedgerError::EraTransition(
                "activation checkpoint mismatch".into(),
            ));
        }
        let simulated = certificate.old_crypto_qc.testnet_simulated
            && certificate.new_crypto_qc.testnet_simulated
            && certificate.notary_qc.testnet_simulated;
        let simulation_allowed = self.descriptor.testnet
            && certificate.previous_validator_keys.is_empty()
            && certificate.previous_notary_keys.is_empty()
            && certificate.new_validator_keys.is_empty()
            && certificate.new_notary_keys.is_empty();
        if simulated && !simulation_allowed {
            return Err(LedgerError::InvalidQuorum(
                "simulated era quorum is forbidden for a configured signer set".into(),
            ));
        }
        if !simulated {
            certificate
                .old_crypto_qc
                .verify(&certificate.previous_validator_keys)
                .map_err(LedgerError::InvalidQuorum)?;
            certificate
                .new_crypto_qc
                .verify(&certificate.new_validator_keys)
                .map_err(LedgerError::InvalidQuorum)?;
            certificate
                .notary_qc
                .verify(&certificate.previous_notary_keys)
                .map_err(LedgerError::InvalidQuorum)?;
        }
        if self
            .stake_resource_accounting
            .as_ref()
            .is_some_and(StakeStateResourceAccountingV1::has_accounted_value)
        {
            return Err(LedgerError::EraTransition(
                "stake resource accounting carries value and no cross-era migration exists".into(),
            ));
        }
        self.ensure_counter_headroom(1, 0)?;
        let mut staged = self.clone();
        staged.advance()?;
        // R6.19 has no authenticated cross-era resource-accounting migration.
        // A value-empty policy plane can be retired safely; immutable governance
        // history remains available for replay and audit under its original era.
        staged.pending_stake_resource_policy = None;
        staged.stake_resource_accounting = None;
        staged.descriptor.protocol_era = certificate.new_protocol_era;
        staged.descriptor.crypto_era = certificate.new_crypto_era;
        staged.descriptor.validator_keys = certificate.new_validator_keys.clone();
        staged.descriptor.notary_keys = certificate.new_notary_keys.clone();
        staged.era_continuity_accumulator = hash_parts(&[
            staged.era_continuity_accumulator.as_bytes(),
            certificate.certificate_hash.as_bytes(),
        ]);
        staged.era_certificates.push(certificate);
        let checkpoint = staged.create_checkpoint()?;
        *self = staged;
        Ok(checkpoint)
    }

    pub fn supply_buckets(&self) -> Result<SupplyBuckets, LedgerError> {
        let payment_fee_pools = self
            .epoch_fee_pools
            .values()
            .try_fold(Amount::ZERO, |total, pool| {
                total.checked_add(pool.collected)
            })?;
        let stake_resource_pool =
            self.stake_resource_accounting
                .as_ref()
                .map_or(Ok(Amount::ZERO), |accounting| {
                    accounting
                        .maintenance_pool()
                        .total_charged_fees
                        .checked_add(accounting.maintenance_pool().total_forfeited_bonds)
                })?;
        let fee_pools = payment_fee_pools.checked_add(stake_resource_pool)?;
        let mut buckets = SupplyBuckets {
            reserve: self.reserve,
            fee_pools,
            imported_total: self.imported_total,
            finalized_export_total: self.finalized_export_total,
            ..SupplyBuckets::default()
        };
        for coin in self.coins.values() {
            let target = match coin.state {
                CoinState::Spendable => &mut buckets.spendable,
                CoinState::Reserved => &mut buckets.reserved,
                CoinState::InTransit => &mut buckets.in_transit,
                CoinState::Returning => &mut buckets.returning,
                CoinState::Quarantined => &mut buckets.quarantined,
                CoinState::Consumed => continue,
            };
            *target = target.checked_add(coin.amount)?;
        }
        Ok(buckets)
    }

    pub fn supply_certificate(&self) -> Result<SupplyConservationCertificate, LedgerError> {
        let buckets = self.supply_buckets()?;
        let position = buckets
            .conservation_position()
            .map_err(LedgerError::Supply)?;
        let reserve_pool_total = self.reserve_pools.total().map_err(LedgerError::Supply)?;
        let mut leaves = Vec::new();
        for coin in self
            .coins
            .values()
            .filter(|coin| coin.state.carries_supply())
        {
            leaves.extend_from_slice(coin.object_id.as_bytes());
            leaves.extend_from_slice(&coin.amount.0.to_be_bytes());
            leaves.extend_from_slice(format!("{:?}", coin.state).as_bytes());
        }
        leaves.extend_from_slice(&self.reserve.0.to_be_bytes());
        leaves.extend_from_slice(&self.reserve_pools.startup_services.0.to_be_bytes());
        leaves.extend_from_slice(&self.reserve_pools.continuity_services.0.to_be_bytes());
        leaves.extend_from_slice(&self.reserve_pools.demand_matching.0.to_be_bytes());
        for (pricing_epoch, pool) in &self.epoch_fee_pools {
            leaves.extend_from_slice(&pricing_epoch.to_be_bytes());
            leaves.extend_from_slice(&pool.collected.0.to_be_bytes());
            leaves.extend_from_slice(&pool.charged_payments.to_be_bytes());
        }
        if let Some(accounting) = &self.stake_resource_accounting {
            let pool = accounting.maintenance_pool();
            leaves.extend_from_slice(b"RLD-STAKE-RESOURCE-POOL-V2");
            leaves.extend_from_slice(pool.pool_commitment.as_bytes());
            leaves.extend_from_slice(&pool.total_charged_fees.0.to_be_bytes());
            leaves.extend_from_slice(&pool.total_forfeited_bonds.0.to_be_bytes());
            leaves.extend_from_slice(&pool.total_live_bonds.0.to_be_bytes());
            leaves.extend_from_slice(&pool.total_refunded_bonds.0.to_be_bytes());
        }
        Ok(SupplyConservationCertificate {
            zone_id: self.descriptor.zone_id.clone(),
            height: self.height,
            merkle_sum_root: hash_bytes(&leaves),
            buckets,
            reserve_pools: self.reserve_pools.clone(),
            conservation_position: position,
            anchor_supply: self.anchor_supply,
            valid: position == self.anchor_supply && reserve_pool_total == self.reserve,
        })
    }

    pub fn assert_conservation(&self) -> Result<(), LedgerError> {
        self.validate_consensus_stake_escrows()?;
        self.validate_consensus_stake_slashes()?;
        self.validate_stake_position_liability_horizons()?;
        self.validate_stake_resource_policy_state()?;
        let reserve_pool_total = self.reserve_pools.total().map_err(LedgerError::Supply)?;
        if reserve_pool_total != self.reserve {
            return Err(LedgerError::Supply(format!(
                "protocol reserve pools {} do not equal reserve {}",
                reserve_pool_total, self.reserve
            )));
        }
        for pool in [
            ProtocolReservePoolKind::StartupServices,
            ProtocolReservePoolKind::ContinuityServices,
            ProtocolReservePoolKind::DemandMatching,
        ] {
            self.available_protocol_reserve(&pool)?;
        }
        let certificate = self.supply_certificate()?;
        if certificate.valid {
            Ok(())
        } else {
            Err(LedgerError::Supply(format!(
                "position {} does not equal anchor {}",
                certificate.conservation_position, certificate.anchor_supply
            )))
        }
    }

    pub fn create_checkpoint(&mut self) -> Result<ContinuityCheckpoint, LedgerError> {
        let state_root = self.state_root()?;
        let supply = self.supply_certificate()?;
        let previous_checkpoint = self
            .checkpoints
            .last()
            .map(|checkpoint| checkpoint.checkpoint_hash.clone());
        let checkpoint_hash = hash_parts(&[
            self.descriptor.zone_id.as_bytes(),
            &self.height.to_be_bytes(),
            state_root.as_bytes(),
            supply.merkle_sum_root.as_bytes(),
            previous_checkpoint
                .as_deref()
                .unwrap_or_default()
                .as_bytes(),
        ]);
        let checkpoint = ContinuityCheckpoint {
            zone_id: self.descriptor.zone_id.clone(),
            height: self.height,
            state_root,
            supply,
            protocol_era: self.descriptor.protocol_era,
            crypto_era: self.descriptor.crypto_era,
            previous_checkpoint,
            checkpoint_hash,
        };
        self.checkpoints.push(checkpoint.clone());
        Ok(checkpoint)
    }

    pub fn latest_checkpoint(&self) -> Option<&ContinuityCheckpoint> {
        self.checkpoints.last()
    }

    pub fn audit_proof_bundle(&self) -> Result<AuditProofBundle, LedgerError> {
        let mut snapshot = self.clone();
        let final_checkpoint = snapshot.create_checkpoint()?;
        let mut bundle = AuditProofBundle {
            zone_descriptor: snapshot.descriptor.clone(),
            currency_genesis_root: snapshot.descriptor.currency_genesis_root.clone(),
            generated_height: snapshot.height,
            checkpoints: snapshot.checkpoints.clone(),
            era_certificates: snapshot.era_certificates.clone(),
            coin_history: snapshot.coins.values().cloned().collect(),
            payments: snapshot.payments.values().cloned().collect(),
            transits: snapshot.transits.values().cloned().collect(),
            import_receipts: snapshot.import_receipts.values().cloned().collect(),
            rejection_proofs: snapshot.rejection_proofs.values().cloned().collect(),
            recipient_receipts: snapshot.recipient_receipts.values().cloned().collect(),
            liquidity_offers: snapshot.liquidity_offers.values().cloned().collect(),
            route_quotes: snapshot.route_quotes.values().cloned().collect(),
            epoch_fee_pools: snapshot.epoch_fee_pools.values().cloned().collect(),
            service_orders: snapshot.service_orders.values().cloned().collect(),
            service_leases: snapshot.service_leases.values().cloned().collect(),
            protocol_reserve_commitments: snapshot
                .protocol_reserve_commitments
                .values()
                .cloned()
                .collect(),
            economic_control_attestations: snapshot
                .economic_control_attestations
                .values()
                .cloned()
                .collect(),
            economic_price_attestations: snapshot
                .economic_price_attestations
                .values()
                .cloned()
                .collect(),
            economic_release_policies: snapshot
                .economic_release_policies
                .values()
                .cloned()
                .collect(),
            protocol_service_bonds: snapshot.protocol_service_bonds.values().cloned().collect(),
            protocol_reserve_releases: snapshot
                .protocol_reserve_releases
                .values()
                .cloned()
                .collect(),
            consensus_commits: snapshot.consensus_commits.values().cloned().collect(),
            m0_network_birth: snapshot.m0_network_birth.clone(),
            m0_network_birth_v3: snapshot.m0_network_birth_v3.clone(),
            m0_active_protocol: snapshot.m0_active_protocol.clone(),
            m0_pending_upgrade: snapshot.m0_pending_upgrade.clone(),
            admission_state: snapshot.admission_state.clone(),
            consensus_stake_authority: snapshot.consensus_stake_authority.clone(),
            consensus_stake_escrows: snapshot.consensus_stake_escrows.values().cloned().collect(),
            consensus_stake_unbonds: snapshot.consensus_stake_unbonds.values().cloned().collect(),
            consensus_stake_slashes: snapshot.consensus_stake_slashes.values().cloned().collect(),
            derived_stake_epochs: snapshot.derived_stake_epochs.values().cloned().collect(),
            stake_position_liability_horizons: snapshot.stake_position_liability_horizons.clone(),
            stake_position_liability_horizon_history: snapshot
                .stake_position_liability_horizon_history
                .clone(),
            stake_liability_horizon_activation_epoch: snapshot
                .stake_liability_horizon_activation_epoch,
            stake_resource_policy_proposals: snapshot
                .stake_resource_policy_proposals
                .values()
                .cloned()
                .collect(),
            stake_resource_policy_activations: snapshot
                .stake_resource_policy_activations
                .values()
                .cloned()
                .collect(),
            pending_stake_resource_policy: snapshot.pending_stake_resource_policy.clone(),
            stake_resource_accounting: snapshot.stake_resource_accounting.clone(),
            authorization_nullifiers: snapshot.authorization_nullifiers.clone(),
            gateway_bonds: snapshot.gateway_bonds.values().cloned().collect(),
            service_receipts: snapshot.service_receipts.values().cloned().collect(),
            voyage_receipts: snapshot.voyage_receipts.values().cloned().collect(),
            final_state_root: final_checkpoint.state_root,
            commitment_hash: String::new(),
        };
        bundle.commitment_hash = bundle
            .compute_commitment()
            .map_err(LedgerError::InvalidOperationalProof)?;
        bundle
            .verify_structure()
            .map_err(LedgerError::InvalidOperationalProof)?;
        Ok(bundle)
    }

    pub fn state_root(&self) -> Result<String, LedgerError> {
        let root_before_admission = self.state_root_before_admission()?;
        let base = match (self.m0_admission_genesis()?, &self.admission_state) {
            (None, None) => Ok(root_before_admission),
            (Some(_), None) => Err(LedgerError::Invalid(
                "M0 network-birth binding has no required admission trust state".into(),
            )),
            (None, Some(_)) => Err(LedgerError::Invalid(
                "ledger admission state cannot exist without an M0 network-birth binding".into(),
            )),
            (Some(admission_genesis), Some(admission_state)) => {
                admission_state
                    .validate_for_descriptor(&self.descriptor)
                    .map_err(|error| LedgerError::Invalid(error.to_string()))?;
                if admission_genesis != &admission_state.genesis {
                    return Err(LedgerError::Invalid(
                        "ledger admission state differs from the signed M0 network-birth trust root"
                            .into(),
                    ));
                }
                let extension_bytes = serde_json::to_vec(&(
                    "RLD-LEDGER-PERMISSIONLESS-ADMISSION-EXTENSION-V1",
                    admission_state,
                ))
                .map_err(|error| LedgerError::Invalid(error.to_string()))?;
                Ok(hash_parts(&[
                    b"RLD-LEDGER-STATE-ROOT-PERMISSIONLESS-ADMISSION-EXTENSION-V1",
                    root_before_admission.as_bytes(),
                    &extension_bytes,
                ]))
            }
        }?;
        if let Some(pending) = &self.m0_pending_upgrade {
            Ok(hash_parts(&[
                b"RLD-LEDGER-STATE-ROOT-PENDING-UPGRADE-V1",
                base.as_bytes(),
                &pending.canonical_bytes().map_err(LedgerError::Invalid)?,
            ]))
        } else {
            Ok(base)
        }
    }

    pub(crate) fn state_root_before_admission(&self) -> Result<String, LedgerError> {
        let base_bytes = serde_json::to_vec(&(
            (
                &self.descriptor,
                self.height,
                self.anchor_supply,
                self.reserve,
                &self.reserve_pools,
                self.imported_total,
                self.finalized_export_total,
                &self.value_risk_policy,
                &self.consensus_stake_authority,
                &self.consensus_stake_escrows,
                &self.consensus_stake_unbonds,
                &self.consensus_stake_slashes,
                &self.consensus_stake_evidence_nullifiers,
                &self.derived_stake_epochs,
                &self.epoch_fee_pools,
                self.sequence,
            ),
            (
                (
                    &self.coins,
                    &self.payments,
                    &self.payment_requests,
                    &self.consumed_payment_requests,
                    &self.recipient_receipts,
                    &self.liquidity_offers,
                    &self.route_quotes,
                    &self.spendability_certificates,
                ),
                (
                    &self.transits,
                    &self.transit_coin_ids,
                    &self.import_receipts,
                    &self.transit_nullifiers,
                    &self.rejected_transit_nullifiers,
                    &self.rejection_proofs,
                    &self.source_object_nullifiers,
                    &self.authorization_nullifiers,
                ),
                (
                    &self.zone_trust_policies,
                    &self.quarantined_zones,
                    &self.trusted_zone_checkpoints,
                    &self.gateway_bonds,
                    &self.zone_advertisements,
                    &self.traveler_capsules,
                ),
                (
                    &self.service_orders,
                    &self.service_leases,
                    &self.protocol_reserve_commitments,
                    (
                        &self.economic_control_attestations,
                        &self.economic_price_attestations,
                        &self.economic_release_policies,
                        &self.protocol_service_bonds,
                        &self.protocol_reserve_releases,
                        &self.economic_consumed_work_ids,
                        &self.economic_consumed_fee_receipts,
                        &self.economic_consumed_completion_qcs,
                        &self.economic_bond_slash_ids,
                    ),
                    &self.matched_service_receipts,
                    &self.service_receipts,
                    &self.node_earnings,
                    &self.voyage_escrows,
                    &self.voyage_receipts,
                    &self.bootstrap_claims,
                ),
                (&self.era_continuity_accumulator, &self.causal_firewall),
            ),
        ))
        .map_err(|error| LedgerError::Invalid(error.to_string()))?;
        let base_root = hash_bytes(&base_bytes);
        let stake_root = if self.stake_resource_policy_proposals.is_empty()
            && self.stake_resource_policy_activations.is_empty()
            && self.pending_stake_resource_policy.is_none()
            && self.stake_resource_accounting.is_none()
            && self.stake_position_liability_horizons.is_empty()
            && self.stake_position_liability_horizon_history.is_empty()
            && self.stake_liability_horizon_activation_epoch.is_none()
        {
            base_root
        } else if self.stake_position_liability_horizons.is_empty()
            && self.stake_position_liability_horizon_history.is_empty()
            && self.stake_liability_horizon_activation_epoch.is_none()
        {
            let extension_bytes = serde_json::to_vec(&(
                "RLD-LEDGER-STAKE-RESOURCE-EXTENSION-V1",
                &self.stake_resource_policy_proposals,
                &self.stake_resource_policy_activations,
                &self.pending_stake_resource_policy,
                &self.stake_resource_accounting,
            ))
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
            hash_parts(&[
                b"RLD-LEDGER-STATE-ROOT-STAKE-RESOURCE-EXTENSION-V1",
                base_root.as_bytes(),
                &extension_bytes,
            ])
        } else {
            let extension_bytes = serde_json::to_vec(&(
                "RLD-LEDGER-STAKE-RESOURCE-EXTENSION-V2",
                &self.stake_resource_policy_proposals,
                &self.stake_resource_policy_activations,
                &self.pending_stake_resource_policy,
                &self.stake_resource_accounting,
                &self.stake_position_liability_horizons,
                &self.stake_position_liability_horizon_history,
                &self.stake_liability_horizon_activation_epoch,
            ))
            .map_err(|error| LedgerError::Invalid(error.to_string()))?;
            hash_parts(&[
                b"RLD-LEDGER-STATE-ROOT-STAKE-RESOURCE-EXTENSION-V2",
                base_root.as_bytes(),
                &extension_bytes,
            ])
        };
        self.m0_admission_genesis()?;
        if let (Some(birth), Some(active)) = (&self.m0_network_birth_v3, &self.m0_active_protocol) {
            Ok(hash_parts(&[
                b"RLD-LEDGER-STATE-ROOT-M0-NETWORK-BIRTH-EXTENSION-V3",
                stake_root.as_bytes(),
                &birth.canonical_bytes().map_err(LedgerError::Invalid)?,
                &active.canonical_bytes().map_err(LedgerError::Invalid)?,
            ]))
        } else if let Some(network_birth) = &self.m0_network_birth {
            let extension_bytes =
                serde_json::to_vec(&("RLD-LEDGER-M0-NETWORK-BIRTH-EXTENSION-V2", network_birth))
                    .map_err(|error| LedgerError::Invalid(error.to_string()))?;
            Ok(hash_parts(&[
                b"RLD-LEDGER-STATE-ROOT-M0-NETWORK-BIRTH-EXTENSION-V2",
                stake_root.as_bytes(),
                &extension_bytes,
            ]))
        } else {
            Ok(stake_root)
        }
    }

    fn verify_source_acceptance(
        &self,
        capsule: &TransitCapsule,
        subject: &str,
        policy: &ZoneTrustPolicy,
    ) -> Result<(), LedgerError> {
        if capsule.validator_qc.subject_hash != subject {
            return Err(LedgerError::InvalidQuorum(
                "validator certificate subject hash mismatch".into(),
            ));
        }
        self.verify_source_quorum(
            &capsule.validator_qc,
            &capsule.source_descriptor.validator_keys,
            capsule.source_descriptor.testnet,
            "validator",
        )?;

        match policy {
            ZoneTrustPolicy::DualQc => {
                if capsule.notary_qc.subject_hash != subject {
                    return Err(LedgerError::InvalidQuorum(
                        "notary certificate subject hash mismatch".into(),
                    ));
                }
                if capsule
                    .source_descriptor
                    .validator_keys
                    .iter()
                    .any(|key| capsule.source_descriptor.notary_keys.contains(key))
                {
                    return Err(LedgerError::InvalidQuorum(
                        "validator and independent notary sets overlap".into(),
                    ));
                }
                self.verify_source_quorum(
                    &capsule.notary_qc,
                    &capsule.source_descriptor.notary_keys,
                    capsule.source_descriptor.testnet,
                    "notary",
                )?;
            }
            ZoneTrustPolicy::LightClient => {
                let trusted = self
                    .trusted_zone_checkpoints
                    .get(&capsule.source_zone)
                    .is_some_and(|checkpoints| checkpoints.contains(&capsule.source_checkpoint));
                if !trusted {
                    return Err(LedgerError::InvalidOperationalProof(
                        "source checkpoint is not anchored by the destination light client".into(),
                    ));
                }
            }
            ZoneTrustPolicy::BondedGateway => {
                let endorsement = capsule.gateway_endorsement.as_ref().ok_or_else(|| {
                    LedgerError::InvalidQuorum(
                        "bonded-gateway policy requires a gateway endorsement".into(),
                    )
                })?;
                endorsement
                    .verify(capsule)
                    .map_err(LedgerError::InvalidSignature)?;
                let bond = self
                    .gateway_bonds
                    .get(&endorsement.bond_id)
                    .ok_or_else(|| {
                        LedgerError::InvalidQuorum("gateway bond is not registered locally".into())
                    })?;
                let escrow = self.coins.get(&bond.escrow_coin_id).ok_or_else(|| {
                    LedgerError::InvalidQuorum("gateway bond escrow coin is missing".into())
                })?;
                if bond.status != GatewayBondStatus::Active
                    || bond.source_zone != capsule.source_zone
                    || bond.gateway_public_key != endorsement.gateway_public_key
                    || bond.amount.is_zero()
                    || escrow.state != CoinState::Reserved
                    || escrow.owner != bond.owner
                    || escrow.amount != bond.amount
                {
                    return Err(LedgerError::InvalidQuorum(
                        "gateway endorsement is not backed by an active local RLD bond".into(),
                    ));
                }
            }
            ZoneTrustPolicy::ObserveOnly | ZoneTrustPolicy::Quarantined => {
                return Err(LedgerError::SourceZoneQuarantined(
                    capsule.source_zone.clone(),
                ));
            }
        }
        Ok(())
    }

    fn verify_source_quorum(
        &self,
        certificate: &QuorumCertificate,
        allowed_keys: &[String],
        source_is_testnet: bool,
        role: &str,
    ) -> Result<(), LedgerError> {
        if certificate.testnet_simulated {
            if self.descriptor.testnet && source_is_testnet && allowed_keys.is_empty() {
                return Ok(());
            }
            return Err(LedgerError::InvalidQuorum(format!(
                "simulated {role} quorum is forbidden for this signer set"
            )));
        }
        certificate
            .verify(allowed_keys)
            .map_err(LedgerError::InvalidQuorum)
    }

    fn verify_local_dual_quorum(
        &self,
        subject: &str,
        validator_qc: &QuorumCertificate,
        notary_qc: &QuorumCertificate,
    ) -> Result<(), LedgerError> {
        if validator_qc.subject_hash != subject || notary_qc.subject_hash != subject {
            return Err(LedgerError::InvalidQuorum("subject hash mismatch".into()));
        }
        let simulated = validator_qc.testnet_simulated && notary_qc.testnet_simulated;
        if simulated {
            if self.descriptor.testnet
                && self.descriptor.validator_keys.is_empty()
                && self.descriptor.notary_keys.is_empty()
            {
                return Ok(());
            }
            return Err(LedgerError::InvalidQuorum(
                "simulated dual quorum is forbidden for this Zone".into(),
            ));
        }
        if validator_qc.testnet_simulated || notary_qc.testnet_simulated {
            return Err(LedgerError::InvalidQuorum(
                "validator and notary quorum modes must match".into(),
            ));
        }
        validator_qc
            .verify(&self.descriptor.validator_keys)
            .map_err(LedgerError::InvalidQuorum)?;
        notary_qc
            .verify(&self.descriptor.notary_keys)
            .map_err(LedgerError::InvalidQuorum)
    }

    fn verify_owner_authorization(
        &self,
        authorization: &SignedActionAuthorization,
        owner: &str,
        action: &str,
        payload_hash: &str,
    ) -> Result<(), LedgerError> {
        if self
            .authorization_nullifiers
            .contains(&authorization.authorization_id)
        {
            return Err(LedgerError::Duplicate(
                authorization.authorization_id.clone(),
            ));
        }
        authorization
            .verify_scope(
                &self.descriptor.zone_id,
                &self.descriptor.currency_genesis_root,
                self.descriptor.protocol_era,
                self.descriptor.crypto_era,
                action,
                payload_hash,
            )
            .map_err(LedgerError::InvalidSignature)?;
        if authorization.signer_address() != owner {
            return Err(LedgerError::OwnerMismatch);
        }
        Ok(())
    }

    fn verify_node_authorization(
        &self,
        authorization: &SignedActionAuthorization,
        node_id: &str,
        action: &str,
        payload_hash: &str,
    ) -> Result<(), LedgerError> {
        if self
            .authorization_nullifiers
            .contains(&authorization.authorization_id)
        {
            return Err(LedgerError::Duplicate(
                authorization.authorization_id.clone(),
            ));
        }
        authorization
            .verify_scope(
                &self.descriptor.zone_id,
                &self.descriptor.currency_genesis_root,
                self.descriptor.protocol_era,
                self.descriptor.crypto_era,
                action,
                payload_hash,
            )
            .map_err(LedgerError::InvalidSignature)?;
        let canonical_node_id = format!("rld-node:{}", authorization.signer_public_key);
        if node_id != authorization.signer_public_key && node_id != canonical_node_id {
            return Err(LedgerError::OwnerMismatch);
        }
        Ok(())
    }

    fn consume_authorization(
        &mut self,
        authorization: &SignedActionAuthorization,
    ) -> Result<(), LedgerError> {
        if !self
            .authorization_nullifiers
            .insert(authorization.authorization_id.clone())
        {
            return Err(LedgerError::Duplicate(
                authorization.authorization_id.clone(),
            ));
        }
        Ok(())
    }

    fn verify_era_certificate(&self, capsule: &TransitCapsule) -> Result<(), LedgerError> {
        let Some(certificate) = &capsule.era_certificate else {
            let genesis_era_hash = hash_parts(&[
                b"RLD-GENESIS-ERA",
                capsule.source_zone.as_bytes(),
                &capsule.source_descriptor.protocol_era.to_be_bytes(),
                &capsule.source_descriptor.crypto_era.to_be_bytes(),
            ]);
            if capsule.source_descriptor.protocol_era != 1
                || capsule.source_descriptor.crypto_era != 1
                || capsule.operational_proof.era_certificate_hash != genesis_era_hash
            {
                return Err(LedgerError::EraTransition(
                    "missing non-genesis era certificate".into(),
                ));
            }
            return Ok(());
        };

        certificate
            .new_suite
            .validate_reference_implementation(
                self.descriptor.testnet && capsule.source_descriptor.testnet,
            )
            .map_err(LedgerError::EraTransition)?;
        let subject = certificate.subject_hash();
        if certificate.zone_id != capsule.source_zone
            || certificate.new_protocol_era != capsule.source_descriptor.protocol_era
            || certificate.new_crypto_era != capsule.source_descriptor.crypto_era
            || certificate.new_validator_keys != capsule.source_descriptor.validator_keys
            || certificate.new_notary_keys != capsule.source_descriptor.notary_keys
            || certificate.certificate_hash != subject
            || capsule.operational_proof.era_certificate_hash != subject
            || certificate.old_crypto_qc.subject_hash != subject
            || certificate.new_crypto_qc.subject_hash != subject
            || certificate.notary_qc.subject_hash != subject
        {
            return Err(LedgerError::EraTransition(
                "era certificate does not bind the source descriptor".into(),
            ));
        }
        let simulated = certificate.old_crypto_qc.testnet_simulated
            && certificate.new_crypto_qc.testnet_simulated
            && certificate.notary_qc.testnet_simulated;
        let simulation_allowed = self.descriptor.testnet
            && capsule.source_descriptor.testnet
            && certificate.previous_validator_keys.is_empty()
            && certificate.previous_notary_keys.is_empty()
            && certificate.new_validator_keys.is_empty()
            && certificate.new_notary_keys.is_empty();
        if simulated && simulation_allowed {
            return Ok(());
        }
        if simulated {
            return Err(LedgerError::InvalidQuorum(
                "simulated era quorum is forbidden for a configured signer set".into(),
            ));
        }
        certificate
            .old_crypto_qc
            .verify(&certificate.previous_validator_keys)
            .map_err(LedgerError::InvalidQuorum)?;
        certificate
            .new_crypto_qc
            .verify(&certificate.new_validator_keys)
            .map_err(LedgerError::InvalidQuorum)?;
        certificate
            .notary_qc
            .verify(&certificate.previous_notary_keys)
            .map_err(LedgerError::InvalidQuorum)?;
        Ok(())
    }

    fn validate_intent(
        &self,
        intent: &UniversalPaymentIntent,
        require_local_destination: bool,
    ) -> Result<(), LedgerError> {
        intent.verify().map_err(LedgerError::InvalidSignature)?;
        if intent.currency_genesis_root != self.descriptor.currency_genesis_root {
            return Err(LedgerError::Invalid(
                "currency genesis root mismatch".into(),
            ));
        }
        if intent.protocol_era != self.descriptor.protocol_era {
            return Err(LedgerError::Invalid("protocol era mismatch".into()));
        }
        if intent.crypto_era != self.descriptor.crypto_era {
            return Err(LedgerError::Invalid("crypto era mismatch".into()));
        }
        if intent.pricing_epoch != LOCAL_PAYMENT_PRICING_EPOCH {
            return Err(LedgerError::Invalid("pricing epoch mismatch".into()));
        }
        if intent.source_zone != self.descriptor.zone_id {
            return Err(LedgerError::Invalid("source Zone mismatch".into()));
        }
        if require_local_destination && intent.destination_zone != self.descriptor.zone_id {
            return Err(LedgerError::Invalid("destination is not local".into()));
        }
        if require_local_destination && intent.route_quote_id.is_some() {
            return Err(LedgerError::Invalid(
                "route quotes apply only to cross-Zone payments".into(),
            ));
        }
        if !require_local_destination && intent.destination_zone == self.descriptor.zone_id {
            return Err(LedgerError::Invalid(
                "use local payment inside one Zone".into(),
            ));
        }
        match (&intent.payment_request_id, &intent.payment_request) {
            (None, None) => {}
            (Some(request_id), Some(request)) => {
                if request_id != &request.request_id {
                    return Err(LedgerError::Invalid(
                        "payment request identifier mismatch".into(),
                    ));
                }
                request.verify().map_err(LedgerError::InvalidSignature)?;
                if request.currency_genesis_root != self.descriptor.currency_genesis_root {
                    return Err(LedgerError::Invalid(
                        "payment request currency genesis root mismatch".into(),
                    ));
                }
                if request.destination_zone != intent.destination_zone
                    || request.recipient != intent.recipient
                    || request.amount != intent.amount
                {
                    return Err(LedgerError::Invalid(
                        "payment intent does not match payment request".into(),
                    ));
                }
                if require_local_destination {
                    self.validate_payment_request_context(request)?;
                    if request.expires_at_height <= self.height {
                        return Err(LedgerError::Invalid("payment request has expired".into()));
                    }
                }
                if self.consumed_payment_requests.contains(request_id) {
                    return Err(LedgerError::Duplicate(request_id.clone()));
                }
                if let Some(registered) = self.payment_requests.get(request_id) {
                    if registered.commitment_hash() != request.commitment_hash() {
                        return Err(LedgerError::Invalid(
                            "registered payment request commitment mismatch".into(),
                        ));
                    }
                }
            }
            _ => {
                return Err(LedgerError::Invalid(
                    "payment request id and signed request must be supplied together".into(),
                ));
            }
        }
        Ok(())
    }

    fn validate_payment_request_context(
        &self,
        request: &PaymentRequest,
    ) -> Result<(), LedgerError> {
        if request.currency_genesis_root != self.descriptor.currency_genesis_root
            || request.protocol_era != self.descriptor.protocol_era
            || request.crypto_era != self.descriptor.crypto_era
        {
            return Err(LedgerError::Invalid(
                "payment request network or era context mismatch".into(),
            ));
        }
        Ok(())
    }

    fn consume_payment_request(
        &mut self,
        intent: &UniversalPaymentIntent,
    ) -> Result<(), LedgerError> {
        if let Some(request_id) = &intent.payment_request_id {
            if !self.consumed_payment_requests.insert(request_id.clone()) {
                return Err(LedgerError::Duplicate(request_id.clone()));
            }
        }
        Ok(())
    }

    fn spendable_owned_coin(
        &self,
        coin_id: &str,
        sender_public_key: &str,
    ) -> Result<CoinObject, LedgerError> {
        let coin = self
            .coins
            .get(coin_id)
            .cloned()
            .ok_or_else(|| LedgerError::CoinNotFound(coin_id.into()))?;
        if coin.state != CoinState::Spendable {
            return Err(LedgerError::CoinNotSpendable);
        }
        let expected = format!("rld:{}:{sender_public_key}", self.descriptor.zone_id);
        if coin.owner != expected {
            return Err(LedgerError::OwnerMismatch);
        }
        Ok(coin)
    }

    fn consume_coin(&mut self, coin_id: &str) -> Result<(), LedgerError> {
        if self.consensus_stake_escrows.contains_key(coin_id) {
            return Err(LedgerError::CoinNotSpendable);
        }
        let coin = self
            .coins
            .get_mut(coin_id)
            .ok_or_else(|| LedgerError::CoinNotFound(coin_id.into()))?;
        if coin.state == CoinState::Consumed {
            return Err(LedgerError::CoinNotSpendable);
        }
        coin.state = CoinState::Consumed;
        Ok(())
    }

    fn ensure_economic_counter_headroom(
        &self,
        height_steps: u64,
        sequence_steps: u64,
    ) -> Result<(), LedgerError> {
        self.ensure_counter_headroom(height_steps, sequence_steps)
            .map_err(|error| LedgerError::Economic(error.to_string()))
    }

    fn ensure_upgrade_height_boundary(&self, steps: u64) -> Result<(), LedgerError> {
        if let Some(pending) = &self.m0_pending_upgrade {
            self.m0_admission_genesis()?;
            if u128::from(self.height) + u128::from(steps) >= pending.schedule.activation_height {
                return Err(LedgerError::Invalid(
                    "scheduled activation required; ordinary height advance is forbidden".into(),
                ));
            }
        }
        Ok(())
    }

    /// Read-only successor evaluator. This does not authenticate a migration,
    /// finalize scheduling, persist state or grant any signing permission.
    pub fn preview_upgrade_schedule(
        &self,
        schedule: &crate::genesis::upgrade_wire::ScheduleUpgradeV1,
    ) -> Result<Self, LedgerError> {
        if self.value_risk_policy.current_cap != crate::ValueCap::ValueCap0
            || self.value_risk_policy.ever_enabled
            || self.value_risk_policy.pending_update.is_some()
        {
            return Err(LedgerError::Invalid(
                "bootstrap upgrade preview requires unchanged VALUE_CAP_0".into(),
            ));
        }
        let pending =
            crate::genesis::upgrade_pending::PendingUpgradeV1::from_parent(self, schedule)
                .map_err(LedgerError::Invalid)?;
        self.ensure_counter_headroom(1, 0)?;
        let mut candidate = self.clone();
        candidate.height += 1;
        candidate.m0_pending_upgrade = Some(pending);
        candidate.state_root()?;
        Ok(candidate)
    }

    fn ensure_counter_headroom(
        &self,
        height_steps: u64,
        sequence_steps: u64,
    ) -> Result<(), LedgerError> {
        self.ensure_upgrade_height_boundary(height_steps)?;
        self.height
            .checked_add(height_steps)
            .ok_or_else(|| LedgerError::Invalid("ledger height counter overflow".into()))?;
        self.sequence.checked_add(sequence_steps).ok_or_else(|| {
            LedgerError::Invalid("ledger object sequence counter overflow".into())
        })?;
        Ok(())
    }

    fn checked_next_coin_version(version: u64) -> Result<u64, LedgerError> {
        version
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("coin version counter overflow".into()))
    }

    fn is_sorted_unique_nonempty(values: &[String]) -> bool {
        !values.is_empty()
            && values.iter().all(|value| !value.trim().is_empty())
            && values.windows(2).all(|pair| pair[0] < pair[1])
    }

    fn economic_member<'a>(
        attestation: &'a EconomicControlAttestation,
        subject_id: &str,
    ) -> Result<&'a crate::EconomicControlMember, LedgerError> {
        attestation
            .members
            .binary_search_by(|member| member.subject_id.as_str().cmp(subject_id))
            .ok()
            .and_then(|index| attestation.members.get(index))
            .ok_or_else(|| {
                LedgerError::Economic(format!(
                    "subject {subject_id} has no persisted UBO control mapping"
                ))
            })
    }

    fn economic_role_for_service(role: &ServiceRole) -> EconomicControlRole {
        match role {
            ServiceRole::Validator => EconomicControlRole::Validator,
            ServiceRole::Notary => EconomicControlRole::Notary,
            ServiceRole::Relay | ServiceRole::Gateway | ServiceRole::FtlGateway => {
                EconomicControlRole::Relay
            }
            ServiceRole::Liquidity => EconomicControlRole::LiquidityProvider,
            ServiceRole::Storage
            | ServiceRole::Archive
            | ServiceRole::ContinuityCustodian
            | ServiceRole::Observer => EconomicControlRole::ServiceProvider,
        }
    }

    fn checked_bps_ceil(value: Amount, bps: u32) -> Result<Amount, LedgerError> {
        let divisor = 10_000u128;
        let multiplier = u128::from(bps);
        let whole = value
            .0
            .checked_div(divisor)
            .and_then(|quotient| quotient.checked_mul(multiplier))
            .ok_or_else(|| LedgerError::Economic("bond coverage calculation overflow".into()))?;
        let remainder_product = (value.0 % divisor)
            .checked_mul(multiplier)
            .ok_or_else(|| LedgerError::Economic("bond coverage calculation overflow".into()))?;
        let rounded_remainder = remainder_product
            .checked_add(divisor - 1)
            .and_then(|rounded| rounded.checked_div(divisor))
            .ok_or_else(|| LedgerError::Economic("bond coverage calculation overflow".into()))?;
        whole
            .checked_add(rounded_remainder)
            .map(Amount::from_runlai)
            .ok_or_else(|| LedgerError::Economic("bond coverage calculation overflow".into()))
    }

    fn protocol_reserve_pool_balance(&self, pool: ProtocolReservePoolKind) -> Amount {
        match pool {
            ProtocolReservePoolKind::StartupServices => self.reserve_pools.startup_services,
            ProtocolReservePoolKind::ContinuityServices => self.reserve_pools.continuity_services,
            ProtocolReservePoolKind::DemandMatching => self.reserve_pools.demand_matching,
        }
    }

    fn protocol_reserve_pool_balance_mut(&mut self, pool: ProtocolReservePoolKind) -> &mut Amount {
        match pool {
            ProtocolReservePoolKind::StartupServices => &mut self.reserve_pools.startup_services,
            ProtocolReservePoolKind::ContinuityServices => {
                &mut self.reserve_pools.continuity_services
            }
            ProtocolReservePoolKind::DemandMatching => &mut self.reserve_pools.demand_matching,
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn make_coin(
        &mut self,
        owner: String,
        amount: Amount,
        state: CoinState,
        parent_ids: Vec<String>,
        lineage_root: Option<String>,
        transit_id: Option<String>,
        imported_from: Option<String>,
        version: u64,
    ) -> Result<CoinObject, LedgerError> {
        let object_id = self.next_id("coin")?;
        let (origin_zone, origin_genesis_root) = parent_ids
            .iter()
            .find_map(|parent_id| self.coins.get(parent_id))
            .map(|parent| {
                (
                    parent.origin_zone.clone(),
                    parent.origin_genesis_root.clone(),
                )
            })
            .unwrap_or_else(|| {
                (
                    self.descriptor.zone_id.clone(),
                    self.descriptor.currency_genesis_root.clone(),
                )
            });
        let lineage_root = lineage_root.unwrap_or_else(|| {
            hash_parts(&[
                self.descriptor.genesis_root.as_bytes(),
                object_id.as_bytes(),
                &amount.0.to_be_bytes(),
            ])
        });
        Ok(CoinObject {
            object_id,
            lineage_root,
            parent_ids,
            owner,
            zone_id: self.descriptor.zone_id.clone(),
            amount,
            state,
            version,
            created_height: self.height,
            transit_id,
            imported_from,
            origin_zone,
            origin_genesis_root,
        })
    }

    fn record_earnings(
        &mut self,
        node_id: &str,
        role: &ServiceRole,
        amount: Amount,
        receipt_id: &str,
    ) -> Result<(), LedgerError> {
        let earnings = self
            .node_earnings
            .entry(node_id.into())
            .or_insert_with(|| NodeEarnings {
                node_id: node_id.into(),
                ..NodeEarnings::default()
            });
        earnings.total = earnings.total.checked_add(amount)?;
        let role_key = format!("{role:?}").to_uppercase();
        let role_total = earnings.by_role.entry(role_key).or_default();
        *role_total = role_total.checked_add(amount)?;
        earnings.receipt_ids.push(receipt_id.into());
        Ok(())
    }

    fn advance(&mut self) -> Result<(), LedgerError> {
        self.ensure_upgrade_height_boundary(1)?;
        self.height = self
            .height
            .checked_add(1)
            .ok_or_else(|| LedgerError::Invalid("ledger height counter overflow".into()))?;
        Ok(())
    }

    fn next_id(&mut self, kind: &str) -> Result<String, LedgerError> {
        self.sequence = self.sequence.checked_add(1).ok_or_else(|| {
            LedgerError::Invalid("ledger object sequence counter overflow".into())
        })?;
        Ok(format!(
            "{kind}-{}",
            &hash_parts(&[
                self.descriptor.zone_id.as_bytes(),
                kind.as_bytes(),
                &self.height.to_be_bytes(),
                &self.sequence.to_be_bytes(),
            ])[..32]
        ))
    }
}

fn protocol_reserve_pools(anchor_supply: Amount) -> Result<ProtocolReservePools, LedgerError> {
    let startup_services = Amount::from_runlai(anchor_supply.0 / 100);
    let continuity_services = Amount::from_runlai(
        startup_services
            .0
            .checked_mul(9)
            .ok_or_else(|| LedgerError::Supply("continuity pool overflow".into()))?,
    );
    let demand_matching = anchor_supply
        .checked_sub(startup_services)?
        .checked_sub(continuity_services)?;
    Ok(ProtocolReservePools {
        startup_services,
        continuity_services,
        demand_matching,
    })
}

fn simulated_qc() -> QuorumCertificate {
    QuorumCertificate {
        subject_hash: String::new(),
        threshold: 0,
        attestations: Vec::new(),
        testnet_simulated: true,
    }
}

fn outbound_qc(keys: &[String]) -> Result<QuorumCertificate, LedgerError> {
    if keys.is_empty() {
        return Ok(simulated_qc());
    }
    let threshold = required_quorum(keys.len())
        .map_err(LedgerError::InvalidQuorum)?
        .try_into()
        .map_err(|_| LedgerError::InvalidQuorum("quorum set exceeds u16".into()))?;
    Ok(QuorumCertificate {
        subject_hash: String::new(),
        threshold,
        attestations: Vec::new(),
        testnet_simulated: false,
    })
}

fn transport_code(transport: &TransportClass) -> &'static str {
    match transport {
        TransportClass::SublightDtn => "SUBLIGHT_DTN",
        TransportClass::CausalFtl => "CAUSAL_FTL",
        TransportClass::CausalWormhole => "CAUSAL_WORMHOLE",
        TransportClass::ChronologyUnsafe => "CHRONOLOGY_UNSAFE",
    }
}

pub fn currency_genesis_root() -> String {
    hash_parts(&[
        b"Rldcoin-v5-currency-genesis",
        &crate::TOTAL_SUPPLY_RUNLAI.to_be_bytes(),
        &crate::RUNLAI_PER_RLD.to_be_bytes(),
    ])
}

