    fn signed_qc(
        subject_hash: &str,
        members: &[crate::Identity],
        signer_count: usize,
    ) -> QuorumCertificate {
        QuorumCertificate {
            subject_hash: subject_hash.into(),
            threshold: required_quorum(members.len()).unwrap().try_into().unwrap(),
            attestations: members
                .iter()
                .take(signer_count)
                .map(|identity| crate::SignedAttestation {
                    public_key: identity.public_key.clone(),
                    signature: sign_bytes(&identity.secret_key, subject_hash.as_bytes()).unwrap(),
                })
                .collect(),
            testnet_simulated: false,
        }
    }

