    fn resource_policy_qc(subject: &str, members: &[crate::Identity]) -> QuorumCertificate {
        if members.is_empty() {
            let mut qc = simulated_qc();
            qc.subject_hash = subject.into();
            qc
        } else {
            signed_qc(subject, members, required_quorum(members.len()).unwrap())
        }
    }

    fn resource_policy_proposal(
        ledger: &Ledger,
        validators: &[crate::Identity],
        notaries: &[crate::Identity],
        proposal_id: &str,
        policy: StakeStateResourcePolicyV1,
        activate_after_height: u64,
        expires_at_height: u64,
    ) -> ProposeStakeStateResourcePolicyV1 {
        let (current_sequence, current_commitment) =
            ledger.current_stake_resource_policy_identity();
        let proposed_policy_commitment =
            stake_state_resource_policy_commitment_v1(&policy).unwrap();
        let mut proposal = ProposeStakeStateResourcePolicyV1 {
            proposal_id: proposal_id.into(),
            network_domain: ledger.descriptor.network_domain.clone(),
            zone_id: ledger.descriptor.zone_id.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            proposed_height: ledger.height,
            activate_after_height,
            expires_at_height,
            expected_current_policy_sequence: current_sequence,
            expected_current_policy_commitment: current_commitment,
            proposed_policy: policy,
            proposed_policy_commitment,
            subject_hash: String::new(),
            validator_qc: simulated_qc(),
            notary_qc: simulated_qc(),
        };
        proposal.subject_hash = proposal.compute_subject_hash();
        proposal.validator_qc = resource_policy_qc(&proposal.subject_hash, validators);
        proposal.notary_qc = resource_policy_qc(&proposal.subject_hash, notaries);
        proposal
    }

    fn resource_policy_activation(
        ledger: &Ledger,
        validators: &[crate::Identity],
        notaries: &[crate::Identity],
        activation_id: &str,
    ) -> ActivateStakeStateResourcePolicyV1 {
        let pending = ledger.pending_stake_resource_policy.as_ref().unwrap();
        let (current_sequence, current_commitment) =
            ledger.current_stake_resource_policy_identity();
        let mut activation = ActivateStakeStateResourcePolicyV1 {
            activation_id: activation_id.into(),
            network_domain: ledger.descriptor.network_domain.clone(),
            zone_id: ledger.descriptor.zone_id.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            proposed_height: ledger.height,
            expires_at_height: pending.expires_at_height,
            proposal_id: pending.proposal_id.clone(),
            expected_pending_policy_commitment: pending.proposed_policy_commitment.clone(),
            expected_current_policy_sequence: current_sequence,
            expected_current_policy_commitment: current_commitment,
            subject_hash: String::new(),
            validator_qc: simulated_qc(),
            notary_qc: simulated_qc(),
        };
        activation.subject_hash = activation.compute_subject_hash();
        activation.validator_qc = resource_policy_qc(&activation.subject_hash, validators);
        activation.notary_qc = resource_policy_qc(&activation.subject_hash, notaries);
        activation
    }

