    fn certified_command(
        ledger: &Ledger,
        validators: &[crate::Identity],
        command: ConsensusCommand,
    ) -> ConsensusCommit {
        let leader = consensus_leader(ledger, validators);
        let proposal = consensus_proposal(ledger, leader, command);
        ConsensusCommit {
            votes: validators
                .iter()
                .take(required_quorum(validators.len()).unwrap())
                .map(|validator| consensus_vote(&proposal, validator))
                .collect(),
            proposal,
        }
    }

    fn seed_mainnet_coin(ledger: &mut Ledger, owner: String, amount: Amount) -> CoinObject {
        assert!(!ledger.descriptor.testnet);
        ledger.reserve_pools.demand_matching = ledger
            .reserve_pools
            .demand_matching
            .checked_sub(amount)
            .unwrap();
        ledger.reserve = ledger.reserve.checked_sub(amount).unwrap();
        ledger.advance().unwrap();
        let coin = ledger
            .make_coin(
                owner,
                amount,
                CoinState::Spendable,
                Vec::new(),
                None,
                None,
                None,
                1,
            )
            .unwrap();
        ledger.coins.insert(coin.object_id.clone(), coin.clone());
        ledger.assert_conservation().unwrap();
        coin
    }

    fn signed_value_risk_update(
        ledger: &Ledger,
        validators: &[crate::Identity],
        notaries: &[crate::Identity],
        to_cap: ValueCap,
        limits: crate::ValueRiskLimits,
        activate_after_height: u64,
        nonce: u64,
    ) -> ValueRiskPolicyUpdate {
        let (safety_case_hash, safety_case_valid_until_height) = if to_cap == ValueCap::ValueCap0 {
            (String::new(), 0)
        } else {
            (
                hash_parts(&[b"RLD-TEST-SAFETY-CASE", &nonce.to_be_bytes()]),
                activate_after_height + 500,
            )
        };
        let mut update = ValueRiskPolicyUpdate {
            update_id: format!("value-risk-update-{nonce}"),
            zone_id: ledger.descriptor.zone_id.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            policy_version: CURRENT_VALUE_RISK_POLICY_VERSION,
            previous_policy_sequence: ledger.value_risk_policy.policy_sequence,
            from_cap: ledger.value_risk_policy.current_cap,
            to_cap,
            limits,
            safety_case_hash,
            safety_case_valid_until_height,
            proposed_height: ledger.height,
            activate_after_height,
            expires_at_height: activate_after_height + 1_000,
            nonce,
            subject_hash: String::new(),
            validator_qc: simulated_qc(),
            notary_qc: simulated_qc(),
        };
        update.subject_hash = update.compute_subject_hash();
        update.validator_qc = signed_qc(
            &update.subject_hash,
            validators,
            required_quorum(validators.len()).unwrap(),
        );
        update.notary_qc = signed_qc(
            &update.subject_hash,
            notaries,
            required_quorum(notaries.len()).unwrap(),
        );
        update
    }

    fn m0_ledger_for_admission_gate(
        display_name: &str,
    ) -> (Ledger, Vec<crate::Identity>, Vec<crate::Identity>) {
        let founder = generate_identity();
        let validators = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let notaries = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let target = crate::AdmissionWork::from_hex(&format!("7f{}", "ff".repeat(31)))
            .expect("valid fixed admission target");
        let manifest = crate::SignedM0GenesisManifest::create(
            display_name,
            validators
                .iter()
                .map(|identity| identity.public_key.clone())
                .collect(),
            notaries
                .iter()
                .map(|identity| identity.public_key.clone())
                .collect(),
            "founder-admission-censorship-gate",
            crate::AdmissionLogConfigV1 {
                minimum_target: target,
                maximum_target: target,
                genesis_target: target,
                confirmation_work_floor: crate::AdmissionWork([32, 0, 0, 0]),
                contribution_epoch_mapping: crate::ContributionEpochMappingV1 {
                    ledger_height_origin: 0,
                    contribution_epoch_origin: 0,
                    ledger_blocks_per_contribution_epoch: 2,
                },
            },
            crate::AdmissionHash32::from_hex(&hash_bytes(b"admission-censorship-gate-benchmark"))
                .expect("valid benchmark digest"),
            &founder,
        )
        .unwrap();
        let mut ledger = Ledger::genesis_zone(
            &manifest.declaration.descriptor.display_name,
            manifest
                .declaration
                .descriptor
                .genesis_validator_keys
                .clone(),
            manifest.declaration.descriptor.genesis_notary_keys.clone(),
            false,
        )
        .unwrap();
        ledger
            .bind_m0_network_birth(manifest.declaration.network_birth_state())
            .unwrap();
        manifest.validate_ledger_identity(&ledger).unwrap();
        (ledger, validators, notaries)
    }

    fn stall_m0_admission_guard(ledger: &mut Ledger, fixture_label: &[u8]) {
        let entry_id = crate::AdmissionHash32::from_hex(&hash_bytes(
            &[b"admission-censorship-entry".as_slice(), fixture_label].concat(),
        ))
        .unwrap();
        let locator_commitment = crate::AdmissionHash32::from_hex(&hash_bytes(
            &[b"admission-censorship-locator".as_slice(), fixture_label].concat(),
        ))
        .unwrap();
        let proof_id = crate::AdmissionHash32::from_hex(&hash_bytes(
            &[b"admission-censorship-proof".as_slice(), fixture_label].concat(),
        ))
        .unwrap();
        let header_id = crate::AdmissionHash32::from_hex(&hash_bytes(
            &[b"admission-censorship-header".as_slice(), fixture_label].concat(),
        ))
        .unwrap();
        let observed_ledger_height = u128::from(ledger.height);
        let committing_ledger_height = u128::from(ledger.height.checked_add(1).unwrap());
        let (
            context,
            confirmation_work_floor,
            contribution_epoch_mapping,
            prior_committed_header,
            checkpoint_count,
            accumulator,
        ) = {
            let admission = ledger.admission_state.as_ref().unwrap();
            (
                admission.genesis.context.clone(),
                admission.genesis.config.confirmation_work_floor,
                admission.genesis.config.contribution_epoch_mapping.clone(),
                admission.committed_header,
                admission.checkpoint_count,
                admission.checkpoint_accumulator,
            )
        };
        let observed_ledger_epoch = contribution_epoch_mapping
            .epoch_at_height(observed_ledger_height)
            .unwrap();
        let committed_ledger_epoch = contribution_epoch_mapping
            .epoch_at_height(committing_ledger_height)
            .unwrap();
        let checkpoint = crate::AdmissionCheckpointV1 {
            context,
            admission_era: 0,
            header_id,
            log_height: 1,
            cumulative_work: crate::AdmissionWork([1, 0, 0, 0]),
            confirmations: crate::MIN_ADMISSION_CONFIRMATIONS as u16,
            descendant_work: confirmation_work_floor,
            entries_root: crate::admission_entry_root([entry_id]).unwrap(),
            availability_root: crate::admission_availability_root(&[
                crate::AdmissionAvailableEntryV1 {
                    entry_id,
                    locator_commitment,
                    declared_bytes: 1,
                },
            ])
            .unwrap(),
            observed_ledger_epoch,
            committed_ledger_epoch,
        };
        let transition = crate::VerifiedAdmissionCheckpointTransitionV1 {
            prior_committed_header,
            entry_ids: vec![entry_id],
            observed_ledger_height,
            committing_ledger_height,
            next_checkpoint_accumulator: crate::admission_checkpoint_accumulator_successor(
                accumulator,
                checkpoint_count,
                checkpoint.checkpoint_id(),
                proof_id,
            )
            .unwrap(),
            checkpoint,
            proof_id,
        };
        let proposal_context = ledger
            .test_authenticated_admission_checkpoint_proposal(&transition)
            .unwrap();
        ledger
            .execute_authenticated_admission_checkpoint_transition(&proposal_context, &transition)
            .unwrap();
        let current_asset_root =
            crate::AdmissionHash32::from_hex(&ledger.state_root_before_admission().unwrap())
                .unwrap();
        ledger
            .admission_state
            .as_mut()
            .unwrap()
            .censorship_guard
            .advance_epoch(committed_ledger_epoch + 3, current_asset_root)
            .unwrap();
        assert_eq!(
            ledger
                .admission_state
                .as_ref()
                .unwrap()
                .censorship_guard
                .status(),
            crate::AdmissionCensorshipStatusV1::CensorshipStalled
        );
    }

    #[test]
    fn formal_tag28_proposal_is_bound_but_pure_dispatch_remains_fail_closed() {
        let (ledger, validators, _) =
            m0_ledger_for_admission_gate("M0 authenticated tag-28 proposal gate");
        let admission = ledger.admission_state.as_ref().unwrap();
        let proof = AdmissionCheckpointProofV1 {
            context: admission.genesis.context.clone(),
            prior_committed_header: admission.committed_header,
            prior_checkpoint_accumulator: admission.checkpoint_accumulator,
            batch_segment: Vec::new(),
            confirmation_segment: Vec::new(),
        };
        let leader = consensus_leader(&ledger, &validators);
        let command = ConsensusCommand::CommitAdmissionCheckpoint(Box::new(proof.clone()));
        let proposal_plan = ledger.plan_admission_checkpoint_proposal(&proof).unwrap();
        assert_eq!(proposal_plan.parent_height(), ledger.height);
        assert_eq!(
            proposal_plan.parent_state_root(),
            ledger.state_root().unwrap()
        );
        assert_eq!(proposal_plan.expected_height(), ledger.height + 1);
        assert_eq!(
            proposal_plan.command_hash(),
            command
                .wire_v1_command_hash(&ledger.descriptor.network_domain)
                .unwrap()
        );
        let mut proposal = ConsensusProposal {
            proposal_id: "tag28-authentication-control".into(),
            zone_id: ledger.descriptor.zone_id.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            parent_height: ledger.height,
            parent_state_root: ledger.state_root().unwrap(),
            round: 0,
            proposer_public_key: leader.public_key.clone(),
            command_hash: command
                .wire_v1_command_hash(&ledger.descriptor.network_domain)
                .unwrap(),
            command,
            expected_height: ledger.height + 1,
            expected_state_root: hash_bytes(b"tag28-externally-derived-successor"),
            signature: String::new(),
        };
        proposal.signature = sign_bytes(
            &leader.secret_key,
            &proposal
                .wire_v1_signing_bytes(&ledger.descriptor.network_domain)
                .unwrap(),
        )
        .unwrap();
        let before = serde_json::to_vec(&ledger).unwrap();
        let authenticated = ledger
            .authenticate_admission_checkpoint_proposal(&proposal, &proof)
            .unwrap();
        assert_eq!(authenticated.command_hash(), proposal.command_hash);
        assert_eq!(authenticated.proof_id(), proof.proof_id().unwrap());
        assert_eq!(authenticated.proof_id(), proposal_plan.proof_id());
        assert_eq!(
            authenticated.committing_ledger_height(),
            proposal_plan.committing_ledger_height()
        );
        let mut dispatch = ledger.clone();
        assert!(matches!(
            dispatch.execute_consensus_command(proposal.command.clone()),
            Err(LedgerError::Invalid(message)) if message.contains("node-local history")
        ));
        assert_eq!(serde_json::to_vec(&dispatch).unwrap(), before);

        let mut other_proof = proof.clone();
        other_proof.prior_checkpoint_accumulator =
            AdmissionHash32::from_hex(&hash_bytes(b"different-accumulator")).unwrap();
        assert!(matches!(
            ledger.authenticate_admission_checkpoint_proposal(&proposal, &other_proof),
            Err(LedgerError::InvalidQuorum(message)) if message.contains("decoded proposal command")
        ));
        assert_eq!(serde_json::to_vec(&ledger).unwrap(), before);
    }

    fn resign_value_risk_update(
        update: &mut ValueRiskPolicyUpdate,
        validators: &[crate::Identity],
        notaries: &[crate::Identity],
    ) {
        update.subject_hash = update.compute_subject_hash();
        update.validator_qc = signed_qc(
            &update.subject_hash,
            validators,
            required_quorum(validators.len()).unwrap(),
        );
        update.notary_qc = signed_qc(
            &update.subject_hash,
            notaries,
            required_quorum(notaries.len()).unwrap(),
        );
    }

    fn activate_mainnet_value_policy(
        ledger: &mut Ledger,
        validators: &[crate::Identity],
        notaries: &[crate::Identity],
        limits: crate::ValueRiskLimits,
        nonce: u64,
    ) {
        let activate_after_height = ledger.height + MIN_VALUE_CAP_UPGRADE_DELAY_BLOCKS;
        let update = signed_value_risk_update(
            ledger,
            validators,
            notaries,
            ValueCap::ValueCap1,
            limits,
            activate_after_height,
            nonce,
        );
        ledger.submit_value_risk_policy_update(update).unwrap();
        while ledger.height < activate_after_height {
            ledger.advance().unwrap();
        }
        ledger.activate_pending_value_risk_policy().unwrap();
    }

    fn mainnet_capsule_for_test(
        source: &mut Ledger,
        validators: &[crate::Identity],
        notaries: &[crate::Identity],
        sender: &crate::Identity,
        destination_zone: &str,
        recipient: &str,
        amount: Amount,
    ) -> TransitCapsule {
        let source_zone = source.descriptor.zone_id.clone();
        let coin = seed_mainnet_coin(
            source,
            sender.address(&source_zone),
            Amount::from_rld_whole(10).unwrap(),
        );
        // The reference node deliberately cannot originate mainnet capsules
        // without an external BFT driver. This test-only switch exercises the
        // destination's fully signed import path without weakening production.
        source.descriptor.testnet = true;
        let intent = signed_intent(
            sender,
            &source_zone,
            destination_zone,
            recipient,
            &coin.object_id,
            amount,
        );
        let mut capsule = source
            .export_payment(intent, TransportClass::SublightDtn)
            .unwrap();
        source.descriptor.testnet = false;
        capsule.source_descriptor.testnet = false;
        let subject = capsule.subject_hash();
        capsule.validator_qc = signed_qc(
            &subject,
            validators,
            required_quorum(validators.len()).unwrap(),
        );
        capsule.notary_qc = signed_qc(&subject, notaries, required_quorum(notaries.len()).unwrap());
        capsule
    }

    fn spendability_request(
        provider: &crate::Identity,
        zone_id: &str,
        coin_id: &str,
        payment_id: &str,
        amount: Amount,
        nonce: u64,
    ) -> SpendabilityCertificateRequest {
        let liquidity_provider = provider.address(zone_id);
        let recipient = format!("rld:{zone_id}:recipient-{nonce}");
        let settlement_claim_transit_id = format!("settlement-claim-{nonce}");
        let payload_hash = action_payload_hash(
            "ISSUE_DSC",
            &[
                payment_id.as_bytes(),
                coin_id.as_bytes(),
                liquidity_provider.as_bytes(),
                recipient.as_bytes(),
                &amount.0.to_be_bytes(),
                settlement_claim_transit_id.as_bytes(),
            ],
        );
        SpendabilityCertificateRequest {
            payment_id: payment_id.into(),
            provider_coin_id: coin_id.into(),
            liquidity_provider,
            recipient,
            amount,
            settlement_claim_transit_id,
            authorization: signed_authorization(
                provider,
                zone_id,
                "ISSUE_DSC",
                payload_hash,
                nonce,
            ),
        }
    }

    fn consensus_proposal(
        ledger: &Ledger,
        proposer: &crate::Identity,
        command: ConsensusCommand,
    ) -> ConsensusProposal {
        let parent_state_root = ledger.state_root().unwrap();
        let command_hash = command.command_hash();
        let mut staged = ledger.clone();
        staged.execute_consensus_command(command.clone()).unwrap();
        let mut proposal = ConsensusProposal {
            proposal_id: format!("proposal-{}", &command_hash[..24]),
            zone_id: ledger.descriptor.zone_id.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            parent_height: ledger.height,
            parent_state_root,
            round: 0,
            proposer_public_key: proposer.public_key.clone(),
            command,
            command_hash,
            expected_height: staged.height,
            expected_state_root: staged.state_root().unwrap(),
            signature: String::new(),
        };
        proposal.signature = sign_bytes(&proposer.secret_key, &proposal.signing_bytes()).unwrap();
        proposal
    }

    fn consensus_leader<'a>(
        ledger: &Ledger,
        validators: &'a [crate::Identity],
    ) -> &'a crate::Identity {
        let leader = crate::deterministic_round_zero_leader(
            &ledger.descriptor.validator_keys,
            ledger.height,
        )
        .unwrap();
        validators
            .iter()
            .find(|validator| validator.public_key == leader)
            .expect("deterministic leader belongs to the test validator set")
    }

    fn consensus_vote(
        proposal: &ConsensusProposal,
        validator: &crate::Identity,
    ) -> crate::ConsensusVote {
        let mut vote = crate::ConsensusVote {
            proposal_id: proposal.proposal_id.clone(),
            proposal_hash: proposal.proposal_hash(),
            zone_id: proposal.zone_id.clone(),
            currency_genesis_root: proposal.currency_genesis_root.clone(),
            protocol_era: proposal.protocol_era,
            crypto_era: proposal.crypto_era,
            parent_height: proposal.parent_height,
            parent_state_root: proposal.parent_state_root.clone(),
            round: proposal.round,
            expected_state_root: proposal.expected_state_root.clone(),
            voter_public_key: validator.public_key.clone(),
            signature: String::new(),
        };
        vote.signature = sign_bytes(&validator.secret_key, &vote.signing_bytes()).unwrap();
        vote
    }

    fn stake_authority_governance_fixture() -> (
        Ledger,
        Vec<crate::Identity>,
        Vec<crate::Identity>,
        Vec<crate::Identity>,
        StakeAuthorityGovernanceUpdateV1,
    ) {
        let validators = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let notaries = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let mut ledger = Ledger::genesis_zone(
            "Stake authority command",
            validators
                .iter()
                .map(|identity| identity.public_key.clone())
                .collect(),
            notaries
                .iter()
                .map(|identity| identity.public_key.clone())
                .collect(),
            true,
        )
        .unwrap();
        let candidate_identities = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();

        let seeded_stake = Amount::from_runlai(40);
        ledger.reserve = ledger.reserve.checked_sub(seeded_stake).unwrap();
        ledger.reserve_pools.demand_matching = ledger
            .reserve_pools
            .demand_matching
            .checked_sub(seeded_stake)
            .unwrap();

        for index in 0..4 {
            let escrow_coin_id = format!("stake-escrow-{index:04}");
            let source_coin_id = format!("stake-source-{index:04}");
            let owner = format!("stake-owner-{index:04}");
            let lineage_root = format!("stake-lineage-{index:04}");
            ledger.coins.insert(
                source_coin_id.clone(),
                CoinObject {
                    object_id: source_coin_id.clone(),
                    lineage_root: lineage_root.clone(),
                    parent_ids: Vec::new(),
                    owner: owner.clone(),
                    zone_id: ledger.descriptor.zone_id.clone(),
                    amount: Amount::from_runlai(10),
                    state: CoinState::Consumed,
                    version: 0,
                    created_height: 0,
                    transit_id: None,
                    imported_from: None,
                    origin_zone: ledger.descriptor.zone_id.clone(),
                    origin_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
                },
            );
            ledger.coins.insert(
                escrow_coin_id.clone(),
                CoinObject {
                    object_id: escrow_coin_id.clone(),
                    lineage_root,
                    parent_ids: vec![source_coin_id.clone()],
                    owner: owner.clone(),
                    zone_id: ledger.descriptor.zone_id.clone(),
                    amount: Amount::from_runlai(10),
                    state: CoinState::Reserved,
                    version: 1,
                    created_height: 0,
                    transit_id: None,
                    imported_from: None,
                    origin_zone: ledger.descriptor.zone_id.clone(),
                    origin_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
                },
            );
            let position = ConsensusStakePosition {
                position_id: format!("stake-position-{index:04}"),
                kind: ConsensusStakePositionKind::SelfBond {
                    validator_id: format!("stake-validator-{index:04}"),
                },
                owner,
                source_coin_id,
                escrow_coin_id,
                amount: Amount::from_runlai(10),
                locked_height: 0,
                committed_through_height: 100,
                slash_terms: None,
            };
            ledger
                .consensus_stake_escrows
                .insert(position.escrow_coin_id.clone(), position);
        }
        ledger.assert_conservation().unwrap();

        let source_root = ledger.state_root().unwrap();
        let context = ledger.stake_context_at(u128::from(ledger.height), source_root.clone());
        let candidates = candidate_identities
            .iter()
            .enumerate()
            .map(|(index, identity)| {
                let mut internal = crate::ValidatorCandidateRecord {
                    validator_id: format!("stake-validator-{index:04}"),
                    owner: format!("stake-owner-{index:04}"),
                    public_key: identity.public_key.clone(),
                    key_era: ledger.descriptor.crypto_era,
                    registered_height: 0,
                    exit_height: None,
                    proof_of_possession: String::new(),
                };
                internal.proof_of_possession = sign_bytes(
                    &identity.secret_key,
                    &crate::validator_candidate_pop_message_v1(&context, &internal),
                )
                .unwrap();
                crate::StakeAuthorityCandidateCommandV1 {
                    validator_id: internal.validator_id,
                    owner: internal.owner,
                    public_key: internal.public_key,
                    key_era: internal.key_era,
                    registered_height: 0,
                    exit_height: None,
                    proof_of_possession: internal.proof_of_possession,
                }
            })
            .collect::<Vec<_>>();
        let positions = (0..4)
            .map(|index| crate::StakeAuthorityPositionCommandV1 {
                position_id: format!("stake-position-{index:04}"),
                position_type: crate::StakePositionTypeV1::SelfBond,
                validator_id: format!("stake-validator-{index:04}"),
                owner: format!("stake-owner-{index:04}"),
                source_coin_id: format!("stake-source-{index:04}"),
                escrow_coin_id: format!("stake-escrow-{index:04}"),
                amount: Amount::from_runlai(10),
                locked_height: 0,
                committed_through_height: 100,
            })
            .collect();
        let ubo_validators = (0..4)
            .map(|index| crate::StakeUboControlEntryV1 {
                validator_id: format!("stake-validator-{index:04}"),
                record: crate::StakeUboControlRecordCommandV1 {
                    control_group: format!("stake-control-{index:04}"),
                    valid_from_height: 0,
                    challenge_ends_height: 0,
                    valid_through_height: 100,
                    evidence_hash: hash_parts(&[
                        b"RLD-TEST-STAKE-UBO-EVIDENCE",
                        &(index as u64).to_be_bytes(),
                    ]),
                },
            })
            .collect();
        let genesis_anchor = ledger_stake_authority_genesis_anchor_v1(&context);
        let mut request = StakeAuthorityGovernanceUpdateV1 {
            update_id: "stake-authority-governance-1".into(),
            zone_id: ledger.descriptor.zone_id.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            proposed_height: ledger.height,
            expires_at_height: ledger.height + 10,
            authority_version: crate::STAKE_AUTHORITY_STATE_VERSION_V1,
            sequence: 1,
            expected_previous_commitment: genesis_anchor,
            policy: crate::StakeAuthorityPolicyCommandV1 {
                policy_version: 1,
                minimum_self_bond: Amount::from_runlai(10),
                minimum_delegation: Amount::from_runlai(1),
                candidate_maturity_blocks: 1,
                stake_maturity_blocks: 1,
                evidence_window_blocks: 1,
                activation_delay_blocks: 2,
                epoch_length_blocks: 10,
                maximum_validators: 4,
            },
            candidates,
            positions,
            ubo_map_version: 1,
            ubo_sequence: 1,
            ubo_predecessor_commitment: hash_parts(&[b"RLD-TEST-UBO-GENESIS"]),
            ubo_verifier_set_commitment: hash_parts(&[b"RLD-TEST-UBO-VERIFIERS"]),
            ubo_evidence_root: hash_parts(&[b"RLD-TEST-UBO-ROOT"]),
            ubo_validators,
            prospective_authority_commitment: "00".repeat(32),
            subject_hash: "00".repeat(32),
            validator_qc: signed_qc("00", &validators, 3),
            notary_qc: signed_qc("00", &notaries, 3),
        };
        let prospective = build_ledger_stake_authority_state_v1(
            &context,
            u128::from(ledger.height + 1),
            None,
            request.to_ledger_update().unwrap(),
            &ledger.coins,
        )
        .unwrap();
        request.prospective_authority_commitment = prospective.commitment;
        request.subject_hash = request.compute_subject_hash();
        request.validator_qc = signed_qc(&request.subject_hash, &validators, 3);
        request.notary_qc = signed_qc(&request.subject_hash, &notaries, 3);
        (ledger, validators, notaries, candidate_identities, request)
    }

