    fn v2_lock_request_from_v1(
        ledger: &Ledger,
        owner: &crate::Identity,
        request: LockConsensusStakeRequestV1,
        nonce: u64,
    ) -> LockConsensusStakeRequestV2 {
        let position_kind = match request.position_type {
            StakePositionTypeV1::SelfBond => ConsensusStakePositionKind::SelfBond {
                validator_id: request.validator_id.clone(),
            },
            StakePositionTypeV1::Delegation => ConsensusStakePositionKind::Delegation {
                validator_id: request.validator_id.clone(),
            },
        };
        let slash_terms_payload = consensus_stake_slash_terms_payload_hash_v2(
            &request.position_id,
            &position_kind,
            &request.owner,
            &request.source_coin_id,
            request.amount,
            u128::from(request.committed_through_height),
            &ConsensusStakeSlashPolicyV2::protocol_v2(),
        );
        let slash_terms_authorization = signed_authorization(
            owner,
            &ledger.descriptor.zone_id,
            ACCEPT_CONSENSUS_STAKE_SLASH_TERMS_ACTION_V2,
            slash_terms_payload,
            nonce,
        );
        let mut v2 = LockConsensusStakeRequestV2 {
            position_id: request.position_id,
            zone_id: request.zone_id,
            currency_genesis_root: request.currency_genesis_root,
            protocol_era: request.protocol_era,
            crypto_era: request.crypto_era,
            proposed_height: request.proposed_height,
            expires_at_height: request.expires_at_height,
            expected_authority_sequence: request.expected_authority_sequence,
            expected_authority_commitment: request.expected_authority_commitment,
            position_type: request.position_type,
            validator_id: request.validator_id,
            owner: request.owner,
            source_coin_id: request.source_coin_id,
            amount: request.amount,
            committed_through_height: request.committed_through_height,
            slash_terms_authorization,
            authorization: signed_authorization(
                owner,
                &ledger.descriptor.zone_id,
                LOCK_CONSENSUS_STAKE_ACTION_V2,
                String::new(),
                nonce + 1,
            ),
        };
        v2.authorization = signed_authorization(
            owner,
            &ledger.descriptor.zone_id,
            LOCK_CONSENSUS_STAKE_ACTION_V2,
            v2.payload_hash(),
            nonce + 1,
        );
        v2
    }

