    fn resign_resource_migration(
        ledger: &Ledger,
        owner: &crate::Identity,
        sponsor: &crate::Identity,
        position: &ConsensusStakePosition,
        request: &mut MigrateConsensusStakeResourceRequestV1,
        sponsor_nonce: u64,
        owner_nonce: u64,
    ) {
        request.resource_envelope.resource_subject_hash = "00".repeat(32);
        request.resource_envelope.authorization = signed_authorization(
            sponsor,
            &ledger.descriptor.zone_id,
            crate::FUND_STAKE_STATE_RESOURCE_ACTION_V1,
            "00".repeat(32),
            sponsor_nonce,
        );
        request.authorization = signed_authorization(
            owner,
            &ledger.descriptor.zone_id,
            MIGRATE_CONSENSUS_STAKE_RESOURCE_ACTION_V1,
            "00".repeat(32),
            owner_nonce,
        );
        let wire = ConsensusCommand::MigrateConsensusStakeResource(Box::new(request.clone()))
            .wire_v1_command_bytes(&ledger.descriptor.network_domain)
            .unwrap();
        let usage = StakeStateResourceUsageV1 {
            wire_bytes: wire.len().try_into().unwrap(),
            persistent_bytes: migrate_consensus_stake_resource_persistent_bytes_v1(
                request, position,
            )
            .unwrap(),
            signature_checks: MIGRATE_CONSENSUS_STAKE_RESOURCE_SIGNATURE_CHECKS_V1,
            state_reads: MIGRATE_CONSENSUS_STAKE_RESOURCE_STATE_READS_V1,
            state_writes: MIGRATE_CONSENSUS_STAKE_RESOURCE_STATE_WRITES_V1,
        };
        let accounting = ledger.stake_resource_accounting.as_ref().unwrap();
        let admission = StakeStateResourceAdmissionRequestV1 {
            resource_key: format!("POSITION/{}", request.position_id),
            resource_kind: StakeStateResourceKindV1::Position,
            resource_owner: request.owner.clone(),
            outer_operation_hash: request.resource_operation_hash(),
            expected_parent_commitment: request.expected_authority_commitment.clone(),
            usage,
            envelope: request.resource_envelope.clone(),
        };
        let subject = stake_state_resource_subject_hash_v1(accounting.context(), &admission);
        request.resource_envelope.resource_subject_hash = subject.clone();
        request.resource_envelope.authorization = signed_authorization(
            sponsor,
            &ledger.descriptor.zone_id,
            crate::FUND_STAKE_STATE_RESOURCE_ACTION_V1,
            subject,
            sponsor_nonce,
        );
        request.authorization = signed_authorization(
            owner,
            &ledger.descriptor.zone_id,
            MIGRATE_CONSENSUS_STAKE_RESOURCE_ACTION_V1,
            request.payload_hash(),
            owner_nonce,
        );
        assert_eq!(
            ConsensusCommand::MigrateConsensusStakeResource(Box::new(request.clone()))
                .wire_v1_command_bytes(&ledger.descriptor.network_domain)
                .unwrap()
                .len(),
            usize::try_from(usage.wire_bytes).unwrap()
        );
    }

