    fn resign_epoch_resource_derivation(
        ledger: &Ledger,
        payer: &crate::Identity,
        sponsor: &crate::Identity,
        epoch: &LedgerDerivedStakeEpochV1,
        request: &mut DeriveNextStakeEpochRequestV2,
        sponsor_nonce: u64,
        payer_nonce: u64,
    ) {
        request.resource_envelope.resource_subject_hash = "00".repeat(32);
        request.resource_envelope.authorization = signed_authorization(
            sponsor,
            &ledger.descriptor.zone_id,
            crate::FUND_STAKE_STATE_RESOURCE_ACTION_V1,
            "00".repeat(32),
            sponsor_nonce,
        );
        request.authorization = signed_authorization(
            payer,
            &ledger.descriptor.zone_id,
            DERIVE_NEXT_STAKE_EPOCH_ACTION_V2,
            "00".repeat(32),
            payer_nonce,
        );
        let wire = ConsensusCommand::DeriveNextStakeEpochV2(Box::new(request.clone()))
            .wire_v1_command_bytes(&ledger.descriptor.network_domain)
            .unwrap();
        let (next_horizons, next_horizon_history) = ledger
            .preview_stake_liability_horizon_update(epoch)
            .unwrap();
        let horizon_usage = stake_liability_horizon_usage_delta_v1(
            &ledger.stake_position_liability_horizons,
            &ledger.stake_position_liability_horizon_history,
            &next_horizons,
            &next_horizon_history,
        )
        .unwrap();
        let usage = StakeStateResourceUsageV1 {
            wire_bytes: wire.len().try_into().unwrap(),
            persistent_bytes: derive_next_stake_epoch_persistent_bytes_v2(
                request,
                epoch,
                horizon_usage,
            )
            .unwrap(),
            signature_checks: DERIVE_NEXT_STAKE_EPOCH_SIGNATURE_CHECKS_V2,
            state_reads: derive_next_stake_epoch_state_reads_v2(epoch, horizon_usage).unwrap(),
            state_writes: derive_next_stake_epoch_state_writes_v2(horizon_usage).unwrap(),
        };
        let accounting = ledger.stake_resource_accounting.as_ref().unwrap();
        let admission = StakeStateResourceAdmissionRequestV1 {
            resource_key: format!("EPOCH/{}", epoch.descriptor.consensus_epoch),
            resource_kind: StakeStateResourceKindV1::Epoch,
            resource_owner: request.payer.clone(),
            outer_operation_hash: request.resource_operation_hash(),
            expected_parent_commitment: epoch.previous_record_hash.clone(),
            usage,
            envelope: request.resource_envelope.clone(),
        };
        let subject = stake_state_resource_subject_hash_v1(accounting.context(), &admission);
        request.resource_envelope.resource_subject_hash = subject.clone();
        request.resource_envelope.authorization = signed_authorization(
            sponsor,
            &ledger.descriptor.zone_id,
            crate::FUND_STAKE_STATE_RESOURCE_ACTION_V1,
            subject,
            sponsor_nonce,
        );
        request.authorization = signed_authorization(
            payer,
            &ledger.descriptor.zone_id,
            DERIVE_NEXT_STAKE_EPOCH_ACTION_V2,
            request.payload_hash(),
            payer_nonce,
        );
        assert_eq!(
            ConsensusCommand::DeriveNextStakeEpochV2(Box::new(request.clone()))
                .wire_v1_command_bytes(&ledger.descriptor.network_domain)
                .unwrap()
                .len(),
            usize::try_from(usage.wire_bytes).unwrap()
        );
    }

    fn resource_bound_epoch_fixture() -> (
        Ledger,
        Vec<crate::Identity>,
        crate::Identity,
        crate::Identity,
        DeriveNextStakeEpochRequestV2,
        LedgerDerivedStakeEpochV1,
    ) {
        let validators = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let notaries = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let owners = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let candidate_keys = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let sponsor = generate_identity();
        let payer = generate_identity();
        let mut ledger = Ledger::genesis_zone(
            "Resource-bound Epoch",
            validators
                .iter()
                .map(|identity| identity.public_key.clone())
                .collect(),
            notaries
                .iter()
                .map(|identity| identity.public_key.clone())
                .collect(),
            true,
        )
        .unwrap();
        let source_root = ledger.state_root().unwrap();
        let context = ledger.stake_context_at(u128::from(ledger.height), source_root.clone());
        let candidates = candidate_keys
            .iter()
            .enumerate()
            .map(|(index, identity)| {
                let mut candidate = ValidatorCandidateRecord {
                    validator_id: format!("epoch-validator-{index:04}"),
                    owner: owners[index].address(&ledger.descriptor.zone_id),
                    public_key: identity.public_key.clone(),
                    key_era: ledger.descriptor.crypto_era,
                    registered_height: 0,
                    exit_height: None,
                    proof_of_possession: String::new(),
                };
                candidate.proof_of_possession = sign_bytes(
                    &identity.secret_key,
                    &crate::validator_candidate_pop_message_v1(&context, &candidate),
                )
                .unwrap();
                candidate
            })
            .collect::<Vec<_>>();
        let candidate_commands = candidates
            .iter()
            .map(|candidate| crate::StakeAuthorityCandidateCommandV1 {
                validator_id: candidate.validator_id.clone(),
                owner: candidate.owner.clone(),
                public_key: candidate.public_key.clone(),
                key_era: candidate.key_era,
                registered_height: u64::try_from(candidate.registered_height).unwrap(),
                exit_height: None,
                proof_of_possession: candidate.proof_of_possession.clone(),
            })
            .collect::<Vec<_>>();
        let ubo_validators = candidates
            .iter()
            .enumerate()
            .map(|(index, candidate)| crate::StakeUboControlEntryV1 {
                validator_id: candidate.validator_id.clone(),
                record: crate::StakeUboControlRecordCommandV1 {
                    control_group: format!("epoch-control-{index:04}"),
                    valid_from_height: 0,
                    challenge_ends_height: 0,
                    valid_through_height: 2_000,
                    evidence_hash: hash_parts(&[
                        b"RLD-TEST-EPOCH-UBO-EVIDENCE",
                        &(index as u64).to_be_bytes(),
                    ]),
                },
            })
            .collect::<Vec<_>>();
        let mut governance = StakeAuthorityGovernanceUpdateV1 {
            update_id: "resource-epoch-authority-1".into(),
            zone_id: ledger.descriptor.zone_id.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            proposed_height: ledger.height,
            expires_at_height: ledger.height + 20,
            authority_version: crate::STAKE_AUTHORITY_STATE_VERSION_V1,
            sequence: 1,
            expected_previous_commitment: ledger_stake_authority_genesis_anchor_v1(&context),
            policy: crate::StakeAuthorityPolicyCommandV1 {
                policy_version: crate::STAKE_EPOCH_DERIVATION_VERSION_V2,
                minimum_self_bond: Amount::from_runlai(10),
                minimum_delegation: Amount::from_runlai(1),
                candidate_maturity_blocks: 1,
                stake_maturity_blocks: 1,
                evidence_window_blocks: 2,
                activation_delay_blocks: 2,
                epoch_length_blocks: 10,
                maximum_validators: 4,
            },
            candidates: candidate_commands,
            positions: Vec::new(),
            ubo_map_version: 1,
            ubo_sequence: 1,
            ubo_predecessor_commitment: hash_parts(&[b"RLD-TEST-EPOCH-UBO-GENESIS"]),
            ubo_verifier_set_commitment: hash_parts(&[b"RLD-TEST-EPOCH-UBO-VERIFIERS"]),
            ubo_evidence_root: hash_parts(&[b"RLD-TEST-EPOCH-UBO-ROOT"]),
            ubo_validators,
            prospective_authority_commitment: "00".repeat(32),
            subject_hash: "00".repeat(32),
            validator_qc: simulated_qc(),
            notary_qc: simulated_qc(),
        };
        let prospective = build_ledger_stake_authority_state_v1(
            &context,
            u128::from(ledger.height + 1),
            None,
            governance.to_ledger_update().unwrap(),
            &ledger.coins,
        )
        .unwrap();
        governance.prospective_authority_commitment = prospective.commitment;
        governance.subject_hash = governance.compute_subject_hash();
        governance.validator_qc = signed_qc(&governance.subject_hash, &validators, 3);
        governance.notary_qc = signed_qc(&governance.subject_hash, &notaries, 3);
        ledger.submit_stake_authority_update(governance).unwrap();

        let sponsor_address = sponsor.address(&ledger.descriptor.zone_id);
        let epoch_zone_id = ledger.descriptor.zone_id.clone();
        let resource_funding = (0..9)
            .map(|index| {
                seed_stake_resource_test_coin(
                    &mut ledger,
                    &format!("epoch-resource-funding-{index:04}"),
                    sponsor_address.clone(),
                    Amount(1_000_000),
                )
            })
            .collect::<Vec<_>>();
        let stake_sources = owners
            .iter()
            .enumerate()
            .map(|(index, owner)| {
                seed_stake_resource_test_coin(
                    &mut ledger,
                    &format!("epoch-stake-source-{index:04}"),
                    owner.address(&epoch_zone_id),
                    Amount::from_runlai(10),
                )
            })
            .collect::<Vec<_>>();
        ledger.assert_conservation().unwrap();

        let mut policy =
            stake_resource_policy(1, crate::stake_resource_accounting::ZERO_SHA256.into(), 1);
        policy.maximum_active_candidates = 8;
        policy.maximum_candidates_per_owner = 2;
        policy.maximum_active_positions = 8;
        policy.maximum_positions_per_owner = 2;
        policy.maximum_total_stake_state_bytes = 10_000_000;
        policy.maximum_stake_state_bytes_per_block = 1_000_000;
        policy.maximum_stake_signature_checks_per_block = 100;
        policy.maximum_stake_state_reads_per_block = 1_000;
        policy.maximum_stake_state_writes_per_block = 100;
        policy.maximum_lease_blocks = 5_000;
        let proposal = resource_policy_proposal(
            &ledger,
            &validators,
            &notaries,
            "epoch-resource-policy-proposal",
            policy,
            ledger.height + 1,
            ledger.height + 100,
        );
        ledger
            .propose_stake_state_resource_policy(proposal)
            .unwrap();
        let activation = resource_policy_activation(
            &ledger,
            &validators,
            &notaries,
            "epoch-resource-policy-activation",
        );
        ledger
            .activate_stake_state_resource_policy(activation)
            .unwrap();

        for index in 0..4 {
            let authority = ledger.consensus_stake_authority.as_ref().unwrap();
            let candidate = authority.candidates[index].clone();
            let accounting = ledger.stake_resource_accounting.as_ref().unwrap();
            let mut request = MigrateConsensusCandidateResourceRequestV1 {
                request_id: format!("epoch-candidate-migration-{index:04}"),
                zone_id: ledger.descriptor.zone_id.clone(),
                currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
                protocol_era: ledger.descriptor.protocol_era,
                crypto_era: ledger.descriptor.crypto_era,
                proposed_height: ledger.height,
                expires_at_height: ledger.height + 100,
                expected_authority_sequence: authority.sequence,
                expected_authority_commitment: authority.commitment.clone(),
                validator_id: candidate.validator_id.clone(),
                owner: candidate.owner.clone(),
                public_key: candidate.public_key.clone(),
                key_era: candidate.key_era,
                registered_height: u64::try_from(candidate.registered_height).unwrap(),
                exit_height: None,
                proof_of_possession: candidate.proof_of_possession.clone(),
                expected_candidate_commitment: candidate.resource_commitment_v1(),
                resource_envelope: crate::StakeStateResourceEnvelopeV1 {
                    resource_policy_sequence: accounting.active_policy().sequence,
                    resource_policy_commitment: accounting.active_policy_commitment().into(),
                    sponsor: sponsor_address.clone(),
                    funding_coin_id: resource_funding[index].object_id.clone(),
                    max_resource_fee: Amount(1_000_000),
                    max_state_bond: Amount(1_000_000),
                    lease_end_height: 2_030,
                    resource_subject_hash: "00".repeat(32),
                    authorization: signed_authorization(
                        &sponsor,
                        &ledger.descriptor.zone_id,
                        crate::FUND_STAKE_STATE_RESOURCE_ACTION_V1,
                        "00".repeat(32),
                        10_000 + index as u64 * 10,
                    ),
                },
                authorization: signed_authorization(
                    &owners[index],
                    &ledger.descriptor.zone_id,
                    MIGRATE_CONSENSUS_CANDIDATE_RESOURCE_ACTION_V1,
                    "00".repeat(32),
                    10_001 + index as u64 * 10,
                ),
            };
            resign_candidate_resource_migration(
                &ledger,
                &owners[index],
                &sponsor,
                &candidate,
                &mut request,
                10_000 + index as u64 * 10,
                10_001 + index as u64 * 10,
            );
            ledger
                .migrate_consensus_candidate_resource(request)
                .unwrap();
        }

        for index in 0..4 {
            let authority = ledger.consensus_stake_authority.as_ref().unwrap();
            let accounting = ledger.stake_resource_accounting.as_ref().unwrap();
            let mut request = LockConsensusStakeRequestV3 {
                position_id: format!("epoch-position-{index:04}"),
                zone_id: ledger.descriptor.zone_id.clone(),
                currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
                protocol_era: ledger.descriptor.protocol_era,
                crypto_era: ledger.descriptor.crypto_era,
                proposed_height: ledger.height,
                expires_at_height: ledger.height + 100,
                expected_authority_sequence: authority.sequence,
                expected_authority_commitment: authority.commitment.clone(),
                position_type: StakePositionTypeV1::SelfBond,
                validator_id: candidates[index].validator_id.clone(),
                owner: candidates[index].owner.clone(),
                source_coin_id: stake_sources[index].object_id.clone(),
                amount: Amount::from_runlai(10),
                committed_through_height: 2_000,
                slash_terms_authorization: signed_authorization(
                    &owners[index],
                    &ledger.descriptor.zone_id,
                    ACCEPT_CONSENSUS_STAKE_SLASH_TERMS_ACTION_V2,
                    "00".repeat(32),
                    11_000 + index as u64 * 10,
                ),
                resource_envelope: crate::StakeStateResourceEnvelopeV1 {
                    resource_policy_sequence: accounting.active_policy().sequence,
                    resource_policy_commitment: accounting.active_policy_commitment().into(),
                    sponsor: sponsor_address.clone(),
                    funding_coin_id: resource_funding[4 + index].object_id.clone(),
                    max_resource_fee: Amount(1_000_000),
                    max_state_bond: Amount(1_000_000),
                    lease_end_height: 2_030,
                    resource_subject_hash: "00".repeat(32),
                    authorization: signed_authorization(
                        &sponsor,
                        &ledger.descriptor.zone_id,
                        crate::FUND_STAKE_STATE_RESOURCE_ACTION_V1,
                        "00".repeat(32),
                        11_002 + index as u64 * 10,
                    ),
                },
                authorization: signed_authorization(
                    &owners[index],
                    &ledger.descriptor.zone_id,
                    LOCK_CONSENSUS_STAKE_ACTION_V3,
                    "00".repeat(32),
                    11_001 + index as u64 * 10,
                ),
            };
            request.slash_terms_authorization = signed_authorization(
                &owners[index],
                &ledger.descriptor.zone_id,
                ACCEPT_CONSENSUS_STAKE_SLASH_TERMS_ACTION_V2,
                request.slash_terms_payload_hash(),
                11_000 + index as u64 * 10,
            );
            resign_resource_bound_stake(
                &ledger,
                &owners[index],
                &sponsor,
                &mut request,
                11_002 + index as u64 * 10,
                11_001 + index as u64 * 10,
            );
            ledger.lock_consensus_stake_v3(request).unwrap();
        }
        // The final self-bond must cross the policy's one-block maturity
        // boundary before it can contribute to the deterministic snapshot.
        ledger.advance().unwrap();
        let mut preview_ledger = ledger.clone();
        let preview = preview_ledger.derive_and_store_next_stake_epoch().unwrap();
        assert_eq!(
            preview.derivation_version,
            crate::STAKE_EPOCH_DERIVATION_VERSION_V2
        );
        let authority = ledger.consensus_stake_authority.as_ref().unwrap();
        let accounting = ledger.stake_resource_accounting.as_ref().unwrap();
        let mut request = DeriveNextStakeEpochRequestV2 {
            request_id: "resource-bound-epoch-request-1".into(),
            zone_id: ledger.descriptor.zone_id.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            proposed_height: ledger.height,
            expires_at_height: ledger.height + 100,
            expected_authority_sequence: authority.sequence,
            expected_authority_commitment: authority.commitment.clone(),
            expected_consensus_epoch: preview.descriptor.consensus_epoch,
            expected_snapshot_height: ledger.height,
            expected_snapshot_state_root: ledger.state_root().unwrap(),
            expected_derived_record_hash: preview.record_hash.clone(),
            payer: payer.address(&ledger.descriptor.zone_id),
            resource_envelope: crate::StakeStateResourceEnvelopeV1 {
                resource_policy_sequence: accounting.active_policy().sequence,
                resource_policy_commitment: accounting.active_policy_commitment().into(),
                sponsor: sponsor_address,
                funding_coin_id: resource_funding[8].object_id.clone(),
                max_resource_fee: Amount(1_000_000),
                max_state_bond: Amount(1_000_000),
                lease_end_height: 2_030,
                resource_subject_hash: "00".repeat(32),
                authorization: signed_authorization(
                    &sponsor,
                    &ledger.descriptor.zone_id,
                    crate::FUND_STAKE_STATE_RESOURCE_ACTION_V1,
                    "00".repeat(32),
                    12_000,
                ),
            },
            authorization: signed_authorization(
                &payer,
                &ledger.descriptor.zone_id,
                DERIVE_NEXT_STAKE_EPOCH_ACTION_V2,
                "00".repeat(32),
                12_001,
            ),
        };
        resign_epoch_resource_derivation(
            &ledger,
            &payer,
            &sponsor,
            &preview,
            &mut request,
            12_000,
            12_001,
        );
        (ledger, validators, payer, sponsor, request, preview)
    }

    fn slash_terms_migration_request(
        ledger: &Ledger,
        owner: &crate::Identity,
        position: &ConsensusStakePosition,
        nonce: u64,
    ) -> MigrateConsensusStakeSlashTermsV2 {
        let slash_terms_authorization = signed_authorization(
            owner,
            &ledger.descriptor.zone_id,
            ACCEPT_CONSENSUS_STAKE_SLASH_TERMS_ACTION_V2,
            position.slash_terms_payload_hash_v2(),
            nonce,
        );
        let authority = ledger.consensus_stake_authority.as_ref().unwrap();
        let mut request = MigrateConsensusStakeSlashTermsV2 {
            request_id: format!("migrate-stake-slash-terms-{nonce}"),
            zone_id: ledger.descriptor.zone_id.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            proposed_height: ledger.height,
            expires_at_height: ledger.height + 20,
            expected_authority_sequence: authority.sequence,
            expected_authority_commitment: authority.commitment.clone(),
            position_id: position.position_id.clone(),
            escrow_coin_id: position.escrow_coin_id.clone(),
            owner: position.owner.clone(),
            slash_terms_authorization,
            authorization: signed_authorization(
                owner,
                &ledger.descriptor.zone_id,
                MIGRATE_CONSENSUS_STAKE_SLASH_TERMS_ACTION_V2,
                String::new(),
                nonce + 1,
            ),
        };
        request.authorization = signed_authorization(
            owner,
            &ledger.descriptor.zone_id,
            MIGRATE_CONSENSUS_STAKE_SLASH_TERMS_ACTION_V2,
            request.payload_hash(position),
            nonce + 1,
        );
        request
    }

    fn consensus_stake_slash_fixture() -> (
        Ledger,
        Vec<crate::Identity>,
        Vec<crate::Identity>,
        Vec<crate::Identity>,
        LedgerDerivedStakeEpochV1,
    ) {
        consensus_stake_slash_fixture_with_shared_validator(false)
    }

    fn consensus_stake_slash_fixture_with_shared_validator(
        shared_validator_liabilities: bool,
    ) -> (
        Ledger,
        Vec<crate::Identity>,
        Vec<crate::Identity>,
        Vec<crate::Identity>,
        LedgerDerivedStakeEpochV1,
    ) {
        let (mut ledger, validators, notaries, candidate_identities, mut governance) =
            stake_authority_governance_fixture();
        if shared_validator_liabilities {
            let amount = Amount::from_runlai(1);
            ledger.reserve = ledger.reserve.checked_sub(amount).unwrap();
            ledger.reserve_pools.demand_matching = ledger
                .reserve_pools
                .demand_matching
                .checked_sub(amount)
                .unwrap();
            let source_coin_id = "stake-source-0004".to_string();
            let escrow_coin_id = "stake-escrow-0004".to_string();
            let owner = "stake-owner-0004".to_string();
            let lineage_root = "stake-lineage-0004".to_string();
            ledger.coins.insert(
                source_coin_id.clone(),
                CoinObject {
                    object_id: source_coin_id.clone(),
                    lineage_root: lineage_root.clone(),
                    parent_ids: Vec::new(),
                    owner: owner.clone(),
                    zone_id: ledger.descriptor.zone_id.clone(),
                    amount,
                    state: CoinState::Consumed,
                    version: 0,
                    created_height: 0,
                    transit_id: None,
                    imported_from: None,
                    origin_zone: ledger.descriptor.zone_id.clone(),
                    origin_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
                },
            );
            ledger.coins.insert(
                escrow_coin_id.clone(),
                CoinObject {
                    object_id: escrow_coin_id.clone(),
                    lineage_root,
                    parent_ids: vec![source_coin_id.clone()],
                    owner: owner.clone(),
                    zone_id: ledger.descriptor.zone_id.clone(),
                    amount,
                    state: CoinState::Reserved,
                    version: 1,
                    created_height: 0,
                    transit_id: None,
                    imported_from: None,
                    origin_zone: ledger.descriptor.zone_id.clone(),
                    origin_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
                },
            );
            let position = ConsensusStakePosition {
                position_id: "stake-position-0004".into(),
                kind: ConsensusStakePositionKind::Delegation {
                    validator_id: "stake-validator-0000".into(),
                },
                owner: owner.clone(),
                source_coin_id: source_coin_id.clone(),
                escrow_coin_id: escrow_coin_id.clone(),
                amount,
                locked_height: 0,
                committed_through_height: 100,
                slash_terms: None,
            };
            ledger
                .consensus_stake_escrows
                .insert(escrow_coin_id.clone(), position);
            governance
                .positions
                .push(crate::StakeAuthorityPositionCommandV1 {
                    position_id: "stake-position-0004".into(),
                    position_type: StakePositionTypeV1::Delegation,
                    validator_id: "stake-validator-0000".into(),
                    owner,
                    source_coin_id,
                    escrow_coin_id,
                    amount,
                    locked_height: 0,
                    committed_through_height: 100,
                });
        }
        ledger.assert_conservation().unwrap();

        let owners = (0..governance.positions.len())
            .map(|_| generate_identity())
            .collect::<Vec<_>>();
        for (candidate, owner) in governance.candidates.iter_mut().zip(owners.iter()) {
            candidate.owner = owner.address(&ledger.descriptor.zone_id);
        }
        for (index, position) in governance.positions.iter_mut().enumerate() {
            let owner = owners[index].address(&ledger.descriptor.zone_id);
            position.owner.clone_from(&owner);
            let source_id = position.source_coin_id.clone();
            let escrow_id = position.escrow_coin_id.clone();
            ledger
                .coins
                .get_mut(&source_id)
                .unwrap()
                .owner
                .clone_from(&owner);
            ledger
                .coins
                .get_mut(&escrow_id)
                .unwrap()
                .owner
                .clone_from(&owner);
            ledger
                .consensus_stake_escrows
                .get_mut(&escrow_id)
                .unwrap()
                .owner
                .clone_from(&owner);
        }
        governance.policy.policy_version = 2;
        let context =
            ledger.stake_context_at(u128::from(ledger.height), ledger.state_root().unwrap());
        for (candidate, identity) in governance
            .candidates
            .iter_mut()
            .zip(candidate_identities.iter())
        {
            let internal = ValidatorCandidateRecord {
                validator_id: candidate.validator_id.clone(),
                owner: candidate.owner.clone(),
                public_key: candidate.public_key.clone(),
                key_era: candidate.key_era,
                registered_height: u128::from(candidate.registered_height),
                exit_height: candidate.exit_height.map(u128::from),
                proof_of_possession: String::new(),
            };
            candidate.proof_of_possession = sign_bytes(
                &identity.secret_key,
                &crate::validator_candidate_pop_message_v1(&context, &internal),
            )
            .unwrap();
        }
        let prospective = build_ledger_stake_authority_state_v1(
            &context,
            u128::from(ledger.height + 1),
            None,
            governance.to_ledger_update().unwrap(),
            &ledger.coins,
        )
        .unwrap();
        governance.prospective_authority_commitment = prospective.commitment;
        governance.subject_hash = governance.compute_subject_hash();
        governance.validator_qc = signed_qc(&governance.subject_hash, &validators, 3);
        governance.notary_qc = signed_qc(&governance.subject_hash, &notaries, 3);
        ledger.submit_stake_authority_update(governance).unwrap();

        for (index, owner) in owners.iter().enumerate() {
            let position = ledger
                .consensus_stake_escrows
                .values()
                .find(|position| position.position_id == format!("stake-position-{index:04}"))
                .cloned()
                .unwrap();
            let request = slash_terms_migration_request(
                &ledger,
                owner,
                &position,
                1_000 + (index as u64) * 2,
            );
            ledger.migrate_consensus_stake_slash_terms(request).unwrap();
        }
        let record = ledger.derive_and_store_next_stake_epoch().unwrap();
        while u128::from(ledger.height) < record.descriptor.activation_height {
            ledger.advance().unwrap();
        }
        (ledger, validators, owners, candidate_identities, record)
    }

    fn signed_stake_vote_statement(
        record: &LedgerDerivedStakeEpochV1,
        validator: &crate::Identity,
        proposal_id: &str,
        proposal_hash: String,
        expected_state_root: String,
    ) -> crate::SignedConsensusVoteStatementV1 {
        let mut statement = crate::SignedConsensusVoteStatementV1 {
            proposal_id: proposal_id.into(),
            proposal_hash,
            zone_id: record.descriptor.zone_id.clone(),
            currency_genesis_root: record.descriptor.currency_genesis_root.clone(),
            protocol_era: record.descriptor.protocol_era,
            crypto_era: record.descriptor.crypto_era,
            parent_height: u64::try_from(record.descriptor.activation_height - 1).unwrap(),
            parent_state_root: hash_parts(&[b"RLD-TEST-SLASH-PARENT"]),
            round: 0,
            expected_state_root,
            voter_public_key: validator.public_key.clone(),
            signature: String::new(),
        };
        statement.signature = sign_bytes(
            &validator.secret_key,
            &statement
                .signing_bytes(&record.descriptor.network_domain)
                .unwrap(),
        )
        .unwrap();
        statement
    }

    fn double_sign_evidence(
        record: &LedgerDerivedStakeEpochV1,
        validator: &crate::Identity,
    ) -> crate::ConsensusStakeSlashEvidenceV1 {
        let first = signed_stake_vote_statement(
            record,
            validator,
            "slash-proposal-a",
            hash_parts(&[b"RLD-TEST-SLASH-PROPOSAL-A"]),
            hash_parts(&[b"RLD-TEST-SLASH-ROOT-A"]),
        );
        let second = signed_stake_vote_statement(
            record,
            validator,
            "slash-proposal-b",
            hash_parts(&[b"RLD-TEST-SLASH-PROPOSAL-B"]),
            hash_parts(&[b"RLD-TEST-SLASH-ROOT-B"]),
        );
        let (first, second) = if first
            .signed_commitment(&record.descriptor.network_domain)
            .unwrap()
            < second
                .signed_commitment(&record.descriptor.network_domain)
                .unwrap()
        {
            (first, second)
        } else {
            (second, first)
        };
        crate::ConsensusStakeSlashEvidenceV1 {
            kind: crate::ConsensusStakeSlashEvidenceKindV1::DoubleSign,
            first_vote: Some(first),
            second_vote: Some(second),
            first_checkpoint: None,
            second_checkpoint: None,
            proposal: None,
            invalid_vote: None,
        }
    }

    fn consensus_stake_slash_request(
        ledger: &Ledger,
        record: &LedgerDerivedStakeEpochV1,
        position_index: usize,
        validator: &crate::Identity,
        expected_unbond_request_commitment: Option<String>,
    ) -> SlashConsensusStakeV1 {
        let liability = &record.stake_liabilities[position_index];
        let evidence = double_sign_evidence(record, validator);
        let evidence_hash = evidence
            .evidence_hash(&record.descriptor.network_domain)
            .unwrap();
        let authority = ledger.consensus_stake_authority.as_ref().unwrap();
        SlashConsensusStakeV1 {
            slash_id: format!("consensus-stake-slash-{position_index}"),
            zone_id: ledger.descriptor.zone_id.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            proposed_height: ledger.height,
            expires_at_height: ledger.height + 20,
            expected_authority_sequence: authority.sequence,
            expected_authority_commitment: authority.commitment.clone(),
            consensus_epoch: record.descriptor.consensus_epoch,
            derived_epoch_record_hash: record.record_hash.clone(),
            position_id: liability.position.position_id.clone(),
            escrow_coin_id: liability.position.escrow_coin_id.clone(),
            expected_position_amount: liability.position.amount,
            liability_commitment: liability.liability_commitment.clone(),
            expected_unbond_request_commitment,
            evidence_hash,
            evidence,
        }
    }

