    #[test]
    fn legacy_snapshot_migrates_reserve_pools_and_bootstrap_records() {
        let alice = generate_identity();
        let mut ledger = Ledger::genesis_zone("Earth", vec![], vec![], true).unwrap();
        let zone = ledger.descriptor.zone_id.clone();
        let (_, receipt) = ledger
            .bootstrap_service_reward(
                "alice-node".into(),
                alice.address(&zone),
                ServiceRole::Observer,
                "proof".into(),
                Amount::from_rld_whole(100).unwrap(),
            )
            .unwrap();
        let old_height = ledger.height;
        let old_checkpoint_count = ledger.checkpoints.len();
        let mut snapshot = serde_json::to_value(&ledger).unwrap();
        let object = snapshot.as_object_mut().unwrap();
        object.remove("reserve_pools");
        object.insert("service_orders".into(), serde_json::json!({}));
        object.insert("service_leases".into(), serde_json::json!({}));

        let mut migrated: Ledger = serde_json::from_value(snapshot).unwrap();
        migrated.ensure_reserve_pools().unwrap();
        assert_eq!(migrated.reserve_pools.total().unwrap(), migrated.reserve);
        assert!(migrated.service_orders.contains_key(&receipt.order_id));
        assert!(migrated.service_leases.contains_key(&receipt.lease_id));
        assert_eq!(migrated.height, old_height + 1);
        assert_eq!(migrated.checkpoints.len(), old_checkpoint_count + 1);
        migrated.assert_conservation().unwrap();
    }

    #[test]
    fn signed_zone_discovery_rejects_stale_and_forged_advertisements() {
        let validators = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let validator_keys = validators
            .iter()
            .map(|identity| identity.public_key.clone())
            .collect::<Vec<_>>();
        let source =
            Ledger::empty_zone("Discovery-source", validator_keys, Vec::new(), true).unwrap();
        let mut observer = Ledger::empty_zone("Discovery-observer", vec![], vec![], true).unwrap();
        let advertisement =
            discovery_advertisement(source.descriptor.clone(), 1, Some(&validators));
        let root_before_advertisement = observer.state_root().unwrap();
        observer
            .register_zone_advertisement(advertisement.clone())
            .unwrap();
        assert_ne!(observer.state_root().unwrap(), root_before_advertisement);
        let mut sequence_tamper = observer.clone();
        sequence_tamper.sequence += 1;
        assert_ne!(
            sequence_tamper.state_root().unwrap(),
            observer.state_root().unwrap()
        );
        assert!(matches!(
            observer.register_zone_advertisement(advertisement.clone()),
            Err(LedgerError::Duplicate(_))
        ));

        let mut forged = advertisement;
        forged.sequence = 2;
        forged.descriptor.validator_keys = vec![generate_identity().public_key];
        let subject = forged.compute_subject_hash();
        forged.subject_hash.clone_from(&subject);
        forged.validator_qc = QuorumCertificate {
            subject_hash: subject.clone(),
            threshold: 1,
            attestations: vec![crate::SignedAttestation {
                public_key: forged.descriptor.validator_keys[0].clone(),
                signature: String::new(),
            }],
            testnet_simulated: false,
        };
        assert!(observer.register_zone_advertisement(forged).is_err());
    }

    #[test]
    fn signed_payment_request_is_single_use_and_recipient_can_confirm() {
        let alice = generate_identity();
        let bob = generate_identity();
        let mut ledger = Ledger::genesis_zone("Earth-request", vec![], vec![], true).unwrap();
        let zone = ledger.descriptor.zone_id.clone();
        let (coin, _) = ledger
            .bootstrap_service_reward(
                "alice-request-node".into(),
                alice.address(&zone),
                ServiceRole::Observer,
                "request-flow".into(),
                Amount::from_rld_whole(20).unwrap(),
            )
            .unwrap();
        let mut request = PaymentRequest {
            request_id: "request-bob-coffee".into(),
            recipient: bob.address(&zone),
            recipient_public_key: bob.public_key.clone(),
            destination_zone: zone.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            amount: Amount::from_rld_whole(3).unwrap(),
            memo: "coffee".into(),
            expires_at_height: ledger.height + 100,
            nonce: 9,
            signature: String::new(),
        };
        request.signature = sign_bytes(&bob.secret_key, &request.signing_bytes()).unwrap();
        let mut foreign_request = request.clone();
        foreign_request.currency_genesis_root = "foreign-currency-root".into();
        foreign_request.signature =
            sign_bytes(&bob.secret_key, &foreign_request.signing_bytes()).unwrap();
        assert!(matches!(
            ledger.register_payment_request(foreign_request),
            Err(LedgerError::Invalid(message))
                if message.contains("network or era context mismatch")
        ));
        ledger.register_payment_request(request.clone()).unwrap();

        let mut intent = signed_intent(
            &alice,
            &zone,
            &zone,
            &bob.address(&zone),
            &coin.object_id,
            request.amount,
        );
        intent.payment_id = "payment-request-bob-coffee".into();
        intent.payment_request_id = Some(request.request_id.clone());
        intent.payment_request = Some(request.clone());
        intent.signature = sign_bytes(&alice.secret_key, &intent.signing_bytes()).unwrap();
        let payment = ledger.local_payment(intent).unwrap();

        let change_coin = ledger
            .coins_for_owner(&alice.address(&zone))
            .into_iter()
            .find(|candidate| candidate.state == CoinState::Spendable)
            .unwrap();
        let mut replay = signed_intent(
            &alice,
            &zone,
            &zone,
            &bob.address(&zone),
            &change_coin.object_id,
            request.amount,
        );
        replay.payment_request_id = Some(request.request_id.clone());
        replay.payment_request = Some(request);
        replay.signature = sign_bytes(&alice.secret_key, &replay.signing_bytes()).unwrap();
        assert!(matches!(
            ledger.local_payment(replay),
            Err(LedgerError::Duplicate(_))
        ));

        let mut receipt = RecipientReceipt {
            receipt_id: "recipient-receipt-coffee".into(),
            payment_id: payment.intent.payment_id.clone(),
            settlement_reference: payment.intent.payment_id.clone(),
            destination_zone: zone.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            recipient: bob.address(&zone),
            recipient_public_key: bob.public_key.clone(),
            amount: payment.intent.amount,
            observed_destination_height: ledger.height,
            nonce: 10,
            signature: String::new(),
        };
        receipt.signature = sign_bytes(&bob.secret_key, &receipt.signing_bytes()).unwrap();
        let mut stale_receipt = receipt.clone();
        stale_receipt.crypto_era += 1;
        stale_receipt.signature =
            sign_bytes(&bob.secret_key, &stale_receipt.signing_bytes()).unwrap();
        assert!(matches!(
            ledger.accept_recipient_receipt(stale_receipt),
            Err(LedgerError::Invalid(message))
                if message.contains("network or era context mismatch")
        ));
        ledger.accept_recipient_receipt(receipt).unwrap();
        assert!(ledger
            .recipient_receipts
            .contains_key("payment-request-bob-coffee"));
    }

    #[test]
    fn cross_zone_payment_request_is_qc_bound_and_destination_validated() {
        let alice = generate_identity();
        let bob = generate_identity();
        let mut earth = Ledger::genesis_zone("Earth-request-cross", vec![], vec![], true).unwrap();
        let mut mars = Ledger::empty_zone("Mars-request-cross", vec![], vec![], true).unwrap();
        let earth_id = earth.descriptor.zone_id.clone();
        let mars_id = mars.descriptor.zone_id.clone();
        let (coin, _) = earth
            .bootstrap_service_reward(
                "cross-request-node".into(),
                alice.address(&earth_id),
                ServiceRole::Relay,
                "cross-request-proof".into(),
                Amount::from_rld_whole(10).unwrap(),
            )
            .unwrap();
        let mut request = PaymentRequest {
            request_id: "request-mars-cross".into(),
            recipient: bob.address(&mars_id),
            recipient_public_key: bob.public_key.clone(),
            destination_zone: mars_id.clone(),
            currency_genesis_root: mars.descriptor.currency_genesis_root.clone(),
            protocol_era: mars.descriptor.protocol_era,
            crypto_era: mars.descriptor.crypto_era + 1,
            amount: Amount::from_rld_whole(2).unwrap(),
            memo: "destination-era-check".into(),
            expires_at_height: mars.height + 100,
            nonce: 11,
            signature: String::new(),
        };
        request.signature = sign_bytes(&bob.secret_key, &request.signing_bytes()).unwrap();
        let mut intent = signed_intent(
            &alice,
            &earth_id,
            &mars_id,
            &bob.address(&mars_id),
            &coin.object_id,
            request.amount,
        );
        intent.payment_request_id = Some(request.request_id.clone());
        intent.payment_request = Some(request.clone());
        intent.signature = sign_bytes(&alice.secret_key, &intent.signing_bytes()).unwrap();

        let capsule = earth
            .export_payment(intent, TransportClass::SublightDtn)
            .unwrap();
        assert_eq!(capsule.payment_request.as_ref(), Some(&request));
        assert!(matches!(
            mars.import_capsule(capsule),
            Err(LedgerError::Invalid(message))
                if message.contains("network or era context mismatch")
        ));
        assert!(!mars.consumed_payment_requests.contains(&request.request_id));
        mars.assert_conservation().unwrap();
    }

