    #[test]
    fn v2_zone_identity_binds_currency_network_and_hash_suite() {
        let testnet = Ledger::empty_zone("Identity-domain", vec![], vec![], true).unwrap();
        let mainnet = Ledger::empty_zone("Identity-domain", vec![], vec![], false).unwrap();

        assert_eq!(
            testnet.descriptor.identity_version,
            CURRENT_ZONE_IDENTITY_VERSION
        );
        assert_eq!(
            testnet.descriptor.identity_hash_suite,
            ZONE_IDENTITY_HASH_SUITE
        );
        assert_eq!(testnet.descriptor.network_domain, RLDCOIN_TESTNET_DOMAIN);
        assert_eq!(mainnet.descriptor.network_domain, RLDCOIN_MAINNET_DOMAIN);
        assert_ne!(testnet.descriptor.zone_id, mainnet.descriptor.zone_id);
        testnet.descriptor.validate_identity().unwrap();
        mainnet.descriptor.validate_identity().unwrap();

        let mut forged_currency = testnet.descriptor.clone();
        forged_currency.currency_genesis_root = "foreign-currency-root".into();
        assert!(forged_currency.validate_identity().is_err());

        let mut forged_domain = testnet.descriptor.clone();
        forged_domain.network_domain = RLDCOIN_MAINNET_DOMAIN.into();
        assert!(forged_domain.validate_identity().is_err());

        let mut forged_suite = testnet.descriptor.clone();
        forged_suite.identity_hash_suite = "UNSUPPORTED-HASH".into();
        assert!(forged_suite.validate_identity().is_err());

        let mut forged_network_kind = testnet.descriptor.clone();
        forged_network_kind.testnet = false;
        assert!(forged_network_kind.validate_identity().is_err());
    }

    #[test]
    fn configured_zone_requires_signed_era_transition() {
        let validators = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let notaries = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let validator_keys = validators
            .iter()
            .map(|identity| identity.public_key.clone())
            .collect::<Vec<_>>();
        let notary_keys = notaries
            .iter()
            .map(|identity| identity.public_key.clone())
            .collect::<Vec<_>>();
        let mut ledger = Ledger::genesis_zone(
            "Earth-era-qc",
            validator_keys.clone(),
            notary_keys.clone(),
            true,
        )
        .unwrap();
        let suite = CryptoSuiteDescriptor {
            suite_id: "era-2-suite".into(),
            signature_algorithm: "ED25519".into(),
            hash_algorithm: "SHA-256".into(),
            encoding: "RLD-CANONICAL-V1".into(),
        };
        assert!(matches!(
            ledger.activate_testnet_era(suite.clone()),
            Err(LedgerError::EraTransition(_))
        ));

        let mut certificate = EraContinuityCertificate {
            zone_id: ledger.descriptor.zone_id.clone(),
            previous_protocol_era: 1,
            new_protocol_era: 2,
            previous_crypto_era: 1,
            new_crypto_era: 2,
            previous_certificate_hash: ledger.era_continuity_accumulator.clone(),
            activation_checkpoint: ledger.latest_checkpoint().unwrap().checkpoint_hash.clone(),
            irreversible_height: ledger.height + 1,
            new_suite: suite,
            previous_validator_keys: validator_keys.clone(),
            previous_notary_keys: notary_keys.clone(),
            new_validator_keys: validator_keys,
            new_notary_keys: notary_keys,
            old_crypto_qc: simulated_qc(),
            new_crypto_qc: simulated_qc(),
            notary_qc: simulated_qc(),
            certificate_hash: String::new(),
        };
        let subject = certificate.subject_hash();
        certificate.certificate_hash.clone_from(&subject);
        certificate.old_crypto_qc = signed_qc(&subject, &validators, 3);
        certificate.new_crypto_qc = signed_qc(&subject, &validators, 3);
        certificate.notary_qc = signed_qc(&subject, &notaries, 3);
        ledger.apply_era_transition(certificate).unwrap();
        assert_eq!(ledger.descriptor.protocol_era, 2);
        assert_eq!(ledger.descriptor.crypto_era, 2);
    }

    #[test]
    fn signed_era_transition_requires_exact_local_predecessor_atomically() {
        let validators = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let notaries = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let mut ledger = Ledger::genesis_zone(
            "Earth-era-predecessor",
            validators
                .iter()
                .map(|key| key.public_key.clone())
                .collect(),
            notaries.iter().map(|key| key.public_key.clone()).collect(),
            true,
        )
        .unwrap();
        let genesis_predecessor = ledger.era_continuity_accumulator.clone();
        let signed = |ledger: &Ledger, previous: String| {
            let mut certificate = EraContinuityCertificate {
                zone_id: ledger.descriptor.zone_id.clone(),
                previous_protocol_era: ledger.descriptor.protocol_era,
                new_protocol_era: ledger.descriptor.protocol_era + 1,
                previous_crypto_era: ledger.descriptor.crypto_era,
                new_crypto_era: ledger.descriptor.crypto_era + 1,
                previous_certificate_hash: previous,
                activation_checkpoint: ledger.latest_checkpoint().unwrap().checkpoint_hash.clone(),
                irreversible_height: ledger.height + 1,
                new_suite: CryptoSuiteDescriptor {
                    suite_id: "linked-ed25519-candidate".into(),
                    signature_algorithm: "ED25519".into(),
                    hash_algorithm: "SHA-256".into(),
                    encoding: "RLD-CANONICAL-V1".into(),
                },
                previous_validator_keys: ledger.descriptor.validator_keys.clone(),
                previous_notary_keys: ledger.descriptor.notary_keys.clone(),
                new_validator_keys: ledger.descriptor.validator_keys.clone(),
                new_notary_keys: ledger.descriptor.notary_keys.clone(),
                old_crypto_qc: simulated_qc(),
                new_crypto_qc: simulated_qc(),
                notary_qc: simulated_qc(),
                certificate_hash: String::new(),
            };
            let subject = certificate.subject_hash();
            certificate.certificate_hash.clone_from(&subject);
            certificate.old_crypto_qc = signed_qc(&subject, &validators, 3);
            certificate.new_crypto_qc = signed_qc(&subject, &validators, 3);
            certificate.notary_qc = signed_qc(&subject, &notaries, 3);
            certificate
        };
        for _ in 0..2 {
            let expected = ledger
                .era_certificates
                .last()
                .map(|certificate| certificate.certificate_hash.clone())
                .unwrap_or_else(|| genesis_predecessor.clone());
            let mut invalid = vec![String::new(), "ff".repeat(32)];
            if expected != genesis_predecessor {
                invalid.push(genesis_predecessor.clone());
                // The rolling accumulator is distinct from the previous
                // individual certificate after the first accepted handoff.
                invalid.push(ledger.era_continuity_accumulator.clone());
            }
            for previous in invalid {
                assert_ne!(previous, expected);
                let certificate = signed(&ledger, previous);
                certificate
                    .old_crypto_qc
                    .verify(&certificate.previous_validator_keys)
                    .unwrap();
                certificate
                    .new_crypto_qc
                    .verify(&certificate.new_validator_keys)
                    .unwrap();
                certificate
                    .notary_qc
                    .verify(&certificate.previous_notary_keys)
                    .unwrap();
                let before = serde_json::to_vec(&ledger).unwrap();
                assert!(
                    matches!(
                        ledger.apply_era_transition(certificate),
                        Err(LedgerError::EraTransition(_))
                    ),
                    "genuinely signed handoff with a false predecessor must refuse"
                );
                assert_eq!(serde_json::to_vec(&ledger).unwrap(), before);
            }
            let certificate = signed(&ledger, expected);
            let id = certificate.certificate_hash.clone();
            let next_era = certificate.new_protocol_era;
            ledger.apply_era_transition(certificate).unwrap();
            assert_eq!(ledger.descriptor.protocol_era, next_era);
            assert_eq!(ledger.era_certificates.last().unwrap().certificate_hash, id);
            ledger.assert_conservation().unwrap();
        }
    }

    #[test]
    fn audit_era_chain_requires_complete_authenticated_handoffs() {
        let validators = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let successors = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let notaries = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let keys = |members: &[crate::Identity]| {
            members
                .iter()
                .map(|key| key.public_key.clone())
                .collect::<Vec<_>>()
        };
        let mut ledger = Ledger::genesis_zone(
            "Earth-audit-era-chain",
            keys(&validators),
            keys(&notaries),
            true,
        )
        .unwrap();
        let certify = |certificate: &mut EraContinuityCertificate,
                       old: &[crate::Identity],
                       new: &[crate::Identity]| {
            let subject = certificate.subject_hash();
            certificate.certificate_hash.clone_from(&subject);
            certificate.old_crypto_qc = signed_qc(&subject, old, 3);
            certificate.new_crypto_qc = signed_qc(&subject, new, 3);
            certificate.notary_qc = signed_qc(&subject, &notaries, 3);
        };
        for (old, new) in [(&validators, &successors), (&successors, &validators)] {
            let mut certificate = EraContinuityCertificate {
                zone_id: ledger.descriptor.zone_id.clone(),
                previous_protocol_era: ledger.descriptor.protocol_era,
                new_protocol_era: ledger.descriptor.protocol_era + 1,
                previous_crypto_era: ledger.descriptor.crypto_era,
                new_crypto_era: ledger.descriptor.crypto_era + 1,
                previous_certificate_hash: ledger
                    .era_certificates
                    .last()
                    .map(|previous| previous.certificate_hash.clone())
                    .unwrap_or_else(|| ledger.era_continuity_accumulator.clone()),
                activation_checkpoint: ledger.latest_checkpoint().unwrap().checkpoint_hash.clone(),
                irreversible_height: ledger.height + 1,
                new_suite: CryptoSuiteDescriptor {
                    suite_id: "audit-linked-ed25519-candidate".into(),
                    signature_algorithm: "ED25519".into(),
                    hash_algorithm: "SHA-256".into(),
                    encoding: "RLD-CANONICAL-V1".into(),
                },
                previous_validator_keys: keys(old),
                previous_notary_keys: keys(&notaries),
                new_validator_keys: keys(new),
                new_notary_keys: keys(&notaries),
                old_crypto_qc: simulated_qc(),
                new_crypto_qc: simulated_qc(),
                notary_qc: simulated_qc(),
                certificate_hash: String::new(),
            };
            certify(&mut certificate, old, new);
            ledger.apply_era_transition(certificate).unwrap();
            if ledger.descriptor.protocol_era == 2 {
                // Ordinary intermediate checkpoints must retain the current
                // era until the next actually authorized handoff.
                ledger.create_checkpoint().unwrap();
                ledger.create_checkpoint().unwrap();
            }
        }
        let bundle = ledger.audit_proof_bundle().unwrap();
        bundle.verify_structure().unwrap();
        let refusal = |mut altered: AuditProofBundle, reason: &str| {
            // A recomputable container digest is not continuity authority.
            altered.commitment_hash = altered.compute_commitment().unwrap();
            assert!(
                altered.verify_structure().is_err(),
                "audit must refuse {reason}"
            );
        };
        let mut premature = bundle.clone();
        assert_eq!(premature.checkpoints[2].protocol_era, 2);
        assert_eq!(premature.checkpoints[2].crypto_era, 2);
        premature.checkpoints[2].protocol_era = 3;
        premature.checkpoints[2].crypto_era = 3;
        refusal(
            premature,
            "intermediate checkpoint claims an unactivated era",
        );
        let mut missing = bundle.clone();
        missing.era_certificates.clear();
        refusal(missing, "missing entire certificate chain");
        let mut truncated = bundle.clone();
        truncated.era_certificates.remove(0);
        refusal(truncated, "missing genesis handoff");
        let mut reordered = bundle.clone();
        reordered.era_certificates.reverse();
        refusal(reordered, "reordered signed handoffs");
        let mut broken = bundle.clone();
        broken.era_certificates[1].previous_certificate_hash = "ff".repeat(32);
        certify(&mut broken.era_certificates[1], &successors, &validators);
        refusal(broken, "genuinely signed false predecessor");
        let mut skipped = bundle.clone();
        skipped.era_certificates[1].new_protocol_era += 1;
        certify(&mut skipped.era_certificates[1], &successors, &validators);
        refusal(skipped, "genuinely signed skipped protocol era");
        let mut forged = bundle.clone();
        forged.era_certificates[1]
            .old_crypto_qc
            .attestations
            .clear();
        refusal(forged, "missing actual old-validator signatures");
        let mut wrong_source = bundle.clone();
        wrong_source.era_certificates[1].previous_validator_keys = keys(&validators);
        certify(
            &mut wrong_source.era_certificates[1],
            &validators,
            &validators,
        );
        refusal(
            wrong_source,
            "genuinely signed incorrect preceding signer set",
        );
        let mut wrong_checkpoint = bundle.clone();
        wrong_checkpoint.era_certificates[1].activation_checkpoint =
            bundle.checkpoints[0].checkpoint_hash.clone();
        certify(
            &mut wrong_checkpoint.era_certificates[1],
            &successors,
            &validators,
        );
        refusal(
            wrong_checkpoint,
            "genuinely signed stale activation checkpoint",
        );
        let mut descriptor_mismatch = bundle.clone();
        descriptor_mismatch.zone_descriptor.crypto_era += 1;
        refusal(
            descriptor_mismatch,
            "terminal descriptor not reached by signed handoffs",
        );
        bundle.verify_structure().unwrap();

        let mut accepted = Vec::new();
        let mut forged_genesis = bundle.clone();
        forged_genesis.zone_descriptor.genesis_validator_keys = keys(&successors);
        forged_genesis.era_certificates[0].previous_validator_keys = keys(&successors);
        certify(
            &mut forged_genesis.era_certificates[0],
            &successors,
            &successors,
        );
        forged_genesis.era_certificates[1].previous_certificate_hash =
            forged_genesis.era_certificates[0].certificate_hash.clone();
        certify(
            &mut forged_genesis.era_certificates[1],
            &successors,
            &validators,
        );
        forged_genesis.commitment_hash = forged_genesis.compute_commitment().unwrap();
        assert!(forged_genesis.zone_descriptor.validate_identity().is_err());
        if forged_genesis.verify_structure().is_ok() {
            accepted.push("forged immutable genesis signer anchor");
        }
        for (field, unsupported) in [
            ("signature", "UNIMPLEMENTED-SIGNATURE"),
            ("hash", "UNIMPLEMENTED-HASH"),
            ("encoding", "UNIMPLEMENTED-ENCODING"),
        ] {
            let mut certificate = bundle.era_certificates.last().unwrap().clone();
            certificate.previous_protocol_era = ledger.descriptor.protocol_era;
            certificate.previous_crypto_era = ledger.descriptor.crypto_era;
            certificate.new_protocol_era = ledger.descriptor.protocol_era + 1;
            certificate.new_crypto_era = ledger.descriptor.crypto_era + 1;
            certificate.previous_validator_keys = keys(&validators);
            certificate.previous_certificate_hash = ledger
                .era_certificates
                .last()
                .unwrap()
                .certificate_hash
                .clone();
            certificate.activation_checkpoint =
                ledger.latest_checkpoint().unwrap().checkpoint_hash.clone();
            certificate.irreversible_height = ledger.height + 1;
            if field == "signature" {
                let mut supported = certificate.clone();
                certify(&mut supported, &validators, &validators);
                ledger.clone().apply_era_transition(supported).unwrap();
            }
            let mut unsupported_archive = bundle.clone();
            let archived_suite = &mut unsupported_archive.era_certificates[1].new_suite;
            match field {
                "signature" => archived_suite.signature_algorithm = unsupported.into(),
                "hash" => archived_suite.hash_algorithm = unsupported.into(),
                "encoding" => archived_suite.encoding = unsupported.into(),
                _ => unreachable!(),
            }
            certify(
                &mut unsupported_archive.era_certificates[1],
                &successors,
                &validators,
            );
            refusal(unsupported_archive, unsupported);
            match field {
                "signature" => certificate.new_suite.signature_algorithm = unsupported.into(),
                "hash" => certificate.new_suite.hash_algorithm = unsupported.into(),
                "encoding" => certificate.new_suite.encoding = unsupported.into(),
                _ => unreachable!(),
            }
            certify(&mut certificate, &validators, &validators);
            certificate
                .old_crypto_qc
                .verify(&keys(&validators))
                .unwrap();
            certificate
                .new_crypto_qc
                .verify(&keys(&validators))
                .unwrap();
            certificate.notary_qc.verify(&keys(&notaries)).unwrap();
            let mut candidate = ledger.clone();
            let before = serde_json::to_vec(&candidate).unwrap();
            match candidate.apply_era_transition(certificate) {
                Ok(_) => accepted.push(unsupported),
                Err(LedgerError::EraTransition(_)) => {
                    assert_eq!(serde_json::to_vec(&candidate).unwrap(), before);
                }
                Err(error) => panic!("suite must refuse at era gate: {error}"),
            }
        }
        assert!(
            accepted.is_empty(),
            "invalid era authority accepted: {accepted:?}"
        );

        // Exercise the complete import gate with fresh in-memory test value,
        // actual owner approval, both source QCs and all three era QCs.
        let alice = generate_identity();
        let bob = generate_identity();
        let mut source = ledger.clone();
        let mut destination =
            Ledger::empty_zone("Earth-audit-era-recipient", vec![], vec![], true).unwrap();
        let source_zone = source.descriptor.zone_id.clone();
        let destination_zone = destination.descriptor.zone_id.clone();
        let (coin, _) = source
            .bootstrap_service_reward(
                "era-import-client".into(),
                alice.address(&source_zone),
                ServiceRole::Relay,
                "era-import-test".into(),
                Amount::from_rld_whole(10).unwrap(),
            )
            .unwrap();
        let mut intent = signed_intent(
            &alice,
            &source_zone,
            &destination_zone,
            &bob.address(&destination_zone),
            &coin.object_id,
            Amount::from_rld_whole(1).unwrap(),
        );
        intent.protocol_era = source.descriptor.protocol_era;
        intent.crypto_era = source.descriptor.crypto_era;
        intent.signature = sign_bytes(&alice.secret_key, &intent.signing_bytes()).unwrap();
        let mut capsule = source
            .export_payment(intent, TransportClass::SublightDtn)
            .unwrap();
        let subject = capsule.subject_hash();
        capsule.validator_qc = signed_qc(&subject, &validators, 3);
        capsule.notary_qc = signed_qc(&subject, &notaries, 3);
        let mut accepted_destination = destination.clone();
        accepted_destination
            .import_capsule(capsule.clone())
            .unwrap();
        accepted_destination.assert_conservation().unwrap();
        source.assert_conservation().unwrap();
        for field in ["signature", "hash", "encoding"] {
            let mut unsupported = capsule.clone();
            let certificate = unsupported.era_certificate.as_mut().unwrap();
            match field {
                "signature" => {
                    certificate.new_suite.signature_algorithm = "UNIMPLEMENTED-SIGNATURE".into()
                }
                "hash" => certificate.new_suite.hash_algorithm = "UNIMPLEMENTED-HASH".into(),
                "encoding" => certificate.new_suite.encoding = "UNIMPLEMENTED-ENCODING".into(),
                _ => unreachable!(),
            }
            certify(certificate, &successors, &validators);
            unsupported.operational_proof.era_certificate_hash =
                certificate.certificate_hash.clone();
            let subject = unsupported.subject_hash();
            unsupported.validator_qc = signed_qc(&subject, &validators, 3);
            unsupported.notary_qc = signed_qc(&subject, &notaries, 3);
            let before = serde_json::to_vec(&destination).unwrap();
            assert!(matches!(
                destination.import_capsule(unsupported),
                Err(LedgerError::EraTransition(_))
            ));
            assert_eq!(serde_json::to_vec(&destination).unwrap(), before);
        }
    }

    #[test]
    fn signed_route_quote_failover_stays_inside_the_preauthorized_budget() {
        let alice = generate_identity();
        let bob = generate_identity();
        let route_node = generate_identity();
        let mut earth = Ledger::genesis_zone("Earth-route", vec![], vec![], true).unwrap();
        let mars = Ledger::empty_zone("Mars-route", vec![], vec![], true).unwrap();
        let earth_id = earth.descriptor.zone_id.clone();
        let mars_id = mars.descriptor.zone_id.clone();
        let (coin, _) = earth
            .bootstrap_service_reward(
                "alice-route-client".into(),
                alice.address(&earth_id),
                ServiceRole::Relay,
                "route-payment".into(),
                Amount::from_rld_whole(100).unwrap(),
            )
            .unwrap();
        let provider = route_node.address(&earth_id);
        let failed_hop = "zone-failed-relay".to_owned();
        let route = vec![earth_id.clone(), failed_hop.clone(), mars_id.clone()];
        let route_path = route.join("|");
        let base_fee = Amount::from_rld_whole(2).unwrap();
        let reroute_budget = Amount::from_rld_whole(1).unwrap();
        let expiry = earth.height + 100;
        let payload = action_payload_hash(
            "CREATE_ROUTE_QUOTE",
            &[
                provider.as_bytes(),
                mars_id.as_bytes(),
                route_path.as_bytes(),
                b"SUBLIGHT_DTN",
                &base_fee.0.to_be_bytes(),
                &reroute_budget.0.to_be_bytes(),
                &expiry.to_be_bytes(),
            ],
        );
        let quote = earth
            .create_route_quote(CreateRouteQuoteRequest {
                provider: provider.clone(),
                destination_zone: mars_id.clone(),
                route,
                transport: TransportClass::SublightDtn,
                base_fee,
                authorized_reroute_budget: reroute_budget,
                expires_at_height: expiry,
                authorization: signed_authorization(
                    &route_node,
                    &earth_id,
                    "CREATE_ROUTE_QUOTE",
                    payload,
                    30,
                ),
            })
            .unwrap();

        let replacement_route = vec![
            earth_id.clone(),
            "zone-backup-relay".into(),
            mars_id.clone(),
        ];
        let incremental_fee = Amount::from_rld_whole(1).unwrap();
        let reroute_payload = action_payload_hash(
            "REROUTE_ROUTE_QUOTE",
            &[
                quote.quote_id.as_bytes(),
                failed_hop.as_bytes(),
                replacement_route.join("|").as_bytes(),
                &incremental_fee.0.to_be_bytes(),
            ],
        );
        let rerouted = earth
            .reroute_route_quote(
                &quote.quote_id,
                RerouteRouteQuoteRequest {
                    failed_hop,
                    replacement_route,
                    incremental_fee,
                    authorization: signed_authorization(
                        &route_node,
                        &earth_id,
                        "REROUTE_ROUTE_QUOTE",
                        reroute_payload,
                        31,
                    ),
                },
            )
            .unwrap();
        assert_eq!(rerouted.consumed_reroute_fee, reroute_budget);

        let mut intent = signed_intent(
            &alice,
            &earth_id,
            &mars_id,
            &bob.address(&mars_id),
            &coin.object_id,
            Amount::from_rld_whole(10).unwrap(),
        );
        intent.route_quote_id = Some(quote.quote_id.clone());
        intent.max_fee = base_fee;
        intent.signature = sign_bytes(&alice.secret_key, &intent.signing_bytes()).unwrap();
        assert!(matches!(
            earth.export_payment(intent.clone(), TransportClass::SublightDtn),
            Err(LedgerError::Invalid(_))
        ));
        assert_eq!(
            earth.route_quotes[&quote.quote_id].status,
            RouteQuoteStatus::Open
        );

        intent.max_fee = base_fee.checked_add(reroute_budget).unwrap();
        intent.signature = sign_bytes(&alice.secret_key, &intent.signing_bytes()).unwrap();
        earth
            .export_payment(intent, TransportClass::SublightDtn)
            .unwrap();
        assert_eq!(
            earth.balance(&provider).unwrap(),
            Amount::from_rld_whole(3).unwrap()
        );
        assert_eq!(
            earth.route_quotes[&quote.quote_id].status,
            RouteQuoteStatus::Locked
        );
        assert_eq!(
            earth.balance(&alice.address(&earth_id)).unwrap(),
            Amount::from_rld_whole(87).unwrap()
        );
    }

    #[test]
    fn liquidity_offer_makes_recipient_final_and_routes_claim_to_provider() {
        let alice = generate_identity();
        let bob = generate_identity();
        let provider = generate_identity();
        let mut earth = Ledger::genesis_zone("Earth-liquidity", vec![], vec![], true).unwrap();
        let mut mars = Ledger::empty_zone("Mars-liquidity", vec![], vec![], true).unwrap();
        let earth_id = earth.descriptor.zone_id.clone();
        let mars_id = mars.descriptor.zone_id.clone();
        let (genesis_coin, _) = earth
            .bootstrap_service_reward(
                "liquidity-seed-node".into(),
                alice.address(&earth_id),
                ServiceRole::Liquidity,
                "seed-destination-liquidity".into(),
                Amount::from_rld_whole(100).unwrap(),
            )
            .unwrap();

        let seed_intent = signed_intent(
            &alice,
            &earth_id,
            &mars_id,
            &provider.address(&mars_id),
            &genesis_coin.object_id,
            Amount::from_rld_whole(20).unwrap(),
        );
        let seed_capsule = earth
            .export_payment(seed_intent, TransportClass::SublightDtn)
            .unwrap();
        let seed_receipt = mars.import_capsule(seed_capsule).unwrap();
        earth.finalize_export(&seed_receipt).unwrap();

        let provider_coin = mars
            .coins_for_owner(&provider.address(&mars_id))
            .into_iter()
            .find(|coin| coin.state == CoinState::Spendable)
            .unwrap();
        let offer_amount = Amount::from_rld_whole(20).unwrap();
        let minimum = Amount::from_rld_whole(1).unwrap();
        let maximum = Amount::from_rld_whole(10).unwrap();
        let expiry = mars.height + 100;
        let offer_payload = action_payload_hash(
            "CREATE_LIQUIDITY_OFFER",
            &[
                provider.address(&mars_id).as_bytes(),
                provider_coin.object_id.as_bytes(),
                &offer_amount.0.to_be_bytes(),
                &minimum.0.to_be_bytes(),
                &maximum.0.to_be_bytes(),
                &expiry.to_be_bytes(),
            ],
        );
        let offer = mars
            .create_liquidity_offer(CreateLiquidityOfferRequest {
                provider: provider.address(&mars_id),
                coin_id: provider_coin.object_id,
                amount: offer_amount,
                minimum,
                maximum,
                expires_at_height: expiry,
                authorization: signed_authorization(
                    &provider,
                    &mars_id,
                    "CREATE_LIQUIDITY_OFFER",
                    offer_payload,
                    40,
                ),
            })
            .unwrap();

        let alice_change = earth
            .coins_for_owner(&alice.address(&earth_id))
            .into_iter()
            .find(|coin| coin.state == CoinState::Spendable)
            .unwrap();
        let payment_intent = signed_intent(
            &alice,
            &earth_id,
            &mars_id,
            &bob.address(&mars_id),
            &alice_change.object_id,
            Amount::from_rld_whole(5).unwrap(),
        );
        let payment_capsule = earth
            .export_payment(payment_intent, TransportClass::SublightDtn)
            .unwrap();
        let certificate = mars
            .take_liquidity_offer(TakeLiquidityOfferRequest {
                offer_id: offer.offer_id,
                settlement_claim: payment_capsule.clone(),
            })
            .unwrap();
        assert_eq!(
            mars.balance(&bob.address(&mars_id)).unwrap(),
            Amount::from_rld_whole(5).unwrap()
        );
        assert_eq!(certificate.recipient, bob.address(&mars_id));

        let receipt = mars.import_capsule(payment_capsule).unwrap();
        assert_eq!(
            mars.coins[&receipt.destination_coin_id].owner,
            provider.address(&mars_id)
        );
        assert_eq!(
            mars.balance(&provider.address(&mars_id)).unwrap(),
            Amount::from_rld_whole(5).unwrap()
        );
        assert_eq!(
            mars.balance(&bob.address(&mars_id)).unwrap(),
            Amount::from_rld_whole(5).unwrap()
        );
        earth.finalize_export(&receipt).unwrap();
        earth.assert_conservation().unwrap();
        mars.assert_conservation().unwrap();
    }

    #[test]
    fn funded_service_lease_pays_the_node() {
        let buyer = generate_identity();
        let archive_node = generate_identity();
        let mut ledger = Ledger::genesis_zone("Earth", vec![], vec![], true).unwrap();
        let zone = ledger.descriptor.zone_id.clone();
        let buyer_address = buyer.address(&zone);
        let (coin, _) = ledger
            .bootstrap_service_reward(
                "buyer-node".into(),
                buyer_address.clone(),
                ServiceRole::Observer,
                "proof".into(),
                Amount::from_rld_whole(100).unwrap(),
            )
            .unwrap();
        let budget = Amount::from_rld_whole(12).unwrap();
        let description = "hold checkpoint".to_owned();
        let create_payload = action_payload_hash(
            "CREATE_SERVICE_ORDER",
            &[
                buyer_address.as_bytes(),
                coin.object_id.as_bytes(),
                b"ARCHIVE",
                &budget.0.to_be_bytes(),
                description.as_bytes(),
            ],
        );
        let order = ledger
            .create_service_order(
                buyer_address,
                coin.object_id,
                ServiceRole::Archive,
                budget,
                description,
                signed_authorization(&buyer, &zone, "CREATE_SERVICE_ORDER", create_payload, 1),
            )
            .unwrap();
        let quote = Amount::from_rld_whole(10).unwrap();
        let lease_payload = action_payload_hash(
            "LEASE_SERVICE",
            &[
                order.order_id.as_bytes(),
                archive_node.public_key.as_bytes(),
                &quote.0.to_be_bytes(),
            ],
        );
        let lease = ledger
            .lease_service(
                &order.order_id,
                archive_node.public_key.clone(),
                quote,
                signed_authorization(&archive_node, &zone, "LEASE_SERVICE", lease_payload, 2),
            )
            .unwrap();
        let proof_hash = "proof-of-storage".to_owned();
        let complete_payload = action_payload_hash(
            "COMPLETE_SERVICE",
            &[
                lease.lease_id.as_bytes(),
                archive_node.public_key.as_bytes(),
                proof_hash.as_bytes(),
            ],
        );
        ledger
            .complete_service(
                &lease.lease_id,
                proof_hash,
                signed_authorization(
                    &archive_node,
                    &zone,
                    "COMPLETE_SERVICE",
                    complete_payload,
                    3,
                ),
            )
            .unwrap();
        assert_eq!(
            ledger.node_earnings[&archive_node.public_key].total,
            Amount::from_rld_whole(10).unwrap()
        );
        ledger.assert_conservation().unwrap();
    }

    #[test]
    fn continuity_pool_requires_dual_qc_for_order_and_completion() {
        let buyer = generate_identity();
        let archive_node = generate_identity();
        let validators = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let notaries = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let validator_keys = validators
            .iter()
            .map(|identity| identity.public_key.clone())
            .collect::<Vec<_>>();
        let notary_keys = notaries
            .iter()
            .map(|identity| identity.public_key.clone())
            .collect::<Vec<_>>();
        let mut ledger =
            Ledger::genesis_zone("Earth-protocol-work", validator_keys, notary_keys, true).unwrap();
        let zone = ledger.descriptor.zone_id.clone();
        let buyer_address = buyer.address(&zone);
        let (buyer_coin, _) = ledger
            .bootstrap_service_reward(
                "continuity-demand-buyer".into(),
                buyer_address.clone(),
                ServiceRole::Observer,
                "continuity-demand-bootstrap".into(),
                Amount::from_rld_whole(100).unwrap(),
            )
            .unwrap();
        let user_budget = Amount::from_rld_whole(50).unwrap();
        let user_description = "user requests checkpoint recovery".to_owned();
        let user_order_payload = action_payload_hash(
            "CREATE_SERVICE_ORDER",
            &[
                buyer_address.as_bytes(),
                buyer_coin.object_id.as_bytes(),
                b"ARCHIVE",
                &user_budget.0.to_be_bytes(),
                user_description.as_bytes(),
            ],
        );
        let user_order = ledger
            .create_service_order(
                buyer_address,
                buyer_coin.object_id,
                ServiceRole::Archive,
                user_budget,
                user_description,
                signed_authorization(
                    &buyer,
                    &zone,
                    "CREATE_SERVICE_ORDER",
                    user_order_payload,
                    55,
                ),
            )
            .unwrap();
        let user_lease_payload = action_payload_hash(
            "LEASE_SERVICE",
            &[
                user_order.order_id.as_bytes(),
                archive_node.public_key.as_bytes(),
                &user_budget.0.to_be_bytes(),
            ],
        );
        let user_lease = ledger
            .lease_service(
                &user_order.order_id,
                archive_node.public_key.clone(),
                user_budget,
                signed_authorization(
                    &archive_node,
                    &zone,
                    "LEASE_SERVICE",
                    user_lease_payload,
                    56,
                ),
            )
            .unwrap();
        let proof_hash = "archive-recovery-challenge-proof".to_owned();
        let user_complete_payload = action_payload_hash(
            "COMPLETE_SERVICE",
            &[
                user_lease.lease_id.as_bytes(),
                archive_node.public_key.as_bytes(),
                proof_hash.as_bytes(),
            ],
        );
        let user_receipt = ledger
            .complete_service(
                &user_lease.lease_id,
                proof_hash.clone(),
                signed_authorization(
                    &archive_node,
                    &zone,
                    "COMPLETE_SERVICE",
                    user_complete_payload,
                    57,
                ),
            )
            .unwrap();
        let initial_reserve = ledger.reserve;
        let initial_continuity = ledger.reserve_pools.continuity_services;
        let budget = Amount::from_rld_whole(50).unwrap();
        let mut request = simulated_protocol_order_request(
            &ledger,
            "protocol-continuity-order-1",
            ProtocolReservePoolKind::ContinuityServices,
            ServiceRole::Archive,
            budget,
            "restore a continuity checkpoint",
            Some(user_receipt.receipt_id),
        );
        assert!(matches!(
            ledger.create_protocol_service_order(request.clone()),
            Err(LedgerError::InvalidQuorum(_))
        ));
        let order_subject = request.subject_hash.clone();
        request.validator_qc = signed_qc(&order_subject, &validators, 3);
        request.notary_qc = signed_qc(&order_subject, &notaries, 3);
        let order = ledger.create_protocol_service_order(request).unwrap();
        assert_eq!(
            ledger
                .available_protocol_reserve(&ProtocolReservePoolKind::ContinuityServices)
                .unwrap(),
            initial_continuity.checked_sub(budget).unwrap()
        );

        let quote = Amount::from_rld_whole(40).unwrap();
        let lease_payload = action_payload_hash(
            "LEASE_SERVICE",
            &[
                order.order_id.as_bytes(),
                archive_node.public_key.as_bytes(),
                &quote.0.to_be_bytes(),
            ],
        );
        let lease = ledger
            .lease_service(
                &order.order_id,
                archive_node.public_key.clone(),
                quote,
                signed_authorization(&archive_node, &zone, "LEASE_SERVICE", lease_payload, 60),
            )
            .unwrap();
        let complete_payload = action_payload_hash(
            "COMPLETE_SERVICE",
            &[
                lease.lease_id.as_bytes(),
                archive_node.public_key.as_bytes(),
                proof_hash.as_bytes(),
            ],
        );
        let node_authorization = signed_authorization(
            &archive_node,
            &zone,
            "COMPLETE_SERVICE",
            complete_payload,
            61,
        );
        assert!(matches!(
            ledger.complete_service(
                &lease.lease_id,
                proof_hash.clone(),
                node_authorization.clone()
            ),
            Err(LedgerError::Invalid(_))
        ));
        let claim = ProtocolServiceCompletionClaim {
            zone_id: zone,
            order_id: order.order_id.clone(),
            lease_id: lease.lease_id.clone(),
            node_id: archive_node.public_key.clone(),
            role: ServiceRole::Archive,
            amount: quote,
            proof_hash: proof_hash.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
        };
        let completion_subject = claim.subject_hash();
        let receipt = ledger
            .complete_protocol_service(
                &lease.lease_id,
                proof_hash,
                node_authorization,
                signed_qc(&completion_subject, &validators, 3),
                signed_qc(&completion_subject, &notaries, 3),
            )
            .unwrap();
        assert_eq!(
            receipt.protocol_reserve_pool,
            Some(ProtocolReservePoolKind::ContinuityServices)
        );
        assert_eq!(
            ledger.reserve_pools.continuity_services,
            initial_continuity.checked_sub(quote).unwrap()
        );
        assert_eq!(ledger.reserve, initial_reserve.checked_sub(quote).unwrap());
        assert_eq!(
            ledger.balance(&archive_node.public_key).unwrap(),
            user_budget.checked_add(quote).unwrap()
        );
        assert_eq!(
            ledger.protocol_reserve_commitments[&order.order_id].settled_amount,
            Some(quote)
        );
        ledger.assert_conservation().unwrap();
    }

