    #[test]
    fn four_validator_commit_requires_three_votes_and_replicates_payment() {
        let validators = (0..4).map(|_| generate_identity()).collect::<Vec<_>>();
        let validator_keys = validators
            .iter()
            .map(|validator| validator.public_key.clone())
            .collect::<Vec<_>>();
        let alice = generate_identity();
        let bob = generate_identity();
        let mut ledger =
            Ledger::genesis_zone("Earth-4V", validator_keys, Vec::new(), true).unwrap();
        let zone = ledger.descriptor.zone_id.clone();
        let (coin, _) = ledger
            .bootstrap_service_reward(
                "alice-observer".into(),
                alice.address(&zone),
                ServiceRole::Observer,
                "four-validator-bootstrap-proof".into(),
                Amount::from_rld_whole(100).unwrap(),
            )
            .unwrap();
        let intent = signed_intent(
            &alice,
            &zone,
            &zone,
            &bob.address(&zone),
            &coin.object_id,
            Amount::from_rld_whole(25).unwrap(),
        );
        let leader = consensus_leader(&ledger, &validators);
        let proposal = consensus_proposal(&ledger, leader, ConsensusCommand::LocalPayment(intent));
        let mut foreign_context = proposal.clone();
        foreign_context.currency_genesis_root = "foreign-currency-root".into();
        foreign_context.signature =
            sign_bytes(&leader.secret_key, &foreign_context.signing_bytes()).unwrap();
        assert!(matches!(
            ledger.validate_consensus_proposal(&foreign_context),
            Err(LedgerError::InvalidQuorum(message))
                if message.contains("not authorized")
        ));
        let state_root_before_vote = ledger.state_root().unwrap();
        ledger.lock_consensus_vote(&proposal).unwrap();
        assert_eq!(ledger.state_root().unwrap(), state_root_before_vote);

        let insufficient = ConsensusCommit {
            proposal: proposal.clone(),
            votes: validators[..2]
                .iter()
                .map(|validator| consensus_vote(&proposal, validator))
                .collect(),
        };
        assert!(ledger.apply_consensus_commit(insufficient).is_err());

        let commit = ConsensusCommit {
            proposal: proposal.clone(),
            votes: validators[..3]
                .iter()
                .map(|validator| consensus_vote(&proposal, validator))
                .collect(),
        };
        let outcome = ledger.apply_consensus_commit(commit.clone()).unwrap();
        let ConsensusOutcome::LocalPayment(record) = &outcome else {
            panic!("local payment proposal returned the wrong consensus outcome");
        };
        assert_eq!(record.status, PaymentStatus::UniversallySettled);
        assert_eq!(
            ledger.balance(&bob.address(&zone)).unwrap(),
            Amount::from_rld_whole(25).unwrap()
        );
        assert!(ledger.consensus_commits.contains_key(&commit.commit_hash()));
        assert_eq!(
            ledger.apply_consensus_commit(commit).unwrap(),
            outcome,
            "commit replay must be idempotent"
        );
        ledger.assert_conservation().unwrap();
    }

    #[test]
    fn external_consensus_execution_capability_preserves_unrooted_metadata() {
        let validator = generate_identity();
        let validators = vec![validator];
        let mut prestate = Ledger::genesis_zone(
            "external-consensus-metadata",
            vec![validators[0].public_key.clone()],
            Vec::new(),
            true,
        )
        .unwrap();
        prestate.create_checkpoint().unwrap();
        let command = ConsensusCommand::NetworkHeartbeat(NetworkHeartbeatV1 {
            heartbeat_id: "external-consensus-metadata-heartbeat".into(),
            zone_id: prestate.descriptor.zone_id.clone(),
            currency_genesis_root: prestate.descriptor.currency_genesis_root.clone(),
            protocol_era: prestate.descriptor.protocol_era,
            crypto_era: prestate.descriptor.crypto_era,
            parent_height: prestate.height,
            note_hash: hash_bytes(b"external consensus metadata capability"),
        });
        let commit = certified_command(&prestate, &validators, command);
        prestate.lock_consensus_vote(&commit.proposal).unwrap();

        let mut canonical = prestate.clone();
        canonical.apply_consensus_commit(commit.clone()).unwrap();

        let authenticated = prestate
            .authenticate_consensus_commit_for_external_execution(&commit)
            .unwrap();
        let mut externally_executed = prestate.clone();
        externally_executed
            .execute_consensus_command(commit.proposal.command.clone())
            .unwrap();
        externally_executed
            .finalize_externally_executed_consensus_commit(authenticated)
            .unwrap();
        assert_eq!(
            serde_json::to_vec(&externally_executed).unwrap(),
            serde_json::to_vec(&canonical).unwrap()
        );

        let authenticated = prestate
            .authenticate_consensus_commit_for_external_execution(&commit)
            .unwrap();
        let mut tampered = prestate;
        tampered
            .execute_consensus_command(commit.proposal.command.clone())
            .unwrap();
        tampered.checkpoints.clear();
        let tampered_before = serde_json::to_vec(&tampered).unwrap();
        assert!(matches!(
            tampered.finalize_externally_executed_consensus_commit(authenticated),
            Err(LedgerError::InvalidQuorum(message))
                if message.contains("protected unrooted Ledger bookkeeping")
        ));
        assert_eq!(serde_json::to_vec(&tampered).unwrap(), tampered_before);
    }

    #[test]
    fn stake_authority_commands_are_dual_authorized_rooted_replayable_and_runtime_disabled() {
        let (mut ledger, validators, _notaries, _candidate_identities, request) =
            stake_authority_governance_fixture();
        let runtime_keys = ledger.descriptor.validator_keys.clone();

        let mut bad_subject = request.clone();
        bad_subject.subject_hash = hash_parts(&[b"RLD-BAD-STAKE-AUTHORITY-SUBJECT"]);
        let baseline = ledger.state_root().unwrap();
        assert!(matches!(
            ledger.execute_consensus_command(ConsensusCommand::SubmitStakeAuthorityUpdate(
                Box::new(bad_subject)
            )),
            Err(LedgerError::Invalid(message)) if message.contains("subject commitment")
        ));
        assert_eq!(ledger.state_root().unwrap(), baseline);

        let mut overlapping = ledger.clone();
        overlapping.descriptor.notary_keys = overlapping.descriptor.validator_keys.clone();
        let overlap_root = overlapping.state_root().unwrap();
        assert!(matches!(
            overlapping.execute_consensus_command(
                ConsensusCommand::SubmitStakeAuthorityUpdate(Box::new(request.clone()))
            ),
            Err(LedgerError::InvalidQuorum(message)) if message.contains("overlap")
        ));
        assert_eq!(overlapping.state_root().unwrap(), overlap_root);

        let leader = consensus_leader(&ledger, &validators);
        let proposal = consensus_proposal(
            &ledger,
            leader,
            ConsensusCommand::SubmitStakeAuthorityUpdate(Box::new(request)),
        );
        let commit = ConsensusCommit {
            proposal: proposal.clone(),
            votes: validators[..3]
                .iter()
                .map(|validator| consensus_vote(&proposal, validator))
                .collect(),
        };

        let mut mismatched = ledger.clone();
        let mut wrong_proposal = proposal.clone();
        wrong_proposal.expected_state_root = hash_parts(&[b"RLD-WRONG-CERTIFIED-POST-ROOT"]);
        wrong_proposal.signature =
            sign_bytes(&leader.secret_key, &wrong_proposal.signing_bytes()).unwrap();
        let wrong_commit = ConsensusCommit {
            votes: validators[..3]
                .iter()
                .map(|validator| consensus_vote(&wrong_proposal, validator))
                .collect(),
            proposal: wrong_proposal,
        };
        let mismatch_root = mismatched.state_root().unwrap();
        assert!(mismatched.apply_consensus_commit(wrong_commit).is_err());
        assert_eq!(mismatched.state_root().unwrap(), mismatch_root);

        let authority_outcome = ledger.apply_consensus_commit(commit.clone()).unwrap();
        let ConsensusOutcome::StakeAuthority(authority) = &authority_outcome else {
            panic!("stake authority command returned the wrong outcome");
        };
        assert_eq!(authority.status, StakeAuthorityStateStatus::StagedOnly);
        assert_eq!(ledger.descriptor.validator_keys, runtime_keys);
        assert_eq!(ledger.consensus_stake_authority.as_ref(), Some(authority));

        let replay_root = ledger.state_root().unwrap();
        assert_eq!(
            ledger.apply_consensus_commit(commit.clone()).unwrap(),
            authority_outcome
        );
        assert_eq!(ledger.state_root().unwrap(), replay_root);

        let authority = ledger.consensus_stake_authority.clone().unwrap();
        let derive_request = DeriveNextStakeEpochRequestV1 {
            request_id: "derive-stake-epoch-1".into(),
            zone_id: ledger.descriptor.zone_id.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            proposed_height: ledger.height,
            expires_at_height: ledger.height + 10,
            expected_authority_sequence: authority.sequence,
            expected_authority_commitment: authority.commitment,
            expected_consensus_epoch: 1,
            expected_snapshot_height: ledger.height,
            expected_snapshot_state_root: ledger.state_root().unwrap(),
        };
        let leader = consensus_leader(&ledger, &validators);
        let derive_proposal = consensus_proposal(
            &ledger,
            leader,
            ConsensusCommand::DeriveNextStakeEpoch(Box::new(derive_request)),
        );
        let derive_commit = ConsensusCommit {
            proposal: derive_proposal.clone(),
            votes: validators[..3]
                .iter()
                .map(|validator| consensus_vote(&derive_proposal, validator))
                .collect(),
        };
        let derived_outcome = ledger
            .apply_consensus_commit(derive_commit.clone())
            .unwrap();
        let ConsensusOutcome::DerivedStakeEpoch(record) = &derived_outcome else {
            panic!("stake Epoch command returned the wrong outcome");
        };
        assert_eq!(record.status, crate::StakeEpochRecordStatus::DerivedOnly);
        assert_eq!(record.descriptor.consensus_epoch, 1);
        assert_eq!(ledger.descriptor.validator_keys, runtime_keys);

        let final_root = ledger.state_root().unwrap();
        assert_eq!(
            ledger.apply_consensus_commit(commit).unwrap(),
            authority_outcome,
            "an older authority commit must replay its exact historical result"
        );
        assert_eq!(
            ledger.apply_consensus_commit(derive_commit).unwrap(),
            derived_outcome
        );
        assert_eq!(ledger.state_root().unwrap(), final_root);
    }

    #[test]
    fn owner_and_candidate_key_authorize_registration_and_one_way_exit() {
        let (mut ledger, validators, owner, candidate_identity, request) =
            consensus_validator_registration_fixture();
        let runtime_keys = ledger.descriptor.validator_keys.clone();
        let prior_authority = ledger.consensus_stake_authority.clone().unwrap();
        let registration_authorization = request.authorization.authorization_id.clone();
        let leader = consensus_leader(&ledger, &validators);
        let proposal = consensus_proposal(
            &ledger,
            leader,
            ConsensusCommand::RegisterConsensusValidator(Box::new(request.clone())),
        );
        let commit = ConsensusCommit {
            proposal: proposal.clone(),
            votes: validators[..3]
                .iter()
                .map(|validator| consensus_vote(&proposal, validator))
                .collect(),
        };
        let registration_outcome = ledger.apply_consensus_commit(commit.clone()).unwrap();
        let ConsensusOutcome::StakeCandidate(registered) = &registration_outcome else {
            panic!("validator registration returned the wrong outcome");
        };
        assert_eq!(registered.validator_id, request.validator_id);
        assert_eq!(
            registered.registered_height,
            u128::from(proposal.expected_height)
        );
        assert_eq!(registered.exit_height, None);
        assert!(ledger
            .authorization_nullifiers
            .contains(&registration_authorization));
        let registered_authority = ledger.consensus_stake_authority.clone().unwrap();
        assert_eq!(registered_authority.sequence, prior_authority.sequence + 1);
        assert!(registered_authority.candidates.contains(registered));
        assert_eq!(ledger.descriptor.validator_keys, runtime_keys);

        let context =
            ledger.stake_context_at(u128::from(ledger.height), ledger.state_root().unwrap());
        let mut exited = registered.clone();
        exited.exit_height = Some(100);
        exited.proof_of_possession = sign_bytes(
            &candidate_identity.secret_key,
            &crate::validator_candidate_pop_message_v1(&context, &exited),
        )
        .unwrap();
        let authority = ledger.consensus_stake_authority.clone().unwrap();
        let mut exit_request = ExitConsensusValidatorRequestV1 {
            request_id: "stake-exit-request-0001".into(),
            zone_id: ledger.descriptor.zone_id.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            proposed_height: ledger.height,
            expires_at_height: ledger.height + 20,
            expected_authority_sequence: authority.sequence,
            expected_authority_commitment: authority.commitment,
            validator_id: exited.validator_id.clone(),
            owner: exited.owner.clone(),
            public_key: exited.public_key.clone(),
            key_era: exited.key_era,
            registered_height: u64::try_from(exited.registered_height).unwrap(),
            exit_height: u64::try_from(exited.exit_height.unwrap()).unwrap(),
            proof_of_possession: exited.proof_of_possession.clone(),
            authorization: signed_authorization(
                &owner,
                &ledger.descriptor.zone_id,
                EXIT_CONSENSUS_VALIDATOR_ACTION_V1,
                String::new(),
                801,
            ),
        };
        exit_request.authorization = signed_authorization(
            &owner,
            &ledger.descriptor.zone_id,
            EXIT_CONSENSUS_VALIDATOR_ACTION_V1,
            exit_request.payload_hash(),
            801,
        );
        let exit_authorization = exit_request.authorization.authorization_id.clone();
        let leader = consensus_leader(&ledger, &validators);
        let exit_proposal = consensus_proposal(
            &ledger,
            leader,
            ConsensusCommand::ExitConsensusValidator(Box::new(exit_request.clone())),
        );
        let exit_commit = ConsensusCommit {
            proposal: exit_proposal.clone(),
            votes: validators[..3]
                .iter()
                .map(|validator| consensus_vote(&exit_proposal, validator))
                .collect(),
        };
        let exit_outcome = ledger.apply_consensus_commit(exit_commit.clone()).unwrap();
        assert_eq!(
            exit_outcome,
            ConsensusOutcome::StakeCandidate(exited.clone())
        );
        assert!(ledger
            .authorization_nullifiers
            .contains(&exit_authorization));
        assert_eq!(ledger.descriptor.validator_keys, runtime_keys);
        assert!(ledger
            .consensus_stake_authority
            .as_ref()
            .unwrap()
            .candidates
            .contains(&exited));
        ledger.assert_conservation().unwrap();

        let replay_root = ledger.state_root().unwrap();
        assert_eq!(
            ledger.apply_consensus_commit(commit).unwrap(),
            registration_outcome
        );
        assert_eq!(
            ledger.apply_consensus_commit(exit_commit).unwrap(),
            exit_outcome
        );
        assert_eq!(ledger.state_root().unwrap(), replay_root);
    }

    #[test]
    fn candidate_forgery_and_broad_lifecycle_rewrite_fail_atomically() {
        let (mut forged_ledger, _validators, _owner, _candidate_identity, mut forged) =
            consensus_validator_registration_fixture();
        let forged_root = forged_ledger.state_root().unwrap();
        let forged_authorization = forged.authorization.authorization_id.clone();
        forged.proof_of_possession = "00".repeat(64);
        assert!(matches!(
            forged_ledger.register_consensus_validator(forged),
            Err(LedgerError::InvalidSignature(_))
        ));
        assert_eq!(forged_ledger.state_root().unwrap(), forged_root);
        assert!(!forged_ledger
            .authorization_nullifiers
            .contains(&forged_authorization));

        let (mut bad_pop_ledger, _validators, bad_pop_owner, _candidate_identity, mut bad_pop) =
            consensus_validator_registration_fixture();
        bad_pop.proof_of_possession = "00".repeat(64);
        bad_pop.authorization = signed_authorization(
            &bad_pop_owner,
            &bad_pop_ledger.descriptor.zone_id,
            REGISTER_CONSENSUS_VALIDATOR_ACTION_V1,
            bad_pop.payload_hash(),
            802,
        );
        let bad_pop_authorization = bad_pop.authorization.authorization_id.clone();
        let bad_pop_root = bad_pop_ledger.state_root().unwrap();
        assert!(bad_pop_ledger
            .register_consensus_validator(bad_pop)
            .is_err());
        assert_eq!(bad_pop_ledger.state_root().unwrap(), bad_pop_root);
        assert!(!bad_pop_ledger
            .authorization_nullifiers
            .contains(&bad_pop_authorization));

        let (mut broad, validators, notaries, _candidate_identities, mut update) =
            stake_authority_governance_fixture();
        broad.submit_stake_authority_update(update.clone()).unwrap();
        let authority = broad.consensus_stake_authority.clone().unwrap();
        let bootstrap_view = update.clone();
        let extra = generate_identity();
        update.update_id = "stake-authority-broad-candidate-rewrite".into();
        update.proposed_height = broad.height;
        update.expires_at_height = broad.height + 10;
        update.sequence = authority.sequence + 1;
        update.expected_previous_commitment = authority.commitment;
        update.ubo_sequence = authority.ubo_control.sequence + 1;
        update.ubo_predecessor_commitment =
            ubo_control_commitment_v1(&authority.ubo_control).unwrap();
        update
            .candidates
            .push(crate::StakeAuthorityCandidateCommandV1 {
                validator_id: "zz-broad-injected-validator".into(),
                owner: "zz-broad-injected-owner".into(),
                public_key: extra.public_key,
                key_era: broad.descriptor.crypto_era,
                registered_height: broad.height,
                exit_height: None,
                proof_of_possession: "11".repeat(64),
            });
        update.prospective_authority_commitment = "00".repeat(32);
        update.subject_hash = update.compute_subject_hash();
        update.validator_qc = signed_qc(&update.subject_hash, &validators, 3);
        update.notary_qc = signed_qc(&update.subject_hash, &notaries, 3);
        let broad_root = broad.state_root().unwrap();
        assert!(matches!(
            broad.submit_stake_authority_update(update),
            Err(LedgerError::Invalid(message))
                if message.contains("bootstrap-only")
        ));
        assert_eq!(broad.state_root().unwrap(), broad_root);

        for (name, mut forbidden) in [
            ("policy", {
                let mut request = bootstrap_view.clone();
                request.policy.activation_delay_blocks += 1;
                request
            }),
            ("positions", {
                let mut request = bootstrap_view.clone();
                request.positions.pop();
                request
            }),
            ("ubo", {
                let mut request = bootstrap_view.clone();
                request.ubo_evidence_root = "77".repeat(32);
                request
            }),
        ] {
            forbidden.update_id = format!("forbidden-broad-{name}");
            forbidden.proposed_height = broad.height;
            forbidden.expires_at_height = broad.height + 10;
            let root = broad.state_root().unwrap();
            assert!(matches!(
                broad.submit_stake_authority_update(forbidden),
                Err(LedgerError::Invalid(message)) if message.contains("bootstrap-only")
            ));
            assert_eq!(broad.state_root().unwrap(), root);
        }
    }

    #[test]
    fn owner_authorized_consensus_stake_lock_is_atomic_supply_preserving_and_replayable() {
        let (mut ledger, validators, _owner, request) = consensus_stake_lock_fixture();
        let source_root = ledger.state_root().unwrap();
        let source_supply = ledger.supply_certificate().unwrap().conservation_position;
        let runtime_keys = ledger.descriptor.validator_keys.clone();
        let prior_authority = ledger.consensus_stake_authority.clone().unwrap();
        let authorization_id = request.authorization.authorization_id.clone();
        let leader = consensus_leader(&ledger, &validators);
        let proposal = consensus_proposal(
            &ledger,
            leader,
            ConsensusCommand::LockConsensusStake(Box::new(request.clone())),
        );
        let commit = ConsensusCommit {
            proposal: proposal.clone(),
            votes: validators[..3]
                .iter()
                .map(|validator| consensus_vote(&proposal, validator))
                .collect(),
        };

        let outcome = ledger.apply_consensus_commit(commit.clone()).unwrap();
        let ConsensusOutcome::ConsensusStake(position) = &outcome else {
            panic!("stake lock command returned the wrong outcome");
        };
        assert_eq!(position.position_id, request.position_id);
        assert_eq!(position.source_coin_id, request.source_coin_id);
        assert_eq!(position.amount, request.amount);
        assert_eq!(
            ledger.coins[&position.source_coin_id].state,
            CoinState::Consumed
        );
        assert_eq!(
            ledger.coins[&position.escrow_coin_id].state,
            CoinState::Reserved
        );
        assert_eq!(
            ledger.consensus_stake_escrows.get(&position.escrow_coin_id),
            Some(position)
        );
        assert_eq!(
            ledger.balance(&request.owner).unwrap(),
            Amount::from_runlai(40)
        );
        let authority = ledger.consensus_stake_authority.clone().unwrap();
        assert_eq!(authority.sequence, prior_authority.sequence + 1);
        assert_eq!(authority.previous_commitment, prior_authority.commitment);
        assert_eq!(authority.source_state_root, source_root);
        assert_eq!(authority.positions, vec![position.clone()]);
        assert_eq!(
            authority.ubo_control.sequence,
            prior_authority.ubo_control.sequence + 1
        );
        assert_eq!(ledger.descriptor.validator_keys, runtime_keys);
        assert!(ledger.authorization_nullifiers.contains(&authorization_id));
        let mut attempted_spend = ledger.clone();
        let attempted_spend_root = attempted_spend.state_root().unwrap();
        assert!(matches!(
            attempted_spend.consume_coin(&position.escrow_coin_id),
            Err(LedgerError::CoinNotSpendable)
        ));
        assert_eq!(attempted_spend.state_root().unwrap(), attempted_spend_root);
        assert_eq!(
            ledger.supply_certificate().unwrap().conservation_position,
            source_supply
        );
        ledger.assert_conservation().unwrap();

        let replay_root = ledger.state_root().unwrap();
        assert_eq!(ledger.apply_consensus_commit(commit).unwrap(), outcome);
        assert_eq!(ledger.state_root().unwrap(), replay_root);
        let audit = ledger.audit_proof_bundle().unwrap();
        assert_eq!(audit.consensus_stake_escrows, vec![position.clone()]);
        assert_eq!(audit.consensus_stake_authority, Some(authority.clone()));
    }

    #[test]
    fn v2_stake_lock_requires_independent_owner_signed_slash_terms_and_replays_exactly() {
        let (mut ledger, validators, owner, legacy_request) = consensus_stake_lock_fixture();
        let request = v2_lock_request_from_v1(&ledger, &owner, legacy_request, 710);
        let slash_authorization_id = request.slash_terms_authorization.authorization_id.clone();
        let mutation_authorization_id = request.authorization.authorization_id.clone();
        let leader = consensus_leader(&ledger, &validators);
        let proposal = consensus_proposal(
            &ledger,
            leader,
            ConsensusCommand::LockConsensusStakeV2(Box::new(request.clone())),
        );
        let commit = ConsensusCommit {
            proposal: proposal.clone(),
            votes: validators[..3]
                .iter()
                .map(|validator| consensus_vote(&proposal, validator))
                .collect(),
        };

        let outcome = ledger.apply_consensus_commit(commit.clone()).unwrap();
        let ConsensusOutcome::ConsensusStake(position) = &outcome else {
            panic!("v2 stake lock returned the wrong outcome");
        };
        let terms = position.slash_terms.as_ref().unwrap();
        assert_eq!(
            terms.slash_policy,
            ConsensusStakeSlashPolicyV2::protocol_v2()
        );
        assert_eq!(terms.owner_authorization, request.slash_terms_authorization);
        assert!(ledger
            .authorization_nullifiers
            .contains(&slash_authorization_id));
        assert!(ledger
            .authorization_nullifiers
            .contains(&mutation_authorization_id));
        assert_eq!(
            ledger.consensus_stake_authority.as_ref().unwrap().positions,
            vec![position.clone()]
        );
        ledger.assert_conservation().unwrap();
        let replay_root = ledger.state_root().unwrap();
        assert_eq!(ledger.apply_consensus_commit(commit).unwrap(), outcome);
        assert_eq!(ledger.state_root().unwrap(), replay_root);

        let (mut forged, _validators, owner, legacy_request) = consensus_stake_lock_fixture();
        let mut forged_request = v2_lock_request_from_v1(&forged, &owner, legacy_request, 720);
        forged_request.slash_terms_authorization.payload_hash = "99".repeat(32);
        forged_request.authorization = signed_authorization(
            &owner,
            &forged.descriptor.zone_id,
            LOCK_CONSENSUS_STAKE_ACTION_V2,
            forged_request.payload_hash(),
            721,
        );
        let forged_slash_id = forged_request
            .slash_terms_authorization
            .authorization_id
            .clone();
        let forged_mutation_id = forged_request.authorization.authorization_id.clone();
        let forged_root = forged.state_root().unwrap();
        assert!(matches!(
            forged.lock_consensus_stake_v2(forged_request),
            Err(LedgerError::InvalidSignature(_))
        ));
        assert_eq!(forged.state_root().unwrap(), forged_root);
        assert!(!forged.authorization_nullifiers.contains(&forged_slash_id));
        assert!(!forged
            .authorization_nullifiers
            .contains(&forged_mutation_id));

        let (mut policy_v2, _validators, owner, mut legacy_request) =
            consensus_stake_lock_fixture();
        let mut authority = policy_v2.consensus_stake_authority.clone().unwrap();
        authority.policy.policy_version = 2;
        authority.commitment =
            crate::ledger_stake_authority_state_commitment_v1(&authority).unwrap();
        legacy_request.expected_authority_commitment = authority.commitment.clone();
        policy_v2.consensus_stake_authority = Some(authority);
        legacy_request.authorization = signed_authorization(
            &owner,
            &policy_v2.descriptor.zone_id,
            LOCK_CONSENSUS_STAKE_ACTION_V1,
            legacy_request.payload_hash(),
            730,
        );
        let legacy_root = policy_v2.state_root().unwrap();
        assert!(matches!(
            policy_v2.lock_consensus_stake(legacy_request),
            Err(LedgerError::Invalid(message)) if message.contains("unslashable")
        ));
        assert_eq!(policy_v2.state_root().unwrap(), legacy_root);
    }

    #[test]
    fn legacy_stake_migration_adds_exact_terms_without_moving_coin_and_replays() {
        let (mut ledger, validators, owner, lock_request) = consensus_stake_lock_fixture();
        let position = ledger.lock_consensus_stake(lock_request).unwrap();
        let source_coin = ledger.coins[&position.source_coin_id].clone();
        let escrow_coin = ledger.coins[&position.escrow_coin_id].clone();
        let supply = ledger.supply_certificate().unwrap().conservation_position;
        let prior_authority = ledger.consensus_stake_authority.clone().unwrap();
        let request = slash_terms_migration_request(&ledger, &owner, &position, 740);

        let mut substituted = request.clone();
        substituted.escrow_coin_id = "substituted-escrow".into();
        let substitution_root = ledger.state_root().unwrap();
        assert!(matches!(
            ledger.migrate_consensus_stake_slash_terms(substituted),
            Err(LedgerError::Invalid(_))
        ));
        assert_eq!(ledger.state_root().unwrap(), substitution_root);

        let leader = consensus_leader(&ledger, &validators);
        let proposal = consensus_proposal(
            &ledger,
            leader,
            ConsensusCommand::MigrateConsensusStakeSlashTerms(Box::new(request.clone())),
        );
        let commit = ConsensusCommit {
            proposal: proposal.clone(),
            votes: validators[..3]
                .iter()
                .map(|validator| consensus_vote(&proposal, validator))
                .collect(),
        };
        let outcome = ledger.apply_consensus_commit(commit.clone()).unwrap();
        let ConsensusOutcome::ConsensusStake(migrated) = &outcome else {
            panic!("stake slash-terms migration returned the wrong outcome");
        };
        assert_eq!(migrated.position_id, position.position_id);
        assert_eq!(migrated.source_coin_id, position.source_coin_id);
        assert_eq!(migrated.escrow_coin_id, position.escrow_coin_id);
        assert_eq!(migrated.amount, position.amount);
        assert_eq!(ledger.coins[&migrated.source_coin_id], source_coin);
        assert_eq!(ledger.coins[&migrated.escrow_coin_id], escrow_coin);
        assert_eq!(
            migrated.slash_terms.as_ref().unwrap().owner_authorization,
            request.slash_terms_authorization
        );
        let authority = ledger.consensus_stake_authority.as_ref().unwrap();
        assert_eq!(authority.sequence, prior_authority.sequence + 1);
        assert_eq!(
            authority.ubo_control.sequence,
            prior_authority.ubo_control.sequence + 1
        );
        assert_eq!(
            ledger.supply_certificate().unwrap().conservation_position,
            supply
        );
        ledger.assert_conservation().unwrap();
        let replay_root = ledger.state_root().unwrap();
        assert_eq!(ledger.apply_consensus_commit(commit).unwrap(), outcome);
        assert_eq!(ledger.state_root().unwrap(), replay_root);

        let (mut duplicate_auth, _validators, owner, lock_request) = consensus_stake_lock_fixture();
        let position = duplicate_auth.lock_consensus_stake(lock_request).unwrap();
        let mut duplicate_request =
            slash_terms_migration_request(&duplicate_auth, &owner, &position, 750);
        duplicate_request.authorization = duplicate_request.slash_terms_authorization.clone();
        let duplicate_root = duplicate_auth.state_root().unwrap();
        assert!(matches!(
            duplicate_auth.migrate_consensus_stake_slash_terms(duplicate_request),
            Err(LedgerError::Duplicate(_))
        ));
        assert_eq!(duplicate_auth.state_root().unwrap(), duplicate_root);
    }

    #[test]
    fn objective_double_sign_slash_is_exact_supply_preserving_and_replay_safe() {
        let (mut ledger, validators, _owners, candidate_identities, epoch) =
            consensus_stake_slash_fixture();
        let position = epoch.stake_liabilities[0].position.clone();
        let source_escrow = ledger.coins[&position.escrow_coin_id].clone();
        let prior_authority = ledger.consensus_stake_authority.clone().unwrap();
        let supply = ledger.supply_certificate().unwrap().conservation_position;
        let request =
            consensus_stake_slash_request(&ledger, &epoch, 0, &candidate_identities[0], None);
        let evidence_hash = request.evidence_hash.clone();
        let leader = consensus_leader(&ledger, &validators);
        let proposal = consensus_proposal(
            &ledger,
            leader,
            ConsensusCommand::SlashConsensusStake(Box::new(request)),
        );
        let commit = ConsensusCommit {
            proposal: proposal.clone(),
            votes: validators[..3]
                .iter()
                .map(|validator| consensus_vote(&proposal, validator))
                .collect(),
        };

        let outcome = ledger.apply_consensus_commit(commit.clone()).unwrap();
        let ConsensusOutcome::ConsensusStakeSlash(record) = &outcome else {
            panic!("stake slash returned the wrong outcome");
        };
        assert_eq!(record.position, position);
        assert_eq!(record.source_escrow_coin_id, source_escrow.object_id);
        assert_eq!(record.slash_bps, 10_000);
        assert_eq!(record.slashed_amount, position.amount);
        assert_eq!(record.evidence_hash, evidence_hash);
        assert_eq!(record.record_hash, record.compute_record_hash());
        let evidence_nullifier =
            consensus_stake_slash_nullifier_v1(&record.evidence_hash, &record.liability_commitment);
        assert!(ledger
            .consensus_stake_evidence_nullifiers
            .contains(&evidence_nullifier));
        assert!(!ledger
            .consensus_stake_escrows
            .contains_key(&position.escrow_coin_id));
        assert_eq!(
            ledger.coins[&position.escrow_coin_id].state,
            CoinState::Consumed
        );
        let safety_coin = &ledger.coins[&record.safety_pool_coin_id];
        assert_eq!(safety_coin.owner, CONSENSUS_SLASH_SAFETY_POOL_V2);
        assert_eq!(safety_coin.state, CoinState::Reserved);
        assert_eq!(safety_coin.amount, position.amount);
        assert_eq!(
            safety_coin.parent_ids,
            vec![position.escrow_coin_id.clone()]
        );
        let authority = ledger.consensus_stake_authority.as_ref().unwrap();
        assert_eq!(authority.sequence, prior_authority.sequence + 1);
        assert_eq!(
            authority.ubo_control.sequence,
            prior_authority.ubo_control.sequence + 1
        );
        assert!(authority
            .positions
            .iter()
            .all(|candidate| candidate.position_id != position.position_id));
        assert_eq!(
            ledger.supply_certificate().unwrap().conservation_position,
            supply
        );
        ledger.assert_conservation().unwrap();

        let replay_root = ledger.state_root().unwrap();
        assert_eq!(ledger.apply_consensus_commit(commit).unwrap(), outcome);
        assert_eq!(ledger.state_root().unwrap(), replay_root);
    }

    #[test]
    fn one_objective_fault_slashes_each_independent_validator_liability_once() {
        let (mut ledger, _validators, _owners, candidate_identities, epoch) =
            consensus_stake_slash_fixture_with_shared_validator(true);
        let delegated_index = epoch
            .stake_liabilities
            .iter()
            .position(|liability| liability.position.position_id == "stake-position-0004")
            .unwrap();
        assert_eq!(
            epoch.stake_liabilities[0].validator_public_key,
            epoch.stake_liabilities[delegated_index].validator_public_key
        );

        let first_request =
            consensus_stake_slash_request(&ledger, &epoch, 0, &candidate_identities[0], None);
        let evidence_hash = first_request.evidence_hash.clone();
        let first_evidence = first_request.evidence.clone();
        let first = ledger.slash_consensus_stake(first_request).unwrap();
        assert_eq!(first.evidence, first_evidence);

        let second_request = consensus_stake_slash_request(
            &ledger,
            &epoch,
            delegated_index,
            &candidate_identities[0],
            None,
        );
        assert_eq!(second_request.evidence_hash, evidence_hash);
        let second = ledger.slash_consensus_stake(second_request).unwrap();
        assert_eq!(second.evidence_hash, evidence_hash);

        let first_nullifier =
            consensus_stake_slash_nullifier_v1(&first.evidence_hash, &first.liability_commitment);
        let second_nullifier =
            consensus_stake_slash_nullifier_v1(&second.evidence_hash, &second.liability_commitment);
        assert_ne!(first_nullifier, second_nullifier);
        assert_eq!(ledger.consensus_stake_evidence_nullifiers.len(), 2);
        assert!(ledger
            .consensus_stake_evidence_nullifiers
            .contains(&first_nullifier));
        assert!(ledger
            .consensus_stake_evidence_nullifiers
            .contains(&second_nullifier));
        assert!(!ledger
            .consensus_stake_escrows
            .contains_key(&epoch.stake_liabilities[0].position.escrow_coin_id));
        assert!(!ledger.consensus_stake_escrows.contains_key(
            &epoch.stake_liabilities[delegated_index]
                .position
                .escrow_coin_id
        ));
        ledger.assert_conservation().unwrap();

        let restored: Ledger =
            serde_json::from_slice(&serde_json::to_vec(&ledger).unwrap()).unwrap();
        restored.assert_conservation().unwrap();
        assert_eq!(
            restored.consensus_stake_slashes[&first.slash_id].evidence,
            first_evidence
        );
        let restored_audit = restored.audit_proof_bundle().unwrap();
        restored_audit.verify_structure().unwrap();
        assert_eq!(
            restored_audit
                .consensus_stake_slashes
                .iter()
                .find(|record| record.slash_id == first.slash_id)
                .unwrap()
                .evidence,
            first_evidence
        );

        let mut forged_archive = ledger.clone();
        forged_archive
            .consensus_stake_slashes
            .get_mut(&first.slash_id)
            .unwrap()
            .evidence
            .first_vote
            .as_mut()
            .unwrap()
            .signature = "00".repeat(64);
        assert!(matches!(
            forged_archive.assert_conservation(),
            Err(LedgerError::Invalid(message)) if message.contains("slash identity, evidence")
        ));

        let mut tampered_ledger = ledger.clone();
        let tampered_record = tampered_ledger
            .consensus_stake_slashes
            .get_mut(&first.slash_id)
            .unwrap();
        tampered_record.derived_epoch_record_hash = hash_parts(&[b"RLD-TAMPERED-SLASH-EPOCH"]);
        tampered_record.record_hash = tampered_record.compute_record_hash();
        assert!(matches!(
            tampered_ledger.assert_conservation(),
            Err(LedgerError::Invalid(message)) if message.contains("slash identity, evidence, liability")
        ));

        let mut tampered_audit = ledger.audit_proof_bundle().unwrap();
        let tampered_record = tampered_audit
            .consensus_stake_slashes
            .iter_mut()
            .find(|record| record.slash_id == first.slash_id)
            .unwrap();
        tampered_record.liability_commitment = hash_parts(&[b"RLD-TAMPERED-SLASH-LIABILITY"]);
        tampered_record.record_hash = tampered_record.compute_record_hash();
        assert!(matches!(
            tampered_audit.verify_structure(),
            Err(message) if message.contains("slash identity, evidence, liability")
        ));

        let replay_root = ledger.state_root().unwrap();
        let mut replay_request =
            consensus_stake_slash_request(&ledger, &epoch, 0, &candidate_identities[0], None);
        replay_request.slash_id = "consensus-stake-slash-replay-0000".into();
        let replay_error = ledger.slash_consensus_stake(replay_request).unwrap_err();
        assert!(
            matches!(&replay_error, LedgerError::Duplicate(_)),
            "unexpected replay error: {replay_error}"
        );
        assert_eq!(ledger.state_root().unwrap(), replay_root);
    }

    #[test]
    fn stake_slash_handles_pending_unbond_and_rejects_forged_evidence_atomically() {
        let (mut ledger, _validators, owners, candidate_identities, epoch) =
            consensus_stake_slash_fixture();
        let position_index = 1;
        let position = epoch.stake_liabilities[position_index].position.clone();
        let owner_address = owners[position_index].address(&ledger.descriptor.zone_id);
        let authority = ledger.consensus_stake_authority.clone().unwrap();
        let withdraw_after_height = u64::try_from(
            epoch.stake_liabilities[position_index]
                .evidence_deadline_height
                .max(position.committed_through_height)
                .max(u128::from(ledger.height + 1) + authority.policy.activation_delay_blocks),
        )
        .unwrap();
        let mut unbond = RequestConsensusStakeUnbondV1 {
            request_id: "slash-pending-unbond-0001".into(),
            zone_id: ledger.descriptor.zone_id.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            proposed_height: ledger.height,
            expires_at_height: ledger.height + 20,
            expected_authority_sequence: authority.sequence,
            expected_authority_commitment: authority.commitment,
            position_id: position.position_id.clone(),
            escrow_coin_id: position.escrow_coin_id.clone(),
            owner: owner_address.clone(),
            beneficiary: owner_address,
            requested_withdraw_after_height: withdraw_after_height,
            authorization: signed_authorization(
                &owners[position_index],
                &ledger.descriptor.zone_id,
                REQUEST_CONSENSUS_STAKE_UNBOND_ACTION_V1,
                String::new(),
                2_000,
            ),
        };
        unbond.authorization = signed_authorization(
            &owners[position_index],
            &ledger.descriptor.zone_id,
            REQUEST_CONSENSUS_STAKE_UNBOND_ACTION_V1,
            unbond.payload_hash(),
            2_000,
        );
        let pending = ledger.request_consensus_stake_unbond(unbond).unwrap();
        assert_eq!(pending.status, ConsensusStakeUnbondStatusV1::Pending);

        let mut wrong_precondition = consensus_stake_slash_request(
            &ledger,
            &epoch,
            position_index,
            &candidate_identities[position_index],
            Some("00".repeat(32)),
        );
        wrong_precondition.slash_id = "slash-wrong-unbond-precondition".into();
        let root = ledger.state_root().unwrap();
        let wrong_error = ledger
            .slash_consensus_stake(wrong_precondition)
            .unwrap_err();
        assert!(
            matches!(&wrong_error, LedgerError::Invalid(message) if message.contains("pending-unbond precondition")),
            "unexpected slash precondition error: {wrong_error}"
        );
        assert_eq!(ledger.state_root().unwrap(), root);

        let mut forged = consensus_stake_slash_request(
            &ledger,
            &epoch,
            position_index,
            &candidate_identities[position_index],
            Some(pending.request_commitment.clone()),
        );
        forged.slash_id = "slash-forged-evidence".into();
        forged.evidence.first_vote.as_mut().unwrap().signature = "00".repeat(64);
        forged.evidence_hash = forged
            .evidence
            .evidence_hash(&epoch.descriptor.network_domain)
            .unwrap();
        let forged_nullifier =
            consensus_stake_slash_nullifier_v1(&forged.evidence_hash, &forged.liability_commitment);
        let root = ledger.state_root().unwrap();
        assert!(matches!(
            ledger.slash_consensus_stake(forged),
            Err(LedgerError::Invalid(message)) if message.contains("evidence rejected")
        ));
        assert_eq!(ledger.state_root().unwrap(), root);
        assert!(!ledger
            .consensus_stake_evidence_nullifiers
            .contains(&forged_nullifier));

        let valid = consensus_stake_slash_request(
            &ledger,
            &epoch,
            position_index,
            &candidate_identities[position_index],
            Some(pending.request_commitment.clone()),
        );
        let record = ledger.slash_consensus_stake(valid.clone()).unwrap();
        let tombstone = &ledger.consensus_stake_unbonds[&pending.request_id];
        assert_eq!(tombstone.status, ConsensusStakeUnbondStatusV1::FullySlashed);
        assert_eq!(
            tombstone.slash_id.as_deref(),
            Some(record.slash_id.as_str())
        );
        assert_eq!(tombstone.slashed_amount, position.amount);
        assert_eq!(tombstone.completed_height, Some(record.applied_height));
        assert!(tombstone.payout_coin_id.is_none());
        assert_eq!(
            record.unbond_request_commitment.as_deref(),
            Some(pending.request_commitment.as_str())
        );
        let evidence_nullifier =
            consensus_stake_slash_nullifier_v1(&record.evidence_hash, &record.liability_commitment);
        assert!(ledger
            .consensus_stake_evidence_nullifiers
            .contains(&evidence_nullifier));
        assert_eq!(
            ledger.coins[&position.escrow_coin_id].state,
            CoinState::Consumed
        );
        ledger.assert_conservation().unwrap();

        let replay_root = ledger.state_root().unwrap();
        assert!(matches!(
            ledger.slash_consensus_stake(valid),
            Err(LedgerError::Invalid(message)) if message.contains("height does not match")
        ));
        assert_eq!(ledger.state_root().unwrap(), replay_root);
    }

    #[test]
    fn all_objective_stake_evidence_types_bind_historical_key_context_and_window() {
        let (_ledger, _validators, _owners, candidate_identities, epoch) =
            consensus_stake_slash_fixture();
        let liability = &epoch.stake_liabilities[0];
        let position_id = liability.position.position_id.as_str();
        let liability_commitment = liability.liability_commitment.as_str();

        let double_sign = double_sign_evidence(&epoch, &candidate_identities[0]);
        let verified = crate::verify_consensus_stake_slash_evidence_v1(
            &epoch,
            position_id,
            liability_commitment,
            &double_sign,
        )
        .unwrap();
        assert_eq!(
            verified.kind,
            crate::ConsensusStakeSlashEvidenceKindV1::DoubleSign
        );
        assert_eq!(verified.slash_bps, 10_000);

        let mut noncanonical = double_sign.clone();
        std::mem::swap(&mut noncanonical.first_vote, &mut noncanonical.second_vote);
        assert!(matches!(
            crate::verify_consensus_stake_slash_evidence_v1(
                &epoch,
                position_id,
                liability_commitment,
                &noncanonical,
            ),
            Err(crate::ConsensusStakeEvidenceError::NonCanonicalPair)
        ));

        let mut malformed = double_sign.clone();
        malformed.proposal = Some(crate::SignedConsensusProposalStatementV1 {
            proposal_id: "inactive-field".into(),
            zone_id: epoch.descriptor.zone_id.clone(),
            currency_genesis_root: epoch.descriptor.currency_genesis_root.clone(),
            protocol_era: epoch.descriptor.protocol_era,
            crypto_era: epoch.descriptor.crypto_era,
            parent_height: 0,
            parent_state_root: String::new(),
            round: 0,
            proposer_public_key: candidate_identities[0].public_key.clone(),
            command_hash: String::new(),
            expected_height: 0,
            expected_state_root: String::new(),
            signature: String::new(),
        });
        assert!(matches!(
            crate::verify_consensus_stake_slash_evidence_v1(
                &epoch,
                position_id,
                liability_commitment,
                &malformed,
            ),
            Err(crate::ConsensusStakeEvidenceError::InvalidEvidenceShape)
        ));

        let mut forged = double_sign.clone();
        forged.first_vote.as_mut().unwrap().signature = "00".repeat(64);
        if forged
            .first_vote
            .as_ref()
            .unwrap()
            .signed_commitment(&epoch.descriptor.network_domain)
            .unwrap()
            > forged
                .second_vote
                .as_ref()
                .unwrap()
                .signed_commitment(&epoch.descriptor.network_domain)
                .unwrap()
        {
            std::mem::swap(&mut forged.first_vote, &mut forged.second_vote);
        }
        assert!(matches!(
            crate::verify_consensus_stake_slash_evidence_v1(
                &epoch,
                position_id,
                liability_commitment,
                &forged,
            ),
            Err(crate::ConsensusStakeEvidenceError::InvalidSignature(_))
        ));

        let wrong_key = double_sign_evidence(&epoch, &candidate_identities[1]);
        assert!(matches!(
            crate::verify_consensus_stake_slash_evidence_v1(
                &epoch,
                position_id,
                liability_commitment,
                &wrong_key,
            ),
            Err(crate::ConsensusStakeEvidenceError::HistoricalKeyMismatch)
        ));

        let mut outside = double_sign.clone();
        for vote in [
            outside.first_vote.as_mut().unwrap(),
            outside.second_vote.as_mut().unwrap(),
        ] {
            vote.parent_height = u64::try_from(liability.exit_height).unwrap();
            vote.signature = sign_bytes(
                &candidate_identities[0].secret_key,
                &vote
                    .signing_bytes(&epoch.descriptor.network_domain)
                    .unwrap(),
            )
            .unwrap();
        }
        if outside
            .first_vote
            .as_ref()
            .unwrap()
            .signed_commitment(&epoch.descriptor.network_domain)
            .unwrap()
            > outside
                .second_vote
                .as_ref()
                .unwrap()
                .signed_commitment(&epoch.descriptor.network_domain)
                .unwrap()
        {
            std::mem::swap(&mut outside.first_vote, &mut outside.second_vote);
        }
        assert!(matches!(
            crate::verify_consensus_stake_slash_evidence_v1(
                &epoch,
                position_id,
                liability_commitment,
                &outside,
            ),
            Err(crate::ConsensusStakeEvidenceError::OutsideLiabilityWindow)
        ));

        let checkpoint_height = liability.activation_height;
        let mut checkpoint_a = crate::SignedConsensusCheckpointStatementV1 {
            network_domain: epoch.descriptor.network_domain.clone(),
            zone_id: epoch.descriptor.zone_id.clone(),
            currency_genesis_root: epoch.descriptor.currency_genesis_root.clone(),
            protocol_era: epoch.descriptor.protocol_era,
            crypto_era: epoch.descriptor.crypto_era,
            consensus_protocol_version: epoch.descriptor.consensus_protocol_version,
            consensus_epoch: epoch.descriptor.consensus_epoch,
            checkpoint_height,
            previous_checkpoint_hash: hash_parts(&[b"RLD-TEST-PREVIOUS-CHECKPOINT"]),
            state_root: hash_parts(&[b"RLD-TEST-CHECKPOINT-A"]),
            validator_id: liability.position.validator_id().to_owned(),
            validator_public_key: liability.validator_public_key.clone(),
            validator_key_era: liability.validator_key_era,
            signature: String::new(),
        };
        checkpoint_a.signature = sign_bytes(
            &candidate_identities[0].secret_key,
            &checkpoint_a.signing_bytes().unwrap(),
        )
        .unwrap();
        let mut checkpoint_b = checkpoint_a.clone();
        checkpoint_b.state_root = hash_parts(&[b"RLD-TEST-CHECKPOINT-B"]);
        checkpoint_b.signature = sign_bytes(
            &candidate_identities[0].secret_key,
            &checkpoint_b.signing_bytes().unwrap(),
        )
        .unwrap();
        let (first_checkpoint, second_checkpoint) = if checkpoint_a.signed_commitment().unwrap()
            < checkpoint_b.signed_commitment().unwrap()
        {
            (checkpoint_a.clone(), checkpoint_b)
        } else {
            (checkpoint_b, checkpoint_a.clone())
        };
        let conflicting_checkpoint = crate::ConsensusStakeSlashEvidenceV1 {
            kind: crate::ConsensusStakeSlashEvidenceKindV1::ConflictingCheckpoint,
            first_vote: None,
            second_vote: None,
            first_checkpoint: Some(first_checkpoint),
            second_checkpoint: Some(second_checkpoint),
            proposal: None,
            invalid_vote: None,
        };
        let verified = crate::verify_consensus_stake_slash_evidence_v1(
            &epoch,
            position_id,
            liability_commitment,
            &conflicting_checkpoint,
        )
        .unwrap();
        assert_eq!(
            verified.kind,
            crate::ConsensusStakeSlashEvidenceKindV1::ConflictingCheckpoint
        );
        let mut same_checkpoint = conflicting_checkpoint.clone();
        same_checkpoint.second_checkpoint = same_checkpoint.first_checkpoint.clone();
        assert!(crate::verify_consensus_stake_slash_evidence_v1(
            &epoch,
            position_id,
            liability_commitment,
            &same_checkpoint,
        )
        .is_err());

        let parent_height = u64::try_from(liability.activation_height - 1).unwrap();
        let proposal_id = "invalid-state-commitment-proposal";
        let mut proposal = crate::SignedConsensusProposalStatementV1 {
            proposal_id: proposal_id.into(),
            zone_id: epoch.descriptor.zone_id.clone(),
            currency_genesis_root: epoch.descriptor.currency_genesis_root.clone(),
            protocol_era: epoch.descriptor.protocol_era,
            crypto_era: epoch.descriptor.crypto_era,
            parent_height,
            parent_state_root: hash_parts(&[b"RLD-TEST-SLASH-PARENT"]),
            round: 0,
            proposer_public_key: candidate_identities[1].public_key.clone(),
            command_hash: hash_parts(&[b"RLD-TEST-INVALID-STATE-COMMAND"]),
            expected_height: parent_height + 1,
            expected_state_root: hash_parts(&[b"RLD-TEST-PROPOSAL-STATE"]),
            signature: String::new(),
        };
        proposal.signature = sign_bytes(
            &candidate_identities[1].secret_key,
            &proposal
                .signing_bytes(&epoch.descriptor.network_domain)
                .unwrap(),
        )
        .unwrap();
        let proposal_hash = proposal
            .content_hash(&epoch.descriptor.network_domain)
            .unwrap();
        let invalid_vote = signed_stake_vote_statement(
            &epoch,
            &candidate_identities[0],
            proposal_id,
            proposal_hash,
            hash_parts(&[b"RLD-TEST-VOTE-INVALID-STATE"]),
        );
        let invalid_state = crate::ConsensusStakeSlashEvidenceV1 {
            kind: crate::ConsensusStakeSlashEvidenceKindV1::InvalidStateCommitment,
            first_vote: None,
            second_vote: None,
            first_checkpoint: None,
            second_checkpoint: None,
            proposal: Some(proposal),
            invalid_vote: Some(invalid_vote),
        };
        let verified = crate::verify_consensus_stake_slash_evidence_v1(
            &epoch,
            position_id,
            liability_commitment,
            &invalid_state,
        )
        .unwrap();
        assert_eq!(
            verified.kind,
            crate::ConsensusStakeSlashEvidenceKindV1::InvalidStateCommitment
        );
    }

    #[test]
    fn delayed_stake_unbond_is_certified_supply_preserving_and_exactly_replayable() {
        let (mut ledger, validators, _owner, request, lock_commit) =
            consensus_stake_unbond_fixture();
        let runtime_keys = ledger.descriptor.validator_keys.clone();
        let supply = ledger.supply_certificate().unwrap().conservation_position;
        let leader = consensus_leader(&ledger, &validators);
        let proposal = consensus_proposal(
            &ledger,
            leader,
            ConsensusCommand::RequestConsensusStakeUnbond(Box::new(request.clone())),
        );
        let request_commit = ConsensusCommit {
            proposal: proposal.clone(),
            votes: validators[..3]
                .iter()
                .map(|validator| consensus_vote(&proposal, validator))
                .collect(),
        };
        let pending_outcome = ledger
            .apply_consensus_commit(request_commit.clone())
            .unwrap();
        let ConsensusOutcome::ConsensusStakeUnbond(pending) = &pending_outcome else {
            panic!("stake unbond request returned the wrong outcome");
        };
        assert_eq!(pending.status, ConsensusStakeUnbondStatusV1::Pending);
        assert_eq!(pending.owner, pending.beneficiary);
        assert_eq!(pending.withdraw_after_height, 100);
        assert!(ledger
            .consensus_stake_authority
            .as_ref()
            .unwrap()
            .positions
            .iter()
            .all(|position| position.position_id != pending.position.position_id));
        assert_eq!(
            ledger.coins[&pending.position.escrow_coin_id].state,
            CoinState::Reserved
        );
        assert_eq!(ledger.descriptor.validator_keys, runtime_keys);

        let early = CompleteConsensusStakeUnbondV1 {
            completion_id: "stake-unbond-completion-early".into(),
            request_id: pending.request_id.clone(),
            zone_id: ledger.descriptor.zone_id.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            proposed_height: ledger.height,
            expires_at_height: 200,
            expected_unbond_request_commitment: pending.request_commitment.clone(),
            beneficiary: pending.beneficiary.clone(),
        };
        let mut redirected = early.clone();
        redirected.completion_id = "stake-unbond-completion-redirected".into();
        redirected.beneficiary = "rld:redirected-beneficiary".into();
        let redirected_root = ledger.state_root().unwrap();
        assert!(matches!(
            ledger.complete_consensus_stake_unbond(redirected),
            Err(LedgerError::Invalid(message)) if message.contains("beneficiary")
        ));
        assert_eq!(ledger.state_root().unwrap(), redirected_root);
        let early_root = ledger.state_root().unwrap();
        assert!(matches!(
            ledger.complete_consensus_stake_unbond(early),
            Err(LedgerError::Invalid(message)) if message.contains("withdrawal height")
        ));
        assert_eq!(ledger.state_root().unwrap(), early_root);

        while ledger.height < pending.withdraw_after_height {
            ledger.advance().unwrap();
        }
        let completion = CompleteConsensusStakeUnbondV1 {
            completion_id: "stake-unbond-completion-0000".into(),
            request_id: pending.request_id.clone(),
            zone_id: ledger.descriptor.zone_id.clone(),
            currency_genesis_root: ledger.descriptor.currency_genesis_root.clone(),
            protocol_era: ledger.descriptor.protocol_era,
            crypto_era: ledger.descriptor.crypto_era,
            proposed_height: ledger.height,
            expires_at_height: ledger.height + 10,
            expected_unbond_request_commitment: pending.request_commitment.clone(),
            beneficiary: pending.beneficiary.clone(),
        };
        let leader = consensus_leader(&ledger, &validators);
        let completion_proposal = consensus_proposal(
            &ledger,
            leader,
            ConsensusCommand::CompleteConsensusStakeUnbond(Box::new(completion)),
        );
        let completion_commit = ConsensusCommit {
            proposal: completion_proposal.clone(),
            votes: validators[..3]
                .iter()
                .map(|validator| consensus_vote(&completion_proposal, validator))
                .collect(),
        };
        let crash_envelope = serde_json::to_vec(&completion_commit).unwrap();
        let recovered_commit: ConsensusCommit = serde_json::from_slice(&crash_envelope).unwrap();
        assert_eq!(recovered_commit, completion_commit);
        let completed_outcome = ledger
            .apply_consensus_commit(recovered_commit.clone())
            .unwrap();
        let ConsensusOutcome::ConsensusStakeUnbond(completed) = &completed_outcome else {
            panic!("stake unbond completion returned the wrong outcome");
        };
        assert_eq!(completed.status, ConsensusStakeUnbondStatusV1::Completed);
        assert_eq!(
            ledger.coins[&completed.position.escrow_coin_id].state,
            CoinState::Consumed
        );
        let payout = &ledger.coins[completed.payout_coin_id.as_ref().unwrap()];
        assert_eq!(payout.state, CoinState::Spendable);
        assert_eq!(payout.owner, completed.owner);
        assert_eq!(payout.amount, completed.position.amount);
        assert_eq!(
            payout.parent_ids.as_slice(),
            std::slice::from_ref(&completed.position.escrow_coin_id)
        );
        assert!(!ledger
            .consensus_stake_escrows
            .contains_key(&completed.position.escrow_coin_id));
        assert_eq!(ledger.descriptor.validator_keys, runtime_keys);
        assert_eq!(
            ledger.supply_certificate().unwrap().conservation_position,
            supply
        );
        ledger.assert_conservation().unwrap();

        let replay_root = ledger.state_root().unwrap();
        assert_eq!(
            ledger.apply_consensus_commit(lock_commit).unwrap(),
            ConsensusOutcome::ConsensusStake(completed.position.clone())
        );
        assert_eq!(
            ledger.apply_consensus_commit(request_commit).unwrap(),
            pending_outcome
        );
        assert_eq!(
            ledger
                .apply_consensus_commit(recovered_commit.clone())
                .unwrap(),
            completed_outcome
        );
        assert_eq!(ledger.state_root().unwrap(), replay_root);
        let mut duplicate_completion = match &recovered_commit.proposal.command {
            ConsensusCommand::CompleteConsensusStakeUnbond(request) => (**request).clone(),
            _ => unreachable!(),
        };
        duplicate_completion.proposed_height = ledger.height;
        duplicate_completion.expires_at_height = ledger.height + 10;
        assert!(matches!(
            ledger.complete_consensus_stake_unbond(duplicate_completion),
            Err(LedgerError::Duplicate(_))
        ));
        assert_eq!(ledger.state_root().unwrap(), replay_root);
        let audit = ledger.audit_proof_bundle().unwrap();
        assert_eq!(audit.consensus_stake_unbonds, vec![completed.clone()]);
    }

