        assert!(matches!(
            duplicate.request_consensus_stake_unbond(replay),
            Err(LedgerError::Duplicate(_))
        ));
        assert_eq!(duplicate.state_root().unwrap(), duplicate_root);

        let (mut overflow, _validators, owner, mut request, _lock_commit) =
            consensus_stake_unbond_fixture();
        let mut authority = overflow.consensus_stake_authority.clone().unwrap();
        authority.policy.activation_delay_blocks = u128::MAX;
